ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))


def _optional_trace_rows(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _smoothstep(edge0: float, edge1: float, value: float) -> float:
    if edge1 <= edge0:
        return float(value >= edge1)
    t = max(0.0, min(1.0, (value - edge0) / (edge1 - edge0)))
    return t * t * (3.0 - 2.0 * t)


def _prospective_carrier_engagement_coverage(
    action_type: str,
    projected_carrier_distance: float,
    threat: float,
    residual_threat: float,
    press_radius: float,
    tackle_range: float,
) -> float:
    """Mirror production engagement with a visible-flight carrier position."""
    contact_reach = (0.75 + 0.36 * max(tackle_range, 0.0)) * (
        1.08 if action_type == "tackle" else 0.94
    )
    contact_access = 1.0 - _smoothstep(
        contact_reach * 0.34, contact_reach, projected_carrier_distance
    )
    threat_denial = (
        max(0.0, min(1.0, 1.0 - residual_threat / threat))
        if threat > 1e-6
        else contact_access
    )
    if action_type == "pursuit":
        convergence_access = 1.0 - _smoothstep(
            max(press_radius, contact_reach) * 0.42,
            max(press_radius, contact_reach),
            projected_carrier_distance,
        )
        return convergence_access * (0.08 + 0.32 * threat_denial)
    contact_intent = {
        "tackle": 1.0,
        "approach": 0.94,
        "close_down": 0.82,
        "block_lane": 0.52,
        "mark_runner": 0.46,
        "hold_position": 0.40,
    }.get(action_type, 0.34)
    contact_engagement = (
        contact_access * contact_intent * (0.30 + 0.70 * threat_denial)
    )
    if action_type == "tackle":
        return contact_engagement
    if action_type not in {"approach", "close_down"}:
        return contact_engagement
    pressure_access = 1.0 - _smoothstep(
        max(press_radius, contact_reach) * 0.32,
        max(press_radius, contact_reach),
        projected_carrier_distance,
    )
    pressure_intent = (0.18 + 0.42 * threat_denial) if action_type == "approach" else (
        0.12 + 0.34 * threat_denial
    )
    return max(contact_engagement, pressure_access * pressure_intent)


def _extend_candidate_motion_to_horizon(
    start: tuple[float, float],
    one_tick: tuple[float, float],
    target: tuple[float, float],
    horizon_ticks: float,
) -> tuple[float, float]:
    """Extend the existing one-tick candidate motion without changing direction."""
    horizon_ticks = max(float(horizon_ticks), 0.0)
    displacement = (one_tick[0] - start[0], one_tick[1] - start[1])
    projected = (
        start[0] + displacement[0] * horizon_ticks,
        start[1] + displacement[1] * horizon_ticks,
    )
    target_vector = (target[0] - start[0], target[1] - start[1])
    target_distance_squared = target_vector[0] ** 2 + target_vector[1] ** 2
    if target_distance_squared <= 1e-12:
        return target
    progress = (
        (projected[0] - start[0]) * target_vector[0]
        + (projected[1] - start[1]) * target_vector[1]
    ) / target_distance_squared
    if progress >= 1.0:
        return target
    return projected


def _iq_temperature_factor(
    iq: float, floor: float, low_iq_range: float, elite_discount: float
) -> float:
    value = max(float(iq), 1.0)
    low_iq_noise = max((100.0 - min(value, 100.0)) / 100.0, 0.0)
    factor = floor + low_iq_noise * low_iq_range
    if value > 100.0:
        elite = 1.0 - exp(-(value - 100.0) / 35.0)
        factor *= 1.0 - max(0.0, min(0.75, elite_discount)) * elite
    return max(factor, floor * (1.0 - max(0.0, min(0.75, elite_discount))))


def _replay_off_ball_softmax(scores: list[float], iq: float, roll: float) -> int | None:
    """Return the production selection index, or None for recover-shape fallback."""
    if not scores:
        return None
    max_score = max(scores)
    if max_score < 0.01:
        return None
    score_spread = max(max_score - min(scores), 0.0)
    temperature = max(
        0.003,
        min(
            0.05,
            (0.004 + score_spread * 0.22)
            * _iq_temperature_factor(iq, 0.35, 0.95, 0.28),
        ),
    )
    weights = [exp((score - max_score) / temperature) for score in scores]
    total_weight = sum(weights)
    if total_weight < 1e-10:
        return 0
    threshold = max(0.0, min(1.0, float(roll))) * total_weight
    cumulative = 0.0
    for index, weight in enumerate(weights):
        cumulative += weight
        if threshold <= cumulative:
            return index
    return len(scores) - 1


def _outlet_quality(
    origin: tuple[float, float],
    target: tuple[float, float],
    opponents: list[tuple[float, float]],
    attacking_right: bool,
) -> float:
    distance_to_target = hypot(target[0] - origin[0], target[1] - origin[1])
    connection_range = _smoothstep(3.0, 8.0, distance_to_target) * (
        1.0 - _smoothstep(28.0, 48.0, distance_to_target)
    )
    pressure = sum(
        (1.0 - hypot(target[0] - opponent[0], target[1] - opponent[1]) / 18.0) ** 1.25
        for opponent in opponents
        if hypot(target[0] - opponent[0], target[1] - opponent[1]) < 18.0
    )
    pressure = max(0.0, min(1.0, pressure * 0.30))
    direction = 1.0 if attacking_right else -1.0
    progression = max(-1.0, min(1.0, (target[0] - origin[0]) * direction / 105.0))
    progression_balance = 0.72 + 0.28 * _smoothstep(-0.18, 0.18, progression)
    return connection_range * (1.0 - pressure) * progression_balance


def _local_pressure(
    pos: tuple[float, float], opponents: Iterable[tuple[float, float]]
) -> float:
    pressure = sum(
        (1.0 - hypot(pos[0] - opponent[0], pos[1] - opponent[1]) / 18.0)
        ** 1.25
        for opponent in opponents
        if hypot(pos[0] - opponent[0], pos[1] - opponent[1]) < 18.0
    )
    return max(0.0, min(1.0, pressure * 0.30))


def _nearest_indexed_position(
    pos: tuple[float, float], rows: Iterable[dict[str, Any]]
) -> dict[str, Any] | None:
    nearest = None
    for row in rows:
        point = row.get("pos") if isinstance(row, dict) else None
        if not (
            isinstance(point, list)
            and len(point) >= 2
            and all(isinstance(value, (int, float)) for value in point[:2])
        ):
            continue
        distance_m = hypot(float(point[0]) - pos[0], float(point[1]) - pos[1])
        if nearest is None or distance_m < nearest["distance_m"]:
            nearest = {
                "idx": row.get("idx"),
                "pos": [float(point[0]), float(point[1])],
                "distance_m": distance_m,
            }
    return nearest


def _candidate_pressure_projection_snapshot(
    candidate: dict[str, Any],
) -> dict[str, Any]:
    projected_state = (
        candidate.get("value", {})
        .get("components", {})
        .get("projected_retained_state", {})
    )
    branch = projected_state.get("dominant_projected_branch", {})
    controller_pos_raw = branch.get("controller_pos") if isinstance(branch, dict) else None
    controller_pos = (
        (float(controller_pos_raw[0]), float(controller_pos_raw[1]))
        if isinstance(controller_pos_raw, list)
        and len(controller_pos_raw) >= 2
        and all(isinstance(value, (int, float)) for value in controller_pos_raw[:2])
        else None
    )
    opponents = (
        branch.get("opponents", [])
        if isinstance(branch, dict) and isinstance(branch.get("opponents"), list)
        else []
    )
    opponent_positions = [
        (float(row["pos"][0]), float(row["pos"][1]))
        for row in opponents
        if isinstance(row, dict)
        and isinstance(row.get("pos"), list)
        and len(row["pos"]) >= 2
        and all(isinstance(value, (int, float)) for value in row["pos"][:2])
    ]
    expected_relief = projected_state.get("pressure_relief")
    expected_pressure = (
        1.0 - float(expected_relief)
        if isinstance(expected_relief, (int, float))
        else None
    )
    return {
        "expected_pressure": expected_pressure,
        "pressure_max": projected_state.get("pressure_max"),
        "pressure_stddev": projected_state.get("pressure_stddev"),
        "control_readiness": projected_state.get("control_readiness"),
        "continuation_value": projected_state.get("continuation_value"),
        "structure": projected_state.get("structure"),
        "dominant_branch": {
            "conditional_probability": (
                branch.get("conditional_probability")
                if isinstance(branch, dict)
                else None
            ),
            "controller_idx": (
                branch.get("controller_idx") if isinstance(branch, dict) else None
            ),
            "controller_pos": list(controller_pos) if controller_pos is not None else None,
            "local_pressure": (
                _local_pressure(controller_pos, opponent_positions)
                if controller_pos is not None
                else None
            ),
            "nearest_opponent": (
                _nearest_indexed_position(controller_pos, opponents)
                if controller_pos is not None
                else None
            ),
            "teammates": (branch.get("teammates", []) if isinstance(branch, dict) else []),
            "opponents": opponents,
        },
    }


def _candidate_receiver_idx(candidate: dict[str, Any]) -> int | None:
    details = candidate.get("details", {})
    receiver_idx = details.get(
        "intended_receiver", details.get("target_player_idx")
    )
    return int(receiver_idx) if isinstance(receiver_idx, int) else None


def _physical_teammate_snapshot(
    candidate_context: dict[str, Any], player_idx: int | None
) -> dict[str, Any] | None:
    if not isinstance(player_idx, int):
        return None
    row = next(
        (
            teammate
            for teammate in candidate_context.get("teammate_goals", [])
            if isinstance(teammate, dict) and teammate.get("idx") == player_idx
        ),
        None,
    )
    if not isinstance(row, dict):
        return None
    pos = row.get("pos")
    point = (
        (float(pos[0]), float(pos[1]))
        if isinstance(pos, list)
        and len(pos) >= 2
        and all(isinstance(value, (int, float)) for value in pos[:2])
        else None
    )
    opponents = [
        opponent
        for opponent in candidate_context.get("opponents_state", [])
        if isinstance(opponent, dict) and opponent.get("position") != "GK"
    ]
    opponent_positions = [
        (float(opponent["pos"][0]), float(opponent["pos"][1]))
        for opponent in opponents
        if isinstance(opponent.get("pos"), list)
        and len(opponent["pos"]) >= 2
        and all(isinstance(value, (int, float)) for value in opponent["pos"][:2])
    ]
    return {
        field: row.get(field)
        for field in (
            "idx",
            "position",
            "pos",
            "velocity",
            "target_pos",
            "tactical_anchor",
            "movement_intent",
            "state",
            "goal_type",
            "goal_target",
            "task_intent",
            "task_phase",
            "task_active",
            "task_target",
            "task_effective_target",
            "task_accepted_tick",
            "task_expires_tick",
            "task_commitment",
        )
    } | {
        "local_pressure": (
            _local_pressure(point, opponent_positions) if point is not None else None
        ),
        "nearest_opponent": (
            _nearest_indexed_position(point, opponents) if point is not None else None
        ),
    }

