def _integrity_check(
    actual: float,
    expected: float,
    *,
    actual_source: str,
    expected_source: str,
    tolerance: float = 0.0,
    severity: str = "error",
) -> dict[str, Any]:
    delta = float(actual) - float(expected)
    return {
        "status": "ok" if abs(delta) <= tolerance + 1e-9 else severity,
        "actual": actual,
        "expected": expected,
        "delta": round(delta, 4),
        "tolerance": tolerance,
        "actual_source": actual_source,
        "expected_source": expected_source,
    }


def _subset_integrity_check(
    subset: float,
    superset: float,
    *,
    subset_source: str,
    superset_source: str,
    severity: str = "error",
) -> dict[str, Any]:
    overflow = max(float(subset) - float(superset), 0.0)
    return {
        "status": "ok" if overflow <= 1e-9 else severity,
        "actual": subset,
        "expected_max": superset,
        "delta": round(overflow, 4),
        "tolerance": 0.0,
        "actual_source": subset_source,
        "expected_source": superset_source,
    }


def _team_event_count(
    events: Iterable[dict[str, Any]],
    team: str,
    event_type: str,
    outcomes: set[str] | None = None,
) -> int:
    return sum(
        1
        for event in events
        if event.get("team_side") == team
        and event.get("event_type") == event_type
        and (outcomes is None or event.get("outcome") in outcomes)
    )


def _event_xg(event: dict[str, Any]) -> float:
    value = event.get("xg_exact", event.get("xg", 0.0))
    return float(value or 0.0)


def _xg_band(xg: float) -> str:
    """Natural diagnostic bands only; never used by engine behaviour."""
    if xg <= 1e-12:
        return "zero"
    if xg < 0.01:
        return "0_0.01"
    if xg < 0.03:
        return "0.01_0.03"
    if xg < 0.07:
        return "0.03_0.07"
    if xg < 0.15:
        return "0.07_0.15"
    return "0.15_plus"


def _numeric_distribution(values: list[float]) -> dict[str, Any]:
    return {
        "count": len(values),
        "mean": round(mean(values), 6) if values else None,
        "median": round(median(values), 6) if values else None,
        "p10": round(_quantile(values, 0.10), 6),
        "p90": round(_quantile(values, 0.90), 6),
    }


def _successor_transition_support_upper_bound(
    first_flight: dict[str, Any],
    final_flight: dict[str, Any],
    *,
    include_passer: bool,
    receipt_terminal: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Project per-player current-vs-role-support choices to the receipt frame.

    This is deliberately an independent-player upper bound. Each non-receiver
    adopts the existing role-aligned successor target only when its production
    score beats the current-position score. Non-adopters keep their baseline
    final-flight distance. No coordination, policy selection, or RNG is run.
    """
    winner_pos = (receipt_terminal or {}).get("winner_pos")
    physical_receipt = (
        isinstance(winner_pos, (list, tuple))
        and len(winner_pos) >= 2
        and all(isinstance(value, (int, float)) for value in winner_pos[:2])
    )
    if physical_receipt:
        receipt_destination = (float(winner_pos[0]), float(winner_pos[1]))
        final_distance_by_index = {
            int(player["idx"]): float(player["distance_to_receiver_m"])
            for player in (receipt_terminal or {}).get(
                "actual_receipt_outfield_teammates", []
            )
            if isinstance(player, dict)
            and isinstance(player.get("idx"), int)
            and isinstance(player.get("distance_to_receiver_m"), (int, float))
        }
    else:
        receipt_destination = None
        final_distance_by_index = {
            int(player["idx"]): float(
                player["distance_to_observed_destination_m"]
            )
            for player in final_flight.get("attacking_players", [])
            if isinstance(player, dict)
            and isinstance(player.get("idx"), int)
            and isinstance(
                player.get("distance_to_observed_destination_m"), (int, float)
            )
        }
    projected_rows: list[dict[str, Any]] = []
    for candidate in first_flight.get("successor_support_counterfactual", []):
        if not isinstance(candidate, dict):
            continue
        player_index = candidate.get("idx")
        is_passer = candidate.get("is_passer") is True
        if (
            not isinstance(player_index, int)
            or (is_passer and not include_passer)
            or player_index not in final_distance_by_index
        ):
            continue
        current_score = candidate.get("current_score")
        successor_score = candidate.get("successor_support_score")
        projected_pos = candidate.get("projected_receipt_pos")
        if (
            receipt_destination is not None
            and isinstance(projected_pos, (list, tuple))
            and len(projected_pos) >= 2
            and all(
                isinstance(value, (int, float)) for value in projected_pos[:2]
            )
        ):
            projected_distance = hypot(
                float(projected_pos[0]) - receipt_destination[0],
                float(projected_pos[1]) - receipt_destination[1],
            )
        else:
            projected_distance = candidate.get(
                "projected_receipt_distance_to_destination_m"
            )
        if not all(
            isinstance(value, (int, float))
            for value in (current_score, successor_score, projected_distance)
        ):
            continue
        adopted = float(successor_score) > float(current_score)
        baseline_distance = final_distance_by_index[player_index]
        projected_rows.append({
            "idx": player_index,
            "is_passer": is_passer,
            "adopted": adopted,
            "production_flight_attack_active": (
                candidate.get("production_flight_attack_active") is True
            ),
            "production_target_to_successor_m": candidate.get(
                "production_target_to_successor_m"
            ),
            "production_effective_target_to_successor_m": candidate.get(
                "production_effective_target_to_successor_m"
            ),
            "baseline_distance_m": baseline_distance,
            "projected_distance_m": (
                float(projected_distance) if adopted else baseline_distance
            ),
        })
    if not projected_rows:
        return None
    baseline_nearest = min(
        projected_rows, key=lambda row: row["baseline_distance_m"]
    )
    projected_nearest = min(
        projected_rows, key=lambda row: row["projected_distance_m"]
    )
    return {
        "eligible_players": len(projected_rows),
        "adopted_players": sum(row["adopted"] for row in projected_rows),
        "baseline_nearest_m": baseline_nearest["baseline_distance_m"],
        "projected_nearest_m": projected_nearest["projected_distance_m"],
        "nearest_is_passer": projected_nearest["is_passer"],
        "nearest_adopted": projected_nearest["adopted"],
        "nearest_player_idx": projected_nearest["idx"],
        "nearest_production_flight_attack_active": projected_nearest[
            "production_flight_attack_active"
        ],
        "nearest_production_target_to_successor_m": projected_nearest[
            "production_target_to_successor_m"
        ],
        "nearest_production_effective_target_to_successor_m": projected_nearest[
            "production_effective_target_to_successor_m"
        ],
    }


def _successor_transition_support_episode_intersection(
    gap_cases: Iterable[dict[str, Any]],
    transition_cases: Iterable[dict[str, Any]],
) -> dict[str, Any]:
    """Join intended-receipt pressure gaps to receipt support projections."""
    targets = [
        case
        for case in gap_cases
        if isinstance(case, dict)
        and case.get("acquisition_source") == "intended_pass_receipt"
        and case.get("acquisition_replay_id") is not None
    ]
    profiles = ("all_nonreceiver", "other_only")
    transition_by_profile_replay: dict[tuple[str, Any], dict[str, Any]] = {}
    duplicate_keys: Counter[tuple[str, Any]] = Counter()
    for case in transition_cases:
        if not isinstance(case, dict):
            continue
        profile = case.get("profile")
        replay_id = case.get("replay_id")
        if profile not in profiles or replay_id is None:
            continue
        key = (str(profile), replay_id)
        if key in transition_by_profile_replay:
            duplicate_keys[key] += 1
            continue
        transition_by_profile_replay[key] = case

    profile_reports: dict[str, Any] = {}
    for profile in profiles:
        counts: Counter[str] = Counter()
        metrics: dict[str, list[float]] = defaultdict(list)
        joined_cases: list[dict[str, Any]] = []
        counts["target_episodes"] = len(targets)
        counts["target_unique_replays"] = len({
            case["acquisition_replay_id"] for case in targets
        })
        counts["duplicate_transition_cases"] = sum(
            count
            for (candidate_profile, _), count in duplicate_keys.items()
            if candidate_profile == profile
        )
        for target in targets:
            replay_id = target["acquisition_replay_id"]
            transition = transition_by_profile_replay.get((profile, replay_id))
            joined = {
                "profile": profile,
                "replay_id": replay_id,
                "gap_tick": target.get("tick"),
                "acquisition_event_tick": target.get("acquisition_event_tick"),
                "possession_id": target.get("possession_id"),
                "team": target.get("team"),
                "holder_idx": target.get("holder_idx"),
                "cause": target.get("cause"),
                "acquisition_to_gap_ticks": target.get("acquisition_to_gap_ticks"),
                "actual_receipt_nearest_support_m": target.get(
                    "actual_receipt_nearest_support_m"
                ),
                "gap_nearest_support_m": target.get(
                    "nearest_support_distance_m"
                ),
            }
            if transition is None or not all(
                isinstance(transition.get(field), (int, float))
                for field in ("baseline_nearest_m", "projected_nearest_m")
            ):
                counts["missing_transition_projection"] += 1
                joined["matched_transition_projection"] = False
                if isinstance(transition, dict) and transition.get("missing_reason"):
                    joined["missing_reason"] = transition["missing_reason"]
                    counts[f"missing_reason={transition['missing_reason']}"] += 1
                joined_cases.append(joined)
                continue

            counts["matched_transition_projection"] += 1
            baseline_nearest = float(transition["baseline_nearest_m"])
            projected_nearest = float(transition["projected_nearest_m"])
            baseline_near = baseline_nearest < 10.0
            projected_near = projected_nearest < 10.0
            creates_within_10m = projected_near and not baseline_near
            counts[
                "baseline_within_10m" if baseline_near else "baseline_outside_10m"
            ] += 1
            counts[
                "upper_bound_within_10m"
                if projected_near
                else "upper_bound_outside_10m"
            ] += 1
            counts[
                "creates_within_10m"
                if creates_within_10m
                else "preserves_within_10m"
                if projected_near
                else "loses_within_10m"
                if baseline_near
                else "remains_outside_10m"
            ] += 1
            counts[
                "nearest_is_passer"
                if transition.get("nearest_is_passer") is True
                else "nearest_is_other"
            ] += 1
            counts[
                "nearest_adopted"
                if transition.get("nearest_adopted") is True
                else "nearest_retained"
            ] += 1
            metrics["baseline_nearest_m"].append(baseline_nearest)
            metrics["projected_nearest_m"].append(projected_nearest)
            metrics["nearest_closure_m"].append(
                baseline_nearest - projected_nearest
            )
            joined.update({
                "matched_transition_projection": True,
                "receipt_tick": transition.get("receipt_tick"),
                "baseline_nearest_m": baseline_nearest,
                "projected_nearest_m": projected_nearest,
                "creates_within_10m": creates_within_10m,
                "upper_bound_within_10m": projected_near,
                "nearest_is_passer": transition.get("nearest_is_passer"),
                "nearest_adopted": transition.get("nearest_adopted"),
            })
            joined_cases.append(joined)
        profile_reports[profile] = {
            "counts": dict(sorted(counts.items())),
            "metrics": {
                field: _numeric_distribution(values)
                for field, values in sorted(metrics.items())
                if values
            },
            "cases": joined_cases,
        }

    return {
        "scope": (
            "exact acquisition_replay_id join from high-pressure unsupported-holder "
            "episodes caused by intended pass receipts to the independent-player "
            "successor-transition upper bound at that receipt; projected support within "
            "10m closes the receipt-geometry gap only and does not assert persistence to "
            "a later pressure-gap tick"
        ),
        "gap_episode_count": sum(1 for case in gap_cases if isinstance(case, dict)),
        "intended_receipt_episode_count": len(targets),
        "intended_receipt_unique_replays": len({
            case["acquisition_replay_id"] for case in targets
        }),
        "profiles": profile_reports,
    }


def _receiver_hierarchical_pass_distribution(
    candidates: Iterable[dict[str, Any]],
    *,
    origin: list[float] | tuple[float, float] | None = None,
    attacking_right: bool = True,
    goalkeeper_idx: int | None = None,
) -> dict[str, float] | None:
    """Compare flat target sampling with receiver-then-target factorization.

    Both distributions reuse the trace's near-optimal set and softmax weights.
    Flat sampling normalizes every target weight together. Hierarchical sampling
    lets each receiver's best target represent that receiver, then preserves the
    original target-weight ratios within the selected receiver. This is a
    probability ledger only; no random choice is replayed.
    """
    rows = [
        row
        for row in candidates
        if isinstance(row, dict)
        and row.get("near_optimal") is True
        and isinstance(row.get("receiver_idx"), int)
        and isinstance(row.get("softmax_weight"), (int, float))
        and float(row["softmax_weight"]) > 0.0
    ]
    if not rows:
        return None
    by_receiver: dict[int, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        by_receiver[int(row["receiver_idx"])].append(row)
    flat_total = sum(float(row["softmax_weight"]) for row in rows)
    receiver_best = {
        receiver: max(float(row["softmax_weight"]) for row in receiver_rows)
        for receiver, receiver_rows in by_receiver.items()
    }
    receiver_best_total = sum(receiver_best.values())
    if flat_total <= 0.0 or receiver_best_total <= 0.0:
        return None

    flat_probabilities: list[float] = []
    hierarchical_probabilities: list[float] = []
    for row in rows:
        receiver = int(row["receiver_idx"])
        receiver_rows = by_receiver[receiver]
        receiver_target_total = sum(
            float(receiver_row["softmax_weight"])
            for receiver_row in receiver_rows
        )
        weight = float(row["softmax_weight"])
        flat_probabilities.append(weight / flat_total)
        hierarchical_probabilities.append(
            receiver_best[receiver] / receiver_best_total
            * weight / max(receiver_target_total, 1e-12)
        )

    result: dict[str, float] = {
        "near_optimal_targets": float(len(rows)),
        "near_optimal_receivers": float(len(by_receiver)),
        "max_targets_per_receiver": float(
            max((len(receiver_rows) for receiver_rows in by_receiver.values()), default=0)
        ),
        "candidate_probability_total_variation": 0.5
        * sum(
            abs(flat - hierarchical)
            for flat, hierarchical in zip(
                flat_probabilities, hierarchical_probabilities
            )
        ),
    }

    def expected(
        probabilities: list[float], predicate_or_field: Any
    ) -> float | None:
        if callable(predicate_or_field):
            return sum(
                probability * float(bool(predicate_or_field(row)))
                for row, probability in zip(rows, probabilities)
            )
        values = [row.get(predicate_or_field) for row in rows]
        if not all(isinstance(value, (int, float)) for value in values):
            return None
        return sum(
            probability * float(value)
            for value, probability in zip(values, probabilities)
        )

    observables: dict[str, Any] = {
        "distance_m": "distance_m",
        "retention_probability": "retention_probability",
        "option_duration_seconds": "option_duration_seconds",
        "retained_control_probability": "retained_control_probability",
        "opposing_control_probability": "opposing_control_probability",
        "unresolved_probability": "unresolved_probability",
        "within_10m": lambda row: isinstance(row.get("distance_m"), (int, float))
        and float(row["distance_m"]) < 10.0,
        "feet": lambda row: row.get("target_kind") == "feet",
        "within_10m_feet": lambda row: row.get("target_kind") == "feet"
        and isinstance(row.get("distance_m"), (int, float))
        and float(row["distance_m"]) < 10.0,
        "exact_feet": lambda row: row.get("target_kind") == "feet"
        and isinstance(row.get("receiver_offset_m"), (int, float))
        and abs(float(row["receiver_offset_m"])) <= 1e-9,
        "long": lambda row: row.get("is_long") is True,
        "goalkeeper": lambda row: goalkeeper_idx is not None
        and row.get("receiver_idx") == goalkeeper_idx,
        "backward": lambda row: (
            isinstance(origin, (list, tuple))
            and len(origin) >= 2
            and isinstance(row.get("target"), list)
            and len(row["target"]) >= 2
            and (float(row["target"][0]) - float(origin[0]))
            * (1.0 if attacking_right else -1.0)
            < 0.0
        ),
        "long_backward_goalkeeper": lambda row: row.get("is_long") is True
        and goalkeeper_idx is not None
        and row.get("receiver_idx") == goalkeeper_idx
        and isinstance(origin, (list, tuple))
        and len(origin) >= 2
        and isinstance(row.get("target"), list)
        and len(row["target"]) >= 2
        and (float(row["target"][0]) - float(origin[0]))
        * (1.0 if attacking_right else -1.0)
        < 0.0,
    }
    for name, predicate_or_field in observables.items():
        flat = expected(flat_probabilities, predicate_or_field)
        hierarchical = expected(hierarchical_probabilities, predicate_or_field)
        if flat is None or hierarchical is None:
            continue
        result[f"flat_expected_{name}"] = flat
        result[f"hierarchical_expected_{name}"] = hierarchical
        result[f"hierarchical_minus_flat_{name}"] = hierarchical - flat
    return result


def _bounded_rational_tolerance(
    best_score: float, iq: float, pressure: float, fatigue: float
) -> float:
    if not isinstance(best_score, (int, float)) or not float(best_score) == float(best_score):
        return 0.0
    iq_value = max(float(iq), 1.0)
    cognitive_noise = (
        max((100.0 - iq_value) / 100.0, 0.01)
        if iq_value <= 100.0
        else max(0.01 * exp(-(iq_value - 100.0) / 35.0), 0.003)
    )
    pressure_load = max(0.0, min(1.0, float(pressure)))
    fatigue_load = max(0.0, min(1.0, float(fatigue)))
    load_tolerance = max(
        0.003,
        min(
            0.032,
            0.003
            + cognitive_noise * 0.014
            + pressure_load * (0.0035 + cognitive_noise * 0.010)
            + fatigue_load * (0.0025 + cognitive_noise * 0.006),
        ),
    )
    relative_tolerance = max(abs(float(best_score)) * 0.35, 0.003)
    return min(load_tolerance, relative_tolerance)


def _possession_transition_distance(
    left: dict[str, Any], right: dict[str, Any]
) -> float:
    def probabilities(transition: dict[str, Any]) -> tuple[float, float, float, float]:
        goal = max(0.0, min(1.0, float(transition.get("goal_probability", 0.0) or 0.0)))
        retained = max(
            0.0,
            min(1.0, float(transition.get("retained_control_probability", 0.0) or 0.0)),
        )
        opposing = max(
            0.0,
            min(1.0, float(transition.get("opposing_control_probability", 0.0) or 0.0)),
        )
        unresolved = max(0.0, min(1.0, 1.0 - goal - retained - opposing))
        return goal, retained, opposing, unresolved

    return 0.5 * sum(
        abs(left_value - right_value)
        for left_value, right_value in zip(probabilities(left), probabilities(right))
    )


def _bounded_rational_probabilities(
    scores: list[float], iq: float, pressure: float, fatigue: float
) -> list[float]:
    if not scores:
        return []
    best = max(scores)
    tolerance = _bounded_rational_tolerance(best, iq, pressure, fatigue)
    eligible = [index for index, score in enumerate(scores) if score >= best - tolerance]
    if len(eligible) <= 1:
        probabilities = [0.0] * len(scores)
        probabilities[scores.index(best)] = 1.0
        return probabilities
    temperature = max(
        tolerance
        * (
            0.55
            + max(0.0, min(1.0, float(pressure))) * 0.30
            + max(0.0, min(1.0, float(fatigue))) * 0.20
        ),
        1e-9,
    )
    weights = [
        exp((score - best) / temperature) if index in eligible else 0.0
        for index, score in enumerate(scores)
    ]
    total = sum(weights)
    return [weight / max(total, 1e-12) for weight in weights]


def _outcome_distinguishability_selection_counterfactual(
    decision: dict[str, Any],
) -> dict[str, float] | None:
    """Separate family- and action-stage outcome-distance penalties."""
    candidates = [
        candidate
        for candidate in [decision.get("chosen", {}), *decision.get("alternatives", [])]
        if isinstance(candidate, dict)
        and isinstance(candidate.get("value", {}).get("score"), (int, float))
    ]
    selection = decision.get("bounded_rational_selection", {})
    iq = selection.get("iq")
    pressure = selection.get("pressure")
    fatigue = selection.get("fatigue")
    if not candidates or not all(isinstance(value, (int, float)) for value in (iq, pressure, fatigue)):
        return None
    family_codes = {
        "carry": 0,
        "pass": 1,
        "shoot": 2,
        "hold": 3,
        "reorient": 3,
        "clear": 4,
    }
    rows = []
    for candidate in candidates:
        action = str(candidate.get("action_type") or "unknown")
        family = family_codes.get(action)
        transition = candidate.get("value", {}).get("components", {}).get(
            "outcome_transition"
        )
        if family is None or not isinstance(transition, dict):
            continue
        target = candidate.get("target")
        origin = decision.get("pos")
        distance_m = (
            hypot(
                float(target[0]) - float(origin[0]),
                float(target[1]) - float(origin[1]),
            )
            if action == "pass"
            and isinstance(target, list)
            and len(target) >= 2
            and isinstance(origin, list)
            and len(origin) >= 2
            else 0.0
        )
        direction = (
            _classify_pass(origin, target, bool(decision.get("attacking_right")))
            if action == "pass" and distance_m > 0.0
            else "none"
        )
        if direction in {"left", "right"}:
            direction = "lateral"
        rows.append({
            "action": action,
            "family": family,
            "score": float(candidate["value"]["score"]),
            "transition": transition,
            "distance_m": distance_m,
            "direction": direction,
            "retention": float(candidate.get("value", {}).get("success_prob", 0.0) or 0.0),
        })
    if not rows:
        return None

    family_rows = {family: [row for row in rows if row["family"] == family] for family in sorted({row["family"] for row in rows})}
    family_best = {family: max(items, key=lambda row: row["score"]) for family, items in family_rows.items()}
    raw_family_scores = [family_best[family]["score"] for family in family_rows]
    best_family_index = max(range(len(raw_family_scores)), key=raw_family_scores.__getitem__)
    best_family_transition = list(family_best.values())[best_family_index]["transition"]
    family_tolerance = _bounded_rational_tolerance(
        raw_family_scores[best_family_index], float(iq), float(pressure), float(fatigue)
    )
    adjusted_family_scores = [
        score
        - family_tolerance
        * _possession_transition_distance(best["transition"], best_family_transition)
        for score, best in zip(raw_family_scores, family_best.values())
    ]

    distributions: dict[str, list[float]] = {}
    for ledger, family_scores, adjust_actions in (
        ("production", adjusted_family_scores, True),
        ("no_family_penalty", raw_family_scores, True),
        ("no_action_penalty", adjusted_family_scores, False),
        ("raw", raw_family_scores, False),
    ):
        family_probabilities = _bounded_rational_probabilities(
            family_scores, float(iq), float(pressure), float(fatigue)
        )
        candidate_probabilities = [0.0] * len(rows)
        for family_slot, (family, items) in enumerate(family_rows.items()):
            item_scores = [item["score"] for item in items]
            if adjust_actions:
                best_index = max(range(len(item_scores)), key=item_scores.__getitem__)
                best_transition = items[best_index]["transition"]
                item_tolerance = _bounded_rational_tolerance(
                    item_scores[best_index], float(iq), float(pressure), float(fatigue)
                )
                item_scores = [
                    score
                    - item_tolerance
                    * _possession_transition_distance(item["transition"], best_transition)
                    for score, item in zip(item_scores, items)
                ]
            item_probabilities = _bounded_rational_probabilities(
                item_scores, float(iq), float(pressure), float(fatigue)
            )
            for item, probability in zip(items, item_probabilities):
                candidate_probabilities[rows.index(item)] = (
                    family_probabilities[family_slot] * probability
                )
        distributions[ledger] = candidate_probabilities

    result: dict[str, float] = {}
    for ledger, probabilities in distributions.items():
        pass_probability = sum(
            probability
            for row, probability in zip(rows, probabilities)
            if row["action"] == "pass"
        )
        result[f"{ledger}_pass_probability"] = pass_probability
        for action in ("carry", "pass", "shoot", "hold", "reorient", "clear"):
            result[f"{ledger}_action_{action}_probability"] = sum(
                probability
                for row, probability in zip(rows, probabilities)
                if row["action"] == action
            )
        if pass_probability > 1e-12:
            result[f"{ledger}_provider_long_share_given_pass"] = sum(
                probability
                for row, probability in zip(rows, probabilities)
                if row["action"] == "pass" and row["distance_m"] >= 32.0
            ) / pass_probability
            result[f"{ledger}_expected_pass_distance_m"] = sum(
                probability * row["distance_m"]
                for row, probability in zip(rows, probabilities)
                if row["action"] == "pass"
            ) / pass_probability
            result[f"{ledger}_expected_pass_retention"] = sum(
                probability * row["retention"]
                for row, probability in zip(rows, probabilities)
                if row["action"] == "pass"
            ) / pass_probability
            for direction in ("backward", "forward", "lateral"):
                result[f"{ledger}_{direction}_share_given_pass"] = sum(
                    probability
                    for row, probability in zip(rows, probabilities)
                    if row["action"] == "pass" and row["direction"] == direction
                ) / pass_probability
    for field in tuple(result):
        if field.startswith("production_"):
            suffix = field.removeprefix("production_")
            raw_field = f"raw_{suffix}"
            if raw_field in result:
                result[f"raw_minus_production_{suffix}"] = (
                    result[raw_field] - result[field]
                )
    return result


def _continuous_connection_redundancy(
    holder_pos: list[float] | tuple[float, float],
    candidates: Iterable[dict[str, Any]],
) -> dict[str, float]:
    """Summarize complementary holder connections without angle/distance bands.

    Each connection contributes ``local_value * projected_outlet_access`` along
    its holder-relative unit vector.  The redundancy term is the harmonic mean
    of the two eigenvalues of the resulting 2-D connection matrix.  Collinear
    outlets therefore add no redundancy, while strong outlets on independent
    axes reinforce one another continuously.
    """
    matrix_xx = 0.0
    matrix_xy = 0.0
    matrix_yy = 0.0
    for candidate in candidates:
        target = candidate.get("target")
        local_value = candidate.get("value", candidate.get("local_value"))
        outlet_access = candidate.get("projected_outlet_access")
        if not (
            isinstance(target, (list, tuple))
            and len(target) >= 2
            and isinstance(local_value, (int, float))
            and isinstance(outlet_access, (int, float))
        ):
            continue
        dx = float(target[0]) - float(holder_pos[0])
        dy = float(target[1]) - float(holder_pos[1])
        target_distance = hypot(dx, dy)
        if target_distance <= 1e-12:
            continue
        # Team connection topology is independent of the player's individual
        # movement utility. Local value remains a separate Pareto/cost axis.
        weight = max(0.0, min(1.0, float(outlet_access)))
        unit_x = dx / target_distance
        unit_y = dy / target_distance
        matrix_xx += weight * unit_x * unit_x
        matrix_xy += weight * unit_x * unit_y
        matrix_yy += weight * unit_y * unit_y
    trace = matrix_xx + matrix_yy
    determinant = max(matrix_xx * matrix_yy - matrix_xy * matrix_xy, 0.0)
    redundancy = 2.0 * determinant / trace if trace > 1e-12 else 0.0
    isotropy = 4.0 * determinant / (trace * trace) if trace > 1e-12 else 0.0
    return {
        "matrix_xx": matrix_xx,
        "matrix_xy": matrix_xy,
        "matrix_yy": matrix_yy,
        "connection_weight": trace,
        "connection_redundancy": redundancy,
        "connection_isotropy": max(0.0, min(1.0, isotropy)),
    }


def _continuous_triangle_closure(
    holder_pos: list[float] | tuple[float, float],
    candidates: Iterable[dict[str, Any]],
) -> float:
    """Return continuous three-edge support-cycle strength around the holder."""
    connections = []
    for candidate in candidates:
        target = candidate.get("target")
        local_value = candidate.get("value", candidate.get("local_value"))
        outlet_access = candidate.get("projected_outlet_access")
        if not (
            isinstance(target, (list, tuple))
            and len(target) >= 2
            and isinstance(local_value, (int, float))
            and isinstance(outlet_access, (int, float))
        ):
            continue
        dx = float(target[0]) - float(holder_pos[0])
        dy = float(target[1]) - float(holder_pos[1])
        distance = hypot(dx, dy)
        if distance <= 1e-12:
            continue
        weight = max(0.0, min(1.0, float(outlet_access)))
        connections.append((target, distance, dx / distance, dy / distance, weight))
    closure = 0.0
    for left_index, left in enumerate(connections):
        for right in connections[left_index + 1 :]:
            if left[4] <= 1e-12 or right[4] <= 1e-12:
                continue
            cosine = max(-1.0, min(1.0, left[2] * right[2] + left[3] * right[3]))
            angular_diversity = max(0.0, 1.0 - cosine * cosine)
            cross_distance = hypot(
                float(left[0][0]) - float(right[0][0]),
                float(left[0][1]) - float(right[0][1]),
            )
            cross_connection = _smoothstep(3.0, 8.0, cross_distance) * (
                1.0 - _smoothstep(28.0, 48.0, cross_distance)
            )
            bottleneck = 2.0 * left[4] * right[4] / (left[4] + right[4])
            closure += bottleneck * cross_connection * angular_diversity
    return closure


def _optimistic_outlet_resource_candidate(
    counterfactual: dict[str, Any],
    holder_pos: list[float] | tuple[float, float],
    endpoints: dict[str, Any],
    turnover_avoidance_value: float = 0.0,
) -> dict[str, float] | None:
    """Price one pressure-responsive outlet against its local opportunity cost.

    This is deliberately an optimistic upper bound.  The possession network's
    full-outlet minus zero-outlet endpoint span is treated as the entire team
    resource capacity available to this one candidate, scaled only by the
    candidate's existing continuous support geometry and physical access.  It
    does not apply the production local floor or spatial-conflict veto; callers
    report those constraints separately.
    """
    target = counterfactual.get("target")
    base_score = counterfactual.get("base_score")
    local_best = counterfactual.get("local_best_base_score")
    ratio = counterfactual.get("to_local_best_ratio")
    components = counterfactual.get("components", {})
    zero_outlet = endpoints.get("zero_outlet")
    full_outlet = endpoints.get("full_outlet")
    support_angle = components.get("support_angle_value")
    immediate_reach = components.get("immediate_reach")
    pass_feasibility = components.get("pass_feasibility")
    if not (
        isinstance(target, (list, tuple))
        and len(target) >= 2
        and all(
            isinstance(value, (int, float))
            for value in (
                base_score,
                local_best,
                ratio,
                zero_outlet,
                full_outlet,
                support_angle,
                immediate_reach,
                pass_feasibility,
            )
        )
    ):
        return None
    coverage = prod(
        max(0.0, min(1.0, float(value)))
        for value in (support_angle, immediate_reach, pass_feasibility)
    )
    endpoint_capacity = max(float(full_outlet) - float(zero_outlet), 0.0)
    local_value_cost = max(float(local_best) - float(base_score), 0.0)
    optimistic_team_value = endpoint_capacity * coverage
    turnover_avoidance_value = max(float(turnover_avoidance_value), 0.0)
    turnover_avoidance_net_team_value = (
        optimistic_team_value + turnover_avoidance_value - local_value_cost
    )
    return {
        "target_distance_m": hypot(
            float(target[0]) - float(holder_pos[0]),
            float(target[1]) - float(holder_pos[1]),
        ),
        "base_score": float(base_score),
        "local_best_base_score": float(local_best),
        "to_local_best_ratio": float(ratio),
        "outlet_coverage": coverage,
        "endpoint_capacity": endpoint_capacity,
        "local_value_cost": local_value_cost,
        "optimistic_team_value": optimistic_team_value,
        "optimistic_net_team_value": optimistic_team_value - local_value_cost,
        "turnover_avoidance_value": turnover_avoidance_value,
        "turnover_avoidance_net_team_value": turnover_avoidance_net_team_value,
    }


def _high_pressure_support_gap_episode_summary(
    trace_entries: Iterable[dict[str, Any]],
    decisions: Iterable[dict[str, Any]] = (),
) -> dict[str, Any]:
    """Classify the first no-near-support state in each high-pressure episode.

    The 2m pressure and 10m support boundaries mirror the external geometry
    audit and are used only to define reportable crossings.  Cause labels are
    derived from continuous distance deltas between physical held-tick states.
    """
    trace_entries = list(trace_entries)
    decisions = list(decisions)
    pass_releases = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("action") == "pass"
        and entry.get("replay_id") is not None
    }
    pass_terminals = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    on_ball_by_identity = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")):
            decision
        for decision in decisions
        if decision.get("phase") == "on_ball"
    }
    on_ball_context_by_identity = {
        (entry.get("tick"), entry.get("team"), entry.get("player_idx")): entry
        for entry in trace_entries
        if entry.get("event") == "on_ball_candidate_counts"
    }
    rows = []
    for entry in trace_entries:
        if entry.get("event") != "held_support_state":
            continue
        tick = entry.get("tick")
        possession_id = entry.get("possession_id")
        team = entry.get("team")
        holder_idx = entry.get("holder_idx")
        holder_pos = entry.get("holder_pos")
        opponent_distance = entry.get("nearest_opponent_distance_m")
        holder_local_pressure = entry.get("holder_local_pressure")
        if not (
            isinstance(tick, int)
            and possession_id is not None
            and team in {"home", "away"}
            and isinstance(holder_idx, int)
            and isinstance(holder_pos, (list, tuple))
            and len(holder_pos) >= 2
            and isinstance(opponent_distance, (int, float))
        ):
            continue
        supporters = []
        for supporter in entry.get("supporters", []):
            pos = supporter.get("pos") if isinstance(supporter, dict) else None
            if (
                not isinstance(supporter, dict)
                or supporter.get("is_goalkeeper") is True
                or not isinstance(supporter.get("idx"), int)
                or not isinstance(pos, (list, tuple))
                or len(pos) < 2
            ):
                continue
            distance_m = hypot(
                float(pos[0]) - float(holder_pos[0]),
                float(pos[1]) - float(holder_pos[1]),
            )
            supporters.append((distance_m, int(supporter["idx"])))
        if not supporters:
            continue
        nearest_support_distance, nearest_supporter_idx = min(supporters)
        rows.append({
            "tick": tick,
            "possession_id": possession_id,
            "team": team,
            "holder_idx": holder_idx,
            "holder_pos": (float(holder_pos[0]), float(holder_pos[1])),
            "nearest_opponent_distance_m": float(opponent_distance),
            "nearest_support_distance_m": nearest_support_distance,
            "nearest_supporter_idx": nearest_supporter_idx,
            "holder_local_pressure": (
                float(holder_local_pressure)
                if isinstance(holder_local_pressure, (int, float))
                else None
            ),
            "opponents": [
                {
                    "idx": int(opponent["idx"]),
                    "pos": (
                        float(opponent["pos"][0]),
                        float(opponent["pos"][1]),
                    ),
                }
                for opponent in entry.get("opponents", [])
                if isinstance(opponent, dict)
                and isinstance(opponent.get("idx"), int)
                and isinstance(opponent.get("pos"), (list, tuple))
                and len(opponent["pos"]) >= 2
            ],
        })
    rows.sort(key=lambda row: (int(row["tick"]), str(row["team"])))

    counts: Counter[str] = Counter()
    metrics: dict[str, list[float]] = defaultdict(list)
    cases = []
    previous_by_team: dict[str, dict[str, Any]] = {}
    previous_bad_by_episode: dict[tuple[Any, str, int], bool] = {}

    def acquisition_event(row: dict[str, Any]) -> tuple[str, dict[str, Any] | None]:
        matches: list[tuple[int, int, str, dict[str, Any]]] = []
        row_tick = int(row["tick"])
        row_team = str(row["team"])
        row_holder = int(row["holder_idx"])
        row_possession = row["possession_id"]
        for event in trace_entries:
            event_tick = event.get("tick")
            if not isinstance(event_tick, int) or not 0 <= row_tick - event_tick <= 12:
                continue
            event_name = str(event.get("event") or "")
            source = None
            priority = 0
            if (
                event_name == "pass_control_terminal"
                and event.get("winner_team") == row_team
                and event.get("winner_player") == row_holder
            ):
                retained = event.get("possession_retained") is True
                intended = event.get("winner_is_intended_receiver") is True
                source = (
                    "intended_pass_receipt"
                    if retained and intended
                    else "same_team_pass_recovery"
                    if retained
                    else "pass_interception"
                )
                priority = 4
            elif (
                event_name == "ball_controlled"
                and event.get("team") == row_team
                and event.get("player_idx") == row_holder
                and event.get("possession_id") == row_possession
            ):
                source = (
                    "settled_pass_control"
                    if event.get("settled_pass") is True
                    else "same_team_loose_control"
                    if event.get("same_team_as_previous_possession") is True
                    else "opposition_loose_control"
                )
                priority = 3
            elif (
                event_name in {"duel", "tackle"}
                and event.get("outcome") == "defender_wins"
                and event.get("defender_idx") == row_holder
            ):
                holder_home = event.get("holder_team_home")
                winner_team = (
                    "away" if holder_home is True
                    else "home" if holder_home is False
                    else None
                )
                old_possession = event.get("possession_id")
                possession_matches = (
                    isinstance(old_possession, int)
                    and isinstance(row_possession, int)
                    and row_possession == old_possession + 1
                )
                if winner_team == row_team and possession_matches:
                    source = "pressure_turnover_control"
                    priority = 2
            elif (
                event_name == "restart"
                and event.get("team") == row_team
            ):
                source = "restart_control"
                priority = 1
            if source is not None:
                matches.append((event_tick, priority, source, event))
        if not matches:
            return "unknown", None
        _, _, source, event = max(matches, key=lambda match: (match[0], match[1]))
        return source, event

    for row in rows:
        team = str(row["team"])
        episode = (row["possession_id"], team, int(row["holder_idx"]))
        bad = (
            row["nearest_opponent_distance_m"] < 2.0
            and row["nearest_support_distance_m"] >= 10.0
        )
        previous_bad = previous_bad_by_episode.get(episode, False)
        previous_bad_by_episode[episode] = bad
        previous = previous_by_team.get(team)
        previous_by_team[team] = row
        if not bad or previous_bad:
            continue

        counts["gap_episode_entries"] += 1
        same_possession = (
            previous is not None
            and previous["possession_id"] == row["possession_id"]
        )
        consecutive_tick = (
            previous is not None and int(previous["tick"]) + 1 == int(row["tick"])
        )
        same_holder = (
            same_possession
            and previous is not None
            and previous["holder_idx"] == row["holder_idx"]
        )
        if same_possession and previous is not None and not same_holder:
            cause = "controller_handoff"
        elif previous is None or not same_possession:
            cause = "new_possession"
        elif not consecutive_tick:
            cause = "observation_gap"
        else:
            pressure_crossed = previous["nearest_opponent_distance_m"] >= 2.0
            support_crossed = previous["nearest_support_distance_m"] < 10.0
            cause = (
                "joint_crossing"
                if pressure_crossed and support_crossed
                else "pressure_crossing"
                if pressure_crossed
                else "support_departure"
                if support_crossed
                else "unresolved_continuation"
            )
        counts[f"cause={cause}"] += 1
        metrics["entry_nearest_opponent_distance_m"].append(
            row["nearest_opponent_distance_m"]
        )
        metrics["entry_nearest_support_distance_m"].append(
            row["nearest_support_distance_m"]
        )
        case = {
            "possession_id": row["possession_id"],
            "team": team,
            "tick": row["tick"],
            "holder_idx": row["holder_idx"],
            "cause": cause,
            "nearest_opponent_distance_m": row["nearest_opponent_distance_m"],
            "nearest_support_distance_m": row["nearest_support_distance_m"],
            "nearest_supporter_idx": row["nearest_supporter_idx"],
            "holder_local_pressure": row["holder_local_pressure"],
        }
        if isinstance(row["holder_local_pressure"], (int, float)):
            metrics["entry_holder_local_pressure"].append(
                float(row["holder_local_pressure"])
            )
        source, source_event = acquisition_event(row)
        case["acquisition_source"] = source
        counts[f"acquisition_source={source}"] += 1
        if source_event is not None and isinstance(source_event.get("tick"), int):
            source_tick = int(source_event["tick"])
            case["acquisition_event_tick"] = source_tick
            case["acquisition_to_gap_ticks"] = int(row["tick"]) - source_tick
            metrics[f"acquisition_source={source}:lead_ticks"].append(
                float(int(row["tick"]) - source_tick)
            )
            if source_event.get("event") is not None:
                case["acquisition_event"] = source_event.get("event")
            if source_event.get("replay_id") is not None:
                case["acquisition_replay_id"] = source_event.get("replay_id")
                replay_id = source_event.get("replay_id")
                release = pass_releases.get(replay_id, {})
                terminal = pass_terminals.get(replay_id, {})
                first_held_after_acquisition = min(
                    (
                        candidate
                        for candidate in rows
                        if candidate["possession_id"] == row["possession_id"]
                        and candidate["team"] == row["team"]
                        and candidate["holder_idx"] == row["holder_idx"]
                        and int(candidate["tick"]) > int(source_event["tick"])
                    ),
                    key=lambda candidate: int(candidate["tick"]),
                    default=None,
                )
                if first_held_after_acquisition is not None:
                    first_tick = int(first_held_after_acquisition["tick"])
                    first_pressure = first_held_after_acquisition.get(
                        "holder_local_pressure"
                    )
                    first_support = first_held_after_acquisition.get(
                        "nearest_support_distance_m"
                    )
                    case["first_held_after_acquisition_tick"] = first_tick
                    case["acquisition_to_first_held_ticks"] = (
                        first_tick - int(source_event["tick"])
                    )
                    case["first_held_to_gap_ticks"] = int(row["tick"]) - first_tick
                    if isinstance(first_pressure, (int, float)):
                        case["first_held_holder_local_pressure"] = float(first_pressure)
                        metrics[
                            f"acquisition_source={source}:first_held_holder_local_pressure"
                        ].append(float(first_pressure))
                    if isinstance(first_support, (int, float)):
                        case["first_held_nearest_support_m"] = float(first_support)
                        metrics[
                            f"acquisition_source={source}:first_held_nearest_support_m"
                        ].append(float(first_support))
                source_decision = on_ball_by_identity.get((
                    release.get("tick"),
                    release.get("team"),
                    release.get("passer_player"),
                ), {})
                chosen_components = (
                    source_decision.get("chosen", {})
                    .get("value", {})
                    .get("components", {})
                )
                pressure_projection = _candidate_pressure_projection_snapshot(
                    source_decision.get("chosen", {})
                )
                case["release_pressure_projection"] = pressure_projection
                actual_receipt_holder = terminal.get("winner_pos")
                actual_receipt_opponents = terminal.get(
                    "actual_receipt_opponents", []
                )
                if (
                    isinstance(actual_receipt_holder, list)
                    and len(actual_receipt_holder) >= 2
                    and isinstance(actual_receipt_opponents, list)
                ):
                    actual_holder = (
                        float(actual_receipt_holder[0]),
                        float(actual_receipt_holder[1]),
                    )
                    predicted_branch = pressure_projection.get(
                        "dominant_branch", {}
                    )
                    predicted_holder = predicted_branch.get("controller_pos")
                    predicted_opponents = {
                        int(opponent["idx"]): (
                            float(opponent["pos"][0]),
                            float(opponent["pos"][1]),
                        )
                        for opponent in predicted_branch.get("opponents", [])
                        if isinstance(opponent, dict)
                        and isinstance(opponent.get("idx"), int)
                        and isinstance(opponent.get("pos"), list)
                        and len(opponent["pos"]) >= 2
                    }
                    actual_opponents = {
                        int(opponent["idx"]): (
                            float(opponent["pos"][0]),
                            float(opponent["pos"][1]),
                        )
                        for opponent in actual_receipt_opponents
                        if isinstance(opponent, dict)
                        and isinstance(opponent.get("idx"), int)
                        and isinstance(opponent.get("pos"), list)
                        and len(opponent["pos"]) >= 2
                    }
                    if (
                        isinstance(predicted_holder, list)
                        and len(predicted_holder) >= 2
                        and predicted_opponents
                        and actual_opponents
                    ):
                        actual_holder_point = (
                            actual_holder[0],
                            actual_holder[1],
                        )
                        predicted_holder_point = (
                            float(predicted_holder[0]),
                            float(predicted_holder[1]),
                        )
                        predicted_pressure = _local_pressure(
                            predicted_holder_point, predicted_opponents.values()
                        )
                        controller_aligned_pressure = _local_pressure(
                            actual_holder_point, predicted_opponents.values()
                        )
                        actual_pressure = _local_pressure(
                            actual_holder_point, actual_opponents.values()
                        )
                        predicted_nearest_idx = min(
                            predicted_opponents,
                            key=lambda index: hypot(
                                predicted_opponents[index][0]
                                - predicted_holder_point[0],
                                predicted_opponents[index][1]
                                - predicted_holder_point[1],
                            ),
                        )
                        actual_nearest_idx = min(
                            actual_opponents,
                            key=lambda index: hypot(
                                actual_opponents[index][0] - actual_holder_point[0],
                                actual_opponents[index][1] - actual_holder_point[1],
                            ),
                        )
                        same_nearest = predicted_nearest_idx == actual_nearest_idx
                        source_context = on_ball_context_by_identity.get((
                            release.get("tick"),
                            release.get("team"),
                            release.get("passer_player"),
                        ), {})
                        source_opponent = next(
                            (
                                opponent
                                for opponent in source_context.get(
                                    "opponents_state", []
                                )
                                if isinstance(opponent, dict)
                                and opponent.get("idx") == actual_nearest_idx
                            ),
                            None,
                        )
                        case["dominant_pressure_geometry"] = {
                            "release_tick": release.get("tick"),
                            "release_to_control_seconds": terminal.get(
                                "release_to_control_seconds"
                            ),
                            "terminal_tick": source_event.get("tick"),
                            "first_held_tick": (
                                first_held_after_acquisition.get("tick")
                                if first_held_after_acquisition is not None
                                else None
                            ),
                            "option_duration_seconds": (
                                source_decision.get("chosen", {})
                                .get("value", {})
                                .get("components", {})
                                .get("option_duration_seconds")
                            ),
                            "predicted_holder_to_actual_holder_m": hypot(
                                actual_holder_point[0] - predicted_holder_point[0],
                                actual_holder_point[1] - predicted_holder_point[1],
                            ),
                            "predicted_pressure": predicted_pressure,
                            "controller_aligned_pressure": controller_aligned_pressure,
                            "actual_pressure": actual_pressure,
                            "controller_position_effect": (
                                controller_aligned_pressure - predicted_pressure
                            ),
                            "defender_position_effect": (
                                actual_pressure - controller_aligned_pressure
                            ),
                            "actual_minus_predicted": (
                                actual_pressure - predicted_pressure
                            ),
                            "predicted_nearest_idx": predicted_nearest_idx,
                            "actual_nearest_idx": actual_nearest_idx,
                            "same_nearest_defender": same_nearest,
                        }
                        release_tick = release.get("tick")
                        first_held_tick = (
                            first_held_after_acquisition.get("tick")
                            if first_held_after_acquisition is not None
                            else None
                        )
                        if isinstance(release_tick, int) and isinstance(
                            first_held_tick, int
                        ):
                            case["dominant_pressure_geometry"][
                                "release_to_first_held_ticks"
                            ] = first_held_tick - release_tick
                        if isinstance(source_opponent, dict):
                            source_pos = source_opponent.get("pos")
                            source_target = source_opponent.get(
                                "effective_movement_target"
                            )
                            predicted_pos = predicted_opponents.get(actual_nearest_idx)
                            actual_pos = actual_opponents.get(actual_nearest_idx)
                            if (
                                isinstance(source_pos, list)
                                and len(source_pos) >= 2
                                and isinstance(source_target, list)
                                and len(source_target) >= 2
                                and predicted_pos is not None
                                and actual_pos is not None
                            ):
                                source_point = (
                                    float(source_pos[0]),
                                    float(source_pos[1]),
                                )
                                target_point = (
                                    float(source_target[0]),
                                    float(source_target[1]),
                                )
                                case["dominant_pressure_geometry"].update({
                                    "source_to_predicted_defender_m": hypot(
                                        predicted_pos[0] - source_point[0],
                                        predicted_pos[1] - source_point[1],
                                    ),
                                    "source_to_actual_defender_m": hypot(
                                        actual_pos[0] - source_point[0],
                                        actual_pos[1] - source_point[1],
                                    ),
                                    "predicted_to_actual_defender_m": hypot(
                                        actual_pos[0] - predicted_pos[0],
                                        actual_pos[1] - predicted_pos[1],
                                    ),
                                    "source_target_to_actual_holder_m": hypot(
                                        target_point[0] - actual_holder_point[0],
                                        target_point[1] - actual_holder_point[1],
                                    ),
                                    "source_position_to_actual_holder_m": hypot(
                                        source_point[0] - actual_holder_point[0],
                                        source_point[1] - actual_holder_point[1],
                                    ),
                                    "source_movement_intent": source_opponent.get(
                                        "movement_intent"
                                    ),
                                    "source_task": source_opponent.get("task"),
                                })
                        counts[
                            f"acquisition_source={source}:dominant_nearest_same"
                            if same_nearest
                            else f"acquisition_source={source}:dominant_nearest_changed"
                        ] += 1
                        for field, value in case[
                            "dominant_pressure_geometry"
                        ].items():
                            if isinstance(value, (int, float)) and not isinstance(
                                value, bool
                            ):
                                metrics[
                                    f"acquisition_source={source}:dominant_{field}"
                                ].append(float(value))
                alternative_ledger = _pass_successor_support_alternative_ledger(
                    source_decision
                )
                if alternative_ledger:
                    case["release_pass_alternative_ledger"] = alternative_ledger
                    closer_count = alternative_ledger.get(
                        "closer_successor_candidate_count"
                    )
                    under_10m_count = alternative_ledger.get(
                        "under_10m_successor_candidate_count"
                    )
                    counts[
                        f"acquisition_source={source}:with_closer_successor_alternative"
                        if isinstance(closer_count, int) and closer_count > 0
                        else f"acquisition_source={source}:without_closer_successor_alternative"
                    ] += 1
                    counts[
                        f"acquisition_source={source}:with_under_10m_successor_alternative"
                        if isinstance(under_10m_count, int) and under_10m_count > 0
                        else f"acquisition_source={source}:without_under_10m_successor_alternative"
                    ] += 1
                    for profile in (
                        "best_closer_successor",
                        "best_under_10m_successor",
                    ):
                        payload = alternative_ledger.get(profile)
                        if not isinstance(payload, dict):
                            continue
                        for field, value in payload.items():
                            if isinstance(value, (int, float)):
                                metrics[
                                    f"acquisition_source={source}:{profile}:{field}"
                                ].append(float(value))
                projected_state = chosen_components.get(
                    "projected_retained_state", {}
                )
                successor_fields = {
                    "release_pass_distance_m": release.get("actual_distance_m"),
                    "release_receiver_nearest_opponent_distance_m": release.get("release_receiver_nearest_opponent_distance"),
                    "release_target_nearest_opponent_distance_m": release.get("release_target_nearest_opponent_distance"),
                    "predicted_retained_control_probability": release.get("predicted_retained_control_probability"),
                    "predicted_opposing_control_probability": release.get("predicted_opposing_control_probability"),
                    "predicted_successor_nearest_support_m": projected_state.get("nearest_outfield_teammate_distance"),
                    "predicted_successor_within_10m": projected_state.get("outfield_teammates_within_10m"),
                    "predicted_successor_pressure": (
                        1.0 - float(projected_state["pressure_relief"])
                        if isinstance(projected_state.get("pressure_relief"), (int, float))
                        else None
                    ),
                    "predicted_successor_pressure_stddev": projected_state.get("pressure_stddev"),
                    "predicted_successor_pressure_max": projected_state.get("pressure_max"),
                    "actual_receipt_nearest_support_m": terminal.get("actual_receipt_nearest_outfield_teammate_distance"),
                    "actual_receipt_within_10m": terminal.get("actual_receipt_outfield_teammates_within_10m"),
                    "actual_receipt_local_pressure": terminal.get("actual_receipt_local_pressure"),
                    "pass_turnover_cost": chosen_components.get("turnover_cost"),
                    "pass_after_value": chosen_components.get("after_value"),
                    "pass_current_value": chosen_components.get("current_value"),
                }
                for field, value in successor_fields.items():
                    if isinstance(value, (int, float)):
                        case[field] = float(value)
                        metrics[f"acquisition_source={source}:{field}"].append(
                            float(value)
                        )
                predicted_nearest = successor_fields[
                    "predicted_successor_nearest_support_m"
                ]
                actual_nearest = successor_fields[
                    "actual_receipt_nearest_support_m"
                ]
                if isinstance(predicted_nearest, (int, float)):
                    predicted_isolated = float(predicted_nearest) >= 10.0
                    case["predicted_successor_isolated"] = predicted_isolated
                    counts[
                        f"acquisition_source={source}:predicted_isolated"
                        if predicted_isolated
                        else f"acquisition_source={source}:predicted_supported"
                    ] += 1
                if isinstance(actual_nearest, (int, float)):
                    actual_isolated = float(actual_nearest) >= 10.0
                    case["actual_receipt_isolated"] = actual_isolated
                    counts[
                        f"acquisition_source={source}:actual_isolated"
                        if actual_isolated
                        else f"acquisition_source={source}:actual_supported"
                    ] += 1
                if isinstance(predicted_nearest, (int, float)) and isinstance(
                    actual_nearest, (int, float)
                ):
                    prediction_error = float(actual_nearest) - float(predicted_nearest)
                    case["actual_minus_predicted_successor_support_m"] = prediction_error
                    metrics[
                        f"acquisition_source={source}:actual_minus_predicted_successor_support_m"
                    ].append(prediction_error)
                predicted_pressure = successor_fields["predicted_successor_pressure"]
                actual_pressure = successor_fields["actual_receipt_local_pressure"]
                if isinstance(predicted_pressure, (int, float)) and isinstance(
                    actual_pressure, (int, float)
                ):
                    pressure_error = float(actual_pressure) - float(predicted_pressure)
                    case["actual_minus_predicted_successor_pressure"] = pressure_error
                    metrics[
                        f"acquisition_source={source}:actual_minus_predicted_successor_pressure"
                    ].append(pressure_error)
                first_pressure = (
                    first_held_after_acquisition.get("holder_local_pressure")
                    if first_held_after_acquisition is not None
                    else None
                )
                if isinstance(predicted_pressure, (int, float)) and isinstance(
                    first_pressure, (int, float)
                ):
                    first_error = float(first_pressure) - float(predicted_pressure)
                    case["first_held_minus_predicted_successor_pressure"] = first_error
                    metrics[
                        f"acquisition_source={source}:first_held_minus_predicted_successor_pressure"
                    ].append(first_error)
                if isinstance(first_pressure, (int, float)) and isinstance(
                    actual_pressure, (int, float)
                ):
                    pressure_growth = float(actual_pressure) - float(first_pressure)
                    case["gap_minus_first_held_pressure"] = pressure_growth
                    metrics[
                        f"acquisition_source={source}:gap_minus_first_held_pressure"
                    ].append(pressure_growth)
        if previous is not None and same_possession:
            opponent_delta = (
                row["nearest_opponent_distance_m"]
                - previous["nearest_opponent_distance_m"]
            )
            support_delta = (
                row["nearest_support_distance_m"]
                - previous["nearest_support_distance_m"]
            )
            holder_step = hypot(
                row["holder_pos"][0] - previous["holder_pos"][0],
                row["holder_pos"][1] - previous["holder_pos"][1],
            )
            case.update({
                "previous_tick": previous["tick"],
                "previous_holder_idx": previous["holder_idx"],
                "previous_nearest_opponent_distance_m": previous["nearest_opponent_distance_m"],
                "previous_nearest_support_distance_m": previous["nearest_support_distance_m"],
                "nearest_opponent_distance_delta_m": opponent_delta,
                "nearest_support_distance_delta_m": support_delta,
                "holder_step_m": holder_step,
                "nearest_supporter_identity_stable": (
                    previous["nearest_supporter_idx"] == row["nearest_supporter_idx"]
                ),
            })
            for field, value in (
                ("nearest_opponent_distance_delta_m", opponent_delta),
                ("nearest_support_distance_delta_m", support_delta),
                ("holder_step_m", holder_step),
            ):
                metrics[f"cause={cause}:{field}"].append(float(value))
        cases.append(case)

    return {
        "scope": (
            "first physical held tick in each holder episode where nearest opponent "
            "is under 2m and nearest outfield teammate is at least 10m away; causes "
            "are classified from the immediately preceding team state, while distance "
            "deltas remain continuous and no behavior is changed"
        ),
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
        "cases": cases,
    }


def _support_responsibility_identity_continuity_summary(
    trace_entries: Iterable[dict[str, Any]],
) -> dict[str, Any]:
    """Track whether the nearest support responsibility changes player.

    Physical-nearest identity and accepted-task target-nearest identity are
    intentionally reported separately.  Pressure bands are descriptive only.
    """
    episodes: dict[tuple[Any, str, int], list[dict[str, Any]]] = defaultdict(list)

    def point(value: Any) -> tuple[float, float] | None:
        if (
            isinstance(value, (list, tuple))
            and len(value) >= 2
            and isinstance(value[0], (int, float))
            and isinstance(value[1], (int, float))
        ):
            return float(value[0]), float(value[1])
        return None

    def pressure_band(distance_m: float) -> str:
        if distance_m < 2.0:
            return "0_2m"
        if distance_m < 4.0:
            return "2_4m"
        if distance_m < 6.0:
            return "4_6m"
        if distance_m < 10.0:
            return "6_10m"
        return "10m_plus"

    for entry in trace_entries:
        if entry.get("event") != "held_support_state":
            continue
        tick = entry.get("tick")
        possession_id = entry.get("possession_id")
        team = entry.get("team")
        holder_idx = entry.get("holder_idx")
        holder_pos = point(entry.get("holder_pos"))
        pressure_distance = entry.get("nearest_opponent_distance_m")
        if not (
            isinstance(tick, int)
            and possession_id is not None
            and team in {"home", "away"}
            and isinstance(holder_idx, int)
            and holder_pos is not None
            and isinstance(pressure_distance, (int, float))
        ):
            continue
        supporters: dict[int, dict[str, Any]] = {}
        for supporter in entry.get("supporters", []):
            if (
                not isinstance(supporter, dict)
                or supporter.get("is_goalkeeper") is True
                or not isinstance(supporter.get("idx"), int)
            ):
                continue
            pos = point(supporter.get("pos"))
            effective_target = point(supporter.get("effective_target"))
            if pos is None or effective_target is None:
                continue
            idx = int(supporter["idx"])
            supporters[idx] = {
                "idx": idx,
                "pos": pos,
                "effective_target": effective_target,
                "physical_distance_m": hypot(
                    pos[0] - holder_pos[0], pos[1] - holder_pos[1]
                ),
                "target_distance_m": hypot(
                    effective_target[0] - holder_pos[0],
                    effective_target[1] - holder_pos[1],
                ),
                "remaining_move_m": hypot(
                    effective_target[0] - pos[0], effective_target[1] - pos[1]
                ),
                "task_active": supporter.get("task_active") is True,
                "task_intent": str(supporter.get("task_intent") or "").lower(),
                "task_accepted_tick": supporter.get("task_accepted_tick"),
            }
        if not supporters:
            continue
        physical_nearest = min(
            supporters.values(), key=lambda supporter: supporter["physical_distance_m"]
        )
        eligible = [
            supporter
            for supporter in supporters.values()
            if supporter["task_active"]
            and supporter["task_intent"] in {"receive", "support"}
        ]
        responsibility = (
            min(eligible, key=lambda supporter: supporter["target_distance_m"])
            if eligible
            else None
        )
        episodes[(possession_id, str(team), holder_idx)].append({
            "tick": tick,
            "pressure_band": pressure_band(float(pressure_distance)),
            "physical_nearest": physical_nearest,
            "responsibility": responsibility,
            "supporters": supporters,
        })

    counts: dict[str, Counter[str]] = defaultdict(Counter)
    metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    for rows in episodes.values():
        rows.sort(key=lambda row: int(row["tick"]))
        for previous, current in zip(rows, rows[1:]):
            if int(current["tick"]) != int(previous["tick"]) + 1:
                continue
            for band in ("all", str(current["pressure_band"])):
                bucket_counts = counts[band]
                bucket_metrics = metrics[band]
                bucket_counts["consecutive_physical_ticks"] += 1
                previous_physical = previous["physical_nearest"]
                current_physical = current["physical_nearest"]
                bucket_counts[
                    "physical_nearest_identity_stable"
                    if previous_physical["idx"] == current_physical["idx"]
                    else "physical_nearest_identity_changed"
                ] += 1
                bucket_metrics["physical_nearest_distance_m"].append(
                    float(current_physical["physical_distance_m"])
                )
                responsibility = current["responsibility"]
                previous_responsibility = previous["responsibility"]
                if responsibility is None or previous_responsibility is None:
                    bucket_counts["missing_active_support_responsibility"] += 1
                    continue
                changed = responsibility["idx"] != previous_responsibility["idx"]
                bucket_counts[
                    "responsibility_identity_changed"
                    if changed
                    else "responsibility_identity_stable"
                ] += 1
                bucket_counts[
                    "responsibility_matches_physical_nearest"
                    if responsibility["idx"] == current_physical["idx"]
                    else "responsibility_differs_from_physical_nearest"
                ] += 1
                bucket_counts[
                    "responsibility_target_within_10m"
                    if responsibility["target_distance_m"] < 10.0
                    else "responsibility_target_outside_10m"
                ] += 1
                bucket_metrics["responsibility_target_distance_m"].append(
                    float(responsibility["target_distance_m"])
                )
                bucket_metrics["responsibility_player_distance_m"].append(
                    float(responsibility["physical_distance_m"])
                )
                bucket_metrics["responsibility_remaining_move_m"].append(
                    float(responsibility["remaining_move_m"])
                )
                if changed:
                    previous_owner_now = current["supporters"].get(
                        previous_responsibility["idx"]
                    )
                    if previous_owner_now is not None:
                        bucket_counts[
                            "changed_previous_owner_still_active"
                            if previous_owner_now["task_active"]
                            and previous_owner_now["task_intent"]
                            in {"receive", "support"}
                            else "changed_previous_owner_inactive"
                        ] += 1
                        bucket_metrics[
                            "changed_previous_owner_current_target_distance_m"
                        ].append(float(previous_owner_now["target_distance_m"]))
                        bucket_metrics[
                            "changed_new_minus_previous_target_distance_m"
                        ].append(
                            float(responsibility["target_distance_m"])
                            - float(previous_owner_now["target_distance_m"])
                        )
                        bucket_metrics[
                            "changed_new_minus_previous_player_distance_m"
                        ].append(
                            float(responsibility["physical_distance_m"])
                            - float(previous_owner_now["physical_distance_m"])
                        )
                        bucket_metrics[
                            "changed_new_minus_previous_remaining_move_m"
                        ].append(
                            float(responsibility["remaining_move_m"])
                            - float(previous_owner_now["remaining_move_m"])
                        )
                        bucket_counts[
                            "changed_new_owner_physically_closer"
                            if responsibility["physical_distance_m"]
                            < previous_owner_now["physical_distance_m"] - 1e-9
                            else "changed_previous_owner_physically_closer"
                            if previous_owner_now["physical_distance_m"]
                            < responsibility["physical_distance_m"] - 1e-9
                            else "changed_owner_physical_distance_tied"
                        ] += 1
                        bucket_counts[
                            "changed_new_owner_less_remaining_move"
                            if responsibility["remaining_move_m"]
                            < previous_owner_now["remaining_move_m"] - 1e-9
                            else "changed_previous_owner_less_remaining_move"
                            if previous_owner_now["remaining_move_m"]
                            < responsibility["remaining_move_m"] - 1e-9
                            else "changed_owner_remaining_move_tied"
                        ] += 1

    return {
        "scope": (
            "exact consecutive held physical ticks within the same possession and "
            "holder; compares the physical-nearest outfield teammate with the player "
            "whose accepted active Receive/Support effective target is nearest the "
            "holder. Pressure and 10m bands are reporting-only"
        ),
        "by_pressure": {
            band: {
                "counts": dict(sorted(counts[band].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(metrics[band].items())
                    if values
                },
            }
            for band in sorted(counts)
        },
    }


def _pass_successor_support_alternative_ledger(
    decision: dict[str, Any],
) -> dict[str, Any]:
    """Compare the selected pass with passes leading to denser successors."""
    chosen = decision.get("chosen", {})
    if chosen.get("action_type") != "pass":
        return {}

    def summarize(candidate: dict[str, Any]) -> dict[str, float] | None:
        if candidate.get("action_type") != "pass":
            return None
        value = candidate.get("value", {})
        components = value.get("components", {})
        projected = components.get("projected_retained_state", {})
        nearest = projected.get("nearest_outfield_teammate_distance")
        score = value.get("score")
        if not all(isinstance(sample, (int, float)) for sample in (nearest, score)):
            return None
        target = candidate.get("target")
        origin = decision.get("pos")
        distance_m = (
            hypot(
                float(target[0]) - float(origin[0]),
                float(target[1]) - float(origin[1]),
            )
            if isinstance(target, (list, tuple))
            and len(target) >= 2
            and isinstance(origin, (list, tuple))
            and len(origin) >= 2
            else None
        )
        result = {
            "score": float(score),
            "nearest_support_m": float(nearest),
        }
        result.update(_bellman_candidate_ledger(candidate, decision.get("pos")))
        if "target_distance_m" in result:
            distance_m = result["target_distance_m"]
        for field, sample in (
            ("distance_m", distance_m),
            ("retained_control_probability", components.get("outcome_transition", {}).get("retained_control_probability")),
            ("opposing_control_probability", components.get("outcome_transition", {}).get("opposing_control_probability")),
            ("temporal_discount", components.get("temporal_discount")),
            ("after_value", components.get("after_value")),
            ("pressure_relief", projected.get("pressure_relief")),
            ("pressure_stddev", projected.get("pressure_stddev")),
            ("pressure_max", projected.get("pressure_max")),
            ("control_residual", projected.get("control_residual")),
            ("outlet_access", projected.get("outlet_access")),
            ("structure", projected.get("structure")),
            ("continuation_value", projected.get("continuation_value")),
        ):
            if isinstance(sample, (int, float)):
                result[field] = float(sample)
        return result

    chosen_summary = summarize(chosen)
    if chosen_summary is None:
        return {}
    alternatives = [
        summary
        for candidate in decision.get("alternatives", [])
        if isinstance(candidate, dict)
        and (summary := summarize(candidate)) is not None
    ]
    closer = [
        candidate
        for candidate in alternatives
        if candidate["nearest_support_m"]
        < chosen_summary["nearest_support_m"] - 1e-12
    ]
    under_10m = [
        candidate for candidate in alternatives if candidate["nearest_support_m"] < 10.0
    ]
    best_closer = max(closer, key=lambda candidate: candidate["score"], default=None)
    best_under_10m = max(
        under_10m, key=lambda candidate: candidate["score"], default=None
    )
    baseline_best = max(
        [chosen_summary, *alternatives],
        key=lambda candidate: candidate["score"],
        default=None,
    )
    def delta_payload(candidate: dict[str, float] | None) -> dict[str, Any] | None:
        if candidate is None:
            return None
        return {
            **candidate,
            "score_minus_chosen": candidate["score"] - chosen_summary["score"],
            "nearest_support_delta_m": (
                candidate["nearest_support_m"]
                - chosen_summary["nearest_support_m"]
            ),
            "bellman_decomposition": _bellman_pair_decomposition(
                candidate, chosen_summary
            ),
        }

    return {
        "chosen": chosen_summary,
        "pass_candidate_count": 1 + len(alternatives),
        "closer_successor_candidate_count": len(closer),
        "under_10m_successor_candidate_count": len(under_10m),
        "best_closer_successor": delta_payload(best_closer),
        "best_under_10m_successor": delta_payload(best_under_10m),
        "baseline_best": delta_payload(baseline_best),
    }


def _holder_relative_support_geometry(
    holder_pos: list[float] | tuple[float, float],
    targets: Iterable[list[float] | tuple[float, float]],
) -> dict[str, float]:
    relative = sorted(
        (
            (
                hypot(
                    float(target[0]) - float(holder_pos[0]),
                    float(target[1]) - float(holder_pos[1]),
                ),
                float(target[0]) - float(holder_pos[0]),
                float(target[1]) - float(holder_pos[1]),
            )
            for target in targets
            if isinstance(target, (list, tuple)) and len(target) >= 2
        ),
        key=lambda point: point[0],
    )
    if not relative:
        return {}
    result = {"nearest_m": relative[0][0]}
    if len(relative) < 2 or relative[0][0] <= 1e-12 or relative[1][0] <= 1e-12:
        return result
    first, second = relative[:2]
    cosine = max(
        -1.0,
        min(1.0, (first[1] * second[1] + first[2] * second[2]) / (first[0] * second[0])),
    )
    angle = degrees(acos(cosine))
    result.update({
        "second_nearest_m": second[0],
        "nearest_pair_angle_deg": angle,
        "nearest_pair_angular_diversity": max(0.0, 1.0 - cosine * cosine),
        # Evaluation-only proxy retained for direct comparability with StatsBomb 360.
        "triangle_45_135_within15": float(
            second[0] < 15.0 and 45.0 <= angle <= 135.0
        ),
    })
    return result


def _rigid_translation_geometry(
    focus_pos: list[float] | tuple[float, float],
    focus_anchor: list[float] | tuple[float, float],
    support_anchors: Iterable[list[float] | tuple[float, float]],
) -> dict[str, float]:
    """Translate one shape rigidly so its reference anchor follows the focus.

    This is an evaluation-only upper bound for ball-relative unit translation.
    Every support anchor receives the same vector, so team width, depth, and all
    pairwise offsets are preserved exactly.  Any remaining focus-to-support gap
    therefore comes from the formation topology rather than translation lag.
    """
    if not (
        isinstance(focus_pos, (list, tuple))
        and len(focus_pos) >= 2
        and isinstance(focus_anchor, (list, tuple))
        and len(focus_anchor) >= 2
    ):
        return {}
    anchors = [
        (float(anchor[0]), float(anchor[1]))
        for anchor in support_anchors
        if isinstance(anchor, (list, tuple)) and len(anchor) >= 2
    ]
    if not anchors:
        return {}
    focus = (float(focus_pos[0]), float(focus_pos[1]))
    reference = (float(focus_anchor[0]), float(focus_anchor[1]))
    translation = (focus[0] - reference[0], focus[1] - reference[1])
    translated = [
        (anchor[0] + translation[0], anchor[1] + translation[1])
        for anchor in anchors
    ]
    baseline = _holder_relative_support_geometry(focus, anchors)
    shifted = _holder_relative_support_geometry(focus, translated)
    baseline_pairs = sorted(
        hypot(left[0] - right[0], left[1] - right[1])
        for index, left in enumerate(anchors)
        for right in anchors[index + 1 :]
    )
    translated_pairs = sorted(
        hypot(left[0] - right[0], left[1] - right[1])
        for index, left in enumerate(translated)
        for right in translated[index + 1 :]
    )
    result = {
        "translation_m": hypot(*translation),
        "formation_debt_m": hypot(*translation),
        "baseline_nearest_m": baseline.get("nearest_m", 0.0),
        "translated_nearest_m": shifted.get("nearest_m", 0.0),
        "baseline_width_m": max(point[1] for point in anchors)
        - min(point[1] for point in anchors),
        "translated_width_m": max(point[1] for point in translated)
        - min(point[1] for point in translated),
        "baseline_depth_m": max(point[0] for point in anchors)
        - min(point[0] for point in anchors),
        "translated_depth_m": max(point[0] for point in translated)
        - min(point[0] for point in translated),
        "maximum_pairwise_distance_drift_m": max(
            (abs(left - right) for left, right in zip(baseline_pairs, translated_pairs)),
            default=0.0,
        ),
    }
    for field in (
        "second_nearest_m",
        "nearest_pair_angle_deg",
        "nearest_pair_angular_diversity",
        "triangle_45_135_within15",
    ):
        if field in baseline:
            result[f"baseline_{field}"] = baseline[field]
        if field in shifted:
            result[f"translated_{field}"] = shifted[field]
    for radius in (10.0, 15.0, 20.0):
        result[f"baseline_within_{radius:.0f}m"] = float(sum(
            hypot(anchor[0] - focus[0], anchor[1] - focus[1]) < radius
            for anchor in anchors
        ))
        result[f"translated_within_{radius:.0f}m"] = float(sum(
            hypot(anchor[0] - focus[0], anchor[1] - focus[1]) < radius
            for anchor in translated
        ))
    return result


def _balanced_formation_graph_elasticity(
    points: Iterable[list[float] | tuple[float, float]],
    focus_pos: list[float] | tuple[float, float],
    demand: float,
) -> dict[str, Any]:
    """Deform a role-free formation graph while preserving its global frame.

    The graph is the Euclidean minimum spanning tree of the supplied anchors.
    The node nearest the ball is the root, and influence decays continuously by
    tree-path length over the median tree edge.  After the local deformation,
    an affine correction restores the original centroid, width, and depth.
    No role labels, radius gates, or coordinate bands participate.
    """
    anchors = [
        (float(point[0]), float(point[1]))
        for point in points
        if isinstance(point, (list, tuple)) and len(point) >= 2
    ]
    if not (
        anchors
        and isinstance(focus_pos, (list, tuple))
        and len(focus_pos) >= 2
    ):
        return {}
    focus = (float(focus_pos[0]), float(focus_pos[1]))
    demand = max(0.0, min(1.0, float(demand)))
    point_count = len(anchors)
    root = min(
        range(point_count),
        key=lambda index: hypot(
            anchors[index][0] - focus[0], anchors[index][1] - focus[1]
        ),
    )
    visited = {root}
    adjacency: list[list[tuple[int, float]]] = [[] for _ in anchors]
    edge_lengths: list[float] = []
    while len(visited) < point_count:
        left, right, edge = min(
            (
                (left, right, hypot(
                    anchors[left][0] - anchors[right][0],
                    anchors[left][1] - anchors[right][1],
                ))
                for left in visited
                for right in range(point_count)
                if right not in visited
            ),
            key=lambda row: (row[2], row[0], row[1]),
        )
        adjacency[left].append((right, edge))
        adjacency[right].append((left, edge))
        edge_lengths.append(edge)
        visited.add(right)
    topology_scale = median(edge_lengths) if edge_lengths else 1.0
    path_distances = [float("inf")] * point_count
    path_distances[root] = 0.0
    stack = [(root, -1)]
    while stack:
        node, parent = stack.pop()
        for neighbor, edge in adjacency[node]:
            if neighbor == parent:
                continue
            path_distances[neighbor] = path_distances[node] + edge
            stack.append((neighbor, node))
    weights = [
        exp(-path_distance / max(topology_scale, 1e-12))
        for path_distance in path_distances
    ]
    deformed = [
        (
            point[0] + (focus[0] - point[0]) * demand * weight,
            point[1] + (focus[1] - point[1]) * demand * weight,
        )
        for point, weight in zip(anchors, weights)
    ]
    original_centroid = (
        mean(point[0] for point in anchors),
        mean(point[1] for point in anchors),
    )
    deformed_centroid = (
        mean(point[0] for point in deformed),
        mean(point[1] for point in deformed),
    )
    centered = [
        (
            point[0] - deformed_centroid[0],
            point[1] - deformed_centroid[1],
        )
        for point in deformed
    ]
    original_depth = max(point[0] for point in anchors) - min(point[0] for point in anchors)
    original_width = max(point[1] for point in anchors) - min(point[1] for point in anchors)
    deformed_depth = max(point[0] for point in centered) - min(point[0] for point in centered)
    deformed_width = max(point[1] for point in centered) - min(point[1] for point in centered)
    depth_scale = original_depth / deformed_depth if deformed_depth > 1e-12 else 1.0
    width_scale = original_width / deformed_width if deformed_width > 1e-12 else 1.0
    balanced = [
        (
            original_centroid[0] + point[0] * depth_scale,
            original_centroid[1] + point[1] * width_scale,
        )
        for point in centered
    ]
    geometry = _holder_relative_support_geometry(focus, balanced)
    pair_distances = sorted(
        hypot(left[0] - right[0], left[1] - right[1])
        for index, left in enumerate(balanced)
        for right in balanced[index + 1 :]
    )
    displacements = [
        hypot(before[0] - after[0], before[1] - after[1])
        for before, after in zip(anchors, balanced)
    ]
    balanced_centroid = (
        mean(point[0] for point in balanced),
        mean(point[1] for point in balanced),
    )
    return {
        "points": balanced,
        "root_index": root,
        "demand": demand,
        "topology_scale_m": topology_scale,
        "root_baseline_distance_m": hypot(
            anchors[root][0] - focus[0], anchors[root][1] - focus[1]
        ),
        "nearest_m": geometry.get("nearest_m", 0.0),
        "second_nearest_m": geometry.get("second_nearest_m", 0.0),
        "nearest_pair_angle_deg": geometry.get("nearest_pair_angle_deg", 0.0),
        "nearest_pair_angular_diversity": geometry.get(
            "nearest_pair_angular_diversity", 0.0
        ),
        "triangle_45_135_within15": geometry.get(
            "triangle_45_135_within15", 0.0
        ),
        "mean_displacement_m": mean(displacements),
        "maximum_displacement_m": max(displacements),
        "minimum_pair_separation_m": min(pair_distances, default=0.0),
        "centroid_drift_m": hypot(
            balanced_centroid[0] - original_centroid[0],
            balanced_centroid[1] - original_centroid[1],
        ),
        "depth_drift_m": (
            max(point[0] for point in balanced)
            - min(point[0] for point in balanced)
            - original_depth
        ),
        "width_drift_m": (
            max(point[1] for point in balanced)
            - min(point[1] for point in balanced)
            - original_width
        ),
        "mean_propagation_weight": mean(weights),
    }


def _targeted_formation_graph_elasticity(
    points: Iterable[list[float] | tuple[float, float]],
    focus_pos: list[float] | tuple[float, float],
    target_nearest_m: float,
) -> dict[str, Any]:
    """Return the closest target match along the continuous graph deformation."""
    points = list(points)
    candidates = [
        _balanced_formation_graph_elasticity(points, focus_pos, step / 100.0)
        for step in range(101)
    ]
    candidates = [candidate for candidate in candidates if candidate]
    if not candidates:
        return {}
    selected = min(
        candidates,
        key=lambda candidate: (
            abs(float(candidate["nearest_m"]) - float(target_nearest_m)),
            float(candidate["demand"]),
        ),
    )
    return {
        **selected,
        "target_nearest_m": float(target_nearest_m),
        "target_error_m": float(selected["nearest_m"]) - float(target_nearest_m),
    }


def _continuous_coordination_optima(
    holder_pos: list[float] | tuple[float, float],
    players_pool: dict[Any, dict[str, Any]],
    claim_conflict_reason: Any,
    fixed_connections: Iterable[dict[str, Any]] = (),
) -> dict[str, Any]:
    """Find exact zero-conflict optima under local and connection objectives."""
    players = []
    baseline_assignment = []
    for player_idx, player in players_pool.items():
        candidates = [
            candidate
            for candidate in player.get("candidates", [])
            if isinstance(candidate, dict)
        ]
        if not candidates:
            continue
        assigned = next(
            (
                candidate
                for candidate in candidates
                if candidate.get("candidate_index") == player.get("assigned_index")
            ),
            max(candidates, key=lambda candidate: float(candidate.get("value", 0.0))),
        )
        players.append((player_idx, candidates))
        baseline_assignment.append(assigned)
    if not players:
        return {}

    # Constrained players first makes the exact branch-and-bound substantially tighter.
    players.sort(key=lambda item: (len(item[1]), item[0]))
    maxima = []
    for _, candidates in players:
        enriched = []
        for candidate in candidates:
            outlet_access = candidate.get("projected_outlet_access")
            local_value = max(float(candidate.get("value", 0.0) or 0.0), 0.0)
            connection_weight = (
                max(0.0, min(1.0, float(outlet_access)))
                if isinstance(outlet_access, (int, float))
                else 0.0
            )
            enriched.append((candidate, local_value, connection_weight))
        enriched.sort(key=lambda item: (item[1] + 0.5 * item[2], item[1]), reverse=True)
        maxima.append((
            max(item[1] for item in enriched),
            max(item[2] for item in enriched),
        ))
        candidates[:] = [item[0] for item in enriched]

    remaining_local = [0.0] * (len(players) + 1)
    remaining_weight = [0.0] * (len(players) + 1)
    for index in range(len(players) - 1, -1, -1):
        remaining_local[index] = remaining_local[index + 1] + maxima[index][0]
        remaining_weight[index] = remaining_weight[index + 1] + maxima[index][1]

    fixed_connections = list(fixed_connections)
    fixed_connection = _continuous_connection_redundancy(
        holder_pos, fixed_connections
    )
    baseline_local = sum(float(candidate.get("value", 0.0) or 0.0) for candidate in baseline_assignment)
    baseline_connection = _continuous_connection_redundancy(
        holder_pos, [*fixed_connections, *baseline_assignment]
    )
    baseline_closure = _continuous_triangle_closure(
        holder_pos, [*fixed_connections, *baseline_assignment]
    )
    baseline_conflicts = sum(
        claim_conflict_reason(left, right) != "clear"
        for left_index, left in enumerate(baseline_assignment)
        for right in baseline_assignment[left_index + 1 :]
    )

    def search(require_noninferior: bool, objective: str) -> tuple[dict[str, Any] | None, int]:
        baseline_objective = (
            baseline_local
            if objective == "local"
            else baseline_connection["connection_redundancy"]
            if objective == "redundancy"
            else baseline_closure
            if objective == "closure"
            else baseline_local + baseline_connection["connection_redundancy"]
        )
        best: dict[str, Any] | None = (
            {
                "objective": baseline_objective,
                "local_value": baseline_local,
                **baseline_connection,
                "triangle_closure": baseline_closure,
                "assignment": list(baseline_assignment),
            }
            if baseline_conflicts == 0
            else None
        )
        visited = 0
        selected: list[dict[str, Any]] = []

        def visit(player_offset: int, local_total: float, connection_weight: float) -> None:
            nonlocal best, visited
            visited += 1
            local_upper = local_total + remaining_local[player_offset]
            if require_noninferior and local_upper + 1e-12 < baseline_local:
                return
            if objective == "local":
                objective_upper = local_upper
            elif objective == "redundancy":
                objective_upper = 0.5 * (
                    connection_weight + remaining_weight[player_offset]
                )
            elif objective == "closure":
                total_weight_upper = connection_weight + remaining_weight[player_offset]
                connection_slots = len(fixed_connections) + len(players)
                objective_upper = (
                    0.5 * total_weight_upper * max(connection_slots - 1, 1)
                )
            else:
                # For a PSD 2-D matrix, 2*det(M)/trace(M) <= trace(M)/2.
                objective_upper = local_upper + 0.5 * (
                    connection_weight + remaining_weight[player_offset]
                )
            if best is not None and objective_upper <= best["objective"] + 1e-12:
                return
            if player_offset == len(players):
                if require_noninferior and local_total + 1e-12 < baseline_local:
                    return
                connection = _continuous_connection_redundancy(
                    holder_pos, [*fixed_connections, *selected]
                )
                triangle_closure = _continuous_triangle_closure(
                    holder_pos, [*fixed_connections, *selected]
                )
                objective_value = (
                    local_total
                    if objective == "local"
                    else connection["connection_redundancy"]
                    if objective == "redundancy"
                    else triangle_closure
                    if objective == "closure"
                    else local_total + connection["connection_redundancy"]
                )
                if best is None or objective_value > best["objective"] + 1e-12:
                    best = {
                        "objective": objective_value,
                        "local_value": local_total,
                        **connection,
                        "triangle_closure": triangle_closure,
                        "assignment": list(selected),
                    }
                return
            _, candidates = players[player_offset]
            for candidate in candidates:
                if any(
                    claim_conflict_reason(candidate, committed) != "clear"
                    for committed in selected
                ):
                    continue
                selected.append(candidate)
                outlet_access = candidate.get("projected_outlet_access")
                local_value = max(float(candidate.get("value", 0.0) or 0.0), 0.0)
                added_weight = (
                    max(0.0, min(1.0, float(outlet_access)))
                    if isinstance(outlet_access, (int, float))
                    else 0.0
                )
                visit(
                    player_offset + 1,
                    local_total + local_value,
                    connection_weight + added_weight,
                )
                selected.pop()

        visit(0, 0.0, fixed_connection["connection_weight"])
        return best, visited

    best_local, local_nodes = search(False, "local")
    best_combined, combined_nodes = search(False, "combined")
    best_noninferior, noninferior_nodes = search(True, "combined")
    best_redundancy_noninferior, redundancy_noninferior_nodes = search(
        True, "redundancy"
    )
    best_closure, closure_nodes = search(False, "closure")
    best_closure_noninferior, closure_noninferior_nodes = search(True, "closure")

    def compact(result: dict[str, Any] | None) -> dict[str, Any]:
        if result is None:
            return {}
        assignment = result.pop("assignment")
        return {
            **result,
            "targets": [
                candidate["target"] for candidate in [*fixed_connections, *assignment]
            ],
            "coordination_targets": [candidate["target"] for candidate in assignment],
            "candidate_indices": [candidate.get("candidate_index") for candidate in assignment],
            "player_indices": [candidate.get("player_idx") for candidate in assignment],
        }

    return {
        "baseline": {
            "objective": baseline_local + baseline_connection["connection_redundancy"],
            "local_value": baseline_local,
            **baseline_connection,
            "triangle_closure": baseline_closure,
            "targets": [
                candidate["target"]
                for candidate in [*fixed_connections, *baseline_assignment]
            ],
            "coordination_targets": [
                candidate["target"] for candidate in baseline_assignment
            ],
            "candidate_indices": [candidate.get("candidate_index") for candidate in baseline_assignment],
            "player_indices": [candidate.get("player_idx") for candidate in baseline_assignment],
            "reconstructed_conflicts": baseline_conflicts,
        },
        "best_local": compact(best_local),
        "best_combined": compact(best_combined),
        "best_combined_local_noninferior": compact(best_noninferior),
        "best_redundancy_local_noninferior": compact(
            best_redundancy_noninferior
        ),
        "best_closure": compact(best_closure),
        "best_closure_local_noninferior": compact(best_closure_noninferior),
        "search_nodes": {
            "best_local": local_nodes,
            "best_combined": combined_nodes,
            "best_combined_local_noninferior": noninferior_nodes,
            "best_redundancy_local_noninferior": redundancy_noninferior_nodes,
            "best_closure": closure_nodes,
            "best_closure_local_noninferior": closure_noninferior_nodes,
        },
    }


def _diagnostic_spatial_claim(
    origin: list[float] | tuple[float, float],
    target: list[float] | tuple[float, float],
    goal_type: str,
    attacking_right: bool,
) -> dict[str, Any]:
    intent = (
        "receive"
        if "arrival" in goal_type or "far_post" in goal_type
        else "carry"
        if "carry" in goal_type or "byline" in goal_type
        else "control"
        if goal_type in {"recycle", "switch_play", "protect_ball", "hold_for_opportunity"}
        else "support"
    )
    base_radius, base_half_width = {
        "receive": (4.4, 2.1),
        "support": (4.2, 2.0),
        "carry": (3.4, 1.7),
        "control": (3.2, 1.6),
    }[intent]
    origin_xy = (float(origin[0]), float(origin[1]))
    target_xy = (float(target[0]), float(target[1]))
    target_distance = hypot(target_xy[0] - origin_xy[0], target_xy[1] - origin_xy[1])
    forward_direction = 1.0 if attacking_right else -1.0

    def spatial_band(value: float) -> int:
        return -2 if value < -14.0 else -1 if value < -4.0 else 0 if value <= 6.0 else 1 if value <= 18.0 else 2

    return {
        "active": True,
        "target": target_xy,
        "origin": origin_xy,
        "occupancy_radius": base_radius + min(0.035 * target_distance, 0.9),
        "corridor_half_width": base_half_width + min(0.020 * target_distance, 0.5),
        "depth_band": spatial_band(
            (target_xy[0] - origin_xy[0]) * forward_direction
        ),
        "width_band": spatial_band(target_xy[1] - origin_xy[1]),
    }


def _diagnostic_spatial_claim_conflict(
    left: dict[str, Any], right: dict[str, Any]
) -> bool:
    if not left.get("active") or not right.get("active"):
        return False
    left_target = left.get("target")
    right_target = right.get("target")
    if not (
        isinstance(left_target, (list, tuple))
        and len(left_target) >= 2
        and isinstance(right_target, (list, tuple))
        and len(right_target) >= 2
    ):
        return False
    target_distance = hypot(
        float(left_target[0]) - float(right_target[0]),
        float(left_target[1]) - float(right_target[1]),
    )
    occupied_distance = float(left.get("occupancy_radius", 0.0) or 0.0) + float(
        right.get("occupancy_radius", 0.0) or 0.0
    )
    if target_distance < occupied_distance:
        return True
    if (
        left.get("depth_band") != right.get("depth_band")
        or left.get("width_band") != right.get("width_band")
    ):
        return False
    left_origin = left.get("origin")
    right_origin = right.get("origin")
    if not (
        isinstance(left_origin, (list, tuple))
        and len(left_origin) >= 2
        and isinstance(right_origin, (list, tuple))
        and len(right_origin) >= 2
    ):
        return False
    left_route = (
        float(left_target[0]) - float(left_origin[0]),
        float(left_target[1]) - float(left_origin[1]),
    )
    right_route = (
        float(right_target[0]) - float(right_origin[0]),
        float(right_target[1]) - float(right_origin[1]),
    )
    left_length = hypot(*left_route)
    right_length = hypot(*right_route)
    if left_length <= 1e-6 or right_length <= 1e-6:
        return target_distance < occupied_distance * 1.4
    route_alignment = (
        left_route[0] * right_route[0] + left_route[1] * right_route[1]
    ) / (left_length * right_length)
    corridor_width = float(left.get("corridor_half_width", 0.0) or 0.0) + float(
        right.get("corridor_half_width", 0.0) or 0.0
    )
    return (
        route_alignment > 0.90
        and target_distance < occupied_distance * 1.65 + corridor_width
    )


def _bellman_candidate_ledger(
    candidate: dict[str, Any],
    origin: list[float] | tuple[float, float] | None,
) -> dict[str, float]:
    """Return comparable Bellman fields already carried by a valued action."""
    value = candidate.get("value", {})
    components = value.get("components", {})
    transition = components.get("outcome_transition") or {}
    delivery_provenance = transition.get("delivery_provenance") or {}
    execution = components.get("execution_transition") or {}
    retained_state = components.get("projected_retained_state") or {}
    ledger: dict[str, float] = {}

    for field, sample in (
        ("score", value.get("score")),
        ("candidate_score", value.get("candidate_score")),
        ("success_probability", value.get("success_prob")),
        ("current_value", components.get("current_value")),
        ("effective_current_value", components.get("effective_current_value")),
        ("after_value", components.get("after_value")),
        ("candidate_value_delta", components.get("delta")),
        ("candidate_value_effective_delta", components.get("effective_delta")),
        ("option_return", components.get("option_return")),
        ("local_shaping", components.get("local_shaping")),
        ("temporal_discount", components.get("temporal_discount")),
        ("option_duration_seconds", components.get("option_duration_seconds")),
        ("turnover_cost", components.get("turnover_cost")),
        ("risk_cost", components.get("risk_cost")),
        ("retained_probability", transition.get("retained_control_probability")),
        ("direct_retained_probability", transition.get("direct_retained_probability")),
        ("successful_delivery_retained_probability", delivery_provenance.get("successful_retained_probability")),
        ("successful_delivery_direct_retained_probability", delivery_provenance.get("successful_direct_retained_probability")),
        ("failed_delivery_retained_probability", delivery_provenance.get("failed_retained_probability")),
        ("failed_delivery_direct_retained_probability", delivery_provenance.get("failed_direct_retained_probability")),
        ("retained_value", transition.get("retained_control_value")),
        ("opposing_probability", transition.get("opposing_control_probability")),
        ("opposing_value", transition.get("opposing_control_value")),
        ("unresolved_probability", transition.get("unresolved_probability")),
        ("goal_probability", transition.get("goal_probability")),
        ("release_probability", execution.get("release_probability")),
        ("technical_delivery_probability", execution.get("technical_delivery_probability")),
        ("receiver_pressure", components.get("receiver_pressure")),
        ("receiver_arrival", components.get("receiver_arrival")),
        ("target_occupation_risk", components.get("target_occupation_risk")),
        ("base_accuracy", components.get("base_accuracy")),
        ("lane_risk", components.get("lane_risk")),
        ("turnover_consequence", components.get("turnover_consequence")),
        ("defender_first_risk", components.get("defender_first_risk")),
        ("retained_direct_xg", retained_state.get("direct_xg")),
        ("retained_territory", retained_state.get("territory")),
        ("retained_pressure_relief", retained_state.get("pressure_relief")),
        ("retained_outlet_access", retained_state.get("outlet_access")),
        ("retained_support_width", retained_state.get("support_width")),
        ("retained_structure", retained_state.get("structure")),
        ("retained_creation_access", retained_state.get("creation_access")),
        ("retained_one_link_xg", retained_state.get("one_link_xg")),
        ("retained_continuation_xg", retained_state.get("continuation_xg")),
        ("retained_control_residual", retained_state.get("control_residual")),
        ("retained_continuation_value", retained_state.get("continuation_value")),
        (
            "retained_link_duration_continuation_value",
            retained_state.get("link_duration_continuation_value"),
        ),
        (
            "retained_link_duration_continuation_value_delta",
            retained_state.get("link_duration_continuation_value_delta"),
        ),
        (
            "retained_network_time_budget_seconds",
            retained_state.get("network_time_budget_seconds"),
        ),
        (
            "retained_time_budget_continuation_value",
            retained_state.get("time_budget_continuation_value"),
        ),
        (
            "retained_time_budget_continuation_value_delta",
            retained_state.get("time_budget_continuation_value_delta"),
        ),
        (
            "retained_symmetric_goalkeeper_network_continuation_value",
            retained_state.get(
                "symmetric_goalkeeper_network_continuation_value"
            ),
        ),
        (
            "retained_symmetric_goalkeeper_network_continuation_value_delta",
            retained_state.get(
                "symmetric_goalkeeper_network_continuation_value_delta"
            ),
        ),
        ("retained_control_readiness", retained_state.get("control_readiness")),
    ):
        if isinstance(sample, (int, float)):
            ledger[field] = float(sample)

    target = candidate.get("target")
    if (
        isinstance(origin, (list, tuple))
        and len(origin) >= 2
        and isinstance(target, list)
        and len(target) >= 2
    ):
        ledger["target_distance_m"] = hypot(
            float(target[0]) - float(origin[0]),
            float(target[1]) - float(origin[1]),
        )

    retained_probability = ledger.get("retained_probability")
    retained_value = ledger.get("retained_value")
    goal_probability = ledger.get("goal_probability")
    if retained_probability is not None and retained_value is not None:
        ledger["continuation_return"] = retained_probability * retained_value
    if goal_probability is not None:
        ledger["terminal_return"] = goal_probability
    if all(
        field in ledger
        for field in ("continuation_return", "terminal_return", "turnover_cost")
    ):
        ledger["pre_discount_net_return"] = (
            ledger["continuation_return"]
            + ledger["terminal_return"]
            - ledger["turnover_cost"]
        )
    if all(
        field in ledger
        for field in ("pre_discount_net_return", "temporal_discount")
    ):
        ledger["reconstructed_option_return"] = (
            ledger["pre_discount_net_return"] * ledger["temporal_discount"]
        )
        if "option_return" in ledger:
            ledger["option_return_reconstruction_error"] = (
                ledger["option_return"] - ledger["reconstructed_option_return"]
            )
    if all(field in ledger for field in ("score", "option_return", "local_shaping")):
        ledger["score_reconstruction_error"] = (
            ledger["score"] - ledger["option_return"] - ledger["local_shaping"]
        )
    if all(
        field in ledger
        for field in (
            "retained_probability",
            "retained_link_duration_continuation_value",
            "terminal_return",
            "turnover_cost",
            "temporal_discount",
            "local_shaping",
            "score",
        )
    ):
        link_duration_continuation_return = (
            ledger["retained_probability"]
            * ledger["retained_link_duration_continuation_value"]
        )
        link_duration_pre_discount_return = (
            link_duration_continuation_return
            + ledger["terminal_return"]
            - ledger["turnover_cost"]
        )
        link_duration_option_return = (
            ledger["temporal_discount"] * link_duration_pre_discount_return
        )
        link_duration_score = (
            link_duration_option_return + ledger["local_shaping"]
        )
        ledger.update({
            "link_duration_cf_continuation_return": link_duration_continuation_return,
            "link_duration_cf_pre_discount_return": link_duration_pre_discount_return,
            "link_duration_cf_option_return": link_duration_option_return,
            "link_duration_cf_score": link_duration_score,
            "link_duration_cf_score_delta": link_duration_score - ledger["score"],
        })
    if all(
        field in ledger
        for field in (
            "retained_probability",
            "retained_time_budget_continuation_value",
            "terminal_return",
            "turnover_cost",
            "temporal_discount",
            "local_shaping",
            "score",
        )
    ):
        time_budget_continuation_return = (
            ledger["retained_probability"]
            * ledger["retained_time_budget_continuation_value"]
        )
        time_budget_pre_discount_return = (
            time_budget_continuation_return
            + ledger["terminal_return"]
            - ledger["turnover_cost"]
        )
        time_budget_option_return = (
            ledger["temporal_discount"] * time_budget_pre_discount_return
        )
        time_budget_score = time_budget_option_return + ledger["local_shaping"]
        ledger.update({
            "time_budget_cf_continuation_return": time_budget_continuation_return,
            "time_budget_cf_pre_discount_return": time_budget_pre_discount_return,
            "time_budget_cf_option_return": time_budget_option_return,
            "time_budget_cf_score": time_budget_score,
            "time_budget_cf_score_delta": time_budget_score - ledger["score"],
        })
    if all(
        field in ledger
        for field in (
            "retained_probability",
            "retained_symmetric_goalkeeper_network_continuation_value",
            "terminal_return",
            "turnover_cost",
            "temporal_discount",
            "local_shaping",
            "score",
        )
    ):
        symmetric_continuation_return = (
            ledger["retained_probability"]
            * ledger[
                "retained_symmetric_goalkeeper_network_continuation_value"
            ]
        )
        symmetric_pre_discount_return = (
            symmetric_continuation_return
            + ledger["terminal_return"]
            - ledger["turnover_cost"]
        )
        symmetric_option_return = (
            ledger["temporal_discount"] * symmetric_pre_discount_return
        )
        symmetric_score = symmetric_option_return + ledger["local_shaping"]
        ledger.update({
            "symmetric_goalkeeper_network_cf_continuation_return":
                symmetric_continuation_return,
            "symmetric_goalkeeper_network_cf_pre_discount_return":
                symmetric_pre_discount_return,
            "symmetric_goalkeeper_network_cf_option_return":
                symmetric_option_return,
            "symmetric_goalkeeper_network_cf_score": symmetric_score,
            "symmetric_goalkeeper_network_cf_score_delta":
                symmetric_score - ledger["score"],
        })
    if "current_value" in ledger:
        if "score" in ledger:
            ledger["score_advantage_over_current"] = (
                ledger["score"] - ledger["current_value"]
            )
        if "option_return" in ledger:
            ledger["option_advantage_over_current"] = (
                ledger["option_return"] - ledger["current_value"]
            )
        if "after_value" in ledger:
            ledger["after_value_minus_current"] = (
                ledger["after_value"] - ledger["current_value"]
            )
    if "effective_current_value" in ledger and "after_value" in ledger:
        ledger["after_value_minus_effective_current"] = (
            ledger["after_value"] - ledger["effective_current_value"]
        )
    if all(
        field in ledger
        for field in (
            "retained_probability",
            "retained_direct_xg",
            "retained_control_residual",
            "retained_continuation_value",
            "retained_control_readiness",
            "terminal_return",
            "turnover_cost",
            "temporal_discount",
            "local_shaping",
            "score",
        )
    ):
        readiness_factor = 0.24 + 0.76 * ledger["retained_control_readiness"]
        priced_source_terminal = ledger["retained_direct_xg"] + (
            1.0 - ledger["retained_direct_xg"]
        ) * ledger["retained_control_residual"] * readiness_factor
        unpriced_source_terminal = ledger["retained_direct_xg"] + (
            1.0 - ledger["retained_direct_xg"]
        ) * ledger["retained_control_residual"]
        counterfactual_retained_value = max(
            ledger["retained_continuation_value"], unpriced_source_terminal
        )
        counterfactual_continuation_return = (
            ledger["retained_probability"] * counterfactual_retained_value
        )
        counterfactual_pre_discount_return = (
            counterfactual_continuation_return
            + ledger["terminal_return"]
            - ledger["turnover_cost"]
        )
        counterfactual_option_return = (
            ledger["temporal_discount"] * counterfactual_pre_discount_return
        )
        counterfactual_score = (
            counterfactual_option_return + ledger["local_shaping"]
        )
        for field, sample in (
            ("ungated_residual_cf_readiness_factor", readiness_factor),
            ("ungated_residual_cf_priced_source_terminal", priced_source_terminal),
            ("ungated_residual_cf_unpriced_source_terminal", unpriced_source_terminal),
            ("ungated_residual_cf_retained_value", counterfactual_retained_value),
            ("ungated_residual_cf_continuation_return", counterfactual_continuation_return),
            ("ungated_residual_cf_option_return", counterfactual_option_return),
            ("ungated_residual_cf_score", counterfactual_score),
            ("ungated_residual_cf_score_uplift", counterfactual_score - ledger["score"]),
        ):
            ledger[field] = sample
    return ledger


def _bellman_pair_decomposition(
    candidate: dict[str, float], chosen: dict[str, float]
) -> dict[str, float]:
    """Decompose candidate-minus-chosen without introducing value bonuses."""
    result: dict[str, float] = {}
    if all(
        field in candidate and field in chosen
        for field in ("retained_probability", "retained_value")
    ):
        probability_effect = (
            candidate["retained_probability"] - chosen["retained_probability"]
        ) * chosen["retained_value"]
        value_effect = candidate["retained_probability"] * (
            candidate["retained_value"] - chosen["retained_value"]
        )
        result["continuation_probability_effect"] = probability_effect
        result["continuation_state_value_effect"] = value_effect
        if "continuation_return" in candidate and "continuation_return" in chosen:
            result["continuation_decomposition_error"] = (
                candidate["continuation_return"]
                - chosen["continuation_return"]
                - probability_effect
                - value_effect
            )
    if all(
        field in candidate and field in chosen
        for field in (
            "continuation_return",
            "terminal_return",
            "turnover_cost",
            "pre_discount_net_return",
        )
    ):
        result["pre_discount_continuation_effect"] = (
            candidate["continuation_return"] - chosen["continuation_return"]
        )
        result["pre_discount_terminal_effect"] = (
            candidate["terminal_return"] - chosen["terminal_return"]
        )
        result["pre_discount_turnover_effect"] = (
            chosen["turnover_cost"] - candidate["turnover_cost"]
        )
        result["pre_discount_decomposition_error"] = (
            candidate["pre_discount_net_return"]
            - chosen["pre_discount_net_return"]
            - result["pre_discount_continuation_effect"]
            - result["pre_discount_terminal_effect"]
            - result["pre_discount_turnover_effect"]
        )
    if all(
        field in candidate and field in chosen
        for field in (
            "temporal_discount",
            "pre_discount_net_return",
            "option_return",
        )
    ):
        discount_effect = (
            candidate["temporal_discount"] - chosen["temporal_discount"]
        ) * chosen["pre_discount_net_return"]
        net_return_effect = candidate["temporal_discount"] * (
            candidate["pre_discount_net_return"]
            - chosen["pre_discount_net_return"]
        )
        result["temporal_discount_effect"] = discount_effect
        result["pre_discount_net_return_effect"] = net_return_effect
        result["option_return_decomposition_error"] = (
            candidate["option_return"]
            - chosen["option_return"]
            - discount_effect
            - net_return_effect
        )
    if all(
        field in candidate and field in chosen
        for field in ("score", "option_return", "local_shaping")
    ):
        result["score_option_return_effect"] = (
            candidate["option_return"] - chosen["option_return"]
        )
        result["score_local_shaping_effect"] = (
            candidate["local_shaping"] - chosen["local_shaping"]
        )
        result["score_decomposition_error"] = (
            candidate["score"]
            - chosen["score"]
            - result["score_option_return_effect"]
            - result["score_local_shaping_effect"]
        )
    return result


def _team_plan_pass_policy_decomposition(
    candidate: dict[str, Any],
    origin: list[float] | tuple[float, float] | None,
    *,
    attacking_right: bool,
    signals: dict[str, Any],
    success_probability_override: float | None = None,
    continuation_probability_override: float | None = None,
    pitch_length: float = 105.0,
    pitch_width: float = 68.0,
) -> dict[str, float] | None:
    """Rebuild production team-plan Pass shaping without changing selection."""
    target = candidate.get("target")
    value = candidate.get("value", {})
    components = value.get("components", {})
    required = {
        "success_probability": value.get("success_prob"),
        "outcome_value": components.get("option_return"),
        "production_policy_value": components.get("local_shaping"),
        "current_control_value": components.get("current_value"),
        "risk": components.get("lane_risk"),
        "forward_bias": signals.get("forward_bias"),
        "recycle_bias": signals.get("recycle_bias"),
        "switch_bias": signals.get("switch_bias"),
        "risk_budget": signals.get("risk_budget"),
    }
    if (
        candidate.get("action_type") != "pass"
        or not isinstance(origin, (list, tuple))
        or len(origin) < 2
        or not isinstance(target, list)
        or len(target) < 2
        or not all(isinstance(sample, (int, float)) for sample in required.values())
    ):
        return None

    samples = {field: float(sample) for field, sample in required.items()}
    length = max(float(pitch_length), 1.0)
    width = max(float(pitch_width), 1.0)
    half_width = width / 2.0
    forward_direction = 1.0 if attacking_right else -1.0
    signed_progress = max(
        -1.0,
        min(
            1.0,
            (float(target[0]) - float(origin[0])) * forward_direction / length,
        ),
    )
    forward_progress = _smoothstep(-0.02, 0.16, signed_progress)
    backward_progress = _smoothstep(-0.02, 0.16, -signed_progress)
    lateral_change = max(
        0.0,
        min(1.0, abs(float(target[1]) - float(origin[1])) / half_width),
    )
    origin_side = (float(origin[1]) - half_width) / half_width
    target_side = (float(target[1]) - half_width) / half_width
    cross_field = max(0.0, min(1.0, -origin_side * target_side))
    success_probability = max(
        0.0,
        min(
            1.0,
            samples["success_probability"]
            if success_probability_override is None
            else float(success_probability_override),
        ),
    )
    continuation_probability = max(
        0.0,
        min(
            1.0,
            samples["success_probability"]
            if continuation_probability_override is None
            else float(continuation_probability_override),
        ),
    )
    # Production currently supplies success_prob for both arguments. Read-only
    # callers may separate intended execution from team-control continuation.
    retention = success_probability * continuation_probability
    recycle_value = backward_progress * retention
    switch_value = lateral_change * cross_field * retention
    risk = max(0.0, min(1.0, samples["risk"]))
    retention_base_alignment = 0.22 * retention
    forward_alignment = 0.34 * samples["forward_bias"] * forward_progress
    recycle_alignment = 0.30 * samples["recycle_bias"] * recycle_value
    switch_alignment = 0.34 * samples["switch_bias"] * switch_value
    risk_penalty_alignment = (
        -0.26 * (1.0 - samples["risk_budget"]) * risk
    )
    raw_alignment = (
        retention_base_alignment
        + forward_alignment
        + recycle_alignment
        + switch_alignment
        + risk_penalty_alignment
    )
    utility_alignment = max(-0.25, min(1.25, raw_alignment))
    applied_alignment = max(-0.25, min(1.0, utility_alignment))
    current_control_value = max(
        0.0, min(1.0, samples["current_control_value"])
    )
    bounded_outcome_value = max(-1.0, min(1.0, samples["outcome_value"]))
    policy_budget = min(
        0.12 * abs(bounded_outcome_value - current_control_value)
        + 0.002 * current_control_value,
        0.012,
    )
    reconstructed_policy_value = policy_budget * applied_alignment
    linear_retention = success_probability
    linear_recycle_value = backward_progress * linear_retention
    linear_switch_value = lateral_change * cross_field * linear_retention
    linear_retention_base_alignment = 0.22 * linear_retention
    linear_recycle_alignment = (
        0.30 * samples["recycle_bias"] * linear_recycle_value
    )
    linear_switch_alignment = 0.34 * samples["switch_bias"] * linear_switch_value
    linear_raw_alignment = (
        linear_retention_base_alignment
        + forward_alignment
        + linear_recycle_alignment
        + linear_switch_alignment
        + risk_penalty_alignment
    )
    linear_utility_alignment = max(-0.25, min(1.25, linear_raw_alignment))
    linear_applied_alignment = max(-0.25, min(1.0, linear_utility_alignment))
    linear_team_plan_policy_value = policy_budget * linear_applied_alignment
    linear_team_plan_policy_delta = (
        linear_team_plan_policy_value - reconstructed_policy_value
    )
    post_team_plan_goal_policy_residual = (
        samples["production_policy_value"] - reconstructed_policy_value
    )
    production_score = value.get("score")
    reconstructed_score = samples["outcome_value"] + reconstructed_policy_value
    result = {
        **samples,
        "signed_progress": signed_progress,
        "forward_progress": forward_progress,
        "backward_progress": backward_progress,
        "lateral_change": lateral_change,
        "cross_field": cross_field,
        "retention": retention,
        "recycle_value": recycle_value,
        "switch_value": switch_value,
        "retention_base_alignment": retention_base_alignment,
        "forward_alignment": forward_alignment,
        "recycle_alignment": recycle_alignment,
        "switch_alignment": switch_alignment,
        "risk_penalty_alignment": risk_penalty_alignment,
        "raw_alignment": raw_alignment,
        "utility_alignment": utility_alignment,
        "utility_clamp_effect": utility_alignment - raw_alignment,
        "applied_alignment": applied_alignment,
        "policy_clamp_effect": applied_alignment - utility_alignment,
        "policy_budget": policy_budget,
        "team_plan_policy_value": reconstructed_policy_value,
        "linear_retention": linear_retention,
        "linear_recycle_value": linear_recycle_value,
        "linear_switch_value": linear_switch_value,
        "linear_retention_base_alignment": linear_retention_base_alignment,
        "linear_recycle_alignment": linear_recycle_alignment,
        "linear_switch_alignment": linear_switch_alignment,
        "linear_raw_alignment": linear_raw_alignment,
        "linear_applied_alignment": linear_applied_alignment,
        "linear_team_plan_policy_value": linear_team_plan_policy_value,
        "linear_team_plan_policy_delta": linear_team_plan_policy_delta,
        "post_team_plan_goal_policy_residual": (
            post_team_plan_goal_policy_residual
        ),
        "team_plan_only_score": reconstructed_score,
    }
    if isinstance(production_score, (int, float)):
        result["production_score"] = float(production_score)
        result["linear_policy_counterfactual_score"] = (
            float(production_score) + linear_team_plan_policy_delta
        )
        result["team_plan_only_score_residual"] = (
            float(production_score) - reconstructed_score
        )
    return result


def _two_stage_bounded_rational_distribution(
    candidates: list[tuple[dict[str, Any], float]],
    *,
    iq: float,
    pressure: float,
    fatigue: float,
) -> list[tuple[dict[str, Any], float]]:
    """Replay the production family-then-action bounded-rational selector."""
    family_codes = {
        "carry": 0,
        "pass": 1,
        "shoot": 2,
        "hold": 3,
        "reorient": 3,
        "clear": 4,
    }
    rows = [
        {
            "candidate": candidate,
            "family": family_codes[str(candidate.get("action_type") or "")],
            "score": float(score),
            "transition": candidate.get("value", {})
            .get("components", {})
            .get("outcome_transition"),
        }
        for candidate, score in candidates
        if str(candidate.get("action_type") or "") in family_codes
        and isinstance(score, (int, float))
    ]
    if not rows:
        return []

    def adjusted_scores(items: list[dict[str, Any]]) -> list[float]:
        scores = [float(item["score"]) for item in items]
        best_index = max(range(len(scores)), key=scores.__getitem__)
        best_transition = items[best_index]["transition"]
        if not isinstance(best_transition, dict):
            return scores
        tolerance = _bounded_rational_tolerance(
            scores[best_index], iq, pressure, fatigue
        )
        return [
            score
            - tolerance
            * _possession_transition_distance(item["transition"], best_transition)
            if isinstance(item["transition"], dict)
            else score
            for score, item in zip(scores, items)
        ]

    families = sorted({int(row["family"]) for row in rows})
    family_rows = {
        family: [row for row in rows if row["family"] == family]
        for family in families
    }
    family_best = {
        family: max(items, key=lambda item: float(item["score"]))
        for family, items in family_rows.items()
    }
    family_items = [family_best[family] for family in families]
    family_probabilities = _bounded_rational_probabilities(
        adjusted_scores(family_items), iq, pressure, fatigue
    )
    probabilities_by_candidate: dict[int, float] = {}
    for family_probability, family in zip(family_probabilities, families):
        items = family_rows[family]
        action_probabilities = _bounded_rational_probabilities(
            adjusted_scores(items), iq, pressure, fatigue
        )
        for item, action_probability in zip(items, action_probabilities):
            probabilities_by_candidate[id(item["candidate"])] = (
                family_probability * action_probability
            )
    return [
        (candidate, probabilities_by_candidate.get(id(candidate), 0.0))
        for candidate, _ in candidates
    ]


def _team_plan_linear_retention_selector_counterfactual(
    decision: dict[str, Any],
    *,
    signals: dict[str, Any],
    pitch_length: float,
    pitch_width: float,
) -> dict[str, float] | None:
    """Replay p-squared versus single-retention policy through both selector stages."""
    selection = decision.get("bounded_rational_selection", {})
    iq = selection.get("iq")
    pressure = selection.get("pressure")
    fatigue = selection.get("fatigue")
    if not all(
        isinstance(value, (int, float)) for value in (iq, pressure, fatigue)
    ):
        return None
    production: list[tuple[dict[str, Any], float]] = []
    linear: list[tuple[dict[str, Any], float]] = []
    pass_candidates = 0
    decomposed_pass_candidates = 0
    for candidate in [decision.get("chosen", {}), *decision.get("alternatives", [])]:
        if not isinstance(candidate, dict):
            continue
        production_score = candidate.get("value", {}).get("score")
        if not isinstance(production_score, (int, float)):
            continue
        counterfactual_score = float(production_score)
        if candidate.get("action_type") == "pass":
            pass_candidates += 1
            decomposition = _team_plan_pass_policy_decomposition(
                candidate,
                decision.get("pos"),
                attacking_right=bool(decision.get("attacking_right")),
                signals=signals,
                pitch_length=pitch_length,
                pitch_width=pitch_width,
            )
            if decomposition is None:
                continue
            decomposed_pass_candidates += 1
            counterfactual_score = decomposition[
                "linear_policy_counterfactual_score"
            ]
        production.append((candidate, float(production_score)))
        linear.append((candidate, counterfactual_score))
    if not production or pass_candidates != decomposed_pass_candidates:
        return None

    production_distribution = _two_stage_bounded_rational_distribution(
        production, iq=float(iq), pressure=float(pressure), fatigue=float(fatigue)
    )
    linear_distribution = _two_stage_bounded_rational_distribution(
        linear, iq=float(iq), pressure=float(pressure), fatigue=float(fatigue)
    )
    if not production_distribution or not linear_distribution:
        return None

    def observables(
        distribution: list[tuple[dict[str, Any], float]],
    ) -> dict[str, float]:
        result = {
            f"action_{action}_probability": sum(
                probability
                for candidate, probability in distribution
                if candidate.get("action_type") == action
            )
            for action in ("carry", "pass", "shoot", "hold", "reorient", "clear")
        }
        pass_rows: list[tuple[dict[str, Any], float, float]] = []
        origin = decision.get("pos")
        for candidate, probability in distribution:
            target = candidate.get("target")
            if (
                candidate.get("action_type") == "pass"
                and isinstance(origin, list)
                and len(origin) >= 2
                and isinstance(target, list)
                and len(target) >= 2
            ):
                pass_rows.append(
                    (
                        candidate,
                        probability,
                        hypot(
                            float(target[0]) - float(origin[0]),
                            float(target[1]) - float(origin[1]),
                        ),
                    )
                )
        pass_probability = sum(probability for _, probability, _ in pass_rows)
        long_probability = sum(
            probability
            for _, probability, distance_m in pass_rows
            if distance_m >= 32.0
        )
        result["provider_long_overall_probability"] = long_probability
        if pass_probability > 1e-12:
            result["provider_long_share_given_pass"] = (
                long_probability / pass_probability
            )
            result["expected_pass_distance_m"] = sum(
                probability * distance_m
                for _, probability, distance_m in pass_rows
            ) / pass_probability
        return result

    production_observables = observables(production_distribution)
    linear_observables = observables(linear_distribution)
    result: dict[str, float] = {
        "candidate_count": float(len(production)),
        "pass_candidate_count": float(pass_candidates),
    }
    for field in sorted(production_observables.keys() | linear_observables.keys()):
        production_value = production_observables.get(field, 0.0)
        linear_value = linear_observables.get(field, 0.0)
        result[f"production_{field}"] = production_value
        result[f"linear_{field}"] = linear_value
        result[f"linear_minus_production_{field}"] = (
            linear_value - production_value
        )
    production_best = max(production, key=lambda item: item[1])
    linear_best = max(linear, key=lambda item: item[1])
    result["deterministic_best_changed"] = float(
        production_best[0] is not linear_best[0]
    )
    result["deterministic_best_score_delta"] = (
        linear_best[1] - production_best[1]
    )
    return result


def _team_plan_policy_pair_decomposition(
    selected: dict[str, float], comparator: dict[str, float]
) -> dict[str, float]:
    """Exactly split selected-minus-comparator score under production policy math."""
    result = {
        "production_score_delta": (
            selected["production_score"] - comparator["production_score"]
        ),
        "outcome_value_effect": (
            selected["outcome_value"] - comparator["outcome_value"]
        ),
        "production_policy_value_delta": (
            selected["production_policy_value"]
            - comparator["production_policy_value"]
        ),
        "post_team_plan_goal_policy_residual_effect": (
            selected["post_team_plan_goal_policy_residual"]
            - comparator["post_team_plan_goal_policy_residual"]
        ),
        "policy_budget_effect": (
            (selected["policy_budget"] - comparator["policy_budget"])
            * comparator["applied_alignment"]
        ),
    }
    alignment_fields = (
        "retention_base_alignment",
        "forward_alignment",
        "recycle_alignment",
        "switch_alignment",
        "risk_penalty_alignment",
        "utility_clamp_effect",
        "policy_clamp_effect",
    )
    for field in alignment_fields:
        result[f"{field}_effect"] = selected["policy_budget"] * (
            selected[field] - comparator[field]
        )
    explained = (
        result["outcome_value_effect"]
        + result["policy_budget_effect"]
        + result["post_team_plan_goal_policy_residual_effect"]
    )
    explained += sum(result[f"{field}_effect"] for field in alignment_fields)
    result["score_decomposition_error"] = (
        result["production_score_delta"] - explained
    )
    result["team_plan_policy_value_delta"] = (
        selected["team_plan_policy_value"]
        - comparator["team_plan_policy_value"]
    )
    result["policy_delta_reconstruction_error"] = (
        result["production_policy_value_delta"]
        - result["team_plan_policy_value_delta"]
        - result["post_team_plan_goal_policy_residual_effect"]
    )
    return result


def _settled_transition_score_counterfactual(
    candidate: dict[str, Any],
    *,
    tick_duration: float,
    tempo: float,
    risk_budget: float,
) -> dict[str, float] | None:
    """Price only the predicted delayed-control mass with production semantics."""
    value = candidate.get("value", {})
    components = value.get("components", {})
    transition = components.get("outcome_transition", {})
    required = {
        "score": value.get("score"),
        "option_return": components.get("option_return"),
        "local_shaping": components.get("local_shaping"),
        "current_value": components.get("current_value"),
        "duration_seconds": components.get("option_duration_seconds"),
        "immediate_retained": transition.get("retained_control_probability"),
        "immediate_opposing": transition.get("opposing_control_probability"),
        "settled_retained": transition.get("settled_retained_probability"),
        "settled_opposing": transition.get("settled_opposing_probability"),
        "settled_recovery_ticks": transition.get(
            "unresolved_settlement_expected_recovery_ticks"
        ),
        "retained_value": transition.get("retained_control_value"),
        "opposing_value": transition.get("opposing_control_value"),
    }
    if not all(isinstance(sample, (int, float)) for sample in required.values()):
        return None
    samples = {field: float(sample) for field, sample in required.items()}
    retained_mass = _additional_settlement_mass(
        samples["settled_retained"], samples["immediate_retained"]
    )
    opposing_mass = _additional_settlement_mass(
        samples["settled_opposing"], samples["immediate_opposing"]
    )
    settled_mass = retained_mass + opposing_mass
    conditional_wait_seconds = (
        samples["settled_recovery_ticks"]
        / settled_mass
        * max(float(tick_duration), 0.0)
        if settled_mass > 1e-12
        else 0.0
    )
    rate = 0.0015 + 0.0060 * max(0.0, min(1.0, float(tempo)))
    delayed_discount = exp(
        -rate
        * max(samples["duration_seconds"] + conditional_wait_seconds, 0.1)
    )
    severity = 0.76 + 0.12 * (1.0 - max(0.0, min(1.0, float(risk_budget))))
    delayed_outcome = delayed_discount * (
        retained_mass * samples["retained_value"]
        - severity * opposing_mass * samples["opposing_value"]
    )
    counterfactual_option_return = samples["option_return"] + delayed_outcome
    old_policy_budget = min(
        0.12
        * abs(samples["option_return"] - max(0.0, min(1.0, samples["current_value"])))
        + 0.002 * max(0.0, min(1.0, samples["current_value"])),
        0.012,
    )
    policy_alignment = (
        samples["local_shaping"] / old_policy_budget
        if old_policy_budget > 1e-12
        else 0.0
    )
    new_policy_budget = min(
        0.12
        * abs(counterfactual_option_return - max(0.0, min(1.0, samples["current_value"])))
        + 0.002 * max(0.0, min(1.0, samples["current_value"])),
        0.012,
    )
    counterfactual_local_shaping = new_policy_budget * max(
        -0.25, min(1.0, policy_alignment)
    )
    counterfactual_score = counterfactual_option_return + counterfactual_local_shaping
    return {
        "score": counterfactual_score,
        "score_delta": counterfactual_score - samples["score"],
        "option_return": counterfactual_option_return,
        "delayed_outcome": delayed_outcome,
        "retained_mass": retained_mass,
        "opposing_mass": opposing_mass,
        "settled_mass": settled_mass,
        "conditional_wait_seconds": conditional_wait_seconds,
        "delayed_discount": delayed_discount,
        "local_shaping": counterfactual_local_shaping,
    }


def _bellman_preference_breakdown(
    decision_count: int,
    score_gaps: list[float],
    ledger_deltas: dict[str, list[float]],
    decomposition: dict[str, list[float]],
    time_budget_counts: Counter[str],
    time_budget_metrics: dict[str, list[float]],
    cases: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Summarize why a production choice outranks a safe near-feet pass."""
    effect_fields = (
        "continuation_probability_effect",
        "continuation_state_value_effect",
        "pre_discount_terminal_effect",
        "pre_discount_turnover_effect",
        "temporal_discount_effect",
        "score_local_shaping_effect",
    )
    check_fields = (
        "continuation_decomposition_error",
        "pre_discount_decomposition_error",
        "option_return_decomposition_error",
        "score_decomposition_error",
    )
    retained_state_fields = (
        "retained_direct_xg",
        "retained_territory",
        "retained_pressure_relief",
        "retained_outlet_access",
        "retained_structure",
        "retained_creation_access",
        "retained_one_link_xg",
        "retained_continuation_xg",
        "retained_control_residual",
        "retained_continuation_value",
        "retained_network_time_budget_seconds",
        "retained_time_budget_continuation_value",
        "retained_time_budget_continuation_value_delta",
        "retained_control_readiness",
    )
    summary = {
        "decisions": decision_count,
        "safe_near_feet_minus_chosen_score": _numeric_distribution(score_gaps),
        "effects": {
            field: _numeric_distribution(decomposition[field])
            for field in effect_fields
            if decomposition.get(field)
        },
        "retained_state_deltas": {
            field: _numeric_distribution(ledger_deltas[field])
            for field in retained_state_fields
            if ledger_deltas.get(field)
        },
        "decomposition_checks": {
            field: _numeric_distribution(decomposition[field])
            for field in check_fields
            if decomposition.get(field)
        },
        "time_budget_counterfactual": {
            "scope": (
                "replaces only each candidate's retained continuation value "
                "with the same after-state network evaluated inside the remaining "
                "3.6-second physical horizon; retention, terminal return, turnover, "
                "temporal discount, and local shaping stay at production values"
            ),
            "counts": dict(sorted(time_budget_counts.items())),
            "metrics": {
                field: _numeric_distribution(values)
                for field, values in sorted(time_budget_metrics.items())
                if values
            },
        },
    }
    if cases:
        summary["cases"] = cases
    return summary


def _relative_motion_projection(
    holder_pos: list[float] | tuple[float, float],
    holder_velocity: list[float] | tuple[float, float],
    opponent_pos: list[float] | tuple[float, float],
    opponent_velocity: list[float] | tuple[float, float],
    horizon_ticks: float,
) -> dict[str, float]:
    """Project separation with the frame's actual velocity vectors, never targets."""
    relative_pos = (
        float(opponent_pos[0]) - float(holder_pos[0]),
        float(opponent_pos[1]) - float(holder_pos[1]),
    )
    relative_velocity = (
        float(opponent_velocity[0]) - float(holder_velocity[0]),
        float(opponent_velocity[1]) - float(holder_velocity[1]),
    )
    horizon = max(float(horizon_ticks), 0.0)
    velocity_squared = (
        relative_velocity[0] * relative_velocity[0]
        + relative_velocity[1] * relative_velocity[1]
    )
    closest_tick = (
        max(
            0.0,
            min(
                horizon,
                -(
                    relative_pos[0] * relative_velocity[0]
                    + relative_pos[1] * relative_velocity[1]
                )
                / velocity_squared,
            ),
        )
        if velocity_squared > 1e-12
        else 0.0
    )
    terminal_relative = (
        relative_pos[0] + relative_velocity[0] * horizon,
        relative_pos[1] + relative_velocity[1] * horizon,
    )
    closest_relative = (
        relative_pos[0] + relative_velocity[0] * closest_tick,
        relative_pos[1] + relative_velocity[1] * closest_tick,
    )
    current_distance = hypot(*relative_pos)
    terminal_distance = hypot(*terminal_relative)
    return {
        "current_distance_m": current_distance,
        "terminal_distance_m": terminal_distance,
        "closest_distance_m": hypot(*closest_relative),
        "closest_tick": closest_tick,
        "terminal_closing_m": current_distance - terminal_distance,
    }


def _retarget_displacement_preserving_motion_components(
    origin: tuple[float, float],
    selected_target: tuple[float, float],
    realized_displacement: tuple[float, float],
    counterfactual_target: tuple[float, float],
) -> tuple[float, float]:
    """Rotate realized along/cross-target motion toward another target.

    This is an offline kinematic counterfactual, not a second engine. Keeping both
    motion components makes the selected-target replay an exact reconstruction.
    """
    selected_vector = (
        selected_target[0] - origin[0],
        selected_target[1] - origin[1],
    )
    counterfactual_vector = (
        counterfactual_target[0] - origin[0],
        counterfactual_target[1] - origin[1],
    )
    selected_distance = hypot(*selected_vector)
    counterfactual_distance = hypot(*counterfactual_vector)
    if selected_distance <= 1e-12 or counterfactual_distance <= 1e-12:
        return realized_displacement
    selected_unit = (
        selected_vector[0] / selected_distance,
        selected_vector[1] / selected_distance,
    )
    selected_cross = (-selected_unit[1], selected_unit[0])
    along = (
        realized_displacement[0] * selected_unit[0]
        + realized_displacement[1] * selected_unit[1]
    )
    across = (
        realized_displacement[0] * selected_cross[0]
        + realized_displacement[1] * selected_cross[1]
    )
    counterfactual_unit = (
        counterfactual_vector[0] / counterfactual_distance,
        counterfactual_vector[1] / counterfactual_distance,
    )
    counterfactual_cross = (-counterfactual_unit[1], counterfactual_unit[0])
    if along >= counterfactual_distance:
        return counterfactual_vector
    return (
        along * counterfactual_unit[0] + across * counterfactual_cross[0],
        along * counterfactual_unit[1] + across * counterfactual_cross[1],
    )


def _spatial_claim_conflict(
    left: dict[str, Any] | None, right: dict[str, Any] | None
) -> bool:
    """Mirror tactical_task::spatial_claim_conflict for trace analysis."""
    if not left or not right or not left.get("active") or not right.get("active"):
        return False
    left_target = left.get("target")
    right_target = right.get("target")
    left_origin = left.get("origin")
    right_origin = right.get("origin")
    if not all(
        isinstance(value, tuple) and len(value) >= 2
        for value in (left_target, right_target, left_origin, right_origin)
    ):
        return False
    target_distance = hypot(
        left_target[0] - right_target[0], left_target[1] - right_target[1]
    )
    occupied_distance = float(left.get("occupancy_radius", 0.0) or 0.0) + float(
        right.get("occupancy_radius", 0.0) or 0.0
    )
    if target_distance < occupied_distance:
        return True
    if (
        left.get("depth_band") != right.get("depth_band")
        or left.get("width_band") != right.get("width_band")
    ):
        return False
    left_route = (
        left_target[0] - left_origin[0], left_target[1] - left_origin[1]
    )
    right_route = (
        right_target[0] - right_origin[0], right_target[1] - right_origin[1]
    )
    left_length = hypot(*left_route)
    right_length = hypot(*right_route)
    if left_length <= 1e-6 or right_length <= 1e-6:
        return target_distance < occupied_distance * 1.4
    route_alignment = (
        left_route[0] * right_route[0] + left_route[1] * right_route[1]
    ) / (left_length * right_length)
    corridor_width = float(left.get("corridor_half_width", 0.0) or 0.0) + float(
        right.get("corridor_half_width", 0.0) or 0.0
    )
    return (
        route_alignment > 0.90
        and target_distance < occupied_distance * 1.65 + corridor_width
    )


def _normalized_trace_spatial_claim(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None

    def point(field: str, alias: str | None = None) -> tuple[float, float] | None:
        raw = value.get(field, value.get(alias) if alias is not None else None)
        if (
            isinstance(raw, (list, tuple))
            and len(raw) >= 2
            and isinstance(raw[0], (int, float))
            and isinstance(raw[1], (int, float))
        ):
            return (float(raw[0]), float(raw[1]))
        return None

    origin = point("origin", "claim_origin")
    target = point("target")
    if origin is None or target is None:
        return None
    return {
        "active": value.get("active", value.get("claim_active")) is True,
        "origin": origin,
        "target": target,
        "occupancy_radius": value.get("occupancy_radius"),
        "corridor_half_width": value.get("corridor_half_width"),
        "depth_band": value.get("depth_band"),
        "width_band": value.get("width_band"),
    }


def _controller_handoff_receipt_upper_bound(
    *,
    release: dict[str, Any],
    receipt: dict[str, Any],
    first_flight: dict[str, Any] | None,
    receipt_state: dict[str, Any] | None,
    passer_decision: dict[str, Any] | None,
) -> dict[str, Any]:
    """Audit one temporal controller-role transfer without changing behavior.

    The receiver's release-time Support/Receive task is immutable evidence. The
    outgoing controller is projected with the Rust live movement model, while
    receipt-time local value, TaskAcceptance, and final teammate claims remain
    the production observations emitted by full trace.
    """

    replay_id = receipt.get("replay_id")
    receipt_tick = receipt.get("tick")
    passer_idx = release.get("passer_player")
    receiver_idx = receipt.get("player_idx")
    projection = (
        first_flight.get("controller_handoff_counterfactual")
        if isinstance(first_flight, dict)
        else None
    )
    candidate = (
        passer_decision.get("controller_handoff_candidate")
        if isinstance(passer_decision, dict)
        else None
    )
    task = (
        projection.get("responsibility_task")
        if isinstance(projection, dict)
        else candidate.get("responsibility_task")
        if isinstance(candidate, dict)
        else None
    )
    task_claim = (
        _normalized_trace_spatial_claim(task.get("spatial_claim"))
        if isinstance(task, dict)
        else None
    )
    intent = str(task.get("intent") or "none").lower() if isinstance(task, dict) else "none"
    task_active_at_receipt = (
        isinstance(receipt_tick, int)
        and isinstance(task, dict)
        and str(task.get("phase") or "").lower() == "active"
        and isinstance(task.get("expires_tick"), int)
        and receipt_tick <= int(task["expires_tick"])
        and intent in {"support", "receive"}
        and task_claim is not None
        and task_claim.get("active") is True
    )
    identity_stable = (
        isinstance(projection, dict)
        and isinstance(candidate, dict)
        and receipt.get("winner_is_intended_receiver") is True
        and release.get("target_player") == receiver_idx
        and projection.get("passer_idx") == passer_idx
        and projection.get("receiver_idx") == receiver_idx
        and projection.get("receiver_task_identity_stable_since_release") is True
        and candidate.get("replay_id") == replay_id
        and candidate.get("passer_idx") == passer_idx
        and candidate.get("receiver_idx") == receiver_idx
        and candidate.get("identity_stable") is True
    )
    release_eligible = (
        isinstance(projection, dict)
        and projection.get("eligible") is True
        and isinstance(candidate, dict)
        and candidate.get("responsibility_active_at_release") is True
        and candidate.get("responsibility_intent_eligible") is True
    )

    candidate_score = candidate.get("candidate_base_score") if isinstance(candidate, dict) else None
    local_best_score = candidate.get("local_best_base_score") if isinstance(candidate, dict) else None
    local_floor_reference_score = (
        candidate.get("local_floor_reference_score")
        if isinstance(candidate, dict)
        else None
    )
    local_floor = (
        float(candidate.get("local_floor"))
        if isinstance(candidate, dict)
        and isinstance(candidate.get("local_floor"), (int, float))
        else max(float(local_floor_reference_score) * 0.54, 0.015)
        if isinstance(local_floor_reference_score, (int, float))
        else max(float(local_best_score) * 0.54, 0.015)
        if isinstance(local_best_score, (int, float))
        else None
    )
    clears_local_floor = (
        isinstance(candidate_score, (int, float))
        and isinstance(local_floor, (int, float))
        and float(candidate_score) + 1e-12 >= local_floor
    )
    acceptance = candidate.get("task_acceptance") if isinstance(candidate, dict) else None
    accepted = isinstance(acceptance, dict) and acceptance.get("accepted") is True

    candidate_claim = _normalized_trace_spatial_claim(
        candidate.get("candidate_claim") if isinstance(candidate, dict) else None
    )
    conflicting_teammates: list[int] = []
    if isinstance(receipt_state, dict) and candidate_claim is not None:
        for supporter in receipt_state.get("supporters", []):
            if not isinstance(supporter, dict):
                continue
            teammate_idx = supporter.get("idx")
            if (
                not isinstance(teammate_idx, int)
                or teammate_idx in {passer_idx, receiver_idx}
                or supporter.get("is_goalkeeper") is True
                or supporter.get("task_active") is not True
            ):
                continue
            teammate_claim = _normalized_trace_spatial_claim(
                supporter.get("task_spatial_claim")
            )
            if _spatial_claim_conflict(candidate_claim, teammate_claim):
                conflicting_teammates.append(teammate_idx)
    conflict_observed = isinstance(receipt_state, dict) and candidate_claim is not None
    conflict_free = conflict_observed and not conflicting_teammates

    def point(value: Any) -> tuple[float, float] | None:
        if (
            isinstance(value, (list, tuple))
            and len(value) >= 2
            and isinstance(value[0], (int, float))
            and isinstance(value[1], (int, float))
        ):
            return (float(value[0]), float(value[1]))
        return None

    receipt_pos = point(receipt.get("winner_pos"))
    projected_passer_pos = (
        point(receipt.get("controller_handoff_counterfactual", {}).get(
            "projected_receipt_pos"
        ))
        if isinstance(receipt.get("controller_handoff_counterfactual"), dict)
        else point(projection.get("projected_receipt_pos"))
        if isinstance(projection, dict)
        else None
    )
    target = (
        point(projection.get("responsibility_effective_target"))
        if isinstance(projection, dict)
        else None
    )
    teammate_rows = [
        row
        for row in receipt.get("actual_receipt_outfield_teammates", [])
        if isinstance(row, dict)
        and isinstance(row.get("idx"), int)
        and isinstance(row.get("distance_to_receiver_m"), (int, float))
    ]
    actual_passer_row = next(
        (row for row in teammate_rows if row.get("idx") == passer_idx), None
    )
    other_distances = [
        float(row["distance_to_receiver_m"])
        for row in teammate_rows
        if row.get("idx") != passer_idx
    ]
    actual_passer_distance = (
        float(actual_passer_row["distance_to_receiver_m"])
        if isinstance(actual_passer_row, dict)
        else None
    )
    projected_passer_distance = (
        hypot(
            projected_passer_pos[0] - receipt_pos[0],
            projected_passer_pos[1] - receipt_pos[1],
        )
        if projected_passer_pos is not None and receipt_pos is not None
        else None
    )
    baseline_nearest = (
        min([actual_passer_distance, *other_distances])
        if actual_passer_distance is not None
        else min(other_distances)
        if other_distances
        else None
    )
    projected_nearest = (
        min([projected_passer_distance, *other_distances])
        if projected_passer_distance is not None
        else None
    )
    target_distance_to_receiver = (
        hypot(target[0] - receipt_pos[0], target[1] - receipt_pos[1])
        if target is not None and receipt_pos is not None
        else None
    )

    all_gates = (
        release_eligible
        and task_active_at_receipt
        and identity_stable
        and clears_local_floor
        and accepted
        and conflict_free
        and projected_passer_distance is not None
    )
    return {
        "replay_id": replay_id,
        "release_eligible": release_eligible,
        "task_active_at_receipt": task_active_at_receipt,
        "identity_stable": identity_stable,
        "clears_local_floor": clears_local_floor,
        "task_acceptance_accepted": accepted,
        "conflict_observed": conflict_observed,
        "conflict_free": conflict_free,
        "conflicting_teammates": conflicting_teammates,
        "all_gates": all_gates,
        "candidate_score": float(candidate_score)
        if isinstance(candidate_score, (int, float))
        else None,
        "local_best_score": float(local_best_score)
        if isinstance(local_best_score, (int, float))
        else None,
        "local_floor_reference_score": float(local_floor_reference_score)
        if isinstance(local_floor_reference_score, (int, float))
        else None,
        "local_floor": local_floor,
        "candidate_to_local_best_ratio": (
            float(candidate_score) / max(float(local_best_score), 1e-12)
            if isinstance(candidate_score, (int, float))
            and isinstance(local_best_score, (int, float))
            else None
        ),
        "acceptance_candidate_value": acceptance.get("candidate_value")
        if isinstance(acceptance, dict)
        else None,
        "acceptance_retained_value": acceptance.get("retained_value")
        if isinstance(acceptance, dict)
        else None,
        "actual_passer_distance_m": actual_passer_distance,
        "projected_passer_distance_m": projected_passer_distance,
        "target_distance_to_receiver_m": target_distance_to_receiver,
        "baseline_nearest_m": baseline_nearest,
        "projected_nearest_m": projected_nearest,
        "nearest_closure_m": (
            baseline_nearest - projected_nearest
            if baseline_nearest is not None and projected_nearest is not None
            else None
        ),
        "creates_within_10m": (
            baseline_nearest >= 10.0 and projected_nearest < 10.0
            if baseline_nearest is not None and projected_nearest is not None
            else False
        ),
        "projected_distance_covered_m": (
            receipt.get("controller_handoff_counterfactual", {}).get(
                "projected_distance_covered_m"
            )
            if isinstance(receipt.get("controller_handoff_counterfactual"), dict)
            else projection.get("projected_distance_covered_m")
            if isinstance(projection, dict)
            else None
        ),
    }


def _pressure_projection_scope_summary(
    counts: Counter[str], metrics: dict[str, list[float]]
) -> dict[str, Any]:
    def classification(prefix: str) -> dict[str, Any]:
        true_positive = counts[f"{prefix}:true_positive"]
        false_positive = counts[f"{prefix}:false_positive"]
        false_negative = counts[f"{prefix}:false_negative"]
        true_negative = counts[f"{prefix}:true_negative"]
        return {
            "true_positive": true_positive,
            "false_positive": false_positive,
            "false_negative": false_negative,
            "true_negative": true_negative,
            "precision": round(
                true_positive / max(true_positive + false_positive, 1), 6
            ),
            "recall": round(
                true_positive / max(true_positive + false_negative, 1), 6
            ),
            "specificity": round(
                true_negative / max(true_negative + false_positive, 1), 6
            ),
        }

    return {
        "counts": dict(sorted(counts.items())),
        "under_4m_classification": {
            "terminal": classification("terminal"),
            "closest_approach": classification("closest"),
        },
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
    }


def _binary_ranking_auc(positive_scores: list[float], negative_scores: list[float]) -> float | None:
    """Return threshold-free pairwise AUC, with ties worth one half."""
    if not positive_scores or not negative_scores:
        return None
    wins = 0.0
    for positive in positive_scores:
        for negative in negative_scores:
            wins += 1.0 if positive > negative else 0.5 if positive == negative else 0.0
    return round(wins / (len(positive_scores) * len(negative_scores)), 6)


def _additional_settlement_mass(cumulative: float, direct: float) -> float:
    """Decode trace-level cumulative settled probability into added mass."""
    return max(0.0, float(cumulative) - float(direct))


def _shot_outcome_summary(
    events: Iterable[dict[str, Any]],
    home_attacking_right: bool = True,
) -> dict[str, Any]:
    event_list = list(events)
    outcomes = ("goal", "saved", "blocked", "off_target", "period_end")
    by_team = {
        team: {
            outcome: _team_event_count(event_list, team, "shot", {outcome})
            for outcome in outcomes
        }
        for team in ("home", "away")
    }
    censored_on_target_by_team = {
        team: sum(
            1
            for event in event_list
            if event.get("team_side") == team
            and event.get("event_type") == "shot"
            and event.get("outcome") == "period_end"
            and _event_has_tag(event, "on_target")
        )
        for team in ("home", "away")
    }
    xg_by_team = {
        team: sum(
            _event_xg(event)
            for event in event_list
            if event.get("team_side") == team
            and event.get("event_type") == "shot"
        )
        for team in ("home", "away")
    }
    xg_band_events: dict[str, list[dict[str, Any]]] = defaultdict(list)
    last_line_blocks_by_team: Counter[str] = Counter()
    for event in event_list:
        if event.get("event_type") == "shot":
            xg_band_events[_xg_band(_event_xg(event))].append(event)
        if event.get("event_type") != "shot" or event.get("outcome") != "blocked":
            continue
        target = event.get("target")
        team = event.get("team_side")
        if not isinstance(target, list) or len(target) < 2 or team not in {"home", "away"}:
            continue
        attacking_right = _event_attacking_right(event, home_attacking_right)
        goal_x = 105.0 if attacking_right else 0.0
        goal_y_min = (68.0 - 7.32) / 2.0
        goal_y_max = (68.0 + 7.32) / 2.0
        if abs(float(target[0]) - goal_x) <= 2.0 and goal_y_min <= float(target[1]) <= goal_y_max:
            last_line_blocks_by_team[team] += 1
    return {
        "by_team": by_team,
        "total": {
            outcome: sum(by_team[team][outcome] for team in ("home", "away"))
            for outcome in outcomes
        },
        "censored_on_target": {
            **censored_on_target_by_team,
            "total": sum(censored_on_target_by_team.values()),
        },
        "last_line_blocks": {
            "home": last_line_blocks_by_team["home"],
            "away": last_line_blocks_by_team["away"],
            "total": sum(last_line_blocks_by_team.values()),
            "definition": "blocked shots whose physical block point is within 2m of the attacked goal line and between the posts",
        },
        "event_xg": {
            **xg_by_team,
            "total": sum(xg_by_team.values()),
        },
        "released_by_xg_band": {
            "scope": "formal shot events only; these are released attempts, not chosen Shoot decisions",
            "bands": {
                band: {
                    "shots": len(events),
                    "xg": _numeric_distribution(
                        [_event_xg(event) for event in events]
                    ),
                    "outcomes": dict(
                        sorted(Counter(str(event.get("outcome")) for event in events).items())
                    ),
                }
                for band, events in sorted(xg_band_events.items())
            },
        },
    }


def _shot_family_summary(events: Iterable[dict[str, Any]]) -> dict[str, Any]:
    event_list = [
        event for event in events if event.get("event_type") == "shot"
    ]
    families = {
        "shoot_action": [
            event
            for event in event_list
            if not _event_has_tag(event, "carry_finish")
        ],
        "carry_finish": [
            event
            for event in event_list
            if _event_has_tag(event, "carry_finish")
        ],
    }
    result: dict[str, Any] = {
        "definition": (
            "mutually exclusive shot-event mechanism families; carry_finish is a "
            "controlled carry crossing the attacking goal line, not a selected Shoot "
            "action, so mechanism tuning must not infer Shoot finishing quality from "
            "the blended conversion rate"
        )
    }
    for family, family_events in families.items():
        shots = len(family_events)
        goals = sum(event.get("outcome") == "goal" for event in family_events)
        event_xg = sum(_event_xg(event) for event in family_events)
        result[family] = {
            "shots": shots,
            "goals": goals,
            "event_xg": event_xg,
            "xg_per_shot": round(event_xg / max(shots, 1), 4),
            "goal_conversion_rate": round(goals / max(shots, 1), 4),
        }
    result["closure"] = {
        "classified": sum(result[family]["shots"] for family in families),
        "shot_events": len(event_list),
        "delta": sum(result[family]["shots"] for family in families) - len(event_list),
    }
    return result


def _restart_release_lifecycle(events: Iterable[dict[str, Any]]) -> dict[str, Any]:
    ordered = sorted(events, key=lambda event: int(event.get("seq", 0) or 0))
    pending: dict[str, Any] | None = None
    events_since_restart: list[dict[str, Any]] = []
    resolved: Counter[str] = Counter()
    resolved_release_waits: dict[str, list[int]] = defaultdict(list)
    orphaned: list[dict[str, Any]] = []
    stray_releases: list[dict[str, Any]] = []
    restart_waits: dict[str, list[int]] = defaultdict(list)
    origin_tags = {
        "goal_kick": "goal_kick_origin",
        "corner": "corner_origin",
        "free_kick": "free_kick_origin",
        "offside": "free_kick_origin",
        "penalty": "penalty_origin",
    }
    for event_index, event in enumerate(ordered):
        if event.get("event_type") == "restart" and isinstance(event.get("tick"), int):
            next_active = next(
                (
                    candidate
                    for candidate in ordered[event_index + 1 :]
                    if candidate.get("event_type") != "restart"
                    and isinstance(candidate.get("tick"), int)
                    and int(candidate["tick"]) >= int(event["tick"])
                ),
                None,
            )
            if next_active is not None:
                restart_waits[str(event.get("outcome", "unknown"))].append(
                    int(next_active["tick"]) - int(event["tick"])
                )
        if (
            pending is not None
            and pending.get("half") is not None
            and event.get("half") is not None
            and pending["half"] != event.get("half")
        ):
            orphaned.append({
                **pending,
                "closed_by": "period_end",
                "intervening_events": events_since_restart,
            })
            pending = None
            events_since_restart = []
        release_event = event.get("event_type") in {
            "pass",
            "shot",
            "interception",
            "offside",
        }
        matched_pending_release = False
        if pending is not None and release_event:
            expected_tag = origin_tags[pending["outcome"]]
            if _event_has_tag(event, expected_tag):
                resolved[pending["outcome"]] += 1
                if isinstance(pending.get("tick"), int) and isinstance(event.get("tick"), int):
                    resolved_release_waits[pending["outcome"]].append(
                        int(event["tick"]) - int(pending["tick"])
                    )
                pending = None
                events_since_restart = []
                matched_pending_release = True
        out_of_play_restart = (
            "corner"
            if event.get("outcome") == "out_of_play"
            and _event_has_tag(event, "corner")
            else "goal_kick"
            if event.get("outcome") == "out_of_play"
            and _event_has_tag(event, "goal_kick")
            else None
        )
        if event.get("event_type") == "shot" and event.get("outcome") == "off_target":
            out_of_play_restart = "goal_kick"
        if out_of_play_restart is not None:
            if pending is not None:
                orphaned.append({
                    **pending,
                    "closed_by": "next_restart",
                    "intervening_events": events_since_restart,
                })
            last_touch_team = event.get("team_side")
            restart_team = (
                "away"
                if last_touch_team == "home"
                else "home"
                if last_touch_team == "away"
                else None
            )
            pending = {
                "seq": event.get("seq"),
                "tick": event.get("tick"),
                "half": event.get("half"),
                "team": restart_team,
                "outcome": out_of_play_restart,
            }
            events_since_restart = []
            continue
        if event.get("event_type") == "restart":
            outcome = str(event.get("outcome", "unknown"))
            same_award = (
                pending is not None
                and pending["outcome"] == outcome
            )
            if pending is not None and not same_award:
                orphaned.append({
                    **pending,
                    "closed_by": "next_restart",
                    "intervening_events": events_since_restart,
                })
            pending = (
                {
                    "seq": event.get("seq"),
                    "tick": event.get("tick"),
                    "half": event.get("half"),
                    "team": event.get("team_side"),
                    "outcome": outcome,
                }
                if outcome in origin_tags
                else None
            )
            events_since_restart = []
            continue
        if pending is not None:
            events_since_restart.append({
                "seq": event.get("seq"),
                "tick": event.get("tick"),
                "event_type": event.get("event_type"),
                "outcome": event.get("outcome"),
                "team": event.get("team_side"),
                "tags": event.get("tags"),
            })
        if release_event:
            restart_tags = [
                tag for tag in origin_tags.values() if _event_has_tag(event, tag)
            ]
            if pending is None and restart_tags and not matched_pending_release:
                stray_releases.append({
                    "seq": event.get("seq"),
                    "tick": event.get("tick"),
                    "event_type": event.get("event_type"),
                    "outcome": event.get("outcome"),
                    "team": event.get("team_side"),
                    "tags": event.get("tags"),
                    "preceding_events": [
                        {
                            "seq": prior.get("seq"),
                            "tick": prior.get("tick"),
                            "event_type": prior.get("event_type"),
                            "outcome": prior.get("outcome"),
                            "team": prior.get("team_side"),
                            "tags": prior.get("tags"),
                        }
                        for prior in ordered[max(0, event_index - 8):event_index]
                    ],
                })
    if pending is not None:
        orphaned.append({
            **pending,
            "closed_by": "period_end",
            "intervening_events": events_since_restart,
        })
    return {
        "resolved": dict(sorted(resolved.items())),
        "restart_event_to_release": {
            outcome: {
                "count": len(values),
                "ticks": sum(values),
                "mean_ticks": round(mean(values), 3),
                "median_ticks": round(median(values), 3),
                "p90_ticks": round(_quantile(values, 0.90), 3),
            }
            for outcome, values in sorted(resolved_release_waits.items())
            if values
        },
        "award_to_next_event": {
            outcome: {
                "count": len(values),
                "ticks": sum(values),
                "mean_ticks": round(mean(values), 3),
                "median_ticks": round(median(values), 3),
                "p90_ticks": round(_quantile(values, 0.90), 3),
            }
            for outcome, values in sorted(restart_waits.items())
            if values
        },
        "orphaned": orphaned,
        "orphaned_count": len(orphaned),
        "stray_releases": stray_releases,
        "stray_release_count": len(stray_releases),
    }


def _shot_release_summary(response: dict[str, Any]) -> dict[str, Any]:
    events = response.get("events", [])
    trace = response.get("trace", {})
    trace_entries = trace.get("entries", [])
    trace_decisions = trace.get("decisions", [])
    released_by_team = Counter(
        event.get("team_side")
        for event in events
        if event.get("event_type") == "shot"
        and not _event_has_tag(event, "carry_finish")
        and not _event_has_tag(event, "corner_header")
        and event.get("team_side") in {"home", "away"}
    )
    unreleased_entries = [
        entry
        for entry in trace_entries
        if entry.get("event") == "shot_unreleased"
        and entry.get("team") in {"home", "away"}
    ]
    prepared_entries = [
        entry
        for entry in trace_entries
        if entry.get("event") == "shot_prepared"
        and entry.get("team") in {"home", "away"}
    ]
    abandoned_entries = [
        entry
        for entry in trace_entries
        if entry.get("event") == "shot_abandoned"
        and entry.get("team") in {"home", "away"}
    ]
    unreleased_by_team = Counter(entry["team"] for entry in unreleased_entries)
    prepared_by_team = Counter(entry["team"] for entry in prepared_entries)
    abandoned_by_team = Counter(entry["team"] for entry in abandoned_entries)
    selected_decisions = [
        decision
        for decision in trace_decisions
        if isinstance(decision.get("chosen"), dict)
        and decision["chosen"].get("action_type") == "shoot"
        and decision.get("team") in {"home", "away"}
    ]
    selected_decisions_by_team = Counter(
        decision["team"] for decision in selected_decisions
    )
    pre_release_duel_losses_by_team: Counter[str] = Counter()
    pre_release_contested_loose_by_team: Counter[str] = Counter()
    for event in events:
        if not _event_has_tag(event, "shot_release"):
            continue
        event_team = event.get("team_side")
        if event_team not in {"home", "away"}:
            continue
        if _event_has_tag(event, "possession_won"):
            attacking_team = "away" if event_team == "home" else "home"
            pre_release_duel_losses_by_team[attacking_team] += 1
        elif event.get("event_type") == "duel" and event.get("outcome") == "loose":
            pre_release_contested_loose_by_team[event_team] += 1
    body_probabilities = [
        float(entry["body_release_probability"])
        for entry in unreleased_entries
        if isinstance(entry.get("body_release_probability"), (int, float))
    ]
    readiness_before = [
        float(entry["release_readiness_before"])
        for entry in unreleased_entries
        if isinstance(entry.get("release_readiness_before"), (int, float))
    ]
    readiness_after = [
        float(entry["release_readiness_after"])
        for entry in unreleased_entries
        if isinstance(entry.get("release_readiness_after"), (int, float))
    ]
    released = sum(released_by_team.values())
    unreleased = len(unreleased_entries)
    pre_release_duel_losses = sum(pre_release_duel_losses_by_team.values())
    pre_release_contested_loose = sum(pre_release_contested_loose_by_team.values())
    observable_resolutions_by_team = {
        team: (
            released_by_team[team]
            + unreleased_by_team[team]
            + abandoned_by_team[team]
            + pre_release_duel_losses_by_team[team]
            + pre_release_contested_loose_by_team[team]
        )
        for team in ("home", "away")
    }
    has_decision_trace = bool(trace_decisions)
    selected_by_team = {
        team: (
            selected_decisions_by_team[team]
            if has_decision_trace
            else observable_resolutions_by_team[team]
        )
        for team in ("home", "away")
    }
    selected = sum(selected_by_team.values())
    unresolved_by_team = {
        team: max(selected_by_team[team] - observable_resolutions_by_team[team], 0)
        for team in ("home", "away")
    }
    unresolved = sum(unresolved_by_team.values())
    over_resolved_by_team = {
        team: max(observable_resolutions_by_team[team] - selected_by_team[team], 0)
        for team in ("home", "away")
    }
    over_resolved = sum(over_resolved_by_team.values())
    return {
        "scope": (
            "full decision trace counts every chosen Shoot and partitions it into formal shot, "
            "terminal shot_unreleased, explicit abandonment, pre-release duel loss, or unresolved; "
            "shot_prepared is an intermediate contact and does not close the selected attempt; "
            "without decision trace the selected count is only the observable resolved lower bound"
        ),
        "selection_source": (
            "decision_trace" if has_decision_trace else "observable_resolution_lower_bound"
        ),
        "selected": selected,
        "prepared_contacts": len(prepared_entries),
        "unreleased": unreleased,
        "abandoned": len(abandoned_entries),
        "pre_release_duel_losses": pre_release_duel_losses,
        "pre_release_contested_loose": pre_release_contested_loose,
        "released": released,
        "unresolved": unresolved,
        "over_resolved": over_resolved,
        "selection_accounting_status": (
            "ok"
            if unresolved == 0 and over_resolved == 0
            else "over_resolved"
            if over_resolved > 0
            else "incomplete"
        ),
        "release_rate": round(released / max(selected, 1), 4),
        "by_team": {
            team: {
                "selected": selected_by_team[team],
                "prepared_contacts": prepared_by_team[team],
                "unreleased": unreleased_by_team[team],
                "abandoned": abandoned_by_team[team],
                "pre_release_duel_losses": pre_release_duel_losses_by_team[team],
                "pre_release_contested_loose": pre_release_contested_loose_by_team[team],
                "released": released_by_team[team],
                "unresolved": unresolved_by_team[team],
                "over_resolved": over_resolved_by_team[team],
                "release_rate": round(
                    released_by_team[team] / max(selected_by_team[team], 1),
                    4,
                ),
            }
            for team in ("home", "away")
        },
        "selected_identities": [
            {
                "tick": decision.get("tick"),
                "team": decision.get("team"),
                "player_idx": decision.get("player_idx"),
                "source": decision.get("chosen", {}).get("source"),
            }
            for decision in selected_decisions
        ],
        "selected_lifecycle": [
            {
                "selected": {
                    "tick": decision.get("tick"),
                    "possession_id": decision.get("possession_id"),
                    "team": decision.get("team"),
                    "player_idx": decision.get("player_idx"),
                },
                "nearby_trace": [
                    {
                        key: entry.get(key)
                        for key in (
                            "tick", "type", "event", "action", "phase",
                            "team", "player_idx", "possession_id", "outcome",
                            "reason", "body_release_probability", "body_release_roll",
                        )
                        if entry.get(key) is not None
                    }
                    for entry in trace_entries
                    if isinstance(entry.get("tick"), int)
                    and isinstance(decision.get("tick"), int)
                    and int(decision["tick"]) <= int(entry["tick"]) <= int(decision["tick"]) + 12
                    and (
                        entry.get("team") == decision.get("team")
                        or entry.get("player_idx") == decision.get("player_idx")
                        or entry.get("event") in {
                            "shot_prepared", "shot_unreleased", "shot_abandoned",
                            "action_commitment_ended", "duel", "tackle",
                        }
                    )
                ],
            }
            for decision in selected_decisions
        ],
        "released_identities": [
            {
                "tick": event.get("tick"),
                "team": event.get("team_side"),
                "player": event.get("player"),
                "outcome": event.get("outcome"),
                "tags": event.get("tags"),
            }
            for event in events
            if event.get("event_type") == "shot"
            and not _event_has_tag(event, "carry_finish")
            and not _event_has_tag(event, "corner_header")
        ],
        "pre_release_duel_loss_identities": [
            {
                "tick": event.get("tick"),
                "attacking_team": (
                    "away" if event.get("team_side") == "home" else "home"
                ),
                "defending_team": event.get("team_side"),
                "player": event.get("player"),
                "target_player": event.get("target_player"),
                "outcome": event.get("outcome"),
                "tags": event.get("tags"),
            }
            for event in events
            if _event_has_tag(event, "shot_release")
            and _event_has_tag(event, "possession_won")
        ],
        "unreleased_body_probability": {
            "mean": round(mean(body_probabilities), 3) if body_probabilities else 0.0,
            "median": round(median(body_probabilities), 3) if body_probabilities else 0.0,
        },
        "unreleased_readiness": {
            "mean_before": round(mean(readiness_before), 3) if readiness_before else 0.0,
            "mean_after": round(mean(readiness_after), 3) if readiness_after else 0.0,
        },
    }


def _free_ball_control_summary(response: dict[str, Any]) -> dict[str, Any]:
    trace_entries = response.get("trace", {}).get("entries", [])
    tick_duration = float(
        response.get("config", {}).get("tick_duration", 1.0) or 1.0
    )
    entries = [
        entry
        for entry in trace_entries
        if entry.get("event") == "continuous_ball_control"
        and isinstance(entry.get("tick"), int)
    ]
    episodes: list[list[dict[str, Any]]] = []
    for entry in entries:
        previous = episodes[-1][-1] if episodes else None
        replay_id = entry.get("pending_pass_replay_id")
        previous_replay_id = (
            previous.get("pending_pass_replay_id") if previous is not None else None
        )
        free_ball_ticks = int(entry.get("free_ball_ticks", 0) or 0)
        previous_free_ball_ticks = (
            int(previous.get("free_ball_ticks", 0) or 0)
            if previous is not None
            else 0
        )
        starts_new_episode = (
            previous is None
            or entry["tick"] > previous["tick"] + 1
            or replay_id != previous_replay_id
            or bool(previous.get("stable"))
            or (
                entry["tick"] > previous["tick"]
                and free_ball_ticks <= previous_free_ball_ticks
            )
        )
        if starts_new_episode:
            episodes.append([entry])
        else:
            episodes[-1].append(entry)

    def elapsed_full_ticks(episode: list[dict[str, Any]]) -> int:
        return max(
            (
                int(entry.get("free_ball_ticks", 0) or 0)
                for entry in episode
                if isinstance(entry.get("free_ball_ticks"), int)
            ),
            default=0,
        )

    def elapsed_phase_ticks(episode: list[dict[str, Any]]) -> float:
        """Physical free-ball time consumed after the pass terminal.

        A receipt-follow-up entry may cover only the unused fraction of the
        arrival tick.  Likewise, a stable terminal consumes only the contact
        substeps before control is established.  Summing the integer tick
        labels therefore overstates settlement time by up to one tick per
        episode.
        """
        elapsed = 0.0
        for entry in episode:
            phase_fraction = float(entry.get("phase_tick_fraction", 1.0) or 0.0)
            if bool(entry.get("stable")):
                consumed = entry.get("stable_control_consumed_fraction")
                elapsed += (
                    float(consumed)
                    if isinstance(consumed, (int, float))
                    else phase_fraction
                )
            else:
                elapsed += phase_fraction
        return elapsed

    durations = [elapsed_full_ticks(episode) for episode in episodes]
    terminal_entries = [episode[-1] for episode in episodes]
    pending_pass_episodes = [
        episode
        for episode in episodes
        if any(entry.get("pending_pass_replay_id") is not None for entry in episode)
    ]
    pending_pass_durations = [elapsed_full_ticks(episode) for episode in pending_pass_episodes]
    pending_same_tick_resolved = [
        episode
        for episode in pending_pass_episodes
        if elapsed_full_ticks(episode) == 0 and bool(episode[-1].get("stable"))
    ]
    pending_crossed_full_tick = [
        episode
        for episode in pending_pass_episodes
        if elapsed_full_ticks(episode) > 0
    ]
    pass_control_terminals = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    releases_for_duration = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("action") == "pass" and entry.get("replay_id") is not None
    }
    physical_terminals = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_physical_terminal"
        and entry.get("replay_id") is not None
    }
    opponent_material_contacts: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    for entry in trace_entries:
        if (
            entry.get("event") == "pending_pass_opponent_material_contact"
            and entry.get("replay_id") is not None
        ):
            opponent_material_contacts[entry.get("replay_id")].append(entry)
    pending_duration_by_outcome: dict[str, list[int]] = defaultdict(list)
    pending_elapsed_by_outcome: dict[str, list[float]] = defaultdict(list)
    pending_unstable_phase_by_outcome: dict[str, Counter[str]] = defaultdict(Counter)
    pending_terminal_by_outcome: dict[str, list[dict[str, float]]] = defaultdict(list)
    completed_contact_by_timing: dict[str, list[dict[str, float]]] = defaultdict(list)
    pending_duration_by_profile: dict[str, list[int]] = defaultdict(list)
    pending_contact_by_outcome: dict[str, Counter[str]] = defaultdict(Counter)
    pending_cases_by_outcome: dict[str, list[dict[str, Any]]] = defaultdict(list)
    residual_source_counts: Counter[str] = Counter()
    residual_source_ticks: Counter[str] = Counter()
    residual_source_labels: dict[str, Counter[str]] = defaultdict(Counter)
    residual_source_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    residual_source_cases: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for episode in episodes:
        if any(entry.get("pending_pass_replay_id") is not None for entry in episode):
            continue
        start_tick = int(episode[0]["tick"])
        nearby_labels = [
            label
            for entry in trace_entries
            if isinstance(entry.get("tick"), int)
            and start_tick - 1 <= int(entry["tick"]) <= start_tick
            and isinstance(
                (label := entry.get("event", entry.get("action"))), str
            )
            and label
            not in {"continuous_ball_control", "off_ball_choice", "off_ball_goal"}
        ]
        source = next(
            (
                label
                for label in (
                    "carry_error",
                    "error",
                    "shot_blocked",
                    "clearance_arrival",
                    "clearance",
                    "duel",
                    "tackle",
                    "first_touch_error",
                )
                if label in nearby_labels
            ),
            nearby_labels[-1] if nearby_labels else "unattributed",
        )
        residual_source_counts[source] += 1
        duration = elapsed_full_ticks(episode)
        residual_source_ticks[source] += duration
        residual_source_labels[source].update(nearby_labels)
        residual_source_metrics[source]["duration_ticks"].append(float(duration))
        for team in ("home", "away"):
            pursuers = [
                entry.get(f"{team}_primary_pursuer")
                for entry in episode
                if entry.get(f"{team}_primary_pursuer") is not None
            ]
            switches = sum(
                current != previous
                for previous, current in zip(pursuers, pursuers[1:])
            )
            residual_source_metrics[source][f"{team}_primary_switches"].append(
                float(switches)
            )
            confidences = [
                float(entry[f"{team}_confidence"])
                for entry in episode
                if isinstance(entry.get(f"{team}_confidence"), (int, float))
            ]
            if confidences:
                residual_source_metrics[source][f"max_{team}_confidence"].append(
                    max(confidences)
                )
        nearest_distances = [
            float(entry["nearest_player_distance"])
            for entry in episode
            if isinstance(entry.get("nearest_player_distance"), (int, float))
        ]
        if nearest_distances:
            residual_source_metrics[source]["minimum_nearest_player_distance"].append(
                min(nearest_distances)
            )
        arrival_leads = [
            float(entry["away_primary_arrival_ticks"])
            - float(entry["home_primary_arrival_ticks"])
            for entry in episode
            if isinstance(entry.get("home_primary_arrival_ticks"), (int, float))
            and isinstance(entry.get("away_primary_arrival_ticks"), (int, float))
        ]
        if arrival_leads:
            residual_source_metrics[source]["minimum_home_arrival_lead_ticks"].append(
                min(arrival_leads)
            )
            residual_source_metrics[source]["maximum_home_arrival_lead_ticks"].append(
                max(arrival_leads)
            )
        claim_pairs = [
            (float(entry["home_confidence"]), float(entry["away_confidence"]))
            for entry in episode
            if isinstance(entry.get("home_confidence"), (int, float))
            and isinstance(entry.get("away_confidence"), (int, float))
        ]
        if claim_pairs:
            residual_source_metrics[source]["maximum_combined_confidence"].append(
                max(home + away for home, away in claim_pairs)
            )
            residual_source_metrics[source]["maximum_claim_margin"].append(
                max(abs(home - away) for home, away in claim_pairs)
            )
            residual_source_metrics[source]["terminal_combined_confidence"].append(
                sum(claim_pairs[-1])
            )
            residual_source_metrics[source]["terminal_claim_margin"].append(
                abs(claim_pairs[-1][0] - claim_pairs[-1][1])
            )
            claim_leaders = [
                "home" if home > away else "away" if away > home else "level"
                for home, away in claim_pairs
            ]
            residual_source_metrics[source]["claim_leader_switches"].append(
                float(
                    sum(
                        current != previous
                        for previous, current in zip(
                            claim_leaders, claim_leaders[1:]
                        )
                    )
                )
            )
        terminal_entry = episode[-1]
        residual_source_cases[source].append(
            {
                "start_tick": start_tick,
                "duration_ticks": duration,
                "initial_speed": (
                    hypot(
                        float(episode[0]["velocity"][0]),
                        float(episode[0]["velocity"][1]),
                    )
                    if isinstance(episode[0].get("velocity"), list)
                    and len(episode[0]["velocity"]) >= 2
                    else None
                ),
                "terminal_speed": (
                    hypot(
                        float(terminal_entry["velocity"][0]),
                        float(terminal_entry["velocity"][1]),
                    )
                    if isinstance(terminal_entry.get("velocity"), list)
                    and len(terminal_entry["velocity"]) >= 2
                    else None
                ),
                "minimum_nearest_player_distance": (
                    min(nearest_distances) if nearest_distances else None
                ),
                "terminal_nearest_player_distance": terminal_entry.get(
                    "nearest_player_distance"
                ),
                "terminal_home_confidence": terminal_entry.get(
                    "home_confidence"
                ),
                "terminal_away_confidence": terminal_entry.get(
                    "away_confidence"
                ),
                "claim_leader_switches": (
                    sum(
                        current != previous
                        for previous, current in zip(
                            claim_leaders, claim_leaders[1:]
                        )
                    )
                    if claim_pairs
                    else None
                ),
                "nearby_labels": nearby_labels,
            }
        )
        for label, entry in (("initial", episode[0]), ("terminal", episode[-1])):
            velocity = entry.get("velocity")
            if (
                isinstance(velocity, list)
                and len(velocity) >= 2
                and isinstance(velocity[0], (int, float))
                and isinstance(velocity[1], (int, float))
            ):
                residual_source_metrics[source][f"{label}_speed"].append(
                    hypot(float(velocity[0]), float(velocity[1]))
                )
            for field in (
                "nearest_player_distance",
                "home_primary_arrival_ticks",
                "away_primary_arrival_ticks",
                "boundary_margin",
                "strongest_contact_relative_speed",
                "strongest_contact_post_relative_speed",
                "strongest_contact_player_speed",
                "strongest_contact_quality",
                "strongest_contact_separation",
            ):
                value = entry.get(field)
                if isinstance(value, (int, float)):
                    residual_source_metrics[source][f"{label}_{field}"].append(
                        float(value)
                    )
    for episode in pending_pass_episodes:
        replay_id = next(
            (
                entry.get("pending_pass_replay_id")
                for entry in episode
                if entry.get("pending_pass_replay_id") is not None
            ),
            None,
        )
        terminal = pass_control_terminals.get(replay_id, {})
        outcome = str(terminal.get("outcome", "unmatched"))
        duration = elapsed_full_ticks(episode)
        elapsed = elapsed_phase_ticks(episode)
        pending_duration_by_outcome[outcome].append(duration)
        pending_elapsed_by_outcome[outcome].append(elapsed)
        for entry in episode:
            if bool(entry.get("stable")):
                continue
            phase_fraction = float(entry.get("phase_tick_fraction", 1.0) or 0.0)
            quality = entry.get("strongest_contact_quality")
            post_relative_speed = entry.get("strongest_contact_post_relative_speed")
            home_confidence = float(entry.get("home_confidence", 0.0) or 0.0)
            away_confidence = float(entry.get("away_confidence", 0.0) or 0.0)
            winner = max(home_confidence, away_confidence)
            margin = abs(home_confidence - away_confidence)
            reason = (
                "no_contact"
                if not isinstance(quality, (int, float))
                else "relative_speed_above_unopposed_limit"
                if isinstance(post_relative_speed, (int, float))
                and float(post_relative_speed) > 4.5
                else "claim_below_unopposed_threshold"
                if winner < 0.60
                else "claim_margin_below_open_ball_threshold"
                if margin < 0.12
                else "other_stability_condition"
            )
            pending_unstable_phase_by_outcome[outcome][reason] += phase_fraction
        release = releases_for_duration.get(replay_id, {})
        release_distance = release.get("actual_distance_m")
        distance_group = "unknown"
        if isinstance(release_distance, (int, float)):
            distance_value = float(release_distance)
            distance_group = (
                "0_10m"
                if distance_value < 10.0
                else "10_20m"
                if distance_value < 20.0
                else "20_32m"
                if distance_value < 32.0
                else "32m_plus"
            )
        target_kind = str(release.get("target_kind", "unknown"))
        delivery = "error" if release.get("delivery_miss") else "clean"
        pending_duration_by_profile[
            f"{distance_group}:{target_kind}:{delivery}:{outcome}"
        ].append(duration)
        physical = physical_terminals.get(replay_id, {})
        pending_contact_by_outcome[outcome][
            f"one_touch_eligible={str(bool(physical.get('one_touch_physically_eligible'))).lower()}"
        ] += 1
        passer_team = physical.get("passer_team")
        strongest_team = physical.get("strongest_contact_team")
        strongest_player = physical.get("strongest_contact_player")
        intended_player = physical.get("intended_receiver_player")
        role = (
            "intended_receiver"
            if strongest_team == passer_team and strongest_player == intended_player
            else "other_teammate"
            if strongest_team == passer_team and strongest_team is not None
            else "opponent"
            if strongest_team is not None
            else "none"
        )
        pending_contact_by_outcome[outcome][f"strongest={role}"] += 1
        pending_contact_by_outcome[outcome][
            f"strongest_intent={physical.get('strongest_contact_intent')}"
        ] += 1
        pending_contact_by_outcome[outcome][
            f"opponent_touch={str(bool(terminal.get('opponent_touch'))).lower()}"
        ] += 1
        pending_contact_by_outcome[outcome][
            f"opponent_material={str(bool(terminal.get('opponent_material_contact'))).lower()}"
        ] += 1
        for material_contact in opponent_material_contacts.get(replay_id, []):
            pending_contact_by_outcome[outcome][
                f"material_intent={material_contact.get('intent')}"
            ] += 1
            pending_contact_by_outcome[outcome][
                f"material_stable={str(bool(material_contact.get('stable'))).lower()}"
            ] += 1
        final_entry = episode[-1]
        first_entry = episode[0]
        passer_prefix = "home" if passer_team == "home" else "away"
        opponent_prefix = "away" if passer_prefix == "home" else "home"
        passer_arrivals = [
            float(entry[f"{passer_prefix}_primary_arrival_ticks"])
            for entry in episode
            if isinstance(
                entry.get(f"{passer_prefix}_primary_arrival_ticks"), (int, float)
            )
        ]
        opponent_arrivals = [
            float(entry[f"{opponent_prefix}_primary_arrival_ticks"])
            for entry in episode
            if isinstance(
                entry.get(f"{opponent_prefix}_primary_arrival_ticks"), (int, float)
            )
        ]
        arrival_leads = [
            float(entry[f"{opponent_prefix}_primary_arrival_ticks"])
            - float(entry[f"{passer_prefix}_primary_arrival_ticks"])
            for entry in episode
            if isinstance(
                entry.get(f"{passer_prefix}_primary_arrival_ticks"), (int, float)
            )
            and isinstance(
                entry.get(f"{opponent_prefix}_primary_arrival_ticks"), (int, float)
            )
        ]
        claim_candidate_switches = {
            team: sum(
                left != right
                for left, right in zip(candidates, candidates[1:])
            )
            for team in ("home", "away")
            if (
                candidates := [
                    entry.get(f"{team}_candidate")
                    for entry in episode
                    if isinstance(entry.get(f"{team}_candidate"), int)
                ]
            )
        }
        boundary_margins = [
            float(entry["boundary_margin"])
            for entry in episode
            if isinstance(entry.get("boundary_margin"), (int, float))
        ]
        def primary_switches(prefix: str) -> int:
            identities = [
                entry.get(f"{prefix}_primary_pursuer")
                for entry in episode
                if isinstance(entry.get(f"{prefix}_primary_pursuer"), int)
            ]
            return sum(left != right for left, right in zip(identities, identities[1:]))
        terminal_row = {
                "duration": float(duration),
                "elapsed_ticks": elapsed,
                "initial_speed": float(first_entry.get("speed", 0.0) or 0.0),
                "initial_nearest_player_distance": float(
                    first_entry.get("nearest_player_distance", 0.0) or 0.0
                ),
                "speed": float(final_entry.get("speed", 0.0) or 0.0),
                "nearest_player_distance": float(
                    final_entry.get("nearest_player_distance", 0.0) or 0.0
                ),
                "winner_confidence": max(
                    float(final_entry.get("home_confidence", 0.0) or 0.0),
                    float(final_entry.get("away_confidence", 0.0) or 0.0),
                ),
                "physical_contact_target_distance": float(
                    physical.get("strongest_contact_target_distance", 0.0) or 0.0
                ),
                "physical_contact_separation": float(
                    physical.get("strongest_contact_separation", 0.0) or 0.0
                ),
                "receiver_displacement": float(
                    physical.get("strongest_contact_player_displacement", 0.0) or 0.0
                ),
                "impulse_access": float(
                    physical.get("strongest_contact_impulse_access", 0.0) or 0.0
                ),
                "materially_contacted": float(bool(physical.get("materially_contacted"))),
                "contact_quality": float(
                    physical.get("strongest_contact_quality", 0.0) or 0.0
                ),
                "facing_alignment": float(
                    physical.get("strongest_contact_facing_alignment", 0.0) or 0.0
                ),
                "relative_speed": float(
                    physical.get("strongest_contact_relative_speed", 0.0) or 0.0
                ),
                "reception_readiness": float(
                    physical.get("strongest_contact_reception_readiness", 0.0) or 0.0
                ),
                "post_relative_speed": float(
                    physical.get("strongest_contact_post_relative_speed", 0.0) or 0.0
                ),
                "remaining_tick_fraction": float(
                    physical.get("remaining_tick_fraction", 0.0) or 0.0
                ),
                "initial_passer_arrival_ticks": (
                    passer_arrivals[0] if passer_arrivals else 0.0
                ),
                "initial_opponent_arrival_ticks": (
                    opponent_arrivals[0] if opponent_arrivals else 0.0
                ),
                "initial_passer_arrival_lead_ticks": (
                    arrival_leads[0] if arrival_leads else 0.0
                ),
                "terminal_passer_arrival_lead_ticks": (
                    arrival_leads[-1] if arrival_leads else 0.0
                ),
                "minimum_passer_arrival_lead_ticks": (
                    min(arrival_leads) if arrival_leads else 0.0
                ),
                "minimum_boundary_margin": (
                    min(boundary_margins) if boundary_margins else 0.0
                ),
                "passer_primary_switches": float(primary_switches(passer_prefix)),
                "opponent_primary_switches": float(primary_switches(opponent_prefix)),
                "passer_claim_candidate_switches": float(
                    claim_candidate_switches.get(passer_prefix, 0)
                ),
                "opponent_claim_candidate_switches": float(
                    claim_candidate_switches.get(opponent_prefix, 0)
                ),
            }
        pending_terminal_by_outcome[outcome].append(terminal_row)
        pending_cases_by_outcome[outcome].append(
            {
                "replay_id": replay_id,
                "duration_ticks": duration,
                "elapsed_ticks": round(elapsed, 6),
                "elapsed_seconds": round(elapsed * tick_duration, 6),
                "release_distance_m": release_distance,
                "distance_group": distance_group,
                "target_kind": target_kind,
                "delivery": delivery,
                "terminal_outcome": outcome,
                "passer_team": passer_team,
                "strongest_contact_role": role,
                "terminal_winner_team": terminal.get("winner_team"),
                "terminal_winner_player": terminal.get("winner_player"),
                "opponent_touch": bool(terminal.get("opponent_touch")),
                "opponent_material_contact": bool(
                    terminal.get("opponent_material_contact")
                ),
                "phases": [
                    {
                        key: entry.get(key)
                        for key in (
                            "tick",
                            "phase_tick_fraction",
                            "speed",
                            "nearest_player_distance",
                            "home_candidate",
                            "home_confidence",
                            "away_candidate",
                            "away_confidence",
                            "home_primary_pursuer",
                            "home_primary_arrival_ticks",
                            "away_primary_pursuer",
                            "away_primary_arrival_ticks",
                            "strongest_contact_relative_speed",
                            "strongest_contact_post_relative_speed",
                            "strongest_contact_quality",
                            "strongest_contact_separation",
                            "simultaneous_contact_phases",
                            "strongest_home_contact_quality",
                            "strongest_away_contact_quality",
                            "boundary_margin",
                            "stable",
                            "stable_control_consumed_fraction",
                        )
                        if entry.get(key) is not None
                    }
                    for entry in episode
                ],
            }
        )
        if outcome == "completed":
            completed_contact_by_timing[
                "same_arrival_tick" if duration == 0 else "crossed_full_tick"
            ].append(terminal_row)
    follow_up_entries = [entry for entry in entries if entry.get("receipt_follow_up") is True]
    pass_releases = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("action") == "pass" and entry.get("replay_id") is not None
    }
    def distance_bucket(distance_m: float) -> str:
        if distance_m < 10.0:
            return "0_10m"
        if distance_m < 20.0:
            return "10_20m"
        if distance_m < 32.0:
            return "20_32m"
        return "32m_plus"

    def pending_episode_strata(
        selected: list[list[dict[str, Any]]],
    ) -> dict[str, dict[str, Any]]:
        observations: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for episode in selected:
            replay_id = next(
                (
                    entry.get("pending_pass_replay_id")
                    for entry in episode
                    if entry.get("pending_pass_replay_id") is not None
                ),
                None,
            )
            release = pass_releases.get(replay_id, {})
            terminal = physical_terminals.get(replay_id, {})
            distance_m = release.get("actual_distance_m")
            if not isinstance(distance_m, (int, float)):
                continue
            passer_team = terminal.get("passer_team")
            same_team_strongest = (
                terminal.get("strongest_contact_team") == passer_team
                and passer_team in {"home", "away"}
            )
            intended_strongest = (
                same_team_strongest
                and terminal.get("strongest_contact_player")
                == terminal.get("intended_receiver_player")
            )
            observation = {
                "full_ticks": elapsed_full_ticks(episode),
                "stable": bool(episode[-1].get("stable")),
                "delivery_miss": bool(release.get("delivery_miss")),
                "target_kind": release.get("target_kind"),
                "terminal_speed": terminal.get("terminal_speed"),
                "same_team_strongest": same_team_strongest,
                "intended_strongest": intended_strongest,
                "one_touch_physically_eligible": bool(
                    terminal.get("one_touch_physically_eligible")
                ),
                "stable_at_physical_terminal": (
                    terminal.get("stable_controller_player") is not None
                ),
                "winning_claim": max(
                    float(terminal.get("home_claim", 0.0) or 0.0),
                    float(terminal.get("away_claim", 0.0) or 0.0),
                ),
            }
            observations[distance_bucket(float(distance_m))].append(observation)

        result: dict[str, dict[str, Any]] = {}
        for bucket, bucket_observations in sorted(observations.items()):
            speeds = [
                float(observation["terminal_speed"])
                for observation in bucket_observations
                if isinstance(observation.get("terminal_speed"), (int, float))
            ]
            claims = [float(observation["winning_claim"]) for observation in bucket_observations]
            count = len(bucket_observations)
            result[bucket] = {
                "episodes": count,
                "full_ticks": sum(observation["full_ticks"] for observation in bucket_observations),
                "same_arrival_tick_resolved": sum(
                    observation["full_ticks"] == 0 and observation["stable"]
                    for observation in bucket_observations
                ),
                "crossed_full_tick": sum(
                    observation["full_ticks"] > 0 for observation in bucket_observations
                ),
                "stable_terminal": sum(
                    observation["stable"] for observation in bucket_observations
                ),
                "delivery_miss": sum(
                    observation["delivery_miss"] for observation in bucket_observations
                ),
                "feet_target": sum(
                    observation["target_kind"] == "feet" for observation in bucket_observations
                ),
                "same_team_strongest_contact": sum(
                    observation["same_team_strongest"] for observation in bucket_observations
                ),
                "intended_receiver_strongest_contact": sum(
                    observation["intended_strongest"] for observation in bucket_observations
                ),
                "stable_at_physical_terminal": sum(
                    observation["stable_at_physical_terminal"]
                    for observation in bucket_observations
                ),
                "one_touch_physically_eligible": sum(
                    observation["one_touch_physically_eligible"]
                    for observation in bucket_observations
                ),
                "terminal_speed_median": round(median(speeds), 3) if speeds else 0.0,
                "winning_claim_median": round(median(claims), 3) if claims else 0.0,
            }
        return result
    residual_durations = [
        elapsed_full_ticks(episode)
        for episode in episodes
        if all(entry.get("pending_pass_replay_id") is None for entry in episode)
    ]
    terminal_speeds = [
        float(entry["speed"])
        for entry in terminal_entries
        if isinstance(entry.get("speed"), (int, float))
    ]
    terminal_winner_confidences = [
        max(
            float(entry.get("home_confidence", 0.0) or 0.0),
            float(entry.get("away_confidence", 0.0) or 0.0),
        )
        for entry in terminal_entries
    ]
    stable_episodes = sum(bool(entry.get("stable")) for entry in terminal_entries)
    stable_remaining_fractions = [
        float(entry["stable_control_remaining_fraction"])
        for entry in terminal_entries
        if bool(entry.get("stable"))
        and isinstance(entry.get("stable_control_remaining_fraction"), (int, float))
    ]
    pending_stable_remaining_fractions = [
        float(episode[-1]["stable_control_remaining_fraction"])
        for episode in pending_pass_episodes
        if bool(episode[-1].get("stable"))
        and isinstance(
            episode[-1].get("stable_control_remaining_fraction"), (int, float)
        )
    ]

    def duration_split_summary(rows: list[dict[str, float]]) -> dict[str, Any]:
        return {
            "episodes": len(rows),
            "ticks": int(sum(row["duration"] for row in rows)),
            "elapsed_ticks": round(sum(row["elapsed_ticks"] for row in rows), 6),
            "mean_elapsed_ticks": (
                round(mean(row["elapsed_ticks"] for row in rows), 6)
                if rows
                else 0.0
            ),
            "median_elapsed_ticks": (
                round(median(row["elapsed_ticks"] for row in rows), 6)
                if rows
                else 0.0
            ),
            **{
                field: round(median(row[field] for row in rows), 3) if rows else 0.0
                for field in (
                    "initial_speed",
                    "initial_nearest_player_distance",
                    "speed",
                    "nearest_player_distance",
                    "winner_confidence",
                    "physical_contact_target_distance",
                    "physical_contact_separation",
                    "receiver_displacement",
                    "impulse_access",
                    "materially_contacted",
                    "contact_quality",
                    "facing_alignment",
                    "relative_speed",
                    "reception_readiness",
                    "post_relative_speed",
                    "remaining_tick_fraction",
                    "initial_passer_arrival_ticks",
                    "initial_opponent_arrival_ticks",
                    "initial_passer_arrival_lead_ticks",
                    "terminal_passer_arrival_lead_ticks",
                    "minimum_passer_arrival_lead_ticks",
                    "minimum_boundary_margin",
                    "passer_primary_switches",
                    "opponent_primary_switches",
                    "passer_claim_candidate_switches",
                    "opponent_claim_candidate_switches",
                )
            },
        }

    completed_rows = pending_terminal_by_outcome.get("completed", [])
    return {
        "scope": (
            "continuous_ball_control trace phases grouped by pending-pass replay identity, "
            "stable terminals, and the monotonic full-tick counter; enabled trace is required. "
            "receipt_follow_up phases consume only the remainder of the pass-arrival tick and "
            "do not increment full free-ball ticks"
        ),
        "observable": bool(entries),
        "episodes": len(episodes),
        "stable_episodes": stable_episodes,
        "unresolved_episodes": len(episodes) - stable_episodes,
        "ticks": sum(durations),
        "median_ticks": round(median(durations), 2) if durations else 0.0,
        "p90_ticks": round(_quantile(durations, 0.90), 2),
        "max_ticks": max(durations, default=0),
        "stable_control_remaining_fraction": {
            "count": len(stable_remaining_fractions),
            "total": round(sum(stable_remaining_fractions), 6),
            "mean": round(mean(stable_remaining_fractions), 6)
            if stable_remaining_fractions
            else 0.0,
            "median": round(median(stable_remaining_fractions), 6)
            if stable_remaining_fractions
            else 0.0,
        },
        "by_source": {
            "pending_pass": {
                "episodes": len(pending_pass_durations),
                "ticks": sum(pending_pass_durations),
                "elapsed_ticks": round(
                    sum(map(elapsed_phase_ticks, pending_pass_episodes)), 6
                ),
                "elapsed_seconds": round(
                    sum(map(elapsed_phase_ticks, pending_pass_episodes))
                    * tick_duration,
                    6,
                ),
                "same_arrival_tick_resolved": len(pending_same_tick_resolved),
                "crossed_full_tick": len(pending_crossed_full_tick),
                "receipt_follow_up_phases": len(follow_up_entries),
                "stable_remaining_fraction": {
                    "count": len(pending_stable_remaining_fractions),
                    "total": round(sum(pending_stable_remaining_fractions), 6),
                    "mean": round(mean(pending_stable_remaining_fractions), 6)
                    if pending_stable_remaining_fractions
                    else 0.0,
                },
                "by_distance": pending_episode_strata(pending_pass_episodes),
                "median_ticks": (
                    round(median(pending_pass_durations), 2)
                    if pending_pass_durations
                    else 0.0
                ),
                "p90_ticks": round(_quantile(pending_pass_durations, 0.90), 2),
                "duration_by_outcome": {
                    outcome: {
                        "episodes": len(values),
                        "ticks": sum(values),
                        "mean_ticks": round(mean(values), 3) if values else 0.0,
                        "median_ticks": round(median(values), 2) if values else 0.0,
                        "p90_ticks": round(_quantile(values, 0.90), 2),
                        "elapsed_ticks": round(
                            sum(pending_elapsed_by_outcome[outcome]), 6
                        ),
                        "elapsed_seconds": round(
                            sum(pending_elapsed_by_outcome[outcome]) * tick_duration, 6
                        ),
                        "mean_elapsed_ticks": round(
                            mean(pending_elapsed_by_outcome[outcome]), 6
                        ),
                        "median_elapsed_ticks": round(
                            median(pending_elapsed_by_outcome[outcome]), 6
                        ),
                        "p90_elapsed_ticks": round(
                            _quantile(pending_elapsed_by_outcome[outcome], 0.90), 6
                        ),
                        "terminal_speed_median": round(
                            median(row["speed"] for row in pending_terminal_by_outcome[outcome]),
                            3,
                        ),
                        "initial_speed_median": round(
                            median(
                                row["initial_speed"]
                                for row in pending_terminal_by_outcome[outcome]
                            ),
                            3,
                        ),
                        "initial_nearest_player_distance_median": round(
                            median(
                                row["initial_nearest_player_distance"]
                                for row in pending_terminal_by_outcome[outcome]
                            ),
                            3,
                        ),
                        "terminal_nearest_player_distance_median": round(
                            median(
                                row["nearest_player_distance"]
                                for row in pending_terminal_by_outcome[outcome]
                            ),
                            3,
                        ),
                        "terminal_winner_confidence_median": round(
                            median(
                                row["winner_confidence"]
                                for row in pending_terminal_by_outcome[outcome]
                            ),
                            3,
                        ),
                        **{
                            f"{field}_median": round(
                                median(
                                    row[field]
                                    for row in pending_terminal_by_outcome[outcome]
                                ),
                                3,
                            )
                            for field in (
                                "initial_passer_arrival_ticks",
                                "initial_opponent_arrival_ticks",
                                "initial_passer_arrival_lead_ticks",
                                "terminal_passer_arrival_lead_ticks",
                                "minimum_passer_arrival_lead_ticks",
                                "minimum_boundary_margin",
                                "passer_primary_switches",
                                "opponent_primary_switches",
                                "passer_claim_candidate_switches",
                                "opponent_claim_candidate_switches",
                            )
                        },
                    }
                    for outcome, values in sorted(pending_duration_by_outcome.items())
                },
                "cases_by_outcome": {
                    outcome: sorted(
                        cases,
                        key=lambda case: int(case.get("duration_ticks", 0)),
                        reverse=True,
                    )[:12]
                    for outcome, cases in sorted(pending_cases_by_outcome.items())
                },
                "unstable_phase_seconds_by_outcome": {
                    outcome: {
                        reason: round(tick_fractions * tick_duration, 3)
                        for reason, tick_fractions in sorted(reasons.items())
                    }
                    for outcome, reasons in sorted(
                        pending_unstable_phase_by_outcome.items()
                    )
                },
                "completed_contact_by_timing": {
                    timing: duration_split_summary(rows)
                    for timing, rows in sorted(completed_contact_by_timing.items())
                },
                "completed_duration_split": {
                    "same_tick": duration_split_summary(
                        [row for row in completed_rows if row["duration"] <= 0]
                    ),
                    "crossed_full_tick": duration_split_summary(
                        [row for row in completed_rows if row["duration"] > 0]
                    ),
                },
                "duration_by_profile": {
                    profile: {
                        "episodes": len(values),
                        "ticks": sum(values),
                        "mean_ticks": round(mean(values), 3) if values else 0.0,
                        "p90_ticks": round(_quantile(values, 0.90), 2),
                    }
                    for profile, values in sorted(pending_duration_by_profile.items())
                },
                "contact_by_outcome": {
                    outcome: dict(sorted(counts.items()))
                    for outcome, counts in sorted(pending_contact_by_outcome.items())
                },
            },
            "residual": {
                "episodes": len(residual_durations),
                "ticks": sum(residual_durations),
                "median_ticks": (
                    round(median(residual_durations), 2) if residual_durations else 0.0
                ),
                "p90_ticks": round(_quantile(residual_durations, 0.90), 2),
                "by_source": {
                    source: {
                        "episodes": count,
                        "ticks": residual_source_ticks[source],
                        "nearby_labels": dict(
                            sorted(residual_source_labels[source].items())
                        ),
                        "metrics": {
                            field: _numeric_distribution(values)
                            for field, values in sorted(
                                residual_source_metrics[source].items()
                            )
                            if values
                        },
                        "cases": residual_source_cases[source],
                    }
                    for source, count in sorted(residual_source_counts.items())
                },
            },
        },
        "terminal_speed": {
            "median": round(median(terminal_speeds), 3) if terminal_speeds else 0.0,
            "p90": round(_quantile(terminal_speeds, 0.90), 3),
        },
        "terminal_winner_confidence": {
            "median": (
                round(median(terminal_winner_confidences), 3)
                if terminal_winner_confidences
                else 0.0
            ),
            "p10": round(_quantile(terminal_winner_confidences, 0.10), 3),
        },
    }


def _pass_terminal_control_summary(response: dict[str, Any]) -> dict[str, Any]:
    trace_entries = response.get("trace", {}).get("entries", [])
    entries = [
        entry
        for entry in trace_entries
        if entry.get("event") == "pass_physical_terminal"
    ]
    control_terminals = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    contacted = [entry for entry in entries if entry.get("materially_contacted")]
    stable = [
        entry for entry in entries if entry.get("stable_controller_player") is not None
    ]
    speeds = [
        float(entry["terminal_speed"])
        for entry in entries
        if isinstance(entry.get("terminal_speed"), (int, float))
    ]
    strongest_qualities = [
        float(entry["strongest_contact_quality"])
        for entry in entries
        if isinstance(entry.get("strongest_contact_quality"), (int, float))
    ]
    winning_claims = [
        max(
            float(entry.get("home_claim", 0.0) or 0.0),
            float(entry.get("away_claim", 0.0) or 0.0),
        )
        for entry in entries
    ]
    stable_remaining_fractions = [
        float(entry["remaining_tick_fraction"])
        for entry in stable
        if isinstance(entry.get("remaining_tick_fraction"), (int, float))
    ]
    intended_contacts = [
        entry
        for entry in contacted
        if entry.get("strongest_contact_team") == entry.get("passer_team")
        and entry.get("strongest_contact_player")
        == entry.get("intended_receiver_player")
    ]
    by_delivery: dict[str, Counter[str]] = defaultdict(Counter)
    long_delivery_geometry: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    for entry in entries:
        length = "long" if entry.get("is_long") else "short"
        delivery = "miss" if entry.get("delivery_miss") else "on_target"
        bucket = by_delivery[f"{length}:{delivery}"]
        bucket["terminals"] += 1
        if entry.get("materially_contacted"):
            bucket["materially_contacted"] += 1
        same_team = entry.get("strongest_contact_team") == entry.get("passer_team")
        if same_team:
            bucket["strongest_contact_passer_team"] += 1
        if (
            same_team
            and entry.get("strongest_contact_player")
            == entry.get("intended_receiver_player")
        ):
            bucket["strongest_contact_intended_receiver"] += 1
        stable_team = entry.get("stable_controller_team")
        if stable_team == entry.get("passer_team"):
            bucket["stable_passer_team"] += 1
        elif stable_team is not None:
            bucket["stable_opponent"] += 1
        else:
            bucket["stable_unresolved"] += 1
        if entry.get("is_long"):
            group = "miss" if entry.get("delivery_miss") else "clean"
            group_bucket = by_delivery[f"long:{group}"]
            terminal = control_terminals.get(entry.get("replay_id"), {})
            terminal_outcome = terminal.get("outcome")
            group_bucket[f"final_{terminal_outcome or 'missing'}"] += 1
            if terminal.get("winner_is_intended_receiver"):
                group_bucket["final_winner_intended_receiver"] += 1
            elif terminal.get("winner_team") == entry.get("passer_team"):
                group_bucket["final_winner_other_teammate"] += 1
            for field in ("winner_target_distance_m", "release_to_control_seconds"):
                value = terminal.get(field)
                if isinstance(value, (int, float)):
                    long_delivery_geometry[group][field].append(float(value))
            for field in (
                "strongest_contact_flight_progress",
                "strongest_contact_separation",
                "strongest_contact_player_displacement",
                "planned_opponent_displacement",
                "planned_opponent_terminal_ball_distance",
            ):
                value = entry.get(field)
                if isinstance(value, (int, float)):
                    long_delivery_geometry[group][field].append(float(value))
            strongest_target_distance = entry.get("strongest_contact_target_distance")
            if isinstance(strongest_target_distance, (int, float)):
                long_delivery_geometry[group]["strongest_contact_target_distance_m"].append(
                    float(strongest_target_distance)
                )
            receiver_target_distance = entry.get("intended_receiver_target_distance")
            if isinstance(receiver_target_distance, (int, float)):
                long_delivery_geometry[group]["intended_receiver_target_distance_m"].append(
                    float(receiver_target_distance)
                )
            nearest_opponent_distance = entry.get("target_nearest_opponent_distance")
            if isinstance(nearest_opponent_distance, (int, float)):
                long_delivery_geometry[group]["target_nearest_opponent_distance_m"].append(
                    float(nearest_opponent_distance)
                )
            # Misses already use the generic ``long:miss`` bucket above.
            # Only copy contact attribution into the additional clean-flight
            # diagnostic; otherwise miss contacts are counted twice.
            if group_bucket is not bucket:
                if entry.get("strongest_contact_team") == entry.get("passer_team"):
                    group_bucket["strongest_contact_passer_team"] += 1
                if (
                    entry.get("strongest_contact_team") == entry.get("passer_team")
                    and entry.get("strongest_contact_player")
                    == entry.get("intended_receiver_player")
                ):
                    group_bucket["strongest_contact_intended_receiver"] += 1
    return {
        "observable": bool(entries),
        "terminals": len(entries),
        "reached_target": sum(bool(entry.get("reaches_target")) for entry in entries),
        "materially_contacted": len(contacted),
        "intended_receiver_contacted": len(intended_contacts),
        "stable_at_terminal": len(stable),
        "stable_contact_remaining_tick_fraction": {
            "count": len(stable_remaining_fractions),
            "total": round(sum(stable_remaining_fractions), 3),
            "mean": (
                round(mean(stable_remaining_fractions), 3)
                if stable_remaining_fractions
                else 0.0
            ),
            "median": (
                round(median(stable_remaining_fractions), 3)
                if stable_remaining_fractions
                else 0.0
            ),
        },
        "terminal_speed": {
            "median": round(median(speeds), 3) if speeds else 0.0,
            "p90": round(_quantile(speeds, 0.90), 3),
        },
        "strongest_contact_quality": {
            "median": (
                round(median(strongest_qualities), 3) if strongest_qualities else 0.0
            ),
            "p10": round(_quantile(strongest_qualities, 0.10), 3),
        },
        "winning_claim": {
            "median": round(median(winning_claims), 3) if winning_claims else 0.0,
            "p10": round(_quantile(winning_claims, 0.10), 3),
        },
        "by_length_and_delivery": {
            group: dict(sorted(counts.items()))
            for group, counts in sorted(by_delivery.items())
        },
        "long_delivery_geometry": {
            group: {
                field: _numeric_distribution(values)
                for field, values in sorted(fields.items())
                if values
            }
            for group, fields in sorted(long_delivery_geometry.items())
        },
    }


def _corner_creation_summary(response: dict[str, Any]) -> dict[str, Any]:
    def summarize(values: list[float]) -> dict[str, float | int]:
        return {
            "count": len(values),
            "mean": round(mean(values), 3) if values else 0.0,
            "median": round(median(values), 3) if values else 0.0,
            "p10": round(_quantile(values, 0.10), 3),
            "p90": round(_quantile(values, 0.90), 3),
        }
    entries = response.get("trace", {}).get("entries", [])
    releases = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("action") == "pass" and entry.get("replay_id") is not None
    }
    continuous_by_replay: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    physical_by_replay = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_physical_terminal"
        and entry.get("replay_id") is not None
    }
    for entry in entries:
        replay_id = entry.get("pending_pass_replay_id")
        if entry.get("event") == "continuous_ball_control" and replay_id is not None:
            continuous_by_replay[replay_id].append(entry)
    corners: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for entry in entries:
        if (
            entry.get("event") == "out_of_bounds"
            and entry.get("reason") == "corner"
        ):
            replay_id = entry.get("pending_pass_replay_id")
            release = releases.get(replay_id)
            if release is None and entry.get("source") == "flight":
                candidates = [
                    candidate
                    for candidate in releases.values()
                    if candidate.get("tick") == entry.get("tick")
                ]
                if len(candidates) == 1:
                    release = candidates[0]
            if release is not None:
                corners.append((entry, release))
    profiles: Counter[str] = Counter()
    distances: list[float] = []
    target_goal_line_margins: list[float] = []
    samples: list[dict[str, Any]] = []
    for out, release in corners:
        distance_m = float(release.get("actual_distance_m", 0.0) or 0.0)
        distances.append(distance_m)
        target = release.get("target")
        margin = None
        if isinstance(target, list) and len(target) >= 2:
            margin = min(float(target[0]), 105.0 - float(target[0]))
            target_goal_line_margins.append(margin)
        profile = ":".join(
            (
                str(release.get("target_kind", "unknown")),
                "long" if release.get("is_long") else "short",
                "error" if release.get("delivery_miss") else "clean",
                "opponent_touch" if out.get("last_touch_changed") else "no_opponent_touch",
                "under_5m" if margin is not None and margin < 5.0 else "5m_plus",
            )
        )
        profiles[profile] += 1
        if len(samples) < 24:
            samples.append({
                "replay_id": release.get("replay_id"),
                "origin": release.get("origin"),
                "target": target,
                "actual_distance_m": distance_m,
                "target_kind": release.get("target_kind"),
                "delivery_miss": bool(release.get("delivery_miss")),
                "retention_probability": release.get("retention_probability"),
                "out_source": out.get("source"),
                "out_boundary": out.get("boundary"),
                "crossing": out.get("crossing"),
                "last_touch_changed": bool(out.get("last_touch_changed")),
                "target_goal_line_margin_m": margin,
                "free_ball_episode": [
                    {
                        "tick": entry.get("tick"),
                        "ball": entry.get("ball"),
                        "speed": entry.get("speed"),
                        "nearest_player_distance": entry.get("nearest_player_distance"),
                        "home_candidate": entry.get("home_candidate"),
                        "home_confidence": entry.get("home_confidence"),
                        "away_candidate": entry.get("away_candidate"),
                        "away_confidence": entry.get("away_confidence"),
                    }
                    for entry in continuous_by_replay.get(release.get("replay_id"), [])
                ],
                "physical_terminal": physical_by_replay.get(release.get("replay_id")),
            })
    return {
        "observable": bool(corners),
        "count": len(corners),
        "profiles": dict(sorted(profiles.items())),
        "distance_m": summarize(distances),
        "target_goal_line_margin_m": summarize(target_goal_line_margins),
        "samples": samples,
    }


def _residual_pass_out_of_play_provenance_summary(
    response: dict[str, Any],
) -> dict[str, Any]:
    """Classify pass-driven boundary exits after the planned flight has ended."""
    entries = response.get("trace", {}).get("entries", [])
    releases = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("action") == "pass" and entry.get("replay_id") is not None
    }
    physical_by_replay = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_physical_terminal"
        and entry.get("replay_id") is not None
    }
    terminal_by_replay = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    residual_boundaries = [
        entry
        for entry in entries
        if entry.get("event") == "out_of_bounds"
        and entry.get("source") == "continuous_ball"
        and entry.get("pending_pass_replay_id") in releases
    ]
    continuous_control_by_replay: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    for entry in entries:
        replay_id = entry.get("pending_pass_replay_id")
        if entry.get("event") == "continuous_ball_control" and replay_id is not None:
            continuous_control_by_replay[replay_id].append(entry)

    def boundary_margin(point: Any) -> float | None:
        if not isinstance(point, list) or len(point) < 2:
            return None
        x, y = float(point[0]), float(point[1])
        return min(x, 105.0 - x, y, 68.0 - y)

    def planned_arrival(value: Any) -> str:
        return {0: "receiver", 1: "opponent", 2: "loose"}.get(
            value, "unknown"
        )

    def contact_class(
        release: dict[str, Any], physical: dict[str, Any]
    ) -> str:
        if not bool(physical.get("materially_contacted")):
            return "no_effective_contact"
        strongest_team = physical.get("strongest_contact_team")
        strongest_player = physical.get("strongest_contact_player")
        passer_team = physical.get("passer_team", release.get("team"))
        intended_receiver = physical.get("intended_receiver_player")
        if strongest_team != passer_team:
            return "opponent_contact"
        if strongest_player == intended_receiver:
            return "intended_receiver_weak_contact"
        return "other_passer_team_contact"

    rows: list[dict[str, Any]] = []
    for boundary in residual_boundaries:
        replay_id = boundary.get("pending_pass_replay_id")
        release = releases[replay_id]
        physical = physical_by_replay.get(replay_id, {})
        terminal = terminal_by_replay.get(replay_id, {})
        rows.append(
            {
                "replay_id": replay_id,
                "contact_class": contact_class(release, physical),
                "boundary": boundary.get("boundary"),
                "restart": boundary.get("reason"),
                "delivery": (
                    "miss" if bool(release.get("delivery_miss")) else "clean"
                ),
                "target_kind": release.get("target_kind"),
                "pass_type": release.get("pass_type"),
                "distance_m": release.get("actual_distance_m"),
                "target_boundary_margin_m": boundary_margin(release.get("target")),
                "physical_terminal_boundary_margin_m": boundary_margin(
                    physical.get("terminal_position")
                ),
                "terminal_speed": physical.get("terminal_speed"),
                "contact_quality": physical.get("strongest_contact_quality"),
                "material_deflection_quality": physical.get(
                    "material_deflection_contact_quality"
                ),
                "material_deflection_substep": physical.get(
                    "material_deflection_substep"
                ),
                "material_deflection_incoming_speed": physical.get(
                    "material_deflection_incoming_speed"
                ),
                "material_deflection_velocity_change": physical.get(
                    "material_deflection_velocity_change"
                ),
                "material_deflection_post_speed": physical.get(
                    "material_deflection_post_speed"
                ),
                "strongest_contact_team": physical.get("strongest_contact_team"),
                "strongest_contact_player": physical.get("strongest_contact_player"),
                "strongest_contact_relative_speed": physical.get(
                    "strongest_contact_relative_speed"
                ),
                "strongest_contact_post_relative_speed": physical.get(
                    "strongest_contact_post_relative_speed"
                ),
                "strongest_contact_player_speed": physical.get(
                    "strongest_contact_player_speed"
                ),
                "strongest_contact_velocity_alignment": physical.get(
                    "strongest_contact_velocity_alignment"
                ),
                "strongest_contact_impulse_access": physical.get(
                    "strongest_contact_impulse_access"
                ),
                "intended_receiver_player": physical.get(
                    "intended_receiver_player"
                ),
                "physical_terminal_home_claim": physical.get("home_claim"),
                "physical_terminal_away_claim": physical.get("away_claim"),
                "planned_arrival": planned_arrival(
                    release.get("planned_arrival_outcome")
                ),
                "planned_receiver_control": release.get(
                    "planned_arrival_receiver_control"
                ),
                "planned_opponent_control": release.get(
                    "planned_arrival_opponent_control"
                ),
                "planned_loose_control": release.get(
                    "planned_arrival_loose_control"
                ),
                "predicted_out_of_play_probability": release.get(
                    "predicted_out_of_play_probability"
                ),
                "control_terminal_outcome": terminal.get("outcome"),
                "origin": release.get("origin"),
                "target": release.get("target"),
                "physical_terminal_position": physical.get("terminal_position"),
                "physical_terminal_velocity": physical.get("terminal_velocity"),
                "continuous_control_phases": [
                    {
                        key: phase.get(key)
                        for key in (
                            "tick",
                            "free_ball_ticks",
                            "ball",
                            "velocity",
                            "speed",
                            "nearest_player_distance",
                            "home_candidate",
                            "home_confidence",
                            "away_candidate",
                            "away_confidence",
                            "strongest_contact_quality",
                            "strongest_contact_separation",
                            "strongest_contact_relative_speed",
                            "strongest_contact_post_relative_speed",
                            "strongest_contact_player_speed",
                            "boundary_margin",
                            "stable",
                        )
                    }
                    for phase in continuous_control_by_replay.get(replay_id, [])
                ],
                "crossing": boundary.get("crossing"),
            }
        )

    def metric_summary(group_rows: list[dict[str, Any]], field: str) -> dict[str, Any]:
        values = [
            float(row[field])
            for row in group_rows
            if isinstance(row.get(field), (int, float))
        ]
        return {
            "count": len(values),
            "mean": round(mean(values), 4) if values else None,
            "median": round(median(values), 4) if values else None,
            "p10": round(_quantile(values, 0.10), 4) if values else None,
            "p90": round(_quantile(values, 0.90), 4) if values else None,
        }

    grouped_rows: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        grouped_rows[row["contact_class"]].append(row)

    def group_summary(group_rows: list[dict[str, Any]]) -> dict[str, Any]:
        return {
            "count": len(group_rows),
            "share": round(len(group_rows) / max(len(rows), 1), 4),
            "delivery": dict(
                sorted(Counter(row["delivery"] for row in group_rows).items())
            ),
            "planned_arrival": dict(
                sorted(Counter(row["planned_arrival"] for row in group_rows).items())
            ),
            "restart": dict(
                sorted(Counter(str(row["restart"]) for row in group_rows).items())
            ),
            "boundary": dict(
                sorted(Counter(str(row["boundary"]) for row in group_rows).items())
            ),
            "metrics": {
                field: metric_summary(group_rows, field)
                for field in (
                    "distance_m",
                    "target_boundary_margin_m",
                    "physical_terminal_boundary_margin_m",
                    "terminal_speed",
                    "contact_quality",
                    "material_deflection_quality",
                    "material_deflection_incoming_speed",
                    "material_deflection_velocity_change",
                    "material_deflection_post_speed",
                    "strongest_contact_relative_speed",
                    "strongest_contact_post_relative_speed",
                    "strongest_contact_player_speed",
                    "strongest_contact_impulse_access",
                    "physical_terminal_home_claim",
                    "physical_terminal_away_claim",
                    "planned_receiver_control",
                    "planned_opponent_control",
                    "planned_loose_control",
                    "predicted_out_of_play_probability",
                )
            },
        }

    return {
        "scope": (
            "all pass releases that later cross a boundary from continuous-ball "
            "motion after the planned flight has ended"
        ),
        "total": len(rows),
        "classified_total": sum(len(group_rows) for group_rows in grouped_rows.values()),
        "by_contact_class": {
            group: group_summary(group_rows)
            for group, group_rows in sorted(grouped_rows.items())
        },
        "by_delivery": dict(
            sorted(Counter(row["delivery"] for row in rows).items())
        ),
        "by_planned_arrival": dict(
            sorted(Counter(row["planned_arrival"] for row in rows).items())
        ),
        "cases": rows,
    }


def _pass_out_of_play_calibration_summary(
    response: dict[str, Any],
) -> dict[str, Any]:
    """Compare selected and sampled-branch out-of-play forecasts with live outcomes."""
    entries = response.get("trace", {}).get("entries", [])
    releases = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("action") == "pass" and entry.get("replay_id") is not None
    }
    physical = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_physical_terminal"
        and entry.get("replay_id") is not None
    }
    terminals = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    defense_decisions: dict[tuple[Any, Any], list[dict[str, Any]]] = defaultdict(list)
    for decision in response.get("trace", {}).get("decisions", []):
        if (
            decision.get("phase") == "off_ball_defense"
            and decision.get("team") in {"home", "away"}
            and isinstance(decision.get("player_idx"), int)
        ):
            defense_decisions[(decision.get("team"), decision.get("player_idx"))].append(
                decision
            )
    for decisions in defense_decisions.values():
        decisions.sort(key=lambda decision: int(decision.get("tick", -1)))
    completed_by_possession: Counter[Any] = Counter()
    prefix_by_replay: dict[Any, int] = {}
    for entry in entries:
        replay_id = entry.get("replay_id")
        if entry.get("action") == "pass" and replay_id in releases:
            prefix_by_replay[replay_id] = completed_by_possession[
                releases[replay_id].get("possession_id")
            ]
        if (
            entry.get("event") == "pass_control_terminal"
            and entry.get("outcome") == "completed"
            and replay_id in releases
        ):
            completed_by_possession[releases[replay_id].get("possession_id")] += 1

    def prefix_band(value: int) -> str:
        if value == 0:
            return "0"
        if value == 1:
            return "1"
        if value <= 4:
            return "2-4"
        return "5+"

    def contact_class(release: dict[str, Any], terminal: dict[str, Any]) -> str:
        if not bool(terminal.get("materially_contacted")):
            return "no_material_contact"
        if terminal.get("strongest_contact_team") != terminal.get("passer_team"):
            return "opponent_material_contact"
        if terminal.get("strongest_contact_player") == terminal.get("intended_receiver_player"):
            return "intended_receiver_material_contact"
        return "other_passer_team_material_contact"

    rows: list[dict[str, Any]] = []
    variant_names = (
        "production_targeting",
        "teammates_exact",
        "receiver_exact",
        "opponents_exact",
        "teammates_and_opponents_exact",
        "receiver_and_opponents_exact",
        "receiver_oriented",
        "hidden_target_blind",
        "time_reachable_opponents",
        "selected_defense_targets",
    )
    for replay_id, release in releases.items():
        terminal = terminals.get(replay_id)
        if terminal is None:
            continue
        sampled_projection = release.get("sampled_endpoint_projection", {})
        sampled = sampled_projection.get("production_targeting", {})
        sampled_out_of_play = sampled.get("out_of_play_probability")
        projected_controller_team = (
            "passer"
            if sampled.get("dominant_retained_controller_idx") is not None
            else "opponent"
            if sampled.get("dominant_opposing_controller_idx") is not None
            else "unresolved"
        )
        physical_terminal = physical.get(replay_id, {})
        live_contact_team = physical_terminal.get("strongest_contact_team")
        live_contact_player = physical_terminal.get("strongest_contact_player")
        release_tick = release.get("tick")
        terminal_tick = physical_terminal.get("match_tick")
        live_contact_decisions = defense_decisions.get(
            (live_contact_team, live_contact_player), []
        )
        release_defense = next(
            (
                decision
                for decision in reversed(live_contact_decisions)
                if isinstance(release_tick, int)
                and decision.get("tick") == release_tick
            ),
            None,
        )
        terminal_defense = next(
            (
                decision
                for decision in reversed(live_contact_decisions)
                if isinstance(release_tick, int)
                and isinstance(terminal_tick, int)
                and release_tick <= int(decision.get("tick", -1)) <= terminal_tick
            ),
            None,
        )
        live_contact_position = physical_terminal.get("strongest_contact_position")
        release_defense_target = (
            release_defense.get("chosen", {}).get("target")
            if isinstance(release_defense, dict)
            else None
        )
        terminal_defense_target = (
            terminal_defense.get("chosen", {}).get("target")
            if isinstance(terminal_defense, dict)
            else None
        )
        release_carrier = (
            release_defense.get("belief", {}).get("observed_carrier")
            if isinstance(release_defense, dict)
            else None
        )
        terminal_carrier = (
            terminal_defense.get("belief", {}).get("observed_carrier")
            if isinstance(terminal_defense, dict)
            else None
        )
        stale_carrier_identity = lambda carrier: (
            "passer"
            if isinstance(carrier, dict)
            and carrier.get("index") == 11 + release.get("passer_player", -1000)
            else "intended_receiver"
            if isinstance(carrier, dict)
            and carrier.get("index")
            == 11 + release.get("target_player", -1000)
            else "other_attacker"
            if isinstance(carrier, dict)
            else "none"
        )

        def point_distance(left: Any, right: Any) -> float | None:
            if not (
                isinstance(left, list)
                and len(left) >= 2
                and isinstance(right, list)
                and len(right) >= 2
            ):
                return None
            return hypot(float(left[0]) - float(right[0]), float(left[1]) - float(right[1]))
        selected = release.get("predicted_out_of_play_probability")
        rows.append({
            "replay_id": replay_id,
            "prefix": prefix_band(prefix_by_replay.get(replay_id, 0)),
            "contact_class": contact_class(release, physical.get(replay_id, {})),
            "actual": float(terminal.get("outcome") == "out_of_play"),
            "selected": float(selected) if isinstance(selected, (int, float)) else None,
            "sampled": (
                float(sampled_out_of_play)
                if isinstance(sampled_out_of_play, (int, float))
                else None
            ),
            "sampled_stage": sampled.get("resolution_stage", "missing"),
            "projected_controller_team": projected_controller_team,
            "live_strongest_team": (
                "passer"
                if physical.get(replay_id, {}).get("strongest_contact_team")
                == physical.get(replay_id, {}).get("passer_team")
                else "opponent"
                if physical.get(replay_id, {}).get("strongest_contact_team") is not None
                else "none"
            ),
            "release_defense_action": (
                release_defense.get("chosen", {}).get("action_type")
                if isinstance(release_defense, dict)
                else "missing"
            ),
            "terminal_defense_action": (
                terminal_defense.get("chosen", {}).get("action_type")
                if isinstance(terminal_defense, dict)
                else "missing"
            ),
            "defense_action_changed_in_flight": (
                release_defense.get("chosen", {}).get("action_type")
                != terminal_defense.get("chosen", {}).get("action_type")
                if isinstance(release_defense, dict)
                and isinstance(terminal_defense, dict)
                else None
            ),
            "release_defense_target_to_contact_m": point_distance(
                release_defense_target, live_contact_position
            ),
            "terminal_defense_target_to_contact_m": point_distance(
                terminal_defense_target, live_contact_position
            ),
            "defense_target_displacement_m": point_distance(
                release_defense_target, terminal_defense_target
            ),
            "release_defense_carrier_visible": isinstance(release_carrier, dict),
            "terminal_defense_carrier_visible": isinstance(terminal_carrier, dict),
            "release_defense_carrier_ticks": (
                release_carrier.get("ticks")
                if isinstance(release_carrier, dict)
                else None
            ),
            "terminal_defense_carrier_ticks": (
                terminal_carrier.get("ticks")
                if isinstance(terminal_carrier, dict)
                else None
            ),
            "release_defense_carrier_identity": stale_carrier_identity(release_carrier),
            "terminal_defense_carrier_identity": stale_carrier_identity(terminal_carrier),
            "distance_m": release.get("actual_distance_m"),
            "flight_elapsed_ticks": physical_terminal.get("flight_elapsed_ticks"),
            "strongest_contact_flight_progress": physical_terminal.get(
                "strongest_contact_flight_progress"
            ),
            "target_kind": release.get("target_kind"),
            "delivery_miss": bool(release.get("delivery_miss")),
            "variants": {
                variant: {
                    "stage": sampled_projection.get(variant, {}).get(
                        "resolution_stage", "missing"
                    ),
                    "controller_team": (
                        "passer"
                        if sampled_projection.get(variant, {}).get(
                            "dominant_retained_controller_idx"
                        )
                        is not None
                        else "opponent"
                        if sampled_projection.get(variant, {}).get(
                            "dominant_opposing_controller_idx"
                        )
                        is not None
                        else "unresolved"
                    ),
                    "out_of_play_probability": sampled_projection.get(variant, {}).get(
                        "out_of_play_probability"
                    ),
                }
                for variant in variant_names
            },
        })

    def summarize(group_rows: list[dict[str, Any]]) -> dict[str, Any]:
        actual = [row["actual"] for row in group_rows]
        result: dict[str, Any] = {
            "count": len(group_rows),
            "actual_out_of_play": int(sum(actual)),
            "actual_rate": round(mean(actual), 6) if actual else None,
        }
        for field in ("selected", "sampled"):
            paired = [
                (float(row[field]), float(row["actual"]))
                for row in group_rows
                if isinstance(row.get(field), (int, float))
            ]
            result[field] = {
                "count": len(paired),
                "expected_rate": round(mean(value for value, _ in paired), 6)
                if paired
                else None,
                "observed_rate": round(mean(actual for _, actual in paired), 6)
                if paired
                else None,
                "observed_minus_expected": round(
                    mean(actual - value for value, actual in paired), 6
                )
                if paired
                else None,
                "brier": round(mean((value - actual) ** 2 for value, actual in paired), 6)
                if paired
                else None,
            }
        return result

    groups: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        groups["all"].append(row)
        groups[f"prefix={row['prefix']}"].append(row)
        groups[f"contact={row['contact_class']}"].append(row)
        groups[f"prefix={row['prefix']}:contact={row['contact_class']}"].append(row)
        groups[f"sampled_stage={row['sampled_stage']}"].append(row)
        groups[
            f"contact={row['contact_class']}:sampled_stage={row['sampled_stage']}"
        ].append(row)
        groups[
            "contact=" + row["contact_class"]
            + ":projected_controller=" + row["projected_controller_team"]
            + ":live_strongest=" + row["live_strongest_team"]
        ].append(row)
        groups[
            f"contact={row['contact_class']}:release_action={row['release_defense_action']}"
        ].append(row)
        groups[
            f"contact={row['contact_class']}:terminal_action={row['terminal_defense_action']}"
        ].append(row)
        if row.get("defense_action_changed_in_flight") is not None:
            groups[
                f"contact={row['contact_class']}:defense_action_changed="
                + str(bool(row["defense_action_changed_in_flight"])).lower()
            ].append(row)
        groups[
            f"contact={row['contact_class']}:release_carrier_visible="
            + str(bool(row["release_defense_carrier_visible"])).lower()
        ].append(row)
        groups[
            f"contact={row['contact_class']}:terminal_carrier_visible="
            + str(bool(row["terminal_defense_carrier_visible"])).lower()
        ].append(row)
        groups[
            f"contact={row['contact_class']}:release_carrier_identity="
            + row["release_defense_carrier_identity"]
        ].append(row)
        groups[
            f"contact={row['contact_class']}:terminal_carrier_identity="
            + row["terminal_defense_carrier_identity"]
        ].append(row)

    variant_groups: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        variant_groups["all"].append(row)
        variant_groups[f"contact={row['contact_class']}"].append(row)
        variant_groups[f"prefix={row['prefix']}:contact={row['contact_class']}"].append(row)

    def summarize_variants(group_rows: list[dict[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for variant in variant_names:
            values = [
                row["variants"].get(variant, {})
                for row in group_rows
                if isinstance(row.get("variants"), dict)
            ]
            expected = [
                float(value["out_of_play_probability"])
                for value in values
                if isinstance(value.get("out_of_play_probability"), (int, float))
            ]
            result[variant] = {
                "count": len(values),
                "controller_team": dict(
                    sorted(Counter(str(value.get("controller_team")) for value in values).items())
                ),
                "resolution_stage": dict(
                    sorted(Counter(str(value.get("stage")) for value in values).items())
                ),
                "expected_out_of_play_rate": round(mean(expected), 6)
                if expected
                else None,
            }
        return result

    def target_motion_summary(group_rows: list[dict[str, Any]]) -> dict[str, Any]:
        return {
            field: _numeric_distribution([
                float(row[field])
                for row in group_rows
                if isinstance(row.get(field), (int, float))
            ])
            for field in (
                "release_defense_target_to_contact_m",
                "terminal_defense_target_to_contact_m",
                "defense_target_displacement_m",
                "flight_elapsed_ticks",
                "strongest_contact_flight_progress",
                "release_defense_carrier_ticks",
                "terminal_defense_carrier_ticks",
            )
        }

    return {
        "scope": (
            "all released passes with a live control terminal. selected is the decision-time "
            "forecast; sampled replays the frozen candidate at the realized endpoint and "
            "technical branch. Prefix is completed passes earlier in the same possession."
        ),
        "rows": len(rows),
        "groups": {group: summarize(group_rows) for group, group_rows in sorted(groups.items())},
        "variant_groups": {
            group: summarize_variants(group_rows)
            for group, group_rows in sorted(variant_groups.items())
        },
        "target_motion_groups": {
            group: target_motion_summary(group_rows)
            for group, group_rows in sorted(variant_groups.items())
        },
    }


def _corner_delivery_trace_summary(response: dict[str, Any]) -> dict[str, Any]:
    entries = response.get("trace", {}).get("entries", [])
    deliveries = [
        entry
        for entry in entries
        if entry.get("event") == "corner_delivery_release"
    ]
    header_shots = [
        entry for entry in entries if entry.get("event") == "corner_header_shot"
    ]
    header_attempts = [
        entry for entry in entries if entry.get("event") == "corner_header_attempt"
    ]
    first_contacts = Counter(
        str(entry.get("outcome", "unknown"))
        for entry in entries
        if entry.get("event") == "aerial_first_contact"
        and entry.get("restart_origin") == "corner_origin"
    )
    targets = [entry.get("target") for entry in deliveries]
    in_box = sum(
        isinstance(target, list)
        and len(target) >= 2
        and _is_central_box(
            target,
            bool(target[0] >= 105.0 * 0.5),
        )
        for entry, target in zip(deliveries, targets)
    )
    return {
        "count": len(deliveries),
        "central_box_targets": in_box,
        "header_shots": len(header_shots),
        "header_attempts": len(header_attempts),
        "header_attempt_samples": header_attempts[:24],
        "first_contacts": dict(sorted(first_contacts.items())),
        "header_shots_on_target": sum(bool(entry.get("on_target")) for entry in header_shots),
        "header_shot_xg": round(
            sum(float(entry.get("xg", 0.0) or 0.0) for entry in header_shots), 4
        ),
        "samples": [
            {
                "origin": entry.get("origin"),
                "target": entry.get("target"),
                "attacking_right": bool(
                    isinstance(entry.get("target"), list)
                    and entry["target"][0] >= 105.0 * 0.5
                ),
                "target_player": entry.get("receiver_idx"),
                "attacking_first_contact_probability": entry.get("attacking_first_contact_probability"),
            }
            for entry in deliveries[:24]
        ],
    }


def _short_feet_pass_geometry_summary(response: dict[str, Any]) -> dict[str, Any]:
    """Close the trace chain for open-play feet-target passes by distance."""
    entries = response.get("trace", {}).get("entries", [])
    releases = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("action") == "pass"
        and entry.get("replay_id") is not None
        and entry.get("target_kind") == "feet"
    }
    terminals = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") in releases
        and entry.get("restart_origin") is None
    }
    physical = {
        entry.get("replay_id"): entry
        for entry in entries
        if entry.get("event") == "pass_physical_terminal"
        and entry.get("replay_id") in terminals
    }
    continuous_out = {
        entry.get("pending_pass_replay_id"): entry
        for entry in entries
        if entry.get("event") == "out_of_bounds"
        and entry.get("source") == "continuous_ball"
        and entry.get("pending_pass_replay_id") in terminals
    }
    direct_out_by_tick: dict[int, list[dict[str, Any]]] = defaultdict(list)
    for entry in entries:
        if (
            entry.get("event") == "out_of_bounds"
            and entry.get("source") == "flight"
            and isinstance(entry.get("tick"), int)
        ):
            direct_out_by_tick[int(entry["tick"])].append(entry)

    pending_ticks: Counter[Any] = Counter()
    for entry in entries:
        replay_id = entry.get("pending_pass_replay_id")
        if entry.get("event") == "continuous_ball_control" and replay_id in terminals:
            pending_ticks[replay_id] = max(
                pending_ticks[replay_id], int(entry.get("free_ball_ticks", 0) or 0)
            )

    def boundary_margin(point: Any) -> float | None:
        if not isinstance(point, list) or len(point) != 2:
            return None
        x, y = float(point[0]), float(point[1])
        return min(x, 105.0 - x, y, 68.0 - y)

    observations = []
    for replay_id, terminal in terminals.items():
        release = releases[replay_id]
        outcome = str(terminal.get("outcome"))
        out_entry = continuous_out.get(replay_id)
        out_stage = None
        if outcome == "out_of_play":
            if out_entry is not None:
                out_stage = "residual_free_ball"
            else:
                candidates = direct_out_by_tick.get(int(terminal.get("tick", -1)), [])
                if len(candidates) == 1:
                    out_entry = candidates[0]
                    out_stage = "direct_flight"
                else:
                    out_stage = "unmatched"
        physical_entry = physical.get(replay_id, {})
        origin = release.get("origin")
        target = release.get("target")
        attacking_right = bool(release.get("attacking_right"))
        progress_m = None
        if (
            isinstance(origin, list)
            and len(origin) == 2
            and isinstance(target, list)
            and len(target) == 2
        ):
            raw_progress = float(target[0]) - float(origin[0])
            progress_m = raw_progress if attacking_right else -raw_progress
        observations.append(
            {
                "replay_id": replay_id,
                "outcome": outcome,
                "opponent_touch": bool(terminal.get("opponent_touch")),
                "opponent_material_contact": bool(
                    terminal.get("opponent_material_contact")
                ),
                "winner_team": terminal.get("winner_team"),
                "winner_player": terminal.get("winner_player"),
                "distance_m": float(release.get("actual_distance_m", 0.0) or 0.0),
                "target_error_m": release.get("target_error_m"),
                "target_error_radius_m": release.get("target_error_radius_m"),
                "progress_m": progress_m,
                "retention_probability": release.get("retention_probability"),
                "frozen_retention_probability": release.get("frozen_retention_probability"),
                "lane_risk": release.get("lane_risk"),
                "receiver_pressure": release.get("receiver_pressure"),
                "release_receiver_nearest_opponent_distance": release.get("release_receiver_nearest_opponent_distance"),
                "release_target_nearest_opponent_distance": release.get("release_target_nearest_opponent_distance"),
                "release_target_nearest_opponent_player": release.get("release_target_nearest_opponent_player"),
                "planned_arrival_outcome": release.get("planned_arrival_outcome"),
                "planned_arrival_opponent_player": release.get("planned_arrival_opponent_player"),
                "planned_arrival_opponent_release_distance": release.get("planned_arrival_opponent_release_distance"),
                "planned_arrival_receiver_control": release.get("planned_arrival_receiver_control"),
                "planned_arrival_opponent_control": release.get("planned_arrival_opponent_control"),
                "planned_arrival_loose_control": release.get("planned_arrival_loose_control"),
                "live_defense_activation_radius": release.get("live_defense_activation_radius"),
                "delivery": "error" if release.get("delivery_miss") else "clean",
                "origin_margin": boundary_margin(release.get("origin")),
                "target_margin": boundary_margin(release.get("target")),
                "terminal_speed": physical_entry.get("terminal_speed"),
                "strongest_quality": physical_entry.get("strongest_contact_quality"),
                "strongest_separation": physical_entry.get("strongest_contact_separation"),
                "strongest_facing_alignment": physical_entry.get("strongest_contact_facing_alignment"),
                "strongest_relative_speed": physical_entry.get("strongest_contact_relative_speed"),
                "strongest_impulse_access": physical_entry.get("strongest_contact_impulse_access"),
                "strongest_player_speed": physical_entry.get("strongest_contact_player_speed"),
                "strongest_velocity_alignment": physical_entry.get("strongest_contact_velocity_alignment"),
                "strongest_incoming_speed": physical_entry.get("strongest_contact_incoming_speed"),
                "strongest_player_displacement": physical_entry.get("strongest_contact_player_displacement"),
                "strongest_flight_progress": physical_entry.get("strongest_contact_flight_progress"),
                "strongest_target_distance": physical_entry.get("strongest_contact_target_distance"),
                "receiver_nearest_opponent_distance": physical_entry.get("intended_receiver_nearest_opponent_distance"),
                "target_nearest_opponent_distance": physical_entry.get("target_nearest_opponent_distance"),
                "target_nearest_opponent_player": physical_entry.get("target_nearest_opponent_player"),
                "target_nearest_opponent_intent": physical_entry.get("target_nearest_opponent_intent"),
                "winning_claim": max(
                    float(physical_entry.get("home_claim", 0.0) or 0.0),
                    float(physical_entry.get("away_claim", 0.0) or 0.0),
                ),
                "stable_team": physical_entry.get("stable_controller_team"),
                "strongest_team": physical_entry.get("strongest_contact_team"),
                "strongest_player": physical_entry.get("strongest_contact_player"),
                "passer_team": physical_entry.get("passer_team"),
                "passer_player": physical_entry.get("passer_player"),
                "intended_receiver_player": physical_entry.get("intended_receiver_player"),
                "origin": release.get("origin"),
                "ideal_target": release.get("ideal_target"),
                "target": release.get("target"),
                "release_tick": release.get("tick"),
                "terminal_tick": terminal.get("tick"),
                "physical_terminal": physical_entry,
                "control_terminal": terminal,
                "pending_full_ticks": pending_ticks[replay_id],
                "out_stage": out_stage,
                "out_boundary": out_entry.get("boundary") if out_entry else None,
                "out_reason": out_entry.get("reason") if out_entry else None,
            }
        )

    def margin_bucket(value: float | None) -> str:
        if value is None:
            return "unknown"
        if value < 1.0:
            return "under_1m"
        if value < 3.0:
            return "1_3m"
        if value < 5.0:
            return "3_5m"
        return "5m_plus"

    def counts(field: str) -> dict[str, int]:
        return dict(sorted(Counter(str(row[field]) for row in observations).items()))

    selected = [row for row in observations if row["distance_m"] < 10.0]
    speeds = [
        float(row["terminal_speed"])
        for row in selected
        if isinstance(row.get("terminal_speed"), (int, float))
    ]
    out_rows = [row for row in selected if row["outcome"] == "out_of_play"]

    def metric_summary(rows: list[dict[str, Any]]) -> dict[str, Any]:
        def values(field: str) -> list[float]:
            return [
                float(row[field])
                for row in rows
                if isinstance(row.get(field), (int, float))
            ]

        role_outcomes: dict[str, Counter[str]] = defaultdict(Counter)
        intended_contact_breakdown: Counter[str] = Counter()
        nearest_defender_identity_by_outcome: dict[str, Counter[str]] = defaultdict(Counter)
        nearest_defender_intent_by_outcome: dict[str, Counter[str]] = defaultdict(Counter)
        direction_by_outcome: dict[str, Counter[str]] = defaultdict(Counter)
        direction_rows: dict[str, list[dict[str, Any]]] = defaultdict(list)
        fine_distance_rows: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for row in rows:
            fine_distance = (
                "3_5m" if row["distance_m"] < 5.0 else
                "5_7m" if row["distance_m"] < 7.0 else
                "7_10m" if row["distance_m"] < 10.0 else
                "10_15m" if row["distance_m"] < 15.0 else
                "15_20m" if row["distance_m"] < 20.0 else
                "20m_plus"
            )
            fine_distance_rows[fine_distance].append(row)
            role = (
                "passer"
                if row["strongest_team"] == row["passer_team"]
                and row["strongest_player"] == row["passer_player"]
                else "intended_receiver"
                if row["strongest_team"] == row["passer_team"]
                and row["strongest_player"] == row["intended_receiver_player"]
                else "other_teammate"
                if row["strongest_team"] == row["passer_team"]
                else "opponent"
                if row["strongest_team"] is not None
                else "none"
            )
            role_outcomes[role][row["outcome"]] += 1
            if role == "intended_receiver":
                intended_contact_breakdown[
                    f"{row['outcome']}:{row['delivery']}:"
                    f"opponent_touch={str(row['opponent_touch']).lower()}:"
                    f"material={str(row['opponent_material_contact']).lower()}"
                ] += 1
            same_nearest_defender = (
                row.get("release_target_nearest_opponent_player") is not None
                and row.get("release_target_nearest_opponent_player")
                == row.get("target_nearest_opponent_player")
            )
            nearest_defender_identity_by_outcome[row["outcome"]][
                "same" if same_nearest_defender else "changed"
            ] += 1
            nearest_defender_intent_by_outcome[row["outcome"]][
                str(row.get("target_nearest_opponent_intent"))
            ] += 1
            progress_m = row.get("progress_m")
            direction = (
                "unknown"
                if not isinstance(progress_m, (int, float))
                else "forward"
                if progress_m >= 10.0
                else "backward"
                if progress_m <= -10.0
                else "lateral"
            )
            direction_by_outcome[row["outcome"]][direction] += 1
            direction_rows[direction].append(row)
        return {
            "attempted": len(rows),
            "outcomes": dict(sorted(Counter(row["outcome"] for row in rows).items())),
            "calibration": {
                "expected_completed": round(
                    sum(values("frozen_retention_probability")), 3
                ),
                "observed_completed": sum(
                    row["outcome"] == "completed" for row in rows
                ),
                "expected_rate": round(
                    mean(values("frozen_retention_probability")), 4
                ) if values("frozen_retention_probability") else None,
                "observed_rate": round(
                    sum(row["outcome"] == "completed" for row in rows)
                    / max(len(rows), 1),
                    4,
                ),
            },
            "terminal_speed_median": (
                round(median(values("terminal_speed")), 3)
                if values("terminal_speed") else None
            ),
            "strongest_quality_median": (
                round(median(values("strongest_quality")), 3)
                if values("strongest_quality") else None
            ),
            "winning_claim_median": (
                round(median(values("winning_claim")), 3)
                if values("winning_claim") else None
            ),
            "predicted": {
                field: (
                    round(median(values(field)), 3) if values(field) else None
                )
                for field in (
                    "retention_probability",
                    "frozen_retention_probability",
                    "lane_risk",
                    "receiver_pressure",
                )
            },
            "predicted_by_outcome": {
                outcome: {
                    field: (
                        round(median(values_for_outcome), 3)
                        if (values_for_outcome := [
                            float(row[field])
                            for row in rows
                            if row["outcome"] == outcome
                            and isinstance(row.get(field), (int, float))
                        ])
                        else None
                    )
                    for field in (
                        "frozen_retention_probability",
                        "lane_risk",
                        "receiver_pressure",
                        "release_receiver_nearest_opponent_distance",
                        "release_target_nearest_opponent_distance",
                    )
                }
                for outcome in sorted({row["outcome"] for row in rows})
            },
            "spatial_error_by_delivery_and_outcome": {
                group: {
                    "count": len(group_rows),
                    "target_error_median": (
                        round(median(error_values), 3)
                        if (error_values := [
                            float(row["target_error_m"])
                            for row in group_rows
                            if isinstance(row.get("target_error_m"), (int, float))
                        ]) else None
                    ),
                    "target_error_p10": (
                        round(_quantile(error_values, 0.10), 3)
                        if error_values else None
                    ),
                    "target_error_p90": (
                        round(_quantile(error_values, 0.90), 3)
                        if error_values else None
                    ),
                    "strongest_target_distance_median": (
                        round(median(contact_values), 3)
                        if (contact_values := [
                            float(row["strongest_target_distance"])
                            for row in group_rows
                            if isinstance(row.get("strongest_target_distance"), (int, float))
                        ]) else None
                    ),
                }
                for group, group_rows in sorted(
                    (
                        group,
                        [
                            row for row in rows
                            if f"{row['delivery']}:{row['outcome']}" == group
                        ],
                    )
                    for group in {
                        f"{row['delivery']}:{row['outcome']}" for row in rows
                    }
                )
            },
            "physical_by_outcome": {
                outcome: {
                    field: (
                        round(median(outcome_values), 3)
                        if (outcome_values := [
                            float(row[field])
                            for row in rows
                            if row["outcome"] == outcome
                            and isinstance(row.get(field), (int, float))
                        ])
                        else None
                    )
                    for field in (
                        "terminal_speed",
                        "strongest_quality",
                        "strongest_separation",
                        "strongest_facing_alignment",
                        "strongest_relative_speed",
                        "strongest_impulse_access",
                        "strongest_player_speed",
                        "strongest_velocity_alignment",
                        "strongest_incoming_speed",
                        "strongest_player_displacement",
                        "strongest_flight_progress",
                        "strongest_target_distance",
                        "receiver_nearest_opponent_distance",
                        "target_nearest_opponent_distance",
                        "winning_claim",
                        "target_margin",
                    )
                }
                for outcome in sorted({row["outcome"] for row in rows})
            },
            "stable_at_physical_terminal": sum(
                row["stable_team"] is not None for row in rows
            ),
            "passer_team_strongest_contact": sum(
                row["strongest_team"] == row["passer_team"]
                and row["passer_team"] is not None
                for row in rows
            ),
            "strongest_contact_role": dict(
                sorted(
                    Counter(
                        "passer"
                        if row["strongest_team"] == row["passer_team"]
                        and row["strongest_player"] == row["passer_player"]
                        else "intended_receiver"
                        if row["strongest_team"] == row["passer_team"]
                        and row["strongest_player"] == row["intended_receiver_player"]
                        else "other_teammate"
                        if row["strongest_team"] == row["passer_team"]
                        else "opponent"
                        if row["strongest_team"] is not None
                        else "none"
                        for row in rows
                    ).items()
                )
            ),
            "strongest_contact_role_outcomes": {
                role: dict(sorted(outcomes.items()))
                for role, outcomes in sorted(role_outcomes.items())
            },
            "intended_contact_breakdown": dict(
                sorted(intended_contact_breakdown.items())
            ),
            "nearest_defender_identity_by_outcome": {
                outcome: dict(sorted(counts.items()))
                for outcome, counts in sorted(nearest_defender_identity_by_outcome.items())
            },
            "nearest_defender_intent_by_outcome": {
                outcome: dict(sorted(counts.items()))
                for outcome, counts in sorted(nearest_defender_intent_by_outcome.items())
            },
            "direction_by_outcome": {
                outcome: dict(sorted(counts.items()))
                for outcome, counts in sorted(direction_by_outcome.items())
            },
            "by_direction": {
                direction: {
                    "attempted": len(group_rows),
                    "completed": sum(
                        row["outcome"] == "completed" for row in group_rows
                    ),
                    "completion_rate": round(
                        sum(row["outcome"] == "completed" for row in group_rows)
                        / max(len(group_rows), 1),
                        4,
                    ),
                    "delivery": dict(
                        sorted(Counter(row["delivery"] for row in group_rows).items())
                    ),
                    "median_metrics": {
                        field: (
                            round(median(metric_values), 3)
                            if (metric_values := [
                                float(row[field])
                                for row in group_rows
                                if isinstance(row.get(field), (int, float))
                            ])
                            else None
                        )
                        for field in (
                            "distance_m",
                            "progress_m",
                            "frozen_retention_probability",
                            "lane_risk",
                            "receiver_pressure",
                            "release_receiver_nearest_opponent_distance",
                            "release_target_nearest_opponent_distance",
                        )
                    },
                }
                for direction, group_rows in sorted(direction_rows.items())
            },
            "by_fine_distance": {
                bucket: {
                    "attempted": len(group_rows),
                    "completion_rate": round(
                        sum(row["outcome"] == "completed" for row in group_rows)
                        / max(len(group_rows), 1), 4
                    ),
                    "incoming_speed_median": (
                        round(median(values), 3)
                        if (values := [
                            float(row["strongest_incoming_speed"])
                            for row in group_rows
                            if isinstance(row.get("strongest_incoming_speed"), (int, float))
                        ]) else None
                    ),
                    "contact_progress_median": (
                        round(median(values), 3)
                        if (values := [
                            float(row["strongest_flight_progress"])
                            for row in group_rows
                            if isinstance(row.get("strongest_flight_progress"), (int, float))
                        ]) else None
                    ),
                }
                for bucket, group_rows in sorted(fine_distance_rows.items())
            },
            "pending_full_ticks": dict(
                sorted(Counter(str(row["pending_full_ticks"]) for row in rows).items())
            ),
        }
    return {
        "scope": "open-play feet-target pass releases, joined by replay_id and grouped by distance",
        "attempted": len(selected),
        "outcomes": dict(sorted(Counter(row["outcome"] for row in selected).items())),
        "by_delivery": dict(sorted(Counter(row["delivery"] for row in selected).items())),
        "origin_boundary_margin": dict(
            sorted(Counter(margin_bucket(row["origin_margin"]) for row in selected).items())
        ),
        "target_boundary_margin": dict(
            sorted(Counter(margin_bucket(row["target_margin"]) for row in selected).items())
        ),
        "terminal_speed_median": round(median(speeds), 3) if speeds else None,
        "stable_at_physical_terminal": sum(
            row["stable_team"] is not None for row in selected
        ),
        "passer_team_strongest_contact": sum(
            row["strongest_team"] == row["passer_team"]
            and row["passer_team"] is not None
            for row in selected
        ),
        "pending_full_ticks": dict(
            sorted(Counter(str(row["pending_full_ticks"]) for row in selected).items())
        ),
        "planned_opponent_actual_completed": [
            {
                field: row.get(field)
                for field in (
                    "distance_m",
                    "delivery",
                    "planned_arrival_opponent_player",
                    "planned_arrival_opponent_release_distance",
                    "live_defense_activation_radius",
                    "planned_arrival_receiver_control",
                    "planned_arrival_opponent_control",
                    "planned_arrival_loose_control",
                    "strongest_team",
                    "strongest_player",
                    "intended_receiver_player",
                    "outcome",
                )
            }
            for row in observations
            if row["distance_m"] >= 32.0
            and row.get("planned_arrival_outcome") == 1
            and row["outcome"] == "completed"
        ][:24],
        "distance_comparison": {
            "0_10m": metric_summary(selected),
            "10_20m": metric_summary(
                [row for row in observations if 10.0 <= row["distance_m"] < 20.0]
            ),
            "30m_plus": metric_summary(
                [row for row in observations if row["distance_m"] >= 30.0]
            ),
        },
        "failure_cases_0_10m": [
            row for row in selected if row["outcome"] != "completed"
        ],
        "out_of_play": {
            "total": len(out_rows),
            "by_stage": dict(sorted(Counter(str(row["out_stage"]) for row in out_rows).items())),
            "by_boundary": dict(
                sorted(Counter(str(row["out_boundary"]) for row in out_rows).items())
            ),
            "by_reason": dict(sorted(Counter(str(row["out_reason"]) for row in out_rows).items())),
            "by_delivery": dict(sorted(Counter(row["delivery"] for row in out_rows).items())),
            "target_boundary_margin": dict(
                sorted(Counter(margin_bucket(row["target_margin"]) for row in out_rows).items())
            ),
        },
    }


def _aggregate_pass_terminal_control(
    summaries: list[dict[str, Any]],
) -> dict[str, Any]:
    totals: Counter[str] = Counter()
    by_delivery: dict[str, Counter[str]] = defaultdict(Counter)
    for summary in summaries:
        terminal_control = summary.get("pass_terminal_control", {})
        for field in (
            "terminals",
            "reached_target",
            "materially_contacted",
            "intended_receiver_contacted",
            "stable_at_terminal",
        ):
            totals[field] += int(terminal_control.get(field, 0))
        for group, counts in terminal_control.get(
            "by_length_and_delivery", {}
        ).items():
            by_delivery[group].update(
                {field: int(count) for field, count in counts.items()}
            )
    return {
        "scope": (
            "all pass_physical_terminal trace events, including direct stable control; "
            "pending-pass free-ball episodes are a conditional subset and must not be "
            "used as the denominator for terminal control"
        ),
        **dict(sorted(totals.items())),
        "direct_stable_share": round(
            totals["stable_at_terminal"] / max(totals["terminals"], 1), 4
        ),
        "by_length_and_delivery": {
            group: dict(sorted(counts.items()))
            for group, counts in sorted(by_delivery.items())
        },
    }


def _aggregate_reorient_follow_up(summaries: list[dict[str, Any]]) -> dict[str, Any]:
    next_actions: Counter[str] = Counter()
    for summary in summaries:
        next_actions.update(
            summary.get("action_pace", {})
            .get("reorient_follow_up", {})
            .get("next_action", {})
        )
    return {
        "selected": sum(
            int(
                summary.get("action_pace", {})
                .get("reorient_follow_up", {})
                .get("selected", 0)
            )
            for summary in summaries
        ),
        "same_holder_next_decision": sum(
            int(
                summary.get("action_pace", {})
                .get("reorient_follow_up", {})
                .get("same_holder_next_decision", 0)
            )
            for summary in summaries
        ),
        "consecutive_reorients": sum(
            int(
                summary.get("action_pace", {})
                .get("reorient_follow_up", {})
                .get("consecutive_reorients", 0)
            )
            for summary in summaries
        ),
        "next_action": dict(sorted(next_actions.items())),
        "per_match_turn_angle_degrees": [
            summary.get("action_pace", {})
            .get("reorient_follow_up", {})
            .get("turn_angle_degrees", {})
            for summary in summaries
        ],
        "live_same_tick": {
            field: sum(
                int(
                    summary.get("action_pace", {})
                    .get("reorient_follow_up", {})
                    .get("live_same_tick", {})
                    .get(field, 0)
                )
                for summary in summaries
            )
            for field in (
                "eligible_reorients",
                "executed_fast_passes",
                "waited",
                "release_interrupted",
                "unaccounted",
                "multiple_follow_up_action_violations",
            )
        }
        | {
            "per_match_elapsed_fraction": [
                summary.get("action_pace", {})
                .get("reorient_follow_up", {})
                .get("live_same_tick", {})
                .get("elapsed_fraction", {})
                for summary in summaries
            ]
        },
    }


def _aggregate_wide_final_third_decisions(
    summaries: list[dict[str, Any]],
) -> dict[str, Any]:
    counts: Counter[str] = Counter()
    metric_counts: Counter[str] = Counter()
    metric_sums: Counter[str] = Counter()
    for summary in summaries:
        diagnostic = summary.get("action_pace", {}).get(
            "wide_final_third_decisions", {}
        )
        counts.update(
            {key: int(value) for key, value in diagnostic.get("counts", {}).items()}
        )
        for field, values in diagnostic.get("metrics", {}).items():
            count = int(values.get("count", 0) or 0)
            mean_value = values.get("mean")
            if count > 0 and isinstance(mean_value, (int, float)):
                metric_counts[field] += count
                metric_sums[field] += count * float(mean_value)
    return {
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: {
                "count": metric_counts[field],
                "mean": round(metric_sums[field] / metric_counts[field], 6),
            }
            for field in sorted(metric_counts)
            if metric_counts[field] > 0
        },
    }


def _aggregate_first_action_after_receipt(
    summaries: Iterable[dict[str, Any]],
) -> dict[str, Any]:
    by_context: dict[str, Counter[str]] = defaultdict(Counter)
    totals: Counter[str] = Counter()
    for summary in summaries:
        contexts = (
            summary.get("action_pace", {})
            .get("pass_candidate_selection", {})
            .get("first_action_after_completed_receipt", {})
        )
        for context, data in contexts.items():
            counts = Counter(
                {action: int(count) for action, count in data.get("counts", {}).items()}
            )
            by_context[context].update(counts)
            totals.update(counts)
    observed = sum(totals.values())
    return {
        "observed_receipts": observed,
        "counts": dict(sorted(totals.items())),
        "shares": {
            action: round(count / max(observed, 1), 4)
            for action, count in sorted(totals.items())
        },
        "by_context": {
            context: {
                "observed_receipts": sum(counts.values()),
                "counts": dict(sorted(counts.items())),
            }
            for context, counts in sorted(by_context.items())
        },
        "scope": "first on-ball decision within two ticks after a physically completed pass receipt; requires decision trace",
    }


def _reorient_live_same_tick_summary(
    trace_entries: list[dict[str, Any]],
) -> dict[str, Any]:
    elapsed_fractions: list[float] = []
    remaining_fractions: list[float] = []
    required_release_fractions: list[float] = []
    flight_fractions: list[float] = []
    executed_fast_passes = 0
    waited = 0
    release_interrupted = 0
    multiple_follow_up_action_violations = 0
    unaccounted_cases: list[dict[str, Any]] = []
    waited_by_action: Counter[str] = Counter()
    waited_by_reason: Counter[str] = Counter()
    target_profile_metrics: dict[str, list[float]] = defaultdict(list)
    optimistic_turn_only_rescues = 0
    optimistic_turn_only_rescue_profiles: Counter[str] = Counter()
    target_counterfactual_by_key = {
        (entry.get("tick"), entry.get("team"), entry.get("player_idx")): entry
        for entry in trace_entries
        if entry.get("event") == "reorient_target_counterfactual"
    }
    for reorient_index, reorient in enumerate(trace_entries):
        if reorient.get("type") != "action" or reorient.get("action") != "reorient":
            continue
        elapsed_fraction = reorient.get("elapsed_fraction")
        tick = reorient.get("tick")
        team = reorient.get("team")
        player_idx = reorient.get("player_idx")
        if not (
            isinstance(elapsed_fraction, (int, float))
            and float(elapsed_fraction) < 1.0 - 1e-9
            and isinstance(tick, int)
            and team in {"home", "away"}
            and isinstance(player_idx, int)
        ):
            continue
        elapsed_fractions.append(float(elapsed_fraction))
        remaining_fractions.append(1.0 - float(elapsed_fraction))
        later_same_tick = [
            entry
            for entry in trace_entries[reorient_index + 1 :]
            if entry.get("tick") == tick
        ]
        fast_pass_index = next(
            (
                index
                for index, entry in enumerate(later_same_tick)
                if entry.get("event") == "receipt_fast_pass"
                and entry.get("holder_team") == team
                and entry.get("holder_idx") == player_idx
            ),
            None,
        )
        wait_entry = next(
            (
                entry
                for entry in later_same_tick
                if entry.get("event") == "receipt_decision_wait"
                and entry.get("holder_team") == team
                and entry.get("holder_idx") == player_idx
            ),
            None,
        )
        target_counterfactual = target_counterfactual_by_key.get(
            (tick, team, player_idx), {}
        )
        target_profiles = {
            str(candidate.get("profile")): candidate
            for candidate in target_counterfactual.get("candidates", [])
            if isinstance(candidate, dict)
        }
        outcome = "fast_pass" if fast_pass_index is not None else "wait"
        for profile in ("goal_center", "best_pass", "best_executable"):
            candidate = target_profiles.get(profile, {})
            for field in (
                "duration_seconds",
                "turn_angle_degrees",
                "score",
                "control_readiness",
            ):
                value = candidate.get(field)
                if isinstance(value, (int, float)):
                    target_profile_metrics[
                        f"{outcome}:{profile}:{field}"
                    ].append(float(value))
        if fast_pass_index is not None:
            fast_pass = later_same_tick[fast_pass_index]
            pass_actions = [
                entry
                for entry in later_same_tick[fast_pass_index + 1 :]
                if entry.get("type") == "action"
                and entry.get("action") == "pass"
                and entry.get("team") == team
                and entry.get("passer_player") == player_idx
            ]
            if pass_actions:
                executed_fast_passes += 1
                multiple_follow_up_action_violations += int(len(pass_actions) > 1)
                for field, target in (
                    ("required_release_fraction", required_release_fractions),
                    ("flight_fraction", flight_fractions),
                ):
                    value = fast_pass.get(field)
                    if isinstance(value, (int, float)):
                        target.append(float(value))
            else:
                release_interrupted += 1
        elif wait_entry is not None:
            waited += 1
            selected_action = str(wait_entry.get("selected_action") or "unknown")
            reason = str(wait_entry.get("reason") or "unknown")
            waited_by_action[selected_action] += 1
            waited_by_reason[reason] += 1
            if reason == "insufficient_release_time":
                required_release_fraction = wait_entry.get(
                    "communication_required_release_fraction"
                )
                best_pass_duration = target_profiles.get("best_pass", {}).get(
                    "duration_seconds"
                )
                if isinstance(required_release_fraction, (int, float)) and isinstance(
                    best_pass_duration, (int, float)
                ):
                    target_profile_metrics[
                        "wait:pass:required_release_fraction"
                    ].append(float(required_release_fraction))
                    target_profile_metrics[
                        "wait:pass:best_pass_duration_plus_release_fraction"
                    ].append(
                        float(best_pass_duration) + float(required_release_fraction)
                    )
                    rescued = (
                        float(best_pass_duration)
                        + float(required_release_fraction)
                        <= 1.0 + 1e-12
                    )
                    optimistic_turn_only_rescues += int(rescued)
                    if rescued:
                        selected_pass = wait_entry.get("selected_pass", {})
                        distance_m = selected_pass.get("distance_m")
                        target_kind = str(
                            selected_pass.get("target_kind") or "unknown"
                        )
                        distance_band = (
                            "0_10m"
                            if isinstance(distance_m, (int, float))
                            and float(distance_m) < 10.0
                            else "10m_plus"
                            if isinstance(distance_m, (int, float))
                            else "unknown"
                        )
                        optimistic_turn_only_rescue_profiles[
                            f"{distance_band}:{target_kind}"
                        ] += 1
        else:
            unaccounted_cases.append(
                {
                    "tick": tick,
                    "team": team,
                    "player_idx": player_idx,
                    "elapsed_fraction": round(float(elapsed_fraction), 6),
                    "later_same_tick": [
                        {
                            key: entry.get(key)
                            for key in (
                                "type", "event", "action", "reason",
                                "team", "player_idx", "holder_team",
                                "holder_idx", "ball_state",
                            )
                            if entry.get(key) is not None
                        }
                        for entry in later_same_tick
                    ],
                }
            )
    eligible_reorients = len(elapsed_fractions)
    return {
        "scope": (
            "live trace pairing of a fractional Reorient action with the later same-tick "
            "receipt_fast_pass and Pass action for the same team and player"
        ),
        "eligible_reorients": eligible_reorients,
        "executed_fast_passes": executed_fast_passes,
        "waited": waited,
        "release_interrupted": release_interrupted,
        "unaccounted": (
            eligible_reorients - executed_fast_passes - waited - release_interrupted
        ),
        "unaccounted_cases": unaccounted_cases,
        "multiple_follow_up_action_violations": multiple_follow_up_action_violations,
        "waited_by_action": dict(sorted(waited_by_action.items())),
        "waited_by_reason": dict(sorted(waited_by_reason.items())),
        "optimistic_best_pass_turn_only_rescues": optimistic_turn_only_rescues,
        "optimistic_best_pass_turn_only_rescue_profiles": dict(
            sorted(optimistic_turn_only_rescue_profiles.items())
        ),
        "target_profiles_by_outcome": {
            field: _numeric_distribution(values)
            for field, values in sorted(target_profile_metrics.items())
            if values
        },
        "elapsed_fraction": _numeric_distribution(elapsed_fractions),
        "remaining_fraction": _numeric_distribution(remaining_fractions),
        "required_release_fraction": _numeric_distribution(required_release_fractions),
        "flight_fraction": _numeric_distribution(flight_fractions),
    }


def _support_task_pass_funnel(
    decisions: list[dict[str, Any]],
) -> dict[str, Any]:
    """Relate accepted support tasks to production pass candidates and selection."""
    counts: Counter[str] = Counter()
    metrics: dict[str, list[float]] = defaultdict(list)
    by_current_distance: dict[str, Counter[str]] = defaultdict(Counter)
    by_target_distance: dict[str, Counter[str]] = defaultdict(Counter)
    by_candidate_distance: dict[str, Counter[str]] = defaultdict(Counter)
    current_distance_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    target_distance_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    candidate_distance_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    by_target_direction: dict[str, Counter[str]] = defaultdict(Counter)
    target_direction_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    by_target_direction_and_movement_intent: dict[str, Counter[str]] = defaultdict(
        Counter
    )
    target_direction_and_movement_intent_metrics: dict[
        str, dict[str, list[float]]
    ] = defaultdict(lambda: defaultdict(list))

    def distance_band(distance_m: float) -> str:
        if distance_m < 10.0:
            return "0_10m"
        if distance_m < 20.0:
            return "10_20m"
        if distance_m < 32.0:
            return "20_32m"
        return "32m_plus"

    def point(value: Any) -> tuple[float, float] | None:
        if (
            isinstance(value, list)
            and len(value) >= 2
            and isinstance(value[0], (int, float))
            and isinstance(value[1], (int, float))
        ):
            return float(value[0]), float(value[1])
        return None

    def candidate_receiver(candidate: dict[str, Any]) -> int | None:
        details = candidate.get("details", {})
        if not isinstance(details, dict):
            return None
        receiver_idx = details.get("target_player_idx")
        if not isinstance(receiver_idx, int):
            receiver_idx = details.get("intended_receiver")
        return receiver_idx if isinstance(receiver_idx, int) else None

    for decision in decisions:
        counts["decisions"] += 1
        origin = point(decision.get("pos"))
        chosen = decision.get("chosen", {})
        chosen_score = (
            chosen.get("value", {}).get("score")
            if isinstance(chosen, dict)
            else None
        )
        counterfactual = decision.get("support_task_network_counterfactual")
        tasks = (
            counterfactual.get("candidates", [])
            if isinstance(counterfactual, dict)
            else []
        )
        tasks = [
            task
            for task in tasks
            if isinstance(task, dict) and isinstance(task.get("player_idx"), int)
        ]
        if not tasks:
            counts["decisions_without_active_support_task"] += 1
            continue
        counts["decisions_with_active_support_task"] += 1
        counts["active_support_task_observations"] += len(tasks)

        candidates = [
            candidate
            for candidate in [chosen, *decision.get("alternatives", [])]
            if isinstance(candidate, dict) and candidate.get("action_type") == "pass"
        ]
        candidates_by_receiver: dict[int, list[dict[str, Any]]] = defaultdict(list)
        for candidate in candidates:
            receiver_idx = candidate_receiver(candidate)
            if receiver_idx is not None:
                candidates_by_receiver[receiver_idx].append(candidate)

        decision_task_passes: list[dict[str, Any]] = []
        task_indices = {int(task["player_idx"]) for task in tasks}
        selected_receiver = candidate_receiver(chosen) if isinstance(chosen, dict) else None
        selected_task_pass = (
            isinstance(chosen, dict)
            and chosen.get("action_type") == "pass"
            and selected_receiver in task_indices
        )
        if selected_task_pass:
            counts["decisions_selected_active_task_receiver"] += 1

        for task in tasks:
            player_idx = int(task["player_idx"])
            current_pos = point(task.get("current_pos"))
            effective_target = point(task.get("effective_target"))
            current_distance = (
                hypot(current_pos[0] - origin[0], current_pos[1] - origin[1])
                if current_pos is not None and origin is not None
                else None
            )
            target_distance = (
                hypot(
                    effective_target[0] - origin[0],
                    effective_target[1] - origin[1],
                )
                if effective_target is not None and origin is not None
                else None
            )
            remaining_move = task.get("move_distance_m")
            if not isinstance(remaining_move, (int, float)) and (
                current_pos is not None and effective_target is not None
            ):
                remaining_move = hypot(
                    effective_target[0] - current_pos[0],
                    effective_target[1] - current_pos[1],
                )
            intent = str(task.get("intent") or "unknown")
            counts[f"task_intent={intent}"] += 1
            source_goal_type = str(task.get("source_goal_type") or "none")
            source_goal_phase = str(task.get("source_goal_phase") or "none")
            movement_intent = str(task.get("movement_intent") or "unknown")
            counts[f"task_source_goal_type={source_goal_type}"] += 1
            counts[f"task_source_goal_phase={source_goal_phase}"] += 1
            counts[f"task_movement_intent={movement_intent}"] += 1
            target_forward_m = (
                (effective_target[0] - origin[0])
                * (1.0 if bool(decision.get("attacking_right")) else -1.0)
                if effective_target is not None and origin is not None
                else None
            )
            target_direction = (
                "forward"
                if isinstance(target_forward_m, (int, float))
                and float(target_forward_m) > 1e-12
                else "backward"
                if isinstance(target_forward_m, (int, float))
                and float(target_forward_m) < -1e-12
                else "lateral"
            )
            counts[f"task_target_direction={target_direction}"] += 1
            by_target_direction[target_direction]["tasks"] += 1
            by_target_direction[target_direction][f"intent={intent}"] += 1
            by_target_direction[target_direction][
                f"source_goal_type={source_goal_type}"
            ] += 1
            direction_intent_group = (
                f"direction={target_direction}:movement_intent={movement_intent}"
            )
            by_target_direction_and_movement_intent[direction_intent_group][
                "tasks"
            ] += 1
            by_target_direction_and_movement_intent[direction_intent_group][
                f"task_intent={intent}"
            ] += 1
            by_target_direction_and_movement_intent[direction_intent_group][
                f"source_goal_type={source_goal_type}"
            ] += 1
            if isinstance(target_forward_m, (int, float)):
                metrics["task_target_forward_m"].append(float(target_forward_m))
                target_direction_metrics[target_direction][
                    "task_target_forward_m"
                ].append(float(target_forward_m))
                target_direction_and_movement_intent_metrics[
                    direction_intent_group
                ]["task_target_forward_m"].append(float(target_forward_m))
            for field, value in (
                ("task_current_distance_to_holder_m", current_distance),
                ("task_target_distance_to_holder_m", target_distance),
                ("task_remaining_move_m", remaining_move),
                ("task_value_delta", task.get("value_delta")),
            ):
                if isinstance(value, (int, float)):
                    metrics[field].append(float(value))
                    target_direction_and_movement_intent_metrics[
                        direction_intent_group
                    ][field].append(float(value))

            current_band = (
                distance_band(float(current_distance))
                if isinstance(current_distance, (int, float))
                else "unknown"
            )
            target_band = (
                distance_band(float(target_distance))
                if isinstance(target_distance, (int, float))
                else "unknown"
            )
            by_current_distance[current_band]["tasks"] += 1
            by_target_distance[target_band]["tasks"] += 1
            receiver_candidates = candidates_by_receiver.get(player_idx, [])
            if not receiver_candidates:
                counts["tasks_without_pass_candidate"] += 1
                by_current_distance[current_band]["without_pass_candidate"] += 1
                by_target_distance[target_band]["without_pass_candidate"] += 1
                by_target_direction_and_movement_intent[direction_intent_group][
                    "without_pass_candidate"
                ] += 1
                continue

            counts["tasks_with_pass_candidate"] += 1
            by_current_distance[current_band]["with_pass_candidate"] += 1
            by_target_distance[target_band]["with_pass_candidate"] += 1
            by_target_direction_and_movement_intent[direction_intent_group][
                "with_pass_candidate"
            ] += 1
            best = max(
                receiver_candidates,
                key=lambda candidate: float(
                    candidate.get("value", {}).get("score", float("-inf"))
                ),
            )
            decision_task_passes.append(best)
            feet_candidates = [
                candidate
                for candidate in receiver_candidates
                if candidate.get("value", {})
                .get("components", {})
                .get("target_kind")
                == "feet"
            ]
            if feet_candidates:
                counts["tasks_with_feet_candidate"] += 1
                by_target_direction_and_movement_intent[direction_intent_group][
                    "with_feet_candidate"
                ] += 1
                best_feet = max(
                    feet_candidates,
                    key=lambda candidate: float(
                        candidate.get("value", {}).get(
                            "score", float("-inf")
                        )
                    ),
                )
                best_feet_value = best_feet.get("value", {})
                best_feet_components = best_feet_value.get("components", {})
                best_feet_target = point(best_feet.get("target"))
                feet_distance = (
                    hypot(
                        best_feet_target[0] - origin[0],
                        best_feet_target[1] - origin[1],
                    )
                    if best_feet_target is not None and origin is not None
                    else None
                )
                feet_task_gap = (
                    hypot(
                        best_feet_target[0] - effective_target[0],
                        best_feet_target[1] - effective_target[1],
                    )
                    if best_feet_target is not None and effective_target is not None
                    else None
                )
                feet_score = best_feet_value.get("score")
                feet_selected = best_feet is chosen
                by_current_distance[current_band]["with_feet_candidate"] += 1
                by_target_distance[target_band]["with_feet_candidate"] += 1
                if feet_selected:
                    counts["tasks_best_feet_selected"] += 1
                    by_current_distance[current_band]["best_feet_selected"] += 1
                    by_target_distance[target_band]["best_feet_selected"] += 1
                    by_target_direction_and_movement_intent[
                        direction_intent_group
                    ]["best_feet_selected"] += 1
                else:
                    counts["tasks_best_feet_not_selected"] += 1
                for field, value in (
                    ("task_feet_pass_distance_m", feet_distance),
                    ("task_feet_pass_score", feet_score),
                    (
                        "task_feet_pass_minus_chosen",
                        float(feet_score) - float(chosen_score)
                        if isinstance(feet_score, (int, float))
                        and isinstance(chosen_score, (int, float))
                        else None,
                    ),
                    (
                        "task_feet_pass_retention",
                        best_feet_value.get("success_prob"),
                    ),
                    (
                        "task_feet_pass_receiver_to_target_distance_m",
                        best_feet.get("details", {})
                        .get("receiver_motion", {})
                        .get("receiver_to_target_distance_m"),
                    ),
                    (
                        "task_feet_pass_to_effective_task_target_gap_m",
                        feet_task_gap,
                    ),
                    (
                        "task_feet_pass_after_value",
                        best_feet_components.get("after_value"),
                    ),
                    (
                        "task_feet_pass_option_return",
                        best_feet_components.get("option_return"),
                    ),
                    (
                        "task_feet_pass_local_shaping",
                        best_feet_components.get("local_shaping"),
                    ),
                    (
                        "task_feet_pass_receiver_arrival",
                        best_feet_components.get("receiver_arrival"),
                    ),
                    (
                        "task_feet_pass_control_readiness",
                        best_feet_components.get("projected_retained_state", {})
                        .get("control_readiness"),
                    ),
                    (
                        "task_feet_pass_control_residual",
                        best_feet_components.get("projected_retained_state", {})
                        .get("control_residual"),
                    ),
                    (
                        "task_feet_pass_continuation_xg",
                        best_feet_components.get("projected_retained_state", {})
                        .get("continuation_xg"),
                    ),
                    (
                        "task_feet_pass_outlet_access",
                        best_feet_components.get("projected_retained_state", {})
                        .get("outlet_access"),
                    ),
                ):
                    if isinstance(value, (int, float)):
                        metrics[field].append(float(value))
                        current_distance_metrics[current_band][field].append(
                            float(value)
                        )
                        target_distance_metrics[target_band][field].append(
                            float(value)
                        )
                        target_direction_and_movement_intent_metrics[
                            direction_intent_group
                        ][field].append(float(value))
            best_target = point(best.get("target"))
            candidate_distance = (
                hypot(best_target[0] - origin[0], best_target[1] - origin[1])
                if best_target is not None and origin is not None
                else None
            )
            candidate_band = (
                distance_band(float(candidate_distance))
                if isinstance(candidate_distance, (int, float))
                else "unknown"
            )
            by_candidate_distance[candidate_band]["tasks_with_candidate"] += 1
            details = best.get("details", {})
            target_kind = (
                best.get("value", {}).get("components", {}).get("target_kind")
            )
            counts[f"task_pass_target_kind={target_kind or 'unknown'}"] += 1
            best_is_selected = best is chosen
            candidate_forward_m = (
                (best_target[0] - origin[0])
                * (1.0 if bool(decision.get("attacking_right")) else -1.0)
                if best_target is not None and origin is not None
                else None
            )
            candidate_direction = (
                "forward"
                if isinstance(candidate_forward_m, (int, float))
                and float(candidate_forward_m) > 1e-12
                else "backward"
                if isinstance(candidate_forward_m, (int, float))
                and float(candidate_forward_m) < -1e-12
                else "lateral"
            )
            counts[
                f"task_target_direction={target_direction}:candidate_direction={candidate_direction}"
            ] += 1
            by_target_direction[target_direction][
                f"candidate_direction={candidate_direction}"
            ] += 1
            if best_is_selected:
                counts["tasks_selected_as_receiver"] += 1
                by_current_distance[current_band]["selected"] += 1
                by_target_distance[target_band]["selected"] += 1
                by_target_direction[target_direction]["selected"] += 1
                by_target_direction[target_direction][
                    f"selected_candidate_direction={candidate_direction}"
                ] += 1
                by_candidate_distance[candidate_band]["selected"] += 1
                by_target_direction_and_movement_intent[direction_intent_group][
                    "selected"
                ] += 1
            else:
                counts["tasks_not_selected_as_receiver"] += 1

            best_score = best.get("value", {}).get("score")
            receiver_offset = (
                details.get("receiver_motion", {}).get(
                    "receiver_to_target_distance_m"
                )
                if isinstance(details, dict)
                else None
            )
            task_target_gap = (
                hypot(
                    best_target[0] - effective_target[0],
                    best_target[1] - effective_target[1],
                )
                if best_target is not None and effective_target is not None
                else None
            )
            for field, value in (
                ("task_pass_distance_m", candidate_distance),
                ("task_pass_score", best_score),
                ("task_pass_retention", best.get("value", {}).get("success_prob")),
                ("task_pass_receiver_to_target_distance_m", receiver_offset),
                ("task_pass_to_effective_task_target_gap_m", task_target_gap),
                ("task_pass_forward_m", candidate_forward_m),
                (
                    "task_pass_minus_chosen",
                    float(best_score) - float(chosen_score)
                    if isinstance(best_score, (int, float))
                    and isinstance(chosen_score, (int, float))
                    else None,
                ),
            ):
                if isinstance(value, (int, float)):
                    metrics[field].append(float(value))
                    current_distance_metrics[current_band][field].append(float(value))
                    target_distance_metrics[target_band][field].append(float(value))
                    candidate_distance_metrics[candidate_band][field].append(float(value))
                    target_direction_metrics[target_direction][field].append(float(value))
                    target_direction_and_movement_intent_metrics[
                        direction_intent_group
                    ][field].append(float(value))

        if not decision_task_passes:
            counts["decisions_without_task_receiver_pass_candidate"] += 1
            continue
        counts["decisions_with_task_receiver_pass_candidate"] += 1
        best_task_pass = max(
            decision_task_passes,
            key=lambda candidate: float(
                candidate.get("value", {}).get("score", float("-inf"))
            ),
        )
        if best_task_pass is chosen:
            counts["decisions_best_task_pass_selected"] += 1
        else:
            counts["decisions_best_task_pass_not_selected"] += 1
            best_score = best_task_pass.get("value", {}).get("score")
            if isinstance(best_score, (int, float)) and isinstance(
                chosen_score, (int, float)
            ):
                counts[
                    "decisions_unselected_task_pass_beats_chosen"
                    if float(best_score) > float(chosen_score) + 1e-12
                    else "decisions_unselected_task_pass_not_better"
                ] += 1

    def grouped_payload(
        groups: dict[str, Counter[str]],
        group_metrics: dict[str, dict[str, list[float]]],
    ) -> dict[str, dict[str, Any]]:
        return {
            band: {
                "counts": dict(sorted(groups[band].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(group_metrics[band].items())
                    if values
                },
            }
            for band in ("0_10m", "10_20m", "20_32m", "32m_plus", "unknown")
            if groups.get(band) or group_metrics.get(band)
        }

    return {
        "scope": (
            "read-only per-decision join from perceived active accepted Receive/Support "
            "tasks to the production pass candidate pool by player_idx; no candidate, "
            "score, selection, execution, or RNG is changed"
        ),
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
        "by_task_current_distance": grouped_payload(
            by_current_distance, current_distance_metrics
        ),
        "by_task_target_distance": grouped_payload(
            by_target_distance, target_distance_metrics
        ),
        "by_best_candidate_distance": grouped_payload(
            by_candidate_distance, candidate_distance_metrics
        ),
        "by_task_target_direction": {
            direction: {
                "counts": dict(sorted(by_target_direction[direction].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(
                        target_direction_metrics[direction].items()
                    )
                    if values
                },
            }
            for direction in ("forward", "backward", "lateral")
            if by_target_direction.get(direction)
            or target_direction_metrics.get(direction)
        },
        "by_task_target_direction_and_movement_intent": {
            group: {
                "counts": dict(
                    sorted(by_target_direction_and_movement_intent[group].items())
                ),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(
                        target_direction_and_movement_intent_metrics[group].items()
                    )
                    if values
                },
            }
            for group in sorted(
                set(by_target_direction_and_movement_intent)
                | set(target_direction_and_movement_intent_metrics)
            )
        },
    }


def _selected_pass_release_funnel(
    decisions: list[dict[str, Any]],
    trace_entries: list[dict[str, Any]],
) -> dict[str, Any]:
    """Close chosen Pass decisions against physical pass-release actions."""
    selected = [
        decision
        for decision in decisions
        if decision.get("chosen", {}).get("action_type") == "pass"
    ]
    releases = [
        entry
        for entry in trace_entries
        if entry.get("action") == "pass"
        and isinstance(entry.get("tick"), int)
        and entry.get("team") in {"home", "away"}
        and isinstance(entry.get("passer_player"), int)
    ]
    release_counts = Counter(
        (entry.get("tick"), entry.get("team"), entry.get("passer_player"))
        for entry in releases
    )
    original_release_counts = release_counts.copy()
    selected_counts = Counter(
        (decision.get("tick"), decision.get("team"), decision.get("player_idx"))
        for decision in selected
    )
    selected_offsets: Counter[tuple[Any, Any, Any]] = Counter()
    events_by_tick: dict[int, list[dict[str, Any]]] = defaultdict(list)
    for entry in trace_entries:
        tick = entry.get("tick")
        if isinstance(tick, int):
            events_by_tick[tick].append(entry)

    counts: Counter[str] = Counter()
    metrics: dict[str, list[float]] = defaultdict(list)
    unmatched_cases: list[dict[str, Any]] = []

    def distance_band(distance_m: float) -> str:
        if distance_m < 10.0:
            return "0_10m"
        if distance_m < 20.0:
            return "10_20m"
        if distance_m < 32.0:
            return "20_32m"
        return "32m_plus"

    for decision in selected:
        tick = decision.get("tick")
        team = decision.get("team")
        player_idx = decision.get("player_idx")
        key = (tick, team, player_idx)
        selected_ordinal = selected_offsets[key]
        selected_offsets[key] += 1
        chosen = decision.get("chosen", {})
        origin = decision.get("pos")
        target = chosen.get("target")
        distance_m = (
            hypot(
                float(target[0]) - float(origin[0]),
                float(target[1]) - float(origin[1]),
            )
            if isinstance(target, list)
            and len(target) >= 2
            and isinstance(origin, list)
            and len(origin) >= 2
            and all(isinstance(value, (int, float)) for value in target[:2] + origin[:2])
            else None
        )
        band = distance_band(distance_m) if isinstance(distance_m, float) else "unknown"
        target_kind = str(
            chosen.get("value", {}).get("components", {}).get("target_kind")
            or "unknown"
        )
        source = str(chosen.get("source") or "unknown")
        counts["selected"] += 1
        counts[f"selected:distance={band}"] += 1
        counts[f"selected:target={target_kind}"] += 1
        counts[f"selected:source={source}"] += 1
        if isinstance(distance_m, float):
            metrics["selected_distance_m"].append(distance_m)

        if release_counts[key] > 0:
            release_counts[key] -= 1
            counts["released"] += 1
            counts[f"released:distance={band}"] += 1
            counts[f"released:target={target_kind}"] += 1
            continue

        counts["not_released"] += 1
        counts[f"not_released:distance={band}"] += 1
        counts[f"not_released:target={target_kind}"] += 1
        if isinstance(distance_m, float):
            metrics["not_released_distance_m"].append(distance_m)
        same_tick = events_by_tick.get(tick, []) if isinstance(tick, int) else []
        evidence = []
        reasons: list[str] = []
        for entry in same_tick:
            same_actor = (
                entry.get("team") == team
                and entry.get("player_idx") == player_idx
            ) or (
                entry.get("holder_team") == team
                and entry.get("holder_idx") == player_idx
            ) or (
                entry.get("holder_team_home") == (team == "home")
                and entry.get("holder_idx") == player_idx
            )
            if not same_actor:
                continue
            label = entry.get("event", entry.get("action"))
            if not isinstance(label, str):
                continue
            reason = entry.get("reason")
            outcome = entry.get("outcome")
            detail = ":".join(
                str(value) for value in (label, reason, outcome) if value is not None
            )
            evidence.append(detail)
            if label == "receipt_decision_wait":
                reasons.append(f"receipt_wait:{reason or 'unknown'}")
            elif label in {
                "duel", "tackle", "foul", "shot_abandoned",
                "action_commitment_ended", "restart", "period_end",
            }:
                reasons.append(f"{label}:{outcome or reason or 'observed'}")
        if not reasons:
            opponent = "away" if team == "home" else "home" if team == "away" else None
            if opponent is not None:
                opposing_foul = next(
                    (
                        entry
                        for entry in same_tick
                        if entry.get("event") == "foul"
                        and entry.get("team") == opponent
                    ),
                    None,
                )
                if opposing_foul is not None:
                    reasons.append("foul:opponent_committed")
        reason = reasons[0] if reasons else "unattributed"
        counts[f"not_released:reason={reason}"] += 1
        if len(unmatched_cases) < 20:
            tick_window = []
            if isinstance(tick, int):
                for window_tick in range(tick, tick + 3):
                    for entry in events_by_tick.get(window_tick, []):
                        label = entry.get("event", entry.get("action", entry.get("type")))
                        if not isinstance(label, str):
                            continue
                        tick_window.append({
                            "tick": window_tick,
                            "label": label,
                            "team": entry.get("team", entry.get("holder_team")),
                            "player_idx": entry.get(
                                "player_idx",
                                entry.get("passer_player", entry.get("holder_idx")),
                            ),
                            "reason": entry.get("reason"),
                            "outcome": entry.get("outcome"),
                            "ball_state_before": entry.get("ball_state_before"),
                            "ball_state": entry.get("ball_state"),
                            "possession_id_before": entry.get("possession_id_before"),
                            "possession_id": entry.get("possession_id"),
                            "holder_team": entry.get("holder_team"),
                        })
            unmatched_cases.append({
                "tick": tick,
                "team": team,
                "player_idx": player_idx,
                "possession_id": decision.get("possession_id"),
                "distance_band": band,
                "distance_m": distance_m,
                "target_kind": target_kind,
                "source": source,
                "score": chosen.get("value", {}).get("score"),
                "reason": reason,
                "same_actor_tick_selected_passes": selected_counts[key],
                "same_actor_tick_pass_releases": original_release_counts[key],
                "selected_pass_ordinal": selected_ordinal,
                "same_tick_evidence": evidence,
                "tick_window": tick_window,
            })

    unmatched_release_count = sum(release_counts.values())
    counts["release_actions"] = len(releases)
    counts["release_actions_without_selected_decision"] = unmatched_release_count
    return {
        "scope": (
            "multiset closure by tick, team, and passer between full-trace chosen Pass "
            "decisions and physical pass action entries; unmatched reasons are same-tick "
            "evidence labels and do not infer hidden causality"
        ),
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
        "not_released_cases": unmatched_cases,
    }


def _physical_short_pass_availability_funnel(
    decisions: list[dict[str, Any]],
    trace_entries: list[dict[str, Any]],
) -> dict[str, Any]:
    """Join physical nearby teammates to belief, candidate, choice, and release."""
    contexts_by_key: dict[tuple[Any, Any, Any], list[dict[str, Any]]] = defaultdict(list)
    for entry in trace_entries:
        if entry.get("event") != "on_ball_candidate_counts":
            continue
        contexts_by_key[(
            entry.get("tick"), entry.get("team"), entry.get("player_idx")
        )].append(entry)
    context_offsets: Counter[tuple[Any, Any, Any]] = Counter()
    release_counts = Counter(
        (entry.get("tick"), entry.get("team"), entry.get("passer_player"))
        for entry in trace_entries
        if entry.get("action") == "pass"
        and isinstance(entry.get("tick"), int)
        and entry.get("team") in {"home", "away"}
        and isinstance(entry.get("passer_player"), int)
    )
    counts: Counter[str] = Counter()
    metrics: dict[str, list[float]] = defaultdict(list)
    by_pressure: dict[str, Counter[str]] = defaultdict(Counter)
    by_pressure_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )

    def point(value: Any) -> tuple[float, float] | None:
        if (
            isinstance(value, list)
            and len(value) >= 2
            and isinstance(value[0], (int, float))
            and isinstance(value[1], (int, float))
        ):
            return float(value[0]), float(value[1])
        return None

    def candidate_receiver(candidate: dict[str, Any]) -> int | None:
        details = candidate.get("details", {})
        if not isinstance(details, dict):
            return None
        receiver = details.get("target_player_idx")
        if not isinstance(receiver, int):
            receiver = details.get("intended_receiver")
        return receiver if isinstance(receiver, int) else None

    def pressure_band(value: Any) -> str:
        if not isinstance(value, (int, float)):
            return "unknown"
        pressure = float(value)
        if pressure < 0.2:
            return "0_0.2"
        if pressure < 0.4:
            return "0.2_0.4"
        if pressure < 0.6:
            return "0.4_0.6"
        if pressure < 0.8:
            return "0.6_0.8"
        return "0.8_1.0"

    for decision in decisions:
        key = (decision.get("tick"), decision.get("team"), decision.get("player_idx"))
        offset = context_offsets[key]
        context_offsets[key] += 1
        contexts = contexts_by_key.get(key, [])
        context = contexts[offset] if offset < len(contexts) else None
        counts["decisions"] += 1
        if not isinstance(context, dict):
            counts["decisions_missing_candidate_context"] += 1
            continue
        counts["decisions_with_candidate_context"] += 1
        holder_pos = point(decision.get("pos"))
        if holder_pos is None:
            counts["decisions_missing_holder_position"] += 1
            continue
        pressure = decision.get("control", {}).get("pressure_load")
        band = pressure_band(pressure)
        by_pressure[band]["decisions"] += 1
        if isinstance(pressure, (int, float)):
            metrics["holder_pressure_load"].append(float(pressure))

        candidates = [
            candidate
            for candidate in [
                decision.get("chosen", {}), *decision.get("alternatives", [])
            ]
            if isinstance(candidate, dict) and candidate.get("action_type") == "pass"
        ]
        candidates_by_receiver: dict[int, list[dict[str, Any]]] = defaultdict(list)
        for candidate in candidates:
            receiver = candidate_receiver(candidate)
            if receiver is not None:
                candidates_by_receiver[receiver].append(candidate)
        chosen = decision.get("chosen", {})
        chosen_score = chosen.get("value", {}).get("score")
        chosen_receiver = candidate_receiver(chosen) if isinstance(chosen, dict) else None
        chosen_target = point(chosen.get("target")) if isinstance(chosen, dict) else None
        chosen_near_feet = (
            chosen.get("action_type") == "pass"
            and chosen.get("value", {}).get("components", {}).get("target_kind")
            == "feet"
            and chosen_target is not None
            and hypot(chosen_target[0] - holder_pos[0], chosen_target[1] - holder_pos[1])
            < 10.0
        )
        selected_released = False
        if chosen_near_feet and release_counts[key] > 0:
            release_counts[key] -= 1
            selected_released = True

        visibility_by_index = {
            row.get("idx"): row
            for row in context.get("teammate_visibility", [])
            if isinstance(row, dict) and isinstance(row.get("idx"), int)
        }
        communicated_indices = {
            row.get("idx")
            for row in context.get("communicated_teammates", [])
            if isinstance(row, dict) and isinstance(row.get("idx"), int)
        }
        physical_rows = []
        for teammate in context.get("teammate_goals", []):
            if not isinstance(teammate, dict) or not isinstance(teammate.get("idx"), int):
                continue
            teammate_pos = point(teammate.get("pos"))
            if teammate_pos is None:
                continue
            distance_m = hypot(
                teammate_pos[0] - holder_pos[0], teammate_pos[1] - holder_pos[1]
            )
            if distance_m >= 10.0:
                continue
            physical_rows.append((teammate, distance_m))
        counts[
            "decisions_with_physical_teammate_under_10m"
            if physical_rows
            else "decisions_without_physical_teammate_under_10m"
        ] += 1
        by_pressure[band][
            "with_physical_teammate_under_10m"
            if physical_rows
            else "without_physical_teammate_under_10m"
        ] += 1
        metrics["physical_teammates_under_10m_per_decision"].append(
            float(len(physical_rows))
        )

        decision_has_perceived_near = False
        decision_has_receiver_candidate = False
        decision_has_near_feet = False
        decision_has_safe_near_feet = False
        for teammate, physical_distance in physical_rows:
            receiver_idx = int(teammate["idx"])
            physical_distance_band = (
                "under_3m" if physical_distance < 3.0 else "3_10m"
            )
            counts["physical_teammate_observations_under_10m"] += 1
            counts[
                f"physical_teammate_distance={physical_distance_band}"
            ] += 1
            by_pressure[band]["physical_teammate_observations_under_10m"] += 1
            metrics["physical_teammate_distance_m"].append(physical_distance)
            by_pressure_metrics[band]["physical_teammate_distance_m"].append(
                physical_distance
            )
            visibility = visibility_by_index.get(receiver_idx, {})
            belief_confidence = visibility.get("belief_confidence")
            in_belief = (
                isinstance(belief_confidence, (int, float))
                and float(belief_confidence) >= 0.08
            )
            communicated = receiver_idx in communicated_indices
            counts[
                "physical_near_in_holder_belief"
                if in_belief
                else "physical_near_missing_from_holder_belief"
            ] += 1
            by_pressure[band][
                "physical_near_in_holder_belief"
                if in_belief
                else "physical_near_missing_from_holder_belief"
            ] += 1
            if communicated:
                counts["physical_near_with_communication_hint"] += 1
            if isinstance(belief_confidence, (int, float)):
                metrics["physical_near_belief_confidence"].append(
                    float(belief_confidence)
                )
            belief_error = visibility.get("belief_position_error_m")
            if isinstance(belief_error, (int, float)):
                metrics["physical_near_belief_position_error_m"].append(
                    float(belief_error)
                )
            if in_belief:
                decision_has_perceived_near = True

            receiver_candidates = candidates_by_receiver.get(receiver_idx, [])
            if not receiver_candidates:
                counts[
                    "physical_near_in_belief_without_receiver_candidate"
                    if in_belief
                    else "physical_near_missing_belief_without_receiver_candidate"
                ] += 1
                continue
            decision_has_receiver_candidate = True
            counts["physical_near_with_receiver_candidate"] += 1
            exact_feet_candidates = []
            for candidate in receiver_candidates:
                target = point(candidate.get("target"))
                receiver_pos = point(teammate.get("pos"))
                if (
                    target is None
                    or receiver_pos is None
                    or candidate.get("value", {})
                    .get("components", {})
                    .get("target_kind")
                    != "feet"
                ):
                    continue
                target_offset = hypot(
                    target[0] - receiver_pos[0],
                    target[1] - receiver_pos[1],
                )
                if target_offset <= 0.5:
                    exact_feet_candidates.append(candidate)
            counts[
                f"physical_near_{physical_distance_band}_with_exact_feet_candidate"
                if exact_feet_candidates
                else f"physical_near_{physical_distance_band}_without_exact_feet_candidate"
            ] += 1
            if exact_feet_candidates:
                counts["physical_near_with_exact_feet_candidate"] += 1
                best_exact_feet = max(
                    exact_feet_candidates,
                    key=lambda candidate: float(
                        candidate.get("value", {}).get("score", float("-inf"))
                    ),
                )
                exact_value = best_exact_feet.get("value", {})
                exact_components = exact_value.get("components", {})
                for field, sample in (
                    ("exact_feet_score", exact_value.get("score")),
                    ("exact_feet_retention", exact_value.get("success_prob")),
                    (
                        "exact_feet_receiver_arrival",
                        exact_components.get("receiver_arrival"),
                    ),
                    (
                        "exact_feet_unresolved",
                        exact_components
                        .get("outcome_transition", {})
                        .get("unresolved_probability"),
                    ),
                    (
                        "exact_feet_minus_chosen",
                        float(exact_value["score"]) - float(chosen_score)
                        if isinstance(exact_value.get("score"), (int, float))
                        and isinstance(chosen_score, (int, float))
                        else None,
                    ),
                ):
                    if isinstance(sample, (int, float)):
                        metrics[field].append(float(sample))
                        metrics[
                            f"physical_distance={physical_distance_band}:{field}"
                        ].append(float(sample))
            near_feet_candidates = []
            for candidate in receiver_candidates:
                target = point(candidate.get("target"))
                if (
                    target is None
                    or candidate.get("value", {})
                    .get("components", {})
                    .get("target_kind")
                    != "feet"
                ):
                    continue
                candidate_distance = hypot(
                    target[0] - holder_pos[0], target[1] - holder_pos[1]
                )
                if candidate_distance < 10.0:
                    near_feet_candidates.append(candidate)
            if not near_feet_candidates:
                counts["physical_near_with_receiver_candidate_without_near_feet"] += 1
                continue
            decision_has_near_feet = True
            counts["physical_near_with_near_feet_candidate"] += 1
            best = max(
                near_feet_candidates,
                key=lambda candidate: float(
                    candidate.get("value", {}).get("score", float("-inf"))
                ),
            )
            value = best.get("value", {})
            components = value.get("components", {})
            retention = value.get("success_prob")
            safe = isinstance(retention, (int, float)) and float(retention) >= 0.85
            counts[
                "physical_near_with_safe_near_feet_candidate"
                if safe
                else "physical_near_with_unsafe_near_feet_candidate"
            ] += 1
            if safe:
                decision_has_safe_near_feet = True
                chosen_action = str(chosen.get("action_type") or "unknown")
                counts[f"safe_near_feet:chosen={chosen_action}"] += 1
                selected_same_candidate = (
                    chosen_near_feet and chosen_receiver == receiver_idx
                )
                counts[
                    "safe_near_feet:selected"
                    if selected_same_candidate
                    else "safe_near_feet:not_selected"
                ] += 1
                chosen_value = chosen.get("value", {})
                chosen_components = chosen_value.get("components", {})
                for field in (
                    "option_return",
                    "continuation_return",
                    "local_shaping",
                    "policy_value",
                    "temporal_discount",
                    "option_duration_seconds",
                    "after_value",
                    "current_value",
                    "effective_current_value",
                ):
                    near_sample = components.get(field)
                    chosen_sample = chosen_components.get(field)
                    if isinstance(near_sample, (int, float)):
                        metrics[f"safe_near_feet:{field}"].append(
                            float(near_sample)
                        )
                    if isinstance(near_sample, (int, float)) and isinstance(
                        chosen_sample, (int, float)
                    ):
                        metrics[
                            f"safe_near_feet_minus_chosen:{field}"
                        ].append(float(near_sample) - float(chosen_sample))
            for field, sample in (
                ("near_feet_score", value.get("score")),
                ("near_feet_retention", retention),
                ("near_feet_receiver_arrival", components.get("receiver_arrival")),
                ("near_feet_receiver_pressure", components.get("receiver_pressure")),
                (
                    "near_feet_minus_chosen",
                    float(value["score"]) - float(chosen_score)
                    if isinstance(value.get("score"), (int, float))
                    and isinstance(chosen_score, (int, float))
                    else None,
                ),
            ):
                if isinstance(sample, (int, float)):
                    metrics[field].append(float(sample))
                    by_pressure_metrics[band][field].append(float(sample))
            selected_for_receiver = chosen_near_feet and chosen_receiver == receiver_idx
            if selected_for_receiver:
                counts["physical_near_selected_near_feet"] += 1
                if selected_released:
                    counts["physical_near_released_near_feet"] += 1

        for label, present in (
            ("perceived_physical_near", decision_has_perceived_near),
            ("physical_near_receiver_candidate", decision_has_receiver_candidate),
            ("physical_near_feet_candidate", decision_has_near_feet),
            ("physical_safe_near_feet_candidate", decision_has_safe_near_feet),
        ):
            if present:
                counts[f"decisions_with_{label}"] += 1
                by_pressure[band][f"with_{label}"] += 1

    return {
        "scope": (
            "truth-world teammates physically under 10m at each on-ball decision joined "
            "by player index to the holder visual belief (the pass-scratch boundary), "
            "production receiver candidates, 0-10m feet candidates, bounded-rational "
            "choice, and physical release; communication hints are reported separately "
            "and never treated as visual entities"
        ),
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
        "by_holder_pressure": {
            band: {
                "counts": dict(sorted(by_pressure[band].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(by_pressure_metrics[band].items())
                    if values
                },
            }
            for band in sorted(by_pressure)
        },
    }


def _communication_pass_counterfactual_summary(
    trace_entries: list[dict[str, Any]],
    decisions: Iterable[dict[str, Any]] = (),
    events: Iterable[dict[str, Any]] = (),
) -> dict[str, Any]:
    """Aggregate read-only pass candidates built from communication hints."""
    counts: Counter[str] = Counter()
    metrics: dict[str, list[float]] = defaultdict(list)
    by_role_counts: dict[str, Counter[str]] = defaultdict(Counter)
    by_role_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    by_distance_counts: dict[str, Counter[str]] = defaultdict(Counter)
    by_distance_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    admission_counts: Counter[str] = Counter()
    admission_metrics: dict[str, list[float]] = defaultdict(list)
    admission_cases: list[dict[str, Any]] = []
    admission_rows_by_profile_identity: dict[
        tuple[Any, Any, Any, str], dict[str, Any]
    ] = {}
    decision_by_identity = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")): decision
        for decision in decisions
        if isinstance(decision, dict)
    }
    safe_beating_under_10m_cases: list[dict[str, Any]] = []

    metric_fields = (
        "value",
        "minus_actual_temporal_best",
        "retention",
        "distance_m",
        "hint_distance_m",
        "hint_age_ticks",
        "hint_confidence",
        "actual_position_error_m",
    )
    for entry in trace_entries:
        if entry.get("event") != "single_communication_pass_admission_counterfactual":
            continue
        profile = str(entry.get("profile") or "static_feet")
        option_identity = entry.get("option", {})
        admission = entry.get("admission", {})
        option = admission.get("option", {})
        family_stage = admission.get("family_stage", {})
        progress_m = option_identity.get("progress_m")
        direction = (
            "forward"
            if isinstance(progress_m, (int, float)) and float(progress_m) > 1e-12
            else "backward"
            if isinstance(progress_m, (int, float)) and float(progress_m) < -1e-12
            else "lateral"
        )
        distance_m = option_identity.get("distance_m")
        distance_band = (
            "0_10m"
            if isinstance(distance_m, (int, float)) and float(distance_m) < 10.0
            else "10_32m"
            if isinstance(distance_m, (int, float)) and float(distance_m) < 32.0
            else "32m_plus"
            if isinstance(distance_m, (int, float))
            else "unknown"
        )
        role = str(option_identity.get("receiver_role") or "unknown")
        actual_best = str(entry.get("actual_best_action") or "unknown")
        option_near = option.get("near_optimal") is True
        family_near = family_stage.get("counterfactual_pass_near_optimal") is True
        overall_probability = option.get("overall_selection_probability")
        selectable = (
            option_near
            and family_near
            and isinstance(overall_probability, (int, float))
            and float(overall_probability) > 1e-12
        )
        profile_identity = (
            entry.get("tick"),
            entry.get("team"),
            entry.get("player_idx"),
            profile,
        )
        profile_row = {
            "tick": entry.get("tick"),
            "team": entry.get("team"),
            "player_idx": entry.get("player_idx"),
            "profile": profile,
            "selectable": selectable,
            "option_near": option_near,
            "family_near": family_near,
            "overall_probability": (
                float(overall_probability)
                if isinstance(overall_probability, (int, float))
                else 0.0
            ),
            "distance_band": distance_band,
            "actual_best": actual_best,
        }
        previous_profile_row = admission_rows_by_profile_identity.get(profile_identity)
        if (
            previous_profile_row is None
            or profile_row["overall_probability"]
            > previous_profile_row["overall_probability"]
        ):
            admission_rows_by_profile_identity[profile_identity] = profile_row
        admission_counts["decisions"] += 1
        admission_counts["within_pass_family"] += int(option_near)
        admission_counts["pass_family_admitted"] += int(family_near)
        admission_counts["selectable_overall"] += int(selectable)
        admission_counts[f"profile={profile}:decisions"] += 1
        admission_counts[f"profile={profile}:within_pass_family"] += int(option_near)
        admission_counts[f"profile={profile}:selectable_overall"] += int(selectable)
        for group in (
            f"actual_best={actual_best}",
            f"direction={direction}",
            f"distance={distance_band}",
            f"receiver_role={role}",
            f"profile={profile}:direction={direction}",
            f"profile={profile}:distance={distance_band}",
            f"profile={profile}:actual_best={actual_best}",
        ):
            admission_counts[f"{group}:decisions"] += 1
            admission_counts[f"{group}:selectable_overall"] += int(selectable)
        for prefix, payload, fields in (
            (
                "option",
                option,
                (
                    "raw_score_gap_to_actual_best",
                    "conditional_pass_family_probability",
                    "overall_selection_probability",
                    "retained_control_probability",
                    "opposing_control_probability",
                    "unresolved_probability",
                ),
            ),
            (
                "family",
                family_stage,
                (
                    "current_pass_probability",
                    "counterfactual_pass_probability",
                    "ground_overall_probability_displaced",
                ),
            ),
            (
                "identity",
                option_identity,
                (
                    "distance_m",
                    "progress_m",
                    "hint_age_ticks",
                    "hint_confidence",
                    "actual_position_error_m",
                ),
            ),
        ):
            for field in fields:
                value = payload.get(field) if isinstance(payload, dict) else None
                if isinstance(value, (int, float)):
                    admission_metrics[f"{prefix}_{field}"].append(float(value))
                    admission_metrics[f"direction={direction}:{prefix}_{field}"].append(
                        float(value)
                    )
                    admission_metrics[
                        f"profile={profile}:{prefix}_{field}"
                    ].append(float(value))
                    admission_metrics[
                        f"profile={profile}:direction={direction}:{prefix}_{field}"
                    ].append(float(value))
        if selectable:
            admission_cases.append({
                "tick": entry.get("tick"),
                "team": entry.get("team"),
                "player_idx": entry.get("player_idx"),
                "player_position": entry.get("player_position"),
                "actual_best_action": actual_best,
                "actual_best_source": entry.get("actual_best_source"),
                "profile": profile,
                "direction": direction,
                "distance_band": distance_band,
                "option": option_identity,
                "admission": admission,
            })
    for entry in trace_entries:
        if entry.get("event") != "communication_pass_counterfactual":
            continue
        counts["events"] += 1
        counts["decisions"] += 1
        candidates = entry.get("candidates")
        if not isinstance(candidates, list):
            counts["events_with_malformed_candidates"] += 1
            continue
        counts[
            "events_with_candidates" if candidates else "events_without_candidates"
        ] += 1
        task_candidates = entry.get("task_space_candidates")
        if isinstance(task_candidates, list):
            counts["task_space_events_with_candidates"] += int(bool(task_candidates))
            counts["task_space_candidates"] += len(task_candidates)
            counts["task_space_forward_candidates"] += sum(
                isinstance(candidate, dict)
                and isinstance(candidate.get("progress_m"), (int, float))
                and float(candidate["progress_m"]) > 1e-12
                for candidate in task_candidates
            )
            counts["task_space_candidates_beating_actual_temporal_best"] += sum(
                isinstance(candidate, dict)
                and isinstance(
                    candidate.get("minus_actual_temporal_best"), (int, float)
                )
                and float(candidate["minus_actual_temporal_best"]) > 0.0
                for candidate in task_candidates
            )
        event_has_safe = False
        event_has_beating = False
        event_has_safe_beating = False
        event_has_safe_beating_under_10m = False
        decision = decision_by_identity.get((
            entry.get("tick"), entry.get("team"), entry.get("player_idx")
        ), {})
        chosen = decision.get("chosen", {}) if isinstance(decision, dict) else {}
        chosen_action = str(chosen.get("action_type") or "missing")
        chosen_score = chosen.get("value", {}).get("score")
        event_safe_beating_under_10m: list[dict[str, Any]] = []
        for candidate in candidates:
            if not isinstance(candidate, dict):
                counts["malformed_candidates"] += 1
                continue
            counts["candidates"] += 1
            role = str(candidate.get("receiver_role") or "unknown")
            by_role_counts[role]["candidates"] += 1
            retention = candidate.get("retention")
            gap = candidate.get("minus_actual_temporal_best")
            distance_m = candidate.get("distance_m")
            distance_band = (
                "0_10m"
                if isinstance(distance_m, (int, float)) and float(distance_m) < 10.0
                else "10m_plus"
                if isinstance(distance_m, (int, float))
                else "unknown"
            )
            by_distance_counts[distance_band]["candidates"] += 1
            safe = isinstance(retention, (int, float)) and float(retention) >= 0.85
            beating = isinstance(gap, (int, float)) and float(gap) > 0.0
            if safe:
                counts["candidates_retention_ge_0.85"] += 1
                by_role_counts[role]["candidates_retention_ge_0.85"] += 1
                by_distance_counts[distance_band][
                    "candidates_retention_ge_0.85"
                ] += 1
                event_has_safe = True
            if beating:
                counts["candidates_beating_actual_temporal_best"] += 1
                by_role_counts[role]["candidates_beating_actual_temporal_best"] += 1
                by_distance_counts[distance_band][
                    "candidates_beating_actual_temporal_best"
                ] += 1
                event_has_beating = True
            if safe and beating:
                counts["candidates_safe_and_beating_actual_temporal_best"] += 1
                by_role_counts[role][
                    "candidates_safe_and_beating_actual_temporal_best"
                ] += 1
                by_distance_counts[distance_band][
                    "candidates_safe_and_beating_actual_temporal_best"
                ] += 1
                event_has_safe_beating = True
                event_has_safe_beating_under_10m |= distance_band == "0_10m"
                if distance_band == "0_10m":
                    event_safe_beating_under_10m.append(candidate)
            for field in metric_fields:
                value = candidate.get(field)
                if isinstance(value, (int, float)):
                    metrics[field].append(float(value))
                    by_role_metrics[role][field].append(float(value))
                    by_distance_metrics[distance_band][field].append(float(value))
        if event_has_safe:
            counts["events_with_retention_ge_0.85_candidate"] += 1
        if event_has_beating:
            counts["events_with_candidate_beating_actual_temporal_best"] += 1
        if event_has_safe_beating:
            counts[
                "events_with_safe_candidate_beating_actual_temporal_best"
            ] += 1
        if event_has_safe_beating_under_10m:
            counts[
                "events_with_safe_0_10m_candidate_beating_actual_temporal_best"
            ] += 1
            counts[f"safe_0_10m:chosen_action={chosen_action}"] += 1
            best = max(
                event_safe_beating_under_10m,
                key=lambda candidate: float(candidate["value"]),
            )
            safe_beating_under_10m_cases.append({
                "tick": entry.get("tick"),
                "team": entry.get("team"),
                "player_idx": entry.get("player_idx"),
                "chosen_action": chosen_action,
                "chosen_score": (
                    float(chosen_score)
                    if isinstance(chosen_score, (int, float))
                    else None
                ),
                "required_release_fraction": entry.get(
                    "required_release_fraction"
                ),
                "candidate_count": len(event_safe_beating_under_10m),
                "best_candidate": best,
            })

    completed_ticks_by_possession_team: dict[tuple[Any, str], list[int]] = defaultdict(list)
    for event in events:
        if (
            isinstance(event, dict)
            and event.get("event_type") == "pass"
            and event.get("outcome") == "completed"
            and event.get("team_side") in {"home", "away"}
            and isinstance(event.get("tick"), int)
        ):
            completed_ticks_by_possession_team[(
                event.get("possession_id"),
                str(event["team_side"]),
            )].append(int(event["tick"]))
    for ticks in completed_ticks_by_possession_team.values():
        ticks.sort()

    def completed_pass_prefix(decision: dict[str, Any]) -> str:
        tick = decision.get("tick")
        completed_before = (
            sum(
                completed_tick < int(tick)
                for completed_tick in completed_ticks_by_possession_team.get(
                    (decision.get("possession_id"), str(decision.get("team"))),
                    [],
                )
            )
            if isinstance(tick, int)
            else 0
        )
        return (
            "0"
            if completed_before == 0
            else "1"
            if completed_before == 1
            else "2-4"
            if completed_before <= 4
            else "5+"
        )

    decisions_by_prefix: dict[str, set[tuple[Any, Any, Any]]] = defaultdict(set)
    for identity, decision in decision_by_identity.items():
        decisions_by_prefix[completed_pass_prefix(decision)].add(identity)
    profile_rows_by_prefix: dict[str, dict[str, list[dict[str, Any]]]] = defaultdict(
        lambda: defaultdict(list)
    )
    rows_by_decision: dict[tuple[Any, Any, Any], list[dict[str, Any]]] = defaultdict(list)
    for row in admission_rows_by_profile_identity.values():
        identity = (row["tick"], row["team"], row["player_idx"])
        decision = decision_by_identity.get(identity)
        if not isinstance(decision, dict):
            continue
        prefix = completed_pass_prefix(decision)
        profile_rows_by_prefix[prefix][str(row["profile"])].append(row)
        rows_by_decision[identity].append(row)
    deduplicated_prefix_counts: dict[str, Counter[str]] = defaultdict(Counter)
    deduplicated_prefix_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    for prefix, identities in decisions_by_prefix.items():
        prefix_counts = deduplicated_prefix_counts[prefix]
        prefix_metrics = deduplicated_prefix_metrics[prefix]
        prefix_counts["on_ball_decisions"] = len(identities)
        for identity in identities:
            rows = rows_by_decision.get(identity, [])
            prefix_counts["with_communication_option"] += int(bool(rows))
            prefix_counts["with_selectable_option"] += int(
                any(bool(row["selectable"]) for row in rows)
            )
            prefix_counts["with_0_10m_option"] += int(
                any(row["distance_band"] == "0_10m" for row in rows)
            )
            prefix_counts["with_selectable_0_10m_option"] += int(
                any(
                    bool(row["selectable"])
                    and row["distance_band"] == "0_10m"
                    for row in rows
                )
            )
            if rows:
                best_row = max(
                    rows, key=lambda row: float(row["overall_probability"])
                )
                prefix_metrics["best_overall_selection_probability"].append(
                    float(best_row["overall_probability"])
                )
                prefix_counts[f"best_profile={best_row['profile']}"] += 1
        for profile, rows in profile_rows_by_prefix[prefix].items():
            prefix_counts[f"profile={profile}:decisions"] = len(rows)
            prefix_counts[f"profile={profile}:selectable"] = sum(
                bool(row["selectable"]) for row in rows
            )
            prefix_counts[f"profile={profile}:0_10m"] = sum(
                row["distance_band"] == "0_10m" for row in rows
            )
            prefix_counts[f"profile={profile}:selectable_0_10m"] = sum(
                bool(row["selectable"]) and row["distance_band"] == "0_10m"
                for row in rows
            )

    return {
        "scope": (
            "raw full-trace communication_pass_counterfactual events; each candidate "
            "is the best production-generator feet pass for one communication-only "
            "receiver, evaluated without entering policy, selection, or RNG; distance "
            "bands are reporting-only"
        ),
        "safe_definition": "retention >= 0.85",
        "beats_actual_definition": "minus_actual_temporal_best > 0",
        "safe_0_10m_cases": safe_beating_under_10m_cases,
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
        "by_receiver_role": {
            role: {
                "counts": dict(sorted(by_role_counts[role].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(by_role_metrics[role].items())
                    if values
                },
            }
            for role in sorted(by_role_counts)
        },
        "by_candidate_distance": {
            band: {
                "counts": dict(sorted(by_distance_counts[band].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(by_distance_metrics[band].items())
                    if values
                },
            }
            for band in ("0_10m", "10m_plus", "unknown")
            if by_distance_counts.get(band)
        },
        "selector_admission": {
            "scope": (
                "the single best temporal communication-only feet Pass per decision, "
                "after applying the same goal policy, is appended only to a read-only "
                "copy of the production family-then-candidate bounded-rational selector"
            ),
            "counts": dict(sorted(admission_counts.items())),
            "metrics": {
                field: _numeric_distribution(values)
                for field, values in sorted(admission_metrics.items())
                if values
            },
            "cases": sorted(
                admission_cases,
                key=lambda case: float(
                    case.get("admission", {})
                    .get("option", {})
                    .get("overall_selection_probability", 0.0)
                    or 0.0
                ),
                reverse=True,
            )[:20],
            "deduplicated_by_completed_passes_before_decision": {
                "scope": (
                    "each real on-ball decision is counted once; each communication "
                    "profile contributes at most its highest-probability option for that "
                    "decision, grouped by completed public passes in the same possession "
                    "strictly before the decision tick"
                ),
                "groups": {
                    prefix: {
                        "counts": dict(sorted(
                            deduplicated_prefix_counts[prefix].items()
                        )),
                        "metrics": {
                            field: _numeric_distribution(values)
                            for field, values in sorted(
                                deduplicated_prefix_metrics[prefix].items()
                            )
                            if values
                        },
                    }
                    for prefix in ("0", "1", "2-4", "5+")
                    if prefix in decisions_by_prefix
                },
            },
        },
    }


def _communication_receipt_follow_up_counterfactual_summary(
    trace_entries: list[dict[str, Any]],
) -> dict[str, Any]:
    """Upper-bound communication-only passes inside the receipt time budget."""
    counts: Counter[str] = Counter()
    metrics: dict[str, list[float]] = defaultdict(list)
    by_outcome: dict[str, Counter[str]] = defaultdict(Counter)
    by_outcome_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    for entry in trace_entries:
        event = entry.get("event")
        if event not in {"receipt_fast_pass", "receipt_decision_wait"}:
            continue
        candidates = entry.get("communication_pass_counterfactual")
        if not isinstance(candidates, list):
            counts["receipt_events_without_counterfactual_snapshot"] += 1
            continue
        outcome = "fast_pass" if event == "receipt_fast_pass" else "wait"
        counts["receipt_decisions"] += 1
        counts[f"receipt_decisions:{outcome}"] += 1
        by_outcome[outcome]["receipt_decisions"] += 1
        available = entry.get("available_fraction", entry.get("remaining_tick_fraction"))
        required = entry.get(
            "communication_required_release_fraction",
            entry.get("required_release_fraction"),
        )
        release_feasible = (
            isinstance(available, (int, float))
            and isinstance(required, (int, float))
            and float(required) <= float(available) + 1e-12
        )
        if release_feasible:
            counts["receipt_decisions_with_communication_release_budget"] += 1
            by_outcome[outcome]["with_communication_release_budget"] += 1
        for field, value in (
            ("available_fraction", available),
            ("required_release_fraction", required),
        ):
            if isinstance(value, (int, float)):
                metrics[field].append(float(value))
                by_outcome_metrics[outcome][field].append(float(value))
        if candidates:
            counts["receipt_decisions_with_communication_candidates"] += 1
            by_outcome[outcome]["with_communication_candidates"] += 1
        event_has_executable_upper_bound = False
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            counts["candidates"] += 1
            by_outcome[outcome]["candidates"] += 1
            distance_m = candidate.get("distance_m")
            retention = candidate.get("retention")
            gap = candidate.get("minus_actual_temporal_best")
            under_10m = (
                isinstance(distance_m, (int, float)) and float(distance_m) < 10.0
            )
            safe = isinstance(retention, (int, float)) and float(retention) >= 0.85
            beating = isinstance(gap, (int, float)) and float(gap) > 0.0
            if under_10m:
                counts["candidates_0_10m"] += 1
                by_outcome[outcome]["candidates_0_10m"] += 1
            if under_10m and safe and beating:
                counts["candidates_safe_0_10m_beating_actual"] += 1
                by_outcome[outcome]["candidates_safe_0_10m_beating_actual"] += 1
            if under_10m and safe and beating and release_feasible:
                counts["candidates_executable_safe_0_10m_beating_actual"] += 1
                by_outcome[outcome][
                    "candidates_executable_safe_0_10m_beating_actual"
                ] += 1
                event_has_executable_upper_bound = True
            for field in (
                "distance_m",
                "retention",
                "minus_actual_temporal_best",
                "hint_age_ticks",
                "actual_position_error_m",
            ):
                value = candidate.get(field)
                if isinstance(value, (int, float)):
                    metrics[field].append(float(value))
                    by_outcome_metrics[outcome][field].append(float(value))
        if event_has_executable_upper_bound:
            counts[
                "receipt_decisions_with_executable_safe_0_10m_candidate_beating_actual"
            ] += 1
            by_outcome[outcome][
                "with_executable_safe_0_10m_candidate_beating_actual"
            ] += 1

    return {
        "scope": (
            "read-only full-trace upper bound at same-tick stable pass receipts; "
            "communication-only feet candidates use the hint-only shadow roster and "
            "must fit the existing remaining release budget; no candidate enters policy, "
            "selection, execution, or RNG"
        ),
        "counts": dict(sorted(counts.items())),
        "metrics": {
            field: _numeric_distribution(values)
            for field, values in sorted(metrics.items())
            if values
        },
        "by_receipt_outcome": {
            outcome: {
                "counts": dict(sorted(by_outcome[outcome].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(by_outcome_metrics[outcome].items())
                    if values
                },
            }
            for outcome in sorted(by_outcome)
        },
    }


def _receipt_time_budget_selector_counterfactual_summary(
    trace_entries: list[dict[str, Any]],
) -> dict[str, Any]:
    """Summarize exact selector mass over physical receipt-time subsets."""
    profiles = (
        "production",
        "duration_feasible",
        "release_feasible_passes",
        "physically_startable",
        "family_preserving_startable",
        "startable",
    )
    counts: Counter[str] = Counter()
    expected: dict[str, Counter[str]] = defaultdict(Counter)
    metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    cases: list[dict[str, Any]] = []

    def summarize(selector: Any) -> dict[str, float]:
        result: Counter[str] = Counter()
        actions = selector.get("actions", []) if isinstance(selector, dict) else []
        for action in actions:
            if not isinstance(action, dict):
                continue
            probability = action.get("overall_selection_probability")
            if not isinstance(probability, (int, float)) or float(probability) <= 0.0:
                continue
            probability = float(probability)
            action_name = str(action.get("action") or "unknown")
            result[f"action={action_name}"] += probability
            duration = action.get("option_duration_seconds")
            if isinstance(duration, (int, float)):
                result["expected_duration_seconds"] += probability * float(duration)
            if action_name != "pass":
                continue
            result["pass_probability"] += probability
            distance_m = action.get("distance_m")
            if isinstance(distance_m, (int, float)):
                distance_m = float(distance_m)
                result["pass_distance_weighted"] += probability * distance_m
                result["pass_long_probability"] += probability * float(distance_m >= 32.0)
            for field in (
                "retained_control_probability",
                "opposing_control_probability",
                "unresolved_probability",
            ):
                value = action.get(field)
                if isinstance(value, (int, float)):
                    result[f"pass_{field}_weighted"] += probability * float(value)
        result["total_probability"] = sum(
            value for key, value in result.items() if key.startswith("action=")
        )
        return dict(result)

    def preserve_family_mass(
        production: Any, physically_startable: Any
    ) -> dict[str, Any]:
        if not isinstance(production, dict) or not isinstance(physically_startable, dict):
            return {}
        production_families = production.get("family_probabilities")
        startable_families = physically_startable.get("family_probabilities")
        startable_actions = physically_startable.get("actions")
        if not (
            isinstance(production_families, list)
            and isinstance(startable_families, list)
            and isinstance(startable_actions, list)
        ):
            return {}
        family_by_action = {
            "carry": 0,
            "pass": 1,
            "shoot": 2,
            "hold": 3,
            "reorient": 4,
        }
        wait_probability = 0.0
        wait_by_family: dict[str, float] = {}
        actions: list[dict[str, Any]] = []
        for action in startable_actions:
            if not isinstance(action, dict):
                continue
            action_name = str(action.get("action") or "unknown")
            family = family_by_action.get(action_name)
            if family is None or family >= len(production_families):
                continue
            production_probability = production_families[family]
            startable_family_probability = (
                startable_families[family]
                if family < len(startable_families)
                else 0.0
            )
            overall_probability = action.get("overall_selection_probability")
            if not all(
                isinstance(value, (int, float))
                for value in (
                    production_probability,
                    startable_family_probability,
                    overall_probability,
                )
            ) or float(startable_family_probability) <= 1e-12:
                continue
            conditional_probability = (
                float(overall_probability) / float(startable_family_probability)
            )
            projected = dict(action)
            projected["overall_selection_probability"] = (
                float(production_probability) * conditional_probability
            )
            actions.append(projected)
        for family, production_probability in enumerate(production_families):
            if not isinstance(production_probability, (int, float)):
                continue
            startable_probability = (
                startable_families[family]
                if family < len(startable_families)
                and isinstance(startable_families[family], (int, float))
                else 0.0
            )
            if float(startable_probability) <= 1e-12:
                probability = float(production_probability)
                if probability > 1e-12:
                    wait_probability += probability
                    wait_by_family[str(family)] = probability
        return {
            "scope": (
                "read-only family-preserving receipt admission: the full pool keeps "
                "production family probability, physically startable candidates only "
                "redistribute probability inside their original family, and unavailable "
                "family mass waits; no state, choice, execution, or RNG changes"
            ),
            "actions": actions,
            "wait_probability": wait_probability,
            "wait_by_family": wait_by_family,
        }

    for entry in trace_entries:
        if entry.get("event") not in {"receipt_fast_pass", "receipt_decision_wait"}:
            continue
        counterfactual = entry.get("time_budget_selector_counterfactual")
        if not isinstance(counterfactual, dict):
            counts["events_without_snapshot"] += 1
            continue
        counts["receipt_decisions"] += 1
        selected_action = (
            "pass"
            if entry.get("event") == "receipt_fast_pass"
            else str(entry.get("selected_action") or "unknown")
        )
        family_preserving = preserve_family_mass(
            counterfactual.get("production"),
            counterfactual.get("physically_startable"),
        )
        selectors = {
            profile: (
                family_preserving
                if profile == "family_preserving_startable"
                else counterfactual.get(profile)
            )
            for profile in profiles
        }
        summaries = {
            profile: summarize(selector) for profile, selector in selectors.items()
        }
        wait_probability = family_preserving.get("wait_probability")
        if isinstance(wait_probability, (int, float)):
            summaries["family_preserving_startable"]["wait_probability"] = (
                float(wait_probability)
            )
        for profile, summary in summaries.items():
            total = summary.get("total_probability", 0.0)
            counts[f"{profile}:nonempty" if total > 1e-12 else f"{profile}:empty"] += 1
            for key, value in summary.items():
                expected[profile][key] += float(value)
                metrics[profile][key].append(float(value))
            action_mass = {
                key.split("=", 1)[1]: value
                for key, value in summary.items()
                if key.startswith("action=")
            }
            best_action = (
                max(action_mass, key=action_mass.get) if action_mass else "none"
            )
            counts[f"{profile}:best={best_action}"] += 1
            counts[
                f"{profile}:selected={selected_action}:best={best_action}"
            ] += 1
        production_best = max(
            (
                (key.split("=", 1)[1], value)
                for key, value in summaries["production"].items()
                if key.startswith("action=")
            ),
            key=lambda row: row[1],
            default=("none", 0.0),
        )[0]
        startable_best = max(
            (
                (key.split("=", 1)[1], value)
                for key, value in summaries["startable"].items()
                if key.startswith("action=")
            ),
            key=lambda row: row[1],
            default=("none", 0.0),
        )[0]
        counts[f"best_transition={production_best}->{startable_best}"] += 1
        if production_best != startable_best:
            counts["best_action_changed"] += 1
        if len(cases) < 30 and (production_best != startable_best or startable_best == "none"):
            cases.append({
                "tick": entry.get("tick"),
                "team": entry.get("holder_team"),
                "player_idx": entry.get("holder_idx"),
                "selected_action": selected_action,
                "available_fraction": counterfactual.get("available_fraction"),
                "required_release_fraction": counterfactual.get("required_release_fraction"),
                "production_best": production_best,
                "startable_best": startable_best,
                "production": summaries["production"],
                "startable": summaries["startable"],
            })

    decision_count = max(counts["receipt_decisions"], 1)
    return {
        "scope": (
            "trace-only exact production family-then-candidate selector replay over "
            "the unchanged receipt action pool and physical time-budget subsets; "
            "duration_feasible requires full candidate duration, "
            "release_feasible_passes uses the existing scalar ground-Pass release "
            "budget, and startable is their union; no state, choice, execution, or RNG changes"
        ),
        "counts": dict(sorted(counts.items())),
        "expected_per_receipt_decision": {
            profile: {
                key: round(value / decision_count, 6)
                for key, value in sorted(values.items())
            }
            for profile, values in sorted(expected.items())
        },
        "metrics": {
            profile: {
                key: _numeric_distribution(values)
                for key, values in sorted(fields.items())
                if values
            }
            for profile, fields in sorted(metrics.items())
        },
        "cases": cases,
    }


def _engine_possession_interruption_hazard(
    response: dict[str, Any],
) -> dict[str, Any]:
    """Measure team-control interruptions per active-play second.

    Engine-v2 increments possession_id only in give_ball_to_player when the
    controlling team changes. The ID span is therefore a direct count of team
    control interruptions, including IDs whose short spell emitted no public
    event between the observed endpoints.
    """
    possession_ids = sorted({
        int(event["possession_id"])
        for event in response.get("events", [])
        if isinstance(event.get("possession_id"), int)
    })
    active_seconds = response.get("match_clock", {}).get("active_play_seconds")
    first_id = possession_ids[0] if possession_ids else None
    last_id = possession_ids[-1] if possession_ids else None
    interruptions = (last_id - first_id) if first_id is not None else 0
    observed_span = interruptions + 1 if first_id is not None else 0
    missing_ids = max(observed_span - len(possession_ids), 0)
    hazard = (
        interruptions / float(active_seconds)
        if interruptions > 0
        and isinstance(active_seconds, (int, float))
        and float(active_seconds) > 0.0
        else None
    )
    return {
        "scope": (
            "team-control changes encoded by the engine possession_id span, divided "
            "by match_clock.active_play_seconds; this is a match-level survival "
            "hazard, not an action-specific failure probability"
        ),
        "first_possession_id": first_id,
        "last_possession_id": last_id,
        "observed_possession_ids": len(possession_ids),
        "missing_observed_ids_in_span": missing_ids,
        "team_control_interruptions": interruptions,
        "active_play_seconds": float(active_seconds)
        if isinstance(active_seconds, (int, float))
        else None,
        "hazard_per_active_second": round(hazard, 9)
        if hazard is not None
        else None,
        "mean_team_control_survival_seconds": round(1.0 / hazard, 6)
        if hazard is not None
        else None,
    }


def _record_near_feet_receiver_task_motion(
    candidate: dict[str, Any],
    decision: dict[str, Any],
    chosen: dict[str, Any],
    cohort: str,
    counts_by_group: dict[str, Counter[str]],
    metrics_by_group: dict[str, dict[str, list[float]]],
) -> None:
    value = candidate.get("value", {})
    components = value.get("components", {})
    transition = components.get("outcome_transition", {})
    motion = candidate.get("details", {}).get("receiver_motion", {})
    task = motion.get("receiver_tactical_task", {})
    receipt_projection = motion.get("production_receipt_projection", {})
    retained = transition.get("retained_control_probability")
    unresolved = transition.get("unresolved_probability")
    holder_radial = motion.get("receiver_velocity_toward_holder_mps")
    effective_velocity = motion.get(
        "receiver_velocity_toward_effective_target_mps"
    )
    receiver_pos = motion.get("receiver_pos")
    holder_pos = decision.get("pos")
    current_holder_distance = (
        hypot(
            float(receiver_pos[0]) - float(holder_pos[0]),
            float(receiver_pos[1]) - float(holder_pos[1]),
        )
        if isinstance(receiver_pos, list)
        and len(receiver_pos) >= 2
        and isinstance(holder_pos, list)
        and len(holder_pos) >= 2
        else None
    )
    effective_holder_distance = motion.get(
        "receiver_effective_target_distance_from_holder_m"
    )
    retention_group = (
        "lt_0.60"
        if isinstance(retained, (int, float)) and float(retained) < 0.60
        else "0.60_0.85"
        if isinstance(retained, (int, float)) and float(retained) < 0.85
        else "gte_0.85"
        if isinstance(retained, (int, float))
        else "unknown"
    )
    unresolved_group = (
        "lt_0.25"
        if isinstance(unresolved, (int, float)) and float(unresolved) < 0.25
        else "0.25_0.50"
        if isinstance(unresolved, (int, float)) and float(unresolved) < 0.50
        else "gte_0.50"
        if isinstance(unresolved, (int, float))
        else "unknown"
    )
    holder_group = (
        "away"
        if isinstance(holder_radial, (int, float)) and float(holder_radial) < -0.05
        else "toward"
        if isinstance(holder_radial, (int, float)) and float(holder_radial) > 0.05
        else "neutral"
        if isinstance(holder_radial, (int, float))
        else "unknown"
    )
    effective_velocity_group = (
        "aligned"
        if isinstance(effective_velocity, (int, float))
        and float(effective_velocity) > 0.05
        else "opposed"
        if isinstance(effective_velocity, (int, float))
        and float(effective_velocity) < -0.05
        else "neutral"
        if isinstance(effective_velocity, (int, float))
        else "unknown"
    )
    effective_holder_geometry = (
        "farther"
        if isinstance(current_holder_distance, (int, float))
        and isinstance(effective_holder_distance, (int, float))
        and float(effective_holder_distance) > float(current_holder_distance) + 0.05
        else "closer"
        if isinstance(current_holder_distance, (int, float))
        and isinstance(effective_holder_distance, (int, float))
        and float(effective_holder_distance) < float(current_holder_distance) - 0.05
        else "equal"
        if isinstance(current_holder_distance, (int, float))
        and isinstance(effective_holder_distance, (int, float))
        else "unknown"
    )
    movement_intent = str(motion.get("receiver_movement_intent") or "unknown")
    task_intent = str(task.get("intent") or "unknown")
    task_active = motion.get("receiver_task_active") is True
    terminal_precontact_distance = receipt_projection.get(
        "terminal_precontact_receiver_to_ball_m"
    )
    terminal_contact_group = (
        "inside_control_radius"
        if isinstance(terminal_precontact_distance, (int, float))
        and float(terminal_precontact_distance) <= 1.35
        else "outside_control_radius"
        if isinstance(terminal_precontact_distance, (int, float))
        else "unknown"
    )
    motion_joint = (
        f"holder={holder_group}:effective_target={effective_velocity_group}"
    )
    prefix = f"offset={cohort}"
    groups = {
        prefix,
        f"{prefix}:retention={retention_group}",
        f"{prefix}:unresolved={unresolved_group}",
        f"{prefix}:movement_intent={movement_intent}",
        f"{prefix}:task_intent={task_intent}",
        f"{prefix}:task_active={str(task_active).lower()}",
        f"{prefix}:holder_radial={holder_group}",
        f"{prefix}:effective_target_velocity={effective_velocity_group}",
        f"{prefix}:effective_target_holder_geometry={effective_holder_geometry}",
        f"{prefix}:terminal_precontact={terminal_contact_group}",
        f"{prefix}:{motion_joint}",
        f"{prefix}:retention={retention_group}:{motion_joint}",
    }
    for group in groups:
        counts = counts_by_group[group]
        metrics = metrics_by_group[group]
        counts["candidates"] += 1
        counts["selected"] += int(candidate is chosen)
        counts["task_active"] += int(task_active)
        counts["moving_away_from_holder"] += int(holder_group == "away")
        counts["velocity_aligned_to_effective_target"] += int(
            effective_velocity_group == "aligned"
        )
        counts["effective_target_farther_from_holder"] += int(
            effective_holder_geometry == "farther"
        )
        for field, sample in (
            ("score", value.get("score")),
            ("retention", retained),
            ("unresolved", unresolved),
            ("receiver_arrival", components.get("receiver_arrival")),
            ("receiver_offset_m", motion.get("receiver_to_target_distance_m")),
            ("receiver_speed_mps", motion.get("receiver_speed_mps")),
            ("velocity_toward_holder_mps", holder_radial),
            ("velocity_toward_effective_target_mps", effective_velocity),
            ("distance_to_effective_target_m", motion.get("receiver_distance_to_effective_target_m")),
            ("current_distance_from_holder_m", current_holder_distance),
            ("effective_target_distance_from_holder_m", effective_holder_distance),
            ("effective_target_holder_distance_delta_m",
                float(effective_holder_distance) - float(current_holder_distance)
                if isinstance(current_holder_distance, (int, float))
                and isinstance(effective_holder_distance, (int, float))
                else None),
            ("exact_flight_ticks", receipt_projection.get("exact_flight_ticks")),
            ("sampled_duration_ticks", receipt_projection.get("sampled_duration_ticks")),
            ("rounded_receiver_end_to_target_m", receipt_projection.get("rounded_receiver_end_to_target_m")),
            ("exact_time_receiver_end_to_target_m", receipt_projection.get("exact_time_receiver_end_to_target_m")),
            ("minimum_precontact_distance_m", receipt_projection.get("minimum_precontact_distance_m")),
            ("minimum_precontact_elapsed_ticks", receipt_projection.get("minimum_precontact_elapsed_ticks")),
            ("terminal_precontact_receiver_to_ball_m", terminal_precontact_distance),
            ("rounded_minus_exact_receiver_end_error_m",
                float(receipt_projection["rounded_receiver_end_to_target_m"])
                - float(receipt_projection["exact_time_receiver_end_to_target_m"])
                if isinstance(receipt_projection.get("rounded_receiver_end_to_target_m"), (int, float))
                and isinstance(receipt_projection.get("exact_time_receiver_end_to_target_m"), (int, float))
                else None),
        ):
            if isinstance(sample, (int, float)):
                metrics[field].append(float(sample))


def _support_arrival_stability_summary(
    trace_entries: list[dict[str, Any]],
    decisions: list[dict[str, Any]],
) -> dict[str, Any]:
    on_ball_by_identity = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")):
            decision
        for decision in decisions
        if decision.get("phase") == "on_ball"
    }
    samples: dict[tuple[Any, Any, Any, Any], list[dict[str, Any]]] = defaultdict(list)
    counts_by_group: dict[str, Counter[str]] = defaultdict(Counter)
    metrics_by_group: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )

    def xy(value: Any) -> tuple[float, float] | None:
        if (
            isinstance(value, list)
            and len(value) >= 2
            and isinstance(value[0], (int, float))
            and isinstance(value[1], (int, float))
        ):
            return (float(value[0]), float(value[1]))
        return None

    def target_gap_band(gap: float) -> str:
        return (
            "0_0.5m" if gap < 0.5
            else "0.5_1m" if gap < 1.0
            else "1_2m" if gap < 2.0
            else "2_4m" if gap < 4.0
            else "4m_plus"
        )

    for entry in trace_entries:
        if entry.get("event") != "held_support_state":
            continue
        tick = entry.get("tick")
        team = entry.get("team")
        holder_idx = entry.get("holder_idx")
        possession_id = entry.get("possession_id")
        holder_pos = xy(entry.get("holder_pos"))
        if (
            not isinstance(tick, int)
            or team not in {"home", "away"}
            or not isinstance(holder_idx, int)
            or holder_pos is None
        ):
            continue
        decision = on_ball_by_identity.get((tick, team, holder_idx), {})
        visible_candidates = [
            candidate
            for candidate in [
                decision.get("chosen", {}),
                *decision.get("alternatives", []),
            ]
            if isinstance(candidate, dict)
            and candidate.get("action_type") == "pass"
        ]
        for supporter in entry.get("supporters", []):
            if (
                not isinstance(supporter, dict)
                or supporter.get("is_goalkeeper") is True
                or supporter.get("task_active") is not True
                or str(supporter.get("task_intent") or "").lower() != "support"
                or not isinstance(supporter.get("idx"), int)
            ):
                continue
            supporter_idx = int(supporter["idx"])
            pos = xy(supporter.get("pos"))
            velocity = xy(supporter.get("velocity"))
            target = xy(supporter.get("effective_target"))
            if pos is None or velocity is None or target is None:
                continue
            target_delta = (target[0] - pos[0], target[1] - pos[1])
            target_gap = hypot(*target_delta)
            speed = hypot(*velocity)
            velocity_toward_target = (
                (velocity[0] * target_delta[0] + velocity[1] * target_delta[1])
                / target_gap
                if target_gap > 1e-9
                else 0.0
            )
            exact_feet_candidates = []
            for candidate in visible_candidates:
                details = candidate.get("details", {})
                receiver_idx = (
                    details.get("target_player_idx")
                    if details.get("target_player_idx") is not None
                    else details.get("intended_receiver")
                )
                candidate_target = xy(candidate.get("target"))
                components = candidate.get("value", {}).get("components", {})
                offset = (
                    details.get("receiver_motion", {})
                    .get("receiver_to_target_distance_m")
                )
                if (
                    receiver_idx == supporter_idx
                    and candidate_target is not None
                    and hypot(
                        candidate_target[0] - holder_pos[0],
                        candidate_target[1] - holder_pos[1],
                    ) < 10.0
                    and components.get("target_kind") == "feet"
                    and isinstance(offset, (int, float))
                    and float(offset) < 0.5
                ):
                    exact_feet_candidates.append(candidate)
            best_exact = (
                max(
                    exact_feet_candidates,
                    key=lambda candidate: float(
                        candidate.get("value", {}).get("score", float("-inf"))
                    ),
                )
                if exact_feet_candidates
                else None
            )
            sample = {
                "tick": tick,
                "pos": pos,
                "velocity": velocity,
                "speed": speed,
                "target": target,
                "target_gap": target_gap,
                "velocity_toward_target": velocity_toward_target,
                "holder_gap": hypot(pos[0] - holder_pos[0], pos[1] - holder_pos[1]),
                "target_holder_gap": hypot(
                    target[0] - holder_pos[0], target[1] - holder_pos[1]
                ),
                "accepted_tick": supporter.get("task_accepted_tick"),
                "movement_intent": str(
                    supporter.get("movement_intent") or "unknown"
                ),
                "goal_type": str(supporter.get("goal_type") or "none"),
                "best_exact": best_exact,
            }
            samples[(possession_id, team, holder_idx, supporter_idx)].append(sample)
            gap_band = target_gap_band(target_gap)
            groups = {
                "all",
                f"target_gap={gap_band}",
                f"movement_intent={sample['movement_intent']}",
                f"goal_type={sample['goal_type']}",
                f"target_gap={gap_band}:movement_intent={sample['movement_intent']}",
            }
            for group in groups:
                counts = counts_by_group[group]
                metrics = metrics_by_group[group]
                counts["frames"] += 1
                counts["moving_toward_target"] += int(velocity_toward_target > 0.05)
                counts["moving_away_from_target"] += int(velocity_toward_target < -0.05)
                counts["exact_feet_candidate"] += int(best_exact is not None)
                metrics["target_gap_m"].append(target_gap)
                metrics["speed_mps"].append(speed)
                metrics["velocity_toward_target_mps"].append(velocity_toward_target)
                metrics["holder_gap_m"].append(sample["holder_gap"])
                metrics["target_holder_gap_m"].append(sample["target_holder_gap"])
                if isinstance(best_exact, dict):
                    value = best_exact.get("value", {})
                    transition = value.get("components", {}).get("outcome_transition", {})
                    retention = transition.get("retained_control_probability")
                    unresolved = transition.get("unresolved_probability")
                    receipt = (
                        best_exact.get("details", {})
                        .get("receiver_motion", {})
                        .get("production_receipt_projection", {})
                    )
                    for field, value_sample in (
                        ("exact_feet_retention", retention),
                        ("exact_feet_unresolved", unresolved),
                        ("exact_feet_terminal_precontact_distance_m", receipt.get("terminal_precontact_receiver_to_ball_m")),
                    ):
                        if isinstance(value_sample, (int, float)):
                            metrics[field].append(float(value_sample))

    for identity_samples in samples.values():
        identity_samples.sort(key=lambda sample: int(sample["tick"]))
        for previous, current in zip(identity_samples, identity_samples[1:]):
            if current["tick"] != previous["tick"] + 1:
                continue
            current_band = target_gap_band(float(current["target_gap"]))
            target_step = hypot(
                current["target"][0] - previous["target"][0],
                current["target"][1] - previous["target"][1],
            )
            previous_target_gap_after_move = hypot(
                previous["target"][0] - current["pos"][0],
                previous["target"][1] - current["pos"][1],
            )
            speed_delta = float(current["speed"]) - float(previous["speed"])
            groups = {
                "all",
                f"target_gap={current_band}",
                f"target_gap={current_band}:target_identity="
                + ("stable" if target_step <= 0.05 else "changed"),
            }
            for group in groups:
                counts = counts_by_group[group]
                metrics = metrics_by_group[group]
                counts["consecutive_transitions"] += 1
                counts["target_identity_stable"] += int(target_step <= 0.05)
                counts["task_identity_stable"] += int(
                    current["accepted_tick"] == previous["accepted_tick"]
                )
                counts["braking"] += int(speed_delta < -0.05)
                counts["accelerating"] += int(speed_delta > 0.05)
                counts["closed_previous_target_gap"] += int(
                    previous_target_gap_after_move
                    < float(previous["target_gap"]) - 1e-9
                )
                metrics["speed_delta_mps"].append(speed_delta)
                metrics["target_step_m"].append(target_step)
                metrics["current_target_gap_change_m"].append(
                    float(current["target_gap"]) - float(previous["target_gap"])
                )
                metrics["previous_target_gap_closure_m"].append(
                    float(previous["target_gap"]) - previous_target_gap_after_move
                )

    return {
        "scope": (
            "read-only exact-tick audit of active Support tasks. It measures physical "
            "speed and convergence as players approach their accepted effective target, "
            "then joins any same-tick under-10m exact-feet candidate for that supporter; "
            "no movement, task, pass, or RNG behavior is changed"
        ),
        "groups": {
            group: {
                "counts": dict(sorted(counts_by_group[group].items())),
                "metrics": {
                    field: _numeric_distribution(values)
                    for field, values in sorted(metrics_by_group[group].items())
                    if values
                },
            }
            for group in sorted(counts_by_group)
        },
    }


def _action_pace_summary(response: dict[str, Any]) -> dict[str, Any]:
    trace_entries = response.get("trace", {}).get("entries", [])
    on_ball_decisions = [
        decision
        for decision in response.get("trace", {}).get("decisions", [])
        if decision.get("phase") == "on_ball"
        and isinstance(decision.get("chosen"), dict)
    ]
    held_action_names = {"pass", "carry", "reorient", "hold", "shot", "clear", "corner_delivery"}
    held_action_events = [
        entry
        for entry in trace_entries
        if entry.get("type") == "action" and entry.get("action") in held_action_names
    ]
    held_action_counts = Counter(str(entry.get("action")) for entry in held_action_events)
    held_action_ticks = {
        int(entry["tick"])
        for entry in held_action_events
        if isinstance(entry.get("tick"), int)
    }
    held_state_ticks = {
        int(entry["tick"])
        for entry in trace_entries
        if entry.get("type") == "state"
        and entry.get("ball_state_before", entry.get("ball_state")) == "held"
        and entry.get("clock_phase_before", "active") == "active"
        and isinstance(entry.get("tick"), int)
    }
    held_no_action_ticks = held_state_ticks - held_action_ticks
    held_no_action_causes: Counter[str] = Counter()
    held_no_action_events: Counter[str] = Counter()
    events_by_tick: dict[int, list[dict[str, Any]]] = defaultdict(list)
    for entry in trace_entries:
        event_tick = (
            entry.get("match_tick")
            if entry.get("event") == "pass_physical_terminal"
            else entry.get("tick")
        )
        if isinstance(event_tick, int):
            events_by_tick[int(event_tick)].append(entry)
    for tick in held_no_action_ticks:
        events = events_by_tick[tick]
        for entry in events:
            label = entry.get("event", entry.get("action"))
            if isinstance(label, str):
                held_no_action_events[label] += 1
        if any(entry.get("event") == "pass_control_terminal" and entry.get("outcome") == "completed" for entry in events):
            held_no_action_causes["completed_pass_receipt"] += 1
        elif any(entry.get("event") == "ball_controlled" for entry in events):
            held_no_action_causes["other_ball_controlled"] += 1
        elif any(entry.get("event") == "restart" for entry in events):
            held_no_action_causes["restart_control"] += 1
        else:
            held_no_action_causes["unattributed"] += 1
    team_plan_counts: Counter[str] = Counter()
    team_plan_selection_metrics: dict[str, list[float]] = defaultdict(list)
    team_plan_pressure_response_counts: Counter[str] = Counter()
    team_plan_pressure_response_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    held_team_plan_control_counts: Counter[str] = Counter()
    held_team_plan_control_metrics: dict[str, list[float]] = defaultdict(list)
    current_observation_plan_counts: Counter[str] = Counter()
    current_observation_plan_metrics: dict[str, list[float]] = defaultdict(list)
    flight_observation_plan_counts: Counter[str] = Counter()
    flight_observation_plan_metrics: dict[str, list[float]] = defaultdict(list)
    flight_observation_plan_replays: set[Any] = set()
    flight_observation_plan_rows: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    free_ball_observation_plan_counts: Counter[str] = Counter()
    free_ball_observation_plan_metrics: dict[str, list[float]] = defaultdict(list)
    stable_control_plan_counts: Counter[str] = Counter()
    stable_control_plan_metrics: dict[str, list[float]] = defaultdict(list)
    pending_pass_phase_counts: Counter[str] = Counter()
    pending_pass_phase_metrics: dict[str, list[float]] = defaultdict(list)
    pending_pass_phase_cases: list[dict[str, Any]] = []
    pending_pass_terminals = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    pending_pass_phase_by_replay: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    for entry in trace_entries:
        if entry.get("event") == "pending_pass_team_phase_counterfactual":
            pending_pass_phase_by_replay[entry.get("replay_id")].append(entry)
    for replay_id, rows in pending_pass_phase_by_replay.items():
        rows.sort(key=lambda row: int(row.get("tick", -1)))
        first = rows[0]
        terminal = pending_pass_terminals.get(replay_id, {})
        outcome = str(terminal.get("outcome") or "unresolved")
        passer_team = str(first.get("passer_team") or "unknown")
        defender_team = (
            "away" if passer_team == "home"
            else "home" if passer_team == "away"
            else "unknown"
        )
        pending_pass_phase_counts["replays"] += 1
        pending_pass_phase_counts[f"outcome={outcome}"] += 1
        pending_pass_phase_counts[f"outcome={outcome}:frames"] += len(rows)
        pending_pass_phase_counts[
            f"opponent_material_contact={str(any(bool(row.get('opponent_material_contact')) for row in rows)).lower()}"
        ] += 1
        pending_pass_phase_metrics["free_ball_frames"].append(float(len(rows)))
        pending_pass_phase_metrics[f"outcome={outcome}:free_ball_frames"].append(
            float(len(rows))
        )
        team_payload: dict[str, Any] = {}
        for team, scope in ((passer_team, "passer"), (defender_team, "defender")):
            if team not in {"home", "away"}:
                continue
            release_phase = str(first.get(team, {}).get("phase_before") or "unknown")
            production_phases = [
                str(row.get(team, {}).get("phase_after") or "unknown")
                for row in rows
            ]
            changed_frames = sum(phase != release_phase for phase in production_phases)
            pending_pass_phase_counts[f"{scope}:release_phase={release_phase}"] += 1
            pending_pass_phase_counts[
                f"{scope}:production_differs_from_release_phase"
            ] += int(changed_frames > 0)
            pending_pass_phase_counts[
                f"{scope}:outcome={outcome}:production_differs"
            ] += int(changed_frames > 0)
            pending_pass_phase_metrics[f"{scope}:changed_frames"].append(
                float(changed_frames)
            )
            pending_pass_phase_metrics[
                f"{scope}:outcome={outcome}:changed_frames"
            ].append(float(changed_frames))
            for phase in production_phases:
                pending_pass_phase_counts[
                    f"{scope}:production_phase={phase}"
                ] += 1
            team_payload[scope] = {
                "team": team,
                "release_phase": release_phase,
                "production_phases": production_phases,
                "changed_frames": changed_frames,
            }
        if outcome == "completed" or len(rows) >= 2:
            pending_pass_phase_cases.append({
                "replay_id": replay_id,
                "start_tick": first.get("tick"),
                "terminal_tick": terminal.get("tick"),
                "outcome": outcome,
                "free_ball_frames": len(rows),
                "opponent_touch": any(bool(row.get("opponent_touch")) for row in rows),
                "opponent_material_contact": any(
                    bool(row.get("opponent_material_contact")) for row in rows
                ),
                **team_payload,
            })
    for entry in trace_entries:
        if entry.get("event") != "held_team_plan_control_counterfactual":
            continue
        holder_team = str(entry.get("holder_team") or "unknown")
        held_team_plan_control_counts["frames"] += 1
        for team in ("home", "away"):
            payload = entry.get(team)
            if not isinstance(payload, dict):
                continue
            scope = "holder" if team == holder_team else "defender"
            production_plan = str(payload.get("production_plan") or "unknown")
            counterfactual_plan = str(
                payload.get("counterfactual_plan") or "unknown"
            )
            transition = f"{production_plan}->{counterfactual_plan}"
            held_team_plan_control_counts[f"{scope}:updates"] += 1
            held_team_plan_control_counts[f"{scope}:transition={transition}"] += 1
            held_team_plan_control_counts[
                f"{scope}:plan_changed={str(production_plan != counterfactual_plan).lower()}"
            ] += 1
            production_probability = payload.get(
                "production_possession_probability"
            )
            counterfactual_probability = payload.get(
                "counterfactual_possession_probability"
            )
            if isinstance(production_probability, (int, float)) and isinstance(
                counterfactual_probability, (int, float)
            ):
                held_team_plan_control_metrics[
                    f"{scope}:production_possession_probability"
                ].append(float(production_probability))
                held_team_plan_control_metrics[
                    f"{scope}:counterfactual_possession_probability"
                ].append(float(counterfactual_probability))
                held_team_plan_control_metrics[
                    f"{scope}:possession_probability_delta"
                ].append(
                    float(counterfactual_probability) - float(production_probability)
                )
            production_signals = payload.get("production_signals", {})
            counterfactual_signals = payload.get("counterfactual_signals", {})
            for field in (
                "forward_bias",
                "recycle_bias",
                "switch_bias",
                "tempo",
                "risk_budget",
            ):
                production_value = production_signals.get(field)
                counterfactual_value = counterfactual_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    held_team_plan_control_metrics[
                        f"{scope}:{field}_delta"
                    ].append(float(counterfactual_value) - float(production_value))
    for entry in trace_entries:
        if entry.get("event") != "current_observation_team_plan_counterfactual":
            continue
        holder_team = str(entry.get("holder_team") or "unknown")
        current_observation_plan_counts["frames"] += 1
        for team in ("home", "away"):
            payload = entry.get(team)
            if not isinstance(payload, dict):
                continue
            scope = "holder" if team == holder_team else "defender"
            production_plan = str(payload.get("production_plan") or "unknown")
            counterfactual_plan = str(
                payload.get("counterfactual_plan") or "unknown"
            )
            transition = f"{production_plan}->{counterfactual_plan}"
            current_observation_plan_counts[f"{scope}:updates"] += 1
            current_observation_plan_counts[f"{scope}:transition={transition}"] += 1
            current_observation_plan_counts[
                f"{scope}:plan_changed={str(production_plan != counterfactual_plan).lower()}"
            ] += 1
            possession_probability = payload.get(
                "counterfactual_possession_probability"
            )
            if isinstance(possession_probability, (int, float)):
                current_observation_plan_metrics[
                    f"{scope}:possession_probability"
                ].append(float(possession_probability))
            production_signals = payload.get("production_signals", {})
            counterfactual_signals = payload.get("counterfactual_signals", {})
            for field in (
                "forward_bias",
                "recycle_bias",
                "switch_bias",
                "tempo",
                "risk_budget",
            ):
                production_value = production_signals.get(field)
                counterfactual_value = counterfactual_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    current_observation_plan_metrics[
                        f"{scope}:{field}_delta"
                    ].append(float(counterfactual_value) - float(production_value))
    for entry in trace_entries:
        if entry.get("event") != "flight_current_observation_team_plan_counterfactual":
            continue
        replay_id = entry.get("replay_id")
        flight_observation_plan_replays.add(replay_id)
        flight_observation_plan_rows[replay_id].append(entry)
        passer_team = str(entry.get("passer_team") or "unknown")
        flight_observation_plan_counts["frames"] += 1
        elapsed = entry.get("flight_elapsed_ticks")
        if isinstance(elapsed, (int, float)):
            flight_observation_plan_metrics["flight_elapsed_ticks"].append(
                float(elapsed)
            )
        for team in ("home", "away"):
            payload = entry.get(team)
            if not isinstance(payload, dict):
                continue
            scope = "passer" if team == passer_team else "defender"
            production_plan = str(payload.get("production_plan") or "unknown")
            counterfactual_plan = str(
                payload.get("counterfactual_plan") or "unknown"
            )
            transition = f"{production_plan}->{counterfactual_plan}"
            flight_observation_plan_counts[f"{scope}:frames"] += 1
            flight_observation_plan_counts[f"{scope}:transition={transition}"] += 1
            flight_observation_plan_counts[
                f"{scope}:plan_changed={str(production_plan != counterfactual_plan).lower()}"
            ] += 1
            possession_probability = payload.get(
                "counterfactual_possession_probability"
            )
            if isinstance(possession_probability, (int, float)):
                flight_observation_plan_metrics[
                    f"{scope}:possession_probability"
                ].append(float(possession_probability))
            production_signals = payload.get("production_signals", {})
            counterfactual_signals = payload.get("counterfactual_signals", {})
            for field in (
                "forward_bias",
                "recycle_bias",
                "switch_bias",
                "tempo",
                "risk_budget",
            ):
                production_value = production_signals.get(field)
                counterfactual_value = counterfactual_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    flight_observation_plan_metrics[
                        f"{scope}:{field}_delta"
                    ].append(float(counterfactual_value) - float(production_value))
    for replay_id, rows in flight_observation_plan_rows.items():
        rows.sort(
            key=lambda row: (
                float(row.get("flight_elapsed_ticks", 0.0) or 0.0),
                int(row.get("tick", -1)),
            )
        )
        terminal_row = rows[-1]
        outcome = str(
            pending_pass_terminals.get(replay_id, {}).get("outcome")
            or "unresolved"
        )
        passer_team = str(terminal_row.get("passer_team") or "unknown")
        flight_observation_plan_counts["terminal_frames"] += 1
        flight_observation_plan_counts[f"terminal:outcome={outcome}"] += 1
        terminal_elapsed = terminal_row.get("flight_elapsed_ticks")
        if isinstance(terminal_elapsed, (int, float)):
            flight_observation_plan_metrics["terminal:flight_elapsed_ticks"].append(
                float(terminal_elapsed)
            )
        for team in ("home", "away"):
            payload = terminal_row.get(team)
            if not isinstance(payload, dict):
                continue
            scope = "passer" if team == passer_team else "defender"
            production_plan = str(payload.get("production_plan") or "unknown")
            counterfactual_plan = str(
                payload.get("counterfactual_plan") or "unknown"
            )
            transition = f"{production_plan}->{counterfactual_plan}"
            changed = production_plan != counterfactual_plan
            flight_observation_plan_counts[
                f"terminal:{scope}:plan_changed={str(changed).lower()}"
            ] += 1
            flight_observation_plan_counts[
                f"terminal:{scope}:outcome={outcome}:plan_changed={str(changed).lower()}"
            ] += 1
            flight_observation_plan_counts[
                f"terminal:{scope}:transition={transition}"
            ] += 1
            production_signals = payload.get("production_signals", {})
            counterfactual_signals = payload.get("counterfactual_signals", {})
            for field in (
                "forward_bias",
                "recycle_bias",
                "switch_bias",
                "tempo",
                "risk_budget",
            ):
                production_value = production_signals.get(field)
                counterfactual_value = counterfactual_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    flight_observation_plan_metrics[
                        f"terminal:{scope}:{field}_delta"
                    ].append(float(counterfactual_value) - float(production_value))
    for entry in trace_entries:
        if entry.get("event") != "free_ball_current_observation_team_plan_counterfactual":
            continue
        pending_scope = (
            "pending_pass"
            if entry.get("pending_pass_replay_id") is not None
            else "other_loose_ball"
        )
        home_claim = entry.get("home_claim_confidence")
        away_claim = entry.get("away_claim_confidence")
        claim_scope = "tied"
        if isinstance(home_claim, (int, float)) and isinstance(
            away_claim, (int, float)
        ):
            home_claim = float(home_claim)
            away_claim = float(away_claim)
            claim_scope = (
                "home" if home_claim > away_claim + 1e-12
                else "away" if away_claim > home_claim + 1e-12
                else "tied"
            )
            free_ball_observation_plan_metrics["home_claim_confidence"].append(
                home_claim
            )
            free_ball_observation_plan_metrics["away_claim_confidence"].append(
                away_claim
            )
            free_ball_observation_plan_metrics["absolute_claim_margin"].append(
                abs(home_claim - away_claim)
            )
        free_ball_observation_plan_counts["frames"] += 1
        free_ball_observation_plan_counts[f"scope={pending_scope}"] += 1
        free_ball_observation_plan_counts[f"claim_leader={claim_scope}"] += 1
        for team in ("home", "away"):
            payload = entry.get(team)
            if not isinstance(payload, dict):
                continue
            relation = (
                "claim_leader" if team == claim_scope
                else "claim_follower" if claim_scope in {"home", "away"}
                else "claim_tied"
            )
            production_plan = str(payload.get("production_plan") or "unknown")
            counterfactual_plan = str(
                payload.get("counterfactual_plan") or "unknown"
            )
            transition = f"{production_plan}->{counterfactual_plan}"
            changed = production_plan != counterfactual_plan
            for group in (relation, f"{pending_scope}:{relation}"):
                free_ball_observation_plan_counts[f"{group}:frames"] += 1
                free_ball_observation_plan_counts[
                    f"{group}:plan_changed={str(changed).lower()}"
                ] += 1
                free_ball_observation_plan_counts[
                    f"{group}:transition={transition}"
                ] += 1
            possession_probability = payload.get(
                "counterfactual_possession_probability"
            )
            if isinstance(possession_probability, (int, float)):
                free_ball_observation_plan_metrics[
                    f"{relation}:possession_probability"
                ].append(float(possession_probability))
            production_signals = payload.get("production_signals", {})
            counterfactual_signals = payload.get("counterfactual_signals", {})
            for field in (
                "forward_bias",
                "recycle_bias",
                "switch_bias",
                "tempo",
                "risk_budget",
            ):
                production_value = production_signals.get(field)
                counterfactual_value = counterfactual_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    free_ball_observation_plan_metrics[
                        f"{relation}:{field}_delta"
                    ].append(float(counterfactual_value) - float(production_value))
    for entry in trace_entries:
        if entry.get("event") != "stable_control_team_plan_counterfactual":
            continue
        provenance = str(entry.get("control_provenance") or "unknown")
        controller_team = str(entry.get("controller_team") or "unknown")
        stable_control_plan_counts["handoffs"] += 1
        stable_control_plan_counts[f"provenance={provenance}"] += 1
        stable_control_plan_counts[
            f"provenance={provenance}:pending_pass={str(entry.get('pending_pass_replay_id') is not None).lower()}"
        ] += 1
        for team in ("home", "away"):
            payload = entry.get(team)
            if not isinstance(payload, dict):
                continue
            relation = "controller" if team == controller_team else "defender"
            production_plan = str(payload.get("production_plan") or "unknown")
            counterfactual_plan = str(
                payload.get("counterfactual_plan") or "unknown"
            )
            event_phase_plan = str(
                payload.get("event_phase_counterfactual_plan") or "unknown"
            )
            transition = f"{production_plan}->{counterfactual_plan}"
            changed = production_plan != counterfactual_plan
            for group in (relation, f"{provenance}:{relation}"):
                stable_control_plan_counts[f"{group}:updates"] += 1
                stable_control_plan_counts[
                    f"{group}:plan_changed={str(changed).lower()}"
                ] += 1
                stable_control_plan_counts[f"{group}:transition={transition}"] += 1
                stable_control_plan_counts[
                    f"{group}:event_phase_plan_changed={str(production_plan != event_phase_plan).lower()}"
                ] += 1
                stable_control_plan_counts[
                    f"{group}:event_phase_transition={production_plan}->{event_phase_plan}"
                ] += 1
            possession_probability = payload.get(
                "counterfactual_possession_probability"
            )
            if isinstance(possession_probability, (int, float)):
                stable_control_plan_metrics[
                    f"{provenance}:{relation}:possession_probability"
                ].append(float(possession_probability))
            production_signals = payload.get("production_signals", {})
            counterfactual_signals = payload.get("counterfactual_signals", {})
            event_phase_signals = payload.get("event_phase_counterfactual_signals", {})
            for field in (
                "forward_bias",
                "recycle_bias",
                "switch_bias",
                "tempo",
                "risk_budget",
            ):
                production_value = production_signals.get(field)
                counterfactual_value = counterfactual_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    stable_control_plan_metrics[
                        f"{provenance}:{relation}:{field}_delta"
                    ].append(float(counterfactual_value) - float(production_value))
                event_phase_value = event_phase_signals.get(field)
                if isinstance(production_value, (int, float)) and isinstance(
                    event_phase_value, (int, float)
                ):
                    stable_control_plan_metrics[
                        f"{provenance}:{relation}:event_phase_{field}_delta"
                    ].append(float(event_phase_value) - float(production_value))
    team_plan_update_by_frame: dict[tuple[Any, Any], dict[str, Any]] = {}
    team_plan_sequences: dict[str, list[str]] = defaultdict(list)
    for entry in trace_entries:
        if entry.get("event") != "team_plan_update":
            continue
        team_plan_update_by_frame[(entry.get("team"), entry.get("tick"))] = entry
        selected = str(entry.get("selected", "unknown"))
        team_plan_sequences[str(entry.get("team", "unknown"))].append(selected)
        team_plan_counts[selected] += 1
        features = entry.get("features", {})
        signals = entry.get("signals", {})
        for field, value in features.items():
            if isinstance(value, (int, float)):
                team_plan_selection_metrics[f"{selected}:feature:{field}"].append(float(value))
        for field, value in signals.items():
            if isinstance(value, (int, float)):
                team_plan_selection_metrics[f"{selected}:signal:{field}"].append(float(value))
        pressure = features.get("ball_pressure")
        possession_probability = features.get("possession_probability")
        if isinstance(pressure, (int, float)) and isinstance(
            possession_probability, (int, float)
        ):
            possession_scope = (
                "possession" if float(possession_probability) >= 0.5 else "out_of_possession"
            )
            pressure_band = (
                "0_0.2"
                if float(pressure) < 0.2
                else "0.2_0.4"
                if float(pressure) < 0.4
                else "0.4_0.6"
                if float(pressure) < 0.6
                else "0.6_0.8"
                if float(pressure) < 0.8
                else "0.8_1.0"
            )
            key = f"{possession_scope}:{pressure_band}"
            team_plan_pressure_response_counts[f"{key}:selected={selected}"] += 1
            team_plan_pressure_response_metrics[key]["ball_pressure"].append(float(pressure))
            team_plan_pressure_response_metrics[key]["possession_probability"].append(
                float(possession_probability)
            )
            for field, value in signals.items():
                if isinstance(value, (int, float)):
                    team_plan_pressure_response_metrics[key][field].append(float(value))
        candidates = {
            str(candidate.get("kind")): candidate
            for candidate in entry.get("candidates", [])
            if isinstance(candidate, dict)
        }
        selected_candidate = candidates.get(selected, {})
        selected_value = selected_candidate.get("value")
        for kind, candidate in candidates.items():
            for field in ("raw_value", "switch_cost", "value"):
                value = candidate.get(field)
                if isinstance(value, (int, float)):
                    team_plan_selection_metrics[f"{selected}:candidate:{kind}:{field}"].append(
                        float(value)
                    )
            candidate_value = candidate.get("value")
            if isinstance(selected_value, (int, float)) and isinstance(
                candidate_value, (int, float)
            ):
                team_plan_selection_metrics[f"{selected}:margin_over:{kind}"].append(
                    float(selected_value) - float(candidate_value)
                )
    team_plan_transition_counts: Counter[str] = Counter()
    team_plan_run_lengths: dict[str, list[float]] = defaultdict(list)
    switch_run_lifecycle_counts: Counter[str] = Counter()
    switch_run_lifecycle_metrics: dict[str, list[float]] = defaultdict(list)
    switch_run_lifecycle_cases: list[dict[str, Any]] = []
    for plans in team_plan_sequences.values():
        if not plans:
            continue
        current = plans[0]
        run_length = 1
        for plan in plans[1:]:
            team_plan_transition_counts[f"{current}->{plan}"] += 1
            if plan == current:
                run_length += 1
            else:
                team_plan_run_lengths[current].append(float(run_length))
                current = plan
                run_length = 1
        team_plan_run_lengths[current].append(float(run_length))
    switch_updates_by_team: dict[str, list[dict[str, Any]]] = defaultdict(list)
    switch_pass_releases_by_team: dict[str, list[dict[str, Any]]] = defaultdict(list)
    switch_pass_terminals = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    for entry in trace_entries:
        if (
            entry.get("action") == "pass"
            and entry.get("team") in {"home", "away"}
            and isinstance(entry.get("tick"), int)
        ):
            switch_pass_releases_by_team[str(entry["team"])].append(entry)
    for releases in switch_pass_releases_by_team.values():
        releases.sort(key=lambda entry: int(entry["tick"]))
    for entry in trace_entries:
        if (
            entry.get("event") == "team_plan_update"
            and entry.get("team") in {"home", "away"}
            and isinstance(entry.get("tick"), int)
        ):
            switch_updates_by_team[str(entry["team"])].append(entry)
    for team, updates in switch_updates_by_team.items():
        updates.sort(key=lambda entry: int(entry["tick"]))
        switch_run: list[dict[str, Any]] = []

        def close_switch_run(rows: list[dict[str, Any]]) -> None:
            if not rows:
                return
            points = [
                (float(entry["ball_pos"][0]), float(entry["ball_pos"][1]))
                for entry in rows
                if isinstance(entry.get("ball_pos"), list)
                and len(entry["ball_pos"]) >= 2
            ]
            if not points:
                return
            half_width = 34.0
            start_side = points[0][1] - half_width
            crossing = next(
                (
                    index
                    for index, (_, y) in enumerate(points[1:], 1)
                    if start_side * (y - half_width) < 0.0
                ),
                None,
            )
            lateral_travel = max(abs(y - points[0][1]) for _, y in points)
            switch_run_lifecycle_counts["runs"] += 1
            switch_run_lifecycle_counts[
                "crossed_pitch_center"
                if crossing is not None
                else "did_not_cross_pitch_center"
            ] += 1
            switch_run_lifecycle_metrics["run_updates"].append(float(len(rows)))
            switch_run_lifecycle_metrics["maximum_lateral_ball_travel_m"].append(
                lateral_travel
            )
            if crossing is not None:
                crossing_entry = rows[crossing]
                crossing_tick = int(crossing_entry["tick"])
                latest_release = next(
                    (
                        release
                        for release in reversed(switch_pass_releases_by_team[team])
                        if int(release["tick"]) <= crossing_tick
                        and int(release["tick"]) >= int(rows[0]["tick"])
                    ),
                    None,
                )
                release_origin = (
                    latest_release.get("origin")
                    if isinstance(latest_release, dict)
                    else None
                )
                release_target = (
                    latest_release.get("target")
                    if isinstance(latest_release, dict)
                    else None
                )
                pass_crossed_center = (
                    isinstance(release_origin, list)
                    and len(release_origin) >= 2
                    and isinstance(release_target, list)
                    and len(release_target) >= 2
                    and (float(release_origin[1]) - half_width)
                    * (float(release_target[1]) - half_width)
                    < 0.0
                )
                release_plan = (
                    team_plan_update_by_frame.get(
                        (team, latest_release.get("tick")), {}
                    ).get("selected")
                    if isinstance(latest_release, dict)
                    else None
                )
                terminal = (
                    switch_pass_terminals.get(latest_release.get("replay_id"), {})
                    if isinstance(latest_release, dict)
                    else {}
                )
                release_gap = (
                    crossing_tick - int(latest_release["tick"])
                    if isinstance(latest_release, dict)
                    else None
                )
                trigger = (
                    pass_crossed_center
                    and release_plan == "switch"
                    and terminal.get("outcome") == "completed"
                    and isinstance(terminal.get("tick"), int)
                    and int(terminal["tick"]) <= crossing_tick
                )
                switch_run_lifecycle_counts[
                    "completion_trigger=switch_pass"
                    if trigger
                    else "completion_trigger=other"
                ] += 1
                switch_run_lifecycle_counts[
                    f"completion_latest_release_plan={release_plan or 'none'}"
                ] += 1
                switch_run_lifecycle_counts[
                    "completion_latest_pass_crossed_center"
                    if pass_crossed_center
                    else "completion_latest_pass_did_not_cross_center"
                ] += 1
                if isinstance(release_gap, int):
                    switch_run_lifecycle_metrics[
                        "completion_latest_pass_release_gap_ticks"
                    ].append(float(release_gap))
                crossing_candidates = [
                    candidate
                    for candidate in crossing_entry.get("candidates", [])
                    if isinstance(candidate, dict)
                    and candidate.get("kind") != "switch"
                    and isinstance(candidate.get("value"), (int, float))
                ]
                best_non_switch = max(
                    crossing_candidates,
                    key=lambda candidate: float(candidate["value"]),
                    default=None,
                )
                switch_candidate = next(
                    (
                        candidate
                        for candidate in crossing_entry.get("candidates", [])
                        if isinstance(candidate, dict)
                        and candidate.get("kind") == "switch"
                    ),
                    None,
                )
                switch_run_lifecycle_metrics["updates_to_crossing"].append(
                    float(crossing)
                )
                switch_run_lifecycle_metrics["updates_after_crossing"].append(
                    float(len(rows) - crossing - 1)
                )
                switch_run_lifecycle_counts[
                    "continued_after_crossing"
                    if crossing + 1 < len(rows)
                    else "ended_at_crossing"
                ] += 1
                if best_non_switch is not None:
                    alternative_kind = str(best_non_switch.get("kind", "unknown"))
                    switch_run_lifecycle_counts[
                        f"completion_best_non_switch={alternative_kind}"
                    ] += 1
                    switch_run_lifecycle_metrics[
                        "completion_best_non_switch_value"
                    ].append(float(best_non_switch["value"]))
                    switch_run_lifecycle_metrics[
                        "completion_best_non_switch_raw_value"
                    ].append(float(best_non_switch.get("raw_value", 0.0)))
                    switch_run_lifecycle_metrics[
                        "completion_best_non_switch_switch_cost"
                    ].append(float(best_non_switch.get("switch_cost", 0.0)))
                    if isinstance(switch_candidate, dict) and isinstance(
                        switch_candidate.get("value"), (int, float)
                    ):
                        switch_run_lifecycle_metrics[
                            "completion_switch_margin_over_best_non_switch"
                        ].append(
                            float(switch_candidate["value"])
                            - float(best_non_switch["value"])
                        )
            switch_run_lifecycle_cases.append({
                "team": team,
                "start_tick": rows[0].get("tick"),
                "end_tick": rows[-1].get("tick"),
                "updates": len(rows),
                "start_ball_pos": list(points[0]),
                "end_ball_pos": list(points[-1]),
                "maximum_lateral_ball_travel_m": lateral_travel,
                "crossed_pitch_center": crossing is not None,
                "updates_to_crossing": crossing,
                "updates_after_crossing": (
                    len(rows) - crossing - 1 if crossing is not None else None
                ),
                "completion_frame": (
                    {
                        "tick": rows[crossing].get("tick"),
                        "prior": rows[crossing].get("prior"),
                        "features": rows[crossing].get("features"),
                        "signals": rows[crossing].get("signals"),
                        "switch_candidate": switch_candidate,
                        "best_non_switch_candidate": best_non_switch,
                        "next_baseline_selected": (
                            rows[crossing + 1].get("selected")
                            if crossing + 1 < len(rows)
                            else None
                        ),
                        "latest_pass": (
                            {
                                "tick": latest_release.get("tick"),
                                "replay_id": latest_release.get("replay_id"),
                                "origin": release_origin,
                                "target": release_target,
                                "release_plan": release_plan,
                                "crossed_pitch_center": pass_crossed_center,
                                "release_gap_ticks": release_gap,
                                "terminal_tick": terminal.get("tick"),
                                "terminal_outcome": terminal.get("outcome"),
                                "trigger_eligible": trigger,
                            }
                            if isinstance(latest_release, dict)
                            else None
                        ),
                    }
                    if crossing is not None
                    else None
                ),
            })

        for entry in updates:
            if entry.get("selected") == "switch":
                switch_run.append(entry)
            else:
                close_switch_run(switch_run)
                switch_run = []
        close_switch_run(switch_run)
    receipt_decision_waits = [
        float(entry["remaining_tick_fraction"])
        for entry in trace_entries
        if entry.get("event") == "receipt_decision_wait"
        and isinstance(entry.get("remaining_tick_fraction"), (int, float))
    ]
    receipt_decision_wait_by_action: dict[str, list[dict[str, float]]] = defaultdict(list)
    receipt_decision_wait_cases: list[dict[str, Any]] = []
    receipt_directional_release_counts: Counter[str] = Counter()
    receipt_directional_release_metrics: dict[str, list[float]] = defaultdict(list)
    ground_receipt_control_counts: Counter[str] = Counter()
    ground_receipt_control_metrics: dict[str, list[float]] = defaultdict(list)
    receipt_partial_preparation_counts: Counter[str] = Counter()
    receipt_partial_preparation_metrics: dict[str, list[float]] = defaultdict(list)
    receipt_neutral_settling_counts: Counter[str] = Counter()
    receipt_neutral_settling_metrics: dict[str, list[float]] = defaultdict(list)
    pass_terminal_outcome_by_replay = {
        entry.get("replay_id"): entry.get("outcome")
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    ground_receipt_control_by_identity: dict[
        tuple[Any, Any, Any], dict[str, Any]
    ] = {}
    for control_entry in trace_entries:
        if control_entry.get("event") != "ball_controlled":
            continue
        replay_id = control_entry.get("pending_pass_replay_id")
        live = control_entry.get("live_control")
        counterfactual = control_entry.get(
            "pass_arrival_control_counterfactual"
        )
        if not (
            replay_id is not None
            and pass_terminal_outcome_by_replay.get(replay_id) == "completed"
            and isinstance(live, dict)
            and isinstance(counterfactual, dict)
        ):
            continue
        identity = (
            control_entry.get("tick"),
            control_entry.get("team"),
            control_entry.get("player_idx"),
        )
        ground_receipt_control_by_identity[identity] = {
            "live": live,
            "counterfactual": counterfactual,
        }
        ground_receipt_control_counts["completed_receipts"] += 1
        for field in (
            "pressure_load",
            "containment_load",
            "forward_control",
            "turn_readiness",
            "release_window",
            "shape_readiness",
            "release_preparation",
            "continuation_control_readiness",
            "shot_release_readiness",
            "stagnation_load",
        ):
            live_value = live.get(field)
            counterfactual_value = counterfactual.get(field)
            if isinstance(live_value, (int, float)) and isinstance(
                counterfactual_value, (int, float)
            ):
                live_value = float(live_value)
                counterfactual_value = float(counterfactual_value)
                ground_receipt_control_metrics[f"live:{field}"].append(live_value)
                ground_receipt_control_metrics[f"counterfactual:{field}"].append(
                    counterfactual_value
                )
                ground_receipt_control_metrics[f"delta:{field}"].append(
                    counterfactual_value - live_value
                )
        live_preparation = live.get("release_preparation")
        counterfactual_preparation = counterfactual.get("release_preparation")
        if isinstance(live_preparation, (int, float)) and isinstance(
            counterfactual_preparation, (int, float)
        ):
            ground_receipt_control_counts[
                "counterfactual_preparation_higher"
                if float(counterfactual_preparation) > float(live_preparation) + 1e-12
                else "counterfactual_preparation_lower"
                if float(counterfactual_preparation) < float(live_preparation) - 1e-12
                else "counterfactual_preparation_equal"
            ] += 1
    for entry in trace_entries:
        event = entry.get("event")
        if event not in {"receipt_fast_pass", "receipt_decision_wait"}:
            continue
        selected_action = (
            "pass" if event == "receipt_fast_pass"
            else str(entry.get("selected_action", "unknown"))
        )
        control_pair = ground_receipt_control_by_identity.get(
            (entry.get("tick"), entry.get("holder_team"), entry.get("holder_idx"))
        )
        control_remaining = (
            entry.get("available_fraction")
            if event == "receipt_fast_pass"
            else entry.get("remaining_tick_fraction")
        )
        if isinstance(control_pair, dict) and isinstance(
            control_remaining, (int, float)
        ):
            live_preparation = control_pair["live"].get("release_preparation")
            counterfactual_preparation = control_pair["counterfactual"].get(
                "release_preparation"
            )
            if isinstance(live_preparation, (int, float)) and isinstance(
                counterfactual_preparation, (int, float)
            ):
                live_required = 1.0 - float(live_preparation)
                counterfactual_required = 1.0 - float(counterfactual_preparation)
                live_feasible = float(control_remaining) + 1e-12 >= live_required
                counterfactual_feasible = (
                    float(control_remaining) + 1e-12 >= counterfactual_required
                )
                transition = (
                    f"live={'feasible' if live_feasible else 'infeasible'}:"
                    f"counterfactual={'feasible' if counterfactual_feasible else 'infeasible'}"
                )
                ground_receipt_control_counts[f"action={selected_action}"] += 1
                ground_receipt_control_counts[
                    f"action={selected_action}:{transition}"
                ] += 1
                ground_receipt_control_metrics[
                    f"action={selected_action}:{transition}:remaining_fraction"
                ].append(float(control_remaining))
                ground_receipt_control_metrics[
                    f"action={selected_action}:{transition}:counterfactual_minus_live_required"
                ].append(counterfactual_required - live_required)
        if selected_action == "pass":
            remaining = (
                entry.get("available_fraction")
                if event == "receipt_fast_pass"
                else entry.get("remaining_tick_fraction")
            )
            production_required = (
                entry.get("required_release_fraction")
                if event == "receipt_fast_pass"
                else entry.get("communication_required_release_fraction")
            )
            directional_required = entry.get(
                "directional_required_release_fraction"
            )
            directional_readiness = entry.get("directional_release_readiness")
            if all(
                isinstance(value, (int, float))
                for value in (remaining, production_required, directional_required)
            ):
                remaining = float(remaining)
                production_required = float(production_required)
                directional_required = float(directional_required)
                production_feasible = remaining + 1e-12 >= production_required
                directional_feasible = remaining + 1e-12 >= directional_required
                transition = (
                    f"production={'feasible' if production_feasible else 'infeasible'}:"
                    f"directional={'feasible' if directional_feasible else 'infeasible'}"
                )
                receipt_directional_release_counts["pass_receipts"] += 1
                receipt_directional_release_counts[transition] += 1
                receipt_directional_release_counts[
                    f"event={'fast_pass' if event == 'receipt_fast_pass' else 'wait'}"
                ] += 1
                receipt_directional_release_metrics[
                    f"{transition}:remaining_fraction"
                ].append(remaining)
                receipt_directional_release_metrics[
                    f"{transition}:production_required_fraction"
                ].append(production_required)
                receipt_directional_release_metrics[
                    f"{transition}:directional_required_fraction"
                ].append(directional_required)
                receipt_directional_release_metrics[
                    f"{transition}:directional_minus_production_required"
                ].append(directional_required - production_required)
                if isinstance(directional_readiness, (int, float)):
                    receipt_directional_release_metrics[
                        f"{transition}:directional_readiness"
                    ].append(float(directional_readiness))
        if event != "receipt_decision_wait":
            continue
        action = str(entry.get("selected_action", "unknown"))
        partial = entry.get("partial_preparation_control_counterfactual")
        if isinstance(partial, dict):
            receipt_partial_preparation_counts[f"action={action}"] += 1
            for field, live_field in (
                ("release_preparation", "live_release_preparation"),
                (
                    "continuation_control_readiness",
                    "live_continuation_control_readiness",
                ),
                ("shot_release_readiness", "live_shot_release_readiness"),
            ):
                live_value = entry.get(live_field)
                counterfactual_value = partial.get(field)
                if isinstance(live_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    live_value = float(live_value)
                    counterfactual_value = float(counterfactual_value)
                    receipt_partial_preparation_metrics[
                        f"action={action}:live:{field}"
                    ].append(live_value)
                    receipt_partial_preparation_metrics[
                        f"action={action}:counterfactual:{field}"
                    ].append(counterfactual_value)
                    receipt_partial_preparation_metrics[
                        f"action={action}:delta:{field}"
                    ].append(counterfactual_value - live_value)
                    receipt_partial_preparation_counts[
                        f"action={action}:{field}=higher"
                        if counterfactual_value > live_value + 1e-12
                        else f"action={action}:{field}=lower"
                        if counterfactual_value < live_value - 1e-12
                        else f"action={action}:{field}=equal"
                    ] += 1
        neutral = entry.get("neutral_settling_control_counterfactual")
        if isinstance(neutral, dict):
            receipt_neutral_settling_counts[f"action={action}"] += 1
            for field, live_field in (
                ("release_preparation", "live_release_preparation"),
                (
                    "continuation_control_readiness",
                    "live_continuation_control_readiness",
                ),
                ("shot_release_readiness", "live_shot_release_readiness"),
            ):
                live_value = entry.get(live_field)
                counterfactual_value = neutral.get(field)
                if isinstance(live_value, (int, float)) and isinstance(
                    counterfactual_value, (int, float)
                ):
                    live_value = float(live_value)
                    counterfactual_value = float(counterfactual_value)
                    receipt_neutral_settling_metrics[
                        f"action={action}:live:{field}"
                    ].append(live_value)
                    receipt_neutral_settling_metrics[
                        f"action={action}:counterfactual:{field}"
                    ].append(counterfactual_value)
                    receipt_neutral_settling_metrics[
                        f"action={action}:delta:{field}"
                    ].append(counterfactual_value - live_value)
                    receipt_neutral_settling_counts[
                        f"action={action}:{field}=higher"
                        if counterfactual_value > live_value + 1e-12
                        else f"action={action}:{field}=lower"
                        if counterfactual_value < live_value - 1e-12
                        else f"action={action}:{field}=equal"
                    ] += 1
        row = receipt_decision_wait_by_action[action]
        remaining = entry.get("remaining_tick_fraction")
        duration = entry.get("selected_action_duration_fraction")
        if isinstance(remaining, (int, float)):
            row.append({"remaining": float(remaining), "duration": float(duration) if isinstance(duration, (int, float)) else 0.0})
        tick = entry.get("tick")
        team = entry.get("holder_team")
        holder_idx = entry.get("holder_idx")
        if isinstance(tick, int) and team in {"home", "away"} and isinstance(
            holder_idx, int
        ):
            next_decision = next(
                (
                    candidate
                    for candidate in on_ball_decisions
                    if candidate.get("team") == team
                    and candidate.get("player_idx") == holder_idx
                    and isinstance(candidate.get("tick"), int)
                    and int(candidate["tick"]) > tick
                ),
                None,
            )
            next_release = next(
                (
                    candidate
                    for candidate in trace_entries
                    if candidate.get("action") == "pass"
                    and candidate.get("team") == team
                    and candidate.get("passer_player") == holder_idx
                    and isinstance(candidate.get("tick"), int)
                    and isinstance(tick, int)
                    and int(candidate["tick"]) > tick
                ),
                None,
            )
            selected_pass = entry.get("selected_pass", {})
            receipt_decision_wait_cases.append({
                "tick": tick,
                "team": team,
                "holder_idx": holder_idx,
                "remaining_tick_fraction": remaining,
                "required_release_fraction": entry.get(
                    "communication_required_release_fraction"
                ),
                "selected_action_duration_fraction": duration,
                "selected_pass": selected_pass,
                "reason": entry.get("reason"),
                "selected_action": entry.get("selected_action"),
                "next_decision_tick": (
                    next_decision.get("tick")
                    if isinstance(next_decision, dict)
                    else None
                ),
                "next_decision_lead_ticks": (
                    int(next_decision["tick"]) - tick
                    if isinstance(next_decision, dict)
                    and isinstance(next_decision.get("tick"), int)
                    else None
                ),
                "next_decision_action": (
                    next_decision.get("chosen", {}).get("action_type")
                    if isinstance(next_decision, dict)
                    else None
                ),
                "next_release_tick": (
                    next_release.get("tick")
                    if isinstance(next_release, dict)
                    else None
                ),
                "next_release_lead_ticks": (
                    int(next_release["tick"]) - tick
                    if isinstance(next_release, dict)
                    and isinstance(next_release.get("tick"), int)
                    and isinstance(tick, int)
                    else None
                ),
                "next_release_distance_m": (
                    next_release.get("actual_distance_m")
                    if isinstance(next_release, dict)
                    else None
                ),
            })
    held_execution_phases: Counter[str] = Counter()
    carry_tick_distance_by_phase: dict[str, list[float]] = defaultdict(list)
    stable_control_provenance: Counter[str] = Counter()
    carry_episode_distances: list[float] = []
    carry_episode_rows: list[dict[str, Any]] = []
    active_carry_episodes: dict[tuple[Any, Any, Any], dict[str, Any]] = {}
    decisions_by_actor: dict[tuple[Any, Any], list[dict[str, Any]]] = defaultdict(list)
    decisions_by_tick_actor: dict[tuple[Any, Any, Any], list[dict[str, Any]]] = defaultdict(list)
    for decision in on_ball_decisions:
        actor = (decision.get("team"), decision.get("player_idx"))
        decisions_by_actor[actor].append(decision)
        decisions_by_tick_actor[(
            decision.get("tick"),
            decision.get("team"),
            decision.get("player_idx"),
        )].append(decision)
    for rows in decisions_by_actor.values():
        rows.sort(key=lambda decision: int(decision.get("tick", -1)))
    carry_commitment_endings = [
        entry
        for entry in trace_entries
        if entry.get("event") == "action_commitment_ended"
        and entry.get("action") == "carry"
        and isinstance(entry.get("tick"), int)
    ]

    def finish_carry_episode(
        key: tuple[Any, Any, Any],
        next_action_entry: dict[str, Any] | None = None,
    ) -> None:
        episode = active_carry_episodes.pop(key, None)
        if episode is None:
            return
        carry_episode_distances.append(float(episode["distance_m"]))
        start_tick_value = episode["start_tick"]
        end_tick_value = episode["end_tick"]
        start_tick = int(start_tick_value) if isinstance(start_tick_value, int) else None
        end_tick = int(end_tick_value) if isinstance(end_tick_value, int) else None
        ending = next((
            entry
            for entry in carry_commitment_endings
            if entry.get("team") == episode["team"]
            and entry.get("player_idx") == episode["player_idx"]
            and start_tick is not None
            and end_tick is not None
            and start_tick <= int(entry["tick"]) <= end_tick + 1
        ), None)
        next_decision = next((
            decision
            for decision in decisions_by_actor.get(
                (episode["team"], episode["player_idx"]), []
            )
            if end_tick is not None and int(decision.get("tick", -1)) > end_tick
        ), None)
        episode["commitment_end_reason"] = (
            ending.get("reason") if isinstance(ending, dict) else None
        )
        episode["commitment_remaining_distance_m"] = (
            ending.get("remaining_distance") if isinstance(ending, dict) else None
        )
        episode["next_action"] = (
            next_action_entry.get("action")
            if isinstance(next_action_entry, dict)
            else next_decision.get("chosen", {}).get("action_type")
            if isinstance(next_decision, dict)
            else None
        )
        episode["next_decision_tick"] = (
            next_decision.get("tick") if isinstance(next_decision, dict) else None
        )
        episode["next_decision_gap_ticks"] = (
            int(next_decision["tick"]) - end_tick
            if isinstance(next_decision, dict)
            and isinstance(next_decision.get("tick"), int)
            and end_tick is not None
            else None
        )
        carry_episode_rows.append(episode)
    restart_readiness_counts: Counter[str] = Counter()
    restart_readiness_distances: dict[str, list[float]] = defaultdict(list)
    for entry in trace_entries:
        action = entry.get("action")
        phase = entry.get("phase")
        if action in {"carry", "hold", "reorient"} and phase in {"start", "continue"}:
            held_execution_phases[f"{action}:{phase}"] += 1
        if entry.get("event") == "ball_controlled":
            provenance = (
                "pass"
                if entry.get("settled_pass") is True
                else "same_team_loose_recovery"
                if entry.get("same_team_as_previous_possession") is True
                else "opponent_control_gain"
            )
            stable_control_provenance[provenance] += 1
        if entry.get("type") == "action" and action in held_action_names:
            actor = (entry.get("team"), entry.get("player_idx"))
            for active_key in [
                key for key in active_carry_episodes if key[:2] == actor
            ]:
                if action != "carry" or phase == "start":
                    finish_carry_episode(active_key, entry)
        if action == "carry" and phase in {"start", "continue"}:
            key = (entry.get("team"), entry.get("player_idx"), entry.get("possession_id"))
            distance_value = entry.get("physical_distance", entry.get("distance"))
            if phase == "start":
                decision = next((
                    candidate
                    for candidate in decisions_by_tick_actor.get(
                        (entry.get("tick"), entry.get("team"), entry.get("player_idx")),
                        [],
                    )
                    if candidate.get("chosen", {}).get("action_type") == "carry"
                ), None)
                chosen = decision.get("chosen", {}) if isinstance(decision, dict) else {}
                decision_candidates = (
                    [chosen, *decision.get("alternatives", [])]
                    if isinstance(decision, dict)
                    else []
                )
                pass_candidates = [
                    candidate
                    for candidate in decision_candidates
                    if isinstance(candidate, dict)
                    and candidate.get("action_type") == "pass"
                    and isinstance(candidate.get("value", {}).get("score"), (int, float))
                ]
                best_pass = max(
                    pass_candidates,
                    key=lambda candidate: float(candidate["value"]["score"]),
                    default=None,
                )
                chosen_score = chosen.get("value", {}).get("score")
                best_pass_score = (
                    best_pass.get("value", {}).get("score")
                    if isinstance(best_pass, dict)
                    else None
                )
                active_carry_episodes[key] = {
                    "team": entry.get("team"),
                    "player_idx": entry.get("player_idx"),
                    "possession_id": entry.get("possession_id"),
                    "start_tick": entry.get("tick"),
                    "end_tick": entry.get("tick"),
                    "action_ticks": 0,
                    "distance_m": 0.0,
                    "start_target": entry.get("target"),
                    "start_from": entry.get("from"),
                    "start_pos": entry.get("pos"),
                    "start_movement_progress": entry.get("movement_progress"),
                    "start_constrained_control": entry.get("constrained_control"),
                    "start_containment_probability": entry.get("containment_probability"),
                    "start_containment_position": entry.get("containment_position"),
                    "start_pressure": (
                        decision.get("pressure") if isinstance(decision, dict) else None
                    ),
                    "start_control": (
                        decision.get("control") if isinstance(decision, dict) else None
                    ),
                    "start_chosen_score": chosen_score,
                    "start_option_duration_seconds": chosen.get("value", {})
                        .get("components", {}).get("option_duration_seconds"),
                    "start_best_pass_score": best_pass_score,
                    "start_carry_minus_best_pass_score": (
                        float(chosen_score) - float(best_pass_score)
                        if isinstance(chosen_score, (int, float))
                        and isinstance(best_pass_score, (int, float))
                        else None
                    ),
                    "start_best_pass_target": (
                        best_pass.get("target") if isinstance(best_pass, dict) else None
                    ),
                }
            if isinstance(distance_value, (int, float)):
                carry_tick_distance_by_phase[str(phase)].append(float(distance_value))
                episode = active_carry_episodes.get(key)
                if episode is not None:
                    episode["end_tick"] = entry.get("tick")
                    episode["action_ticks"] = int(episode["action_ticks"]) + 1
                    episode["distance_m"] = float(episode["distance_m"]) + float(
                        distance_value
                    )
        if entry.get("event") == "restart_readiness":
            reason = str(entry.get("reason", "unknown"))
            restart_readiness_counts[f"{reason}:count"] += 1
            restart_readiness_counts[
                f"{reason}:set_receiver_pos={str(bool(entry.get('set_receiver_pos'))).lower()}"
            ] += 1
            distance_value = entry.get("taker_distance_before_force")
            if isinstance(distance_value, (int, float)):
                restart_readiness_distances[reason].append(float(distance_value))
    for key in list(active_carry_episodes):
        finish_carry_episode(key)
    support_goal_distance_counterfactual: Counter[str] = Counter()
    support_goal_distance_metrics: dict[str, list[float]] = defaultdict(list)
    passer_flight_support_counts: Counter[str] = Counter()
    passer_flight_support_metrics: dict[str, list[float]] = defaultdict(list)
    passer_flight_support_by_replay: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    for entry in response.get("trace", {}).get("entries", []):
        if entry.get("event") == "passer_flight_support_eligibility":
            passer_flight_support_by_replay[entry.get("replay_id")].append(entry)
    for rows in passer_flight_support_by_replay.values():
        distances = [
            float(row["distance_to_destination_m"])
            for row in rows
            if isinstance(row.get("distance_to_destination_m"), (int, float))
        ]
        eligible = any(bool(row.get("excluded_while_physically_eligible")) for row in rows)
        passer_flight_support_counts["passes"] += 1
        passer_flight_support_counts["ever_eligible" if eligible else "never_eligible"] += 1
        if distances:
            passer_flight_support_metrics["minimum_distance_to_destination_m"].append(min(distances))
            passer_flight_support_metrics["terminal_distance_to_destination_m"].append(distances[-1])
    off_ball_decisions = [
        decision
        for decision in response.get("trace", {}).get("decisions", [])
        if decision.get("phase") == "off_ball_attack"
        and isinstance(decision.get("chosen"), dict)
    ]
    off_ball_by_key = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")): decision
        for decision in off_ball_decisions
    }
    controller_handoff_decisions_by_replay: dict[
        Any, list[dict[str, Any]]
    ] = defaultdict(list)
    for decision in off_ball_decisions:
        handoff_candidate = decision.get("controller_handoff_candidate")
        if isinstance(handoff_candidate, dict):
            controller_handoff_decisions_by_replay[
                handoff_candidate.get("replay_id")
            ].append(decision)
    for replay_decisions in controller_handoff_decisions_by_replay.values():
        replay_decisions.sort(key=lambda decision: int(decision.get("tick", -1)))
    off_ball_by_team_tick: dict[tuple[Any, Any], list[dict[str, Any]]] = defaultdict(list)
    last_visual_carrier_by_player: dict[tuple[Any, Any], dict[str, Any]] = {}
    for decision in sorted(
        off_ball_decisions,
        key=lambda row: (
            int(row.get("tick", -1)),
            str(row.get("team")),
            int(row.get("player_idx", -1)),
        ),
    ):
        off_ball_by_team_tick[(decision.get("team"), decision.get("tick"))].append(decision)
        for candidate in [decision.get("chosen", {}), *decision.get("alternatives", [])]:
            if not isinstance(candidate, dict):
                continue
            value = candidate.get("value", {})
            if value.get("goal_type") != "support_carrier":
                continue
            components = value.get("components", {})
            distance_to_ball = components.get("dist_to_ball")
            support_angle = components.get("support_angle_value")
            layoff = components.get("layoff_window")
            if not all(
                isinstance(metric, (int, float))
                for metric in (distance_to_ball, support_angle, layoff)
            ):
                continue
            distance_weight = exp(-float(distance_to_ball) / 12.0)
            weighted_support = float(support_angle) * distance_weight
            weighted_layoff = float(layoff) * distance_weight
            retained = weighted_support > 0.18 or weighted_layoff > 0.10
            candidate_progress = components.get("candidate_progress")
            candidate_width = components.get("candidate_width")
            if retained:
                reclassified_goal = "support_carrier"
            elif isinstance(candidate_progress, (int, float)) and float(candidate_progress) > 0.76:
                reclassified_goal = "run_behind"
            elif (
                isinstance(candidate_width, (int, float))
                and isinstance(candidate_progress, (int, float))
                and float(candidate_width) > 0.62
                and float(candidate_progress) > 0.58
            ):
                reclassified_goal = "hold_width"
            else:
                reclassified_goal = "recycle_support"
            label = (
                "retained_support_carrier"
                if retained
                else f"reclassified_to_{reclassified_goal}"
            )
            support_goal_distance_counterfactual[label] += 1
            support_goal_distance_metrics[f"{label}:distance_to_ball_m"].append(
                float(distance_to_ball)
            )
            support_goal_distance_metrics[f"{label}:distance_weight"].append(distance_weight)
            support_goal_distance_metrics[f"{label}:weighted_support_angle"].append(
                weighted_support
            )
            support_goal_distance_metrics[f"{label}:weighted_layoff"].append(
                weighted_layoff
            )
    off_ball_coordination = [
        decision
        for decision in response.get("trace", {}).get("decisions", [])
        if decision.get("phase") == "off_ball_attack_spatial_coordination"
    ]
    off_ball_coordination_rows_by_key: dict[
        tuple[Any, Any, Any], list[dict[str, Any]]
    ] = defaultdict(list)
    for decision in off_ball_coordination:
        off_ball_coordination_rows_by_key[(
            decision.get("tick"),
            decision.get("team"),
            decision.get("player_idx"),
        )].append(decision)
    latest_off_ball_decision_by_key = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")): decision
        for decision in response.get("trace", {}).get("decisions", [])
        if decision.get("phase") == "off_ball_attack"
    }
    off_ball_coordination_by_key = {
        key: rows[-1]
        for key, rows in off_ball_coordination_rows_by_key.items()
    }
    tactical_task_decisions = [
        decision
        for decision in response.get("trace", {}).get("decisions", [])
        if decision.get("phase") == "tactical_task"
    ]

    def task_fingerprint(task: Any) -> tuple[Any, ...] | None:
        if not isinstance(task, dict):
            return None
        raw_target = task.get("raw_target")
        target = (
            (round(float(raw_target[0]), 9), round(float(raw_target[1]), 9))
            if isinstance(raw_target, (list, tuple))
            and len(raw_target) >= 2
            and all(isinstance(value, (int, float)) for value in raw_target[:2])
            else None
        )
        return (
            str(task.get("intent") or "none"),
            str(task.get("phase") or "none"),
            task.get("accepted_tick"),
            task.get("expires_tick"),
            target,
        )

    # Reconstruct task provenance from the operation that actually commits a
    # spatial goal.  A later goal->task synchronization only replays the stored
    # goal, so it must not silently rebind that goal to a new holder.
    task_provenance_before_off_ball: dict[
        tuple[Any, Any, Any], dict[str, Any]
    ] = {}
    live_task_provenance: dict[tuple[Any, Any], dict[str, Any]] = {}
    off_ball_holder_by_key = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")):
            decision.get("holder_idx")
        for decision in off_ball_decisions
    }
    for trace_decision in response.get("trace", {}).get("decisions", []):
        phase = trace_decision.get("phase")
        tick = trace_decision.get("tick")
        team = trace_decision.get("team")
        player_idx = trace_decision.get("player_idx")
        if not (
            isinstance(tick, int)
            and team in {"home", "away"}
            and isinstance(player_idx, int)
        ):
            continue
        player_key = (team, player_idx)
        frame_key = (tick, team, player_idx)
        if phase == "off_ball_attack":
            previous_task = trace_decision.get("previous_tactical_task")
            provenance = live_task_provenance.get(player_key)
            if (
                isinstance(provenance, dict)
                and task_fingerprint(provenance.get("task"))
                != task_fingerprint(previous_task)
            ):
                # Some non-spatial clear/goal paths do not carry owner identity.
                # Drop the stale reconstruction rather than attributing it to
                # the wrong controller.
                live_task_provenance.pop(player_key, None)
                provenance = None
            if isinstance(provenance, dict):
                task_provenance_before_off_ball[frame_key] = dict(provenance)
            continue
        if phase == "off_ball_attack_spatial_coordination":
            resolution = trace_decision.get("resolution", {})
            declaration = trace_decision.get("declaration", {})
            actual_task = resolution.get("actual_task")
            if declaration.get("task_accepted") is True:
                owner_holder_idx = off_ball_holder_by_key.get(frame_key)
                live_task_provenance[player_key] = {
                    "owner_holder_idx": (
                        int(owner_holder_idx)
                        if isinstance(owner_holder_idx, int)
                        else None
                    ),
                    "source_goal": str(
                        declaration.get("goal_type") or "unknown"
                    ),
                    "committed_tick": tick,
                    "task": actual_task,
                }
            elif isinstance(actual_task, dict) and player_key in live_task_provenance:
                live_task_provenance[player_key]["task"] = actual_task
            continue
        if phase == "tactical_task":
            outcome = str(
                trace_decision.get("resolution", {}).get("outcome") or "unknown"
            )
            task = trace_decision.get("task")
            if outcome == "cancelled" or (
                isinstance(task, dict)
                and str(task.get("phase") or "").lower() != "active"
            ):
                live_task_provenance.pop(player_key, None)
            elif player_key in live_task_provenance and isinstance(task, dict):
                # Preserve the goal/controller provenance while following the
                # task payload written by the normal synchronization pass.
                live_task_provenance[player_key]["task"] = task
    commitment_decisions = [
        decision
        for decision in response.get("trace", {}).get("decisions", [])
        if decision.get("phase") == "on_ball_commitment"
    ]
    commitment_counts: Counter[str] = Counter()
    commitment_metrics: dict[str, list[float]] = defaultdict(list)
    commitment_interrupt_profiles: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    interrupted_replacement_counts: Counter[str] = Counter()
    commitment_end_counts: Counter[str] = Counter()
    commitment_end_metrics: dict[str, list[float]] = defaultdict(list)
    carry_tick_progress: dict[tuple[Any, Any, Any], float] = {}
    for entry in trace_entries:
        if entry.get("action") != "carry" or not isinstance(entry.get("tick"), int):
            continue
        key = (entry.get("tick"), entry.get("team"), entry.get("player_idx"))
        progress = entry.get("movement_progress")
        if isinstance(progress, (int, float)):
            carry_tick_progress[key] = float(progress)
    on_ball_decisions_by_identity: dict[
        tuple[Any, Any], list[dict[str, Any]]
    ] = defaultdict(list)
    for decision in response.get("trace", {}).get("decisions", []):
        if decision.get("phase") == "on_ball" and isinstance(
            decision.get("chosen"), dict
        ):
            on_ball_decisions_by_identity[
                (
                    decision.get("team"),
                    decision.get("player_idx"),
                )
            ].append(decision)
    for identity_decisions in on_ball_decisions_by_identity.values():
        identity_decisions.sort(key=lambda decision: int(decision.get("tick", -1)))
    for entry in trace_entries:
        if entry.get("event") != "action_commitment_ended":
            continue
        action = str(entry.get("action", "unknown"))
        reason = str(entry.get("reason", "unknown"))
        commitment_end_counts[f"{action}:{reason}"] += 1
        if action == "carry" and reason == "target_reached":
            progress = carry_tick_progress.get(
                (entry.get("tick"), entry.get("team"), entry.get("player_idx"))
            )
            if isinstance(progress, (int, float)):
                commitment_end_metrics["carry:target_reached:movement_progress"].append(
                    float(progress)
                )
                commitment_end_metrics["carry:target_reached:unused_tick_fraction"].append(
                    max(1.0 - float(progress), 0.0)
                )
            next_decision = next(
                (
                    decision
                    for decision in on_ball_decisions_by_identity.get(
                        (
                            entry.get("team"),
                            entry.get("player_idx"),
                        ),
                        [],
                    )
                    if int(entry.get("tick", -1))
                    < int(decision.get("tick", -1))
                    <= int(entry.get("tick", -1)) + 2
                ),
                None,
            )
            if next_decision is None:
                commitment_end_counts["carry:target_reached:next=none"] += 1
            else:
                next_chosen = next_decision.get("chosen", {})
                next_action = str(next_chosen.get("action_type", "unknown"))
                commitment_end_counts[f"carry:target_reached:next={next_action}"] += 1
                commitment_end_metrics["carry:target_reached:next_tick_gap"].append(
                    float(int(next_decision.get("tick", -1)) - int(entry.get("tick", -1)))
                )
                previous_origin = entry.get("holder_pos")
                previous_target = entry.get("local_action_target")
                next_origin = next_decision.get("pos")
                next_target = next_chosen.get("target")
                if (
                    next_action == "carry"
                    and all(
                        isinstance(value, list) and len(value) >= 2
                        for value in (
                            previous_origin,
                            previous_target,
                            next_origin,
                            next_target,
                        )
                    )
                ):
                    previous_angle = atan2(
                        float(previous_target[1]) - float(previous_origin[1]),
                        float(previous_target[0]) - float(previous_origin[0]),
                    )
                    next_angle = atan2(
                        float(next_target[1]) - float(next_origin[1]),
                        float(next_target[0]) - float(next_origin[0]),
                    )
                    commitment_end_metrics[
                        "carry:target_reached:next_carry_turn_degrees"
                    ].append(
                        abs(
                            (degrees(next_angle - previous_angle) + 180.0) % 360.0
                            - 180.0
                        )
                    )
        for field in (
            "elapsed_seconds",
            "initial_ticks",
            "valued_duration_ticks",
            "valued_carry_segment_count",
            "commitment_target_distance",
            "elapsed_ticks",
            "remaining_distance",
            "completion_distance",
        ):
            value = entry.get(field)
            if isinstance(value, (int, float)):
                commitment_end_metrics[f"{action}:{reason}:{field}"].append(float(value))
        commitment_origin = entry.get("commitment_origin")
        holder_pos = entry.get("holder_pos")
        if (
            action == "carry"
            and isinstance(commitment_origin, list)
            and len(commitment_origin) >= 2
            and isinstance(holder_pos, list)
            and len(holder_pos) >= 2
        ):
            commitment_end_metrics[f"carry:{reason}:executed_displacement_m"].append(
                hypot(
                    float(holder_pos[0]) - float(commitment_origin[0]),
                    float(holder_pos[1]) - float(commitment_origin[1]),
                )
            )
        remaining = entry.get("remaining_distance")
        completion = entry.get("completion_distance")
        if isinstance(remaining, (int, float)) and isinstance(completion, (int, float)):
            commitment_end_metrics[f"{action}:{reason}:remaining_over_completion"].append(
                float(remaining) / max(float(completion), 1e-9)
            )
        local_target = entry.get("local_action_target")
        for label in ("tactical", "goal"):
            reference_target = entry.get(f"{label}_target")
            if not (
                isinstance(local_target, list)
                and len(local_target) >= 2
                and isinstance(reference_target, list)
                and len(reference_target) >= 2
            ):
                continue
            origin = entry.get("holder_pos")
            if not (isinstance(origin, list) and len(origin) >= 2):
                continue
            local_angle = atan2(
                float(local_target[1]) - float(origin[1]),
                float(local_target[0]) - float(origin[0]),
            )
            reference_angle = atan2(
                float(reference_target[1]) - float(origin[1]),
                float(reference_target[0]) - float(origin[0]),
            )
            angle_gap = abs((degrees(local_angle - reference_angle) + 180.0) % 360.0 - 180.0)
            commitment_end_metrics[f"{action}:{reason}:{label}_angle_gap_degrees"].append(
                angle_gap
            )
    for decision in commitment_decisions:
        action = str(decision.get("committed_action", "unknown"))
        interrupted = bool(decision.get("interrupted"))
        release = decision.get("best_visible_release")
        release_action = (
            str(release.get("action_type", "none"))
            if isinstance(release, dict) else "none"
        )
        commitment_counts[f"{action}:evaluated"] += 1
        commitment_counts[f"{action}:{'interrupted' if interrupted else 'continued'}"] += 1
        commitment_counts[f"{action}:release={release_action}"] += 1
        continuation_value = decision.get("continuation_value")
        switch_cost = decision.get("switch_cost")
        release_value = (
            release.get("value", {}).get("score")
            if isinstance(release, dict) else None
        )
        if isinstance(continuation_value, (int, float)):
            commitment_metrics[f"{action}:continuation_value"].append(float(continuation_value))
        if isinstance(switch_cost, (int, float)):
            commitment_metrics[f"{action}:switch_cost"].append(float(switch_cost))
        if isinstance(release_value, (int, float)) and isinstance(continuation_value, (int, float)):
            advantage = float(release_value) - float(continuation_value)
            commitment_metrics[f"{action}:release_advantage"].append(advantage)
            if release_action == "pass":
                commitment_counts[
                    f"{action}:better_pass_blocked"
                    if advantage > 1e-12 and not interrupted
                    else f"{action}:pass_other"
                ] += 1
            if interrupted and isinstance(release, dict):
                profile = commitment_interrupt_profiles[f"{action}->{release_action}"]
                release_components = release.get("value", {}).get("components", {})
                motor_context = decision.get("release_motor_context", {})
                for field, value in (
                    ("retention", release.get("value", {}).get("success_prob")),
                    ("score", release_value),
                    ("after_value", release_components.get("after_value")),
                    ("base_accuracy", release_components.get("base_accuracy")),
                    ("lane_risk", release_components.get("lane_risk")),
                    ("option_duration_seconds", release_components.get("option_duration_seconds")),
                    ("switch_cost", switch_cost),
                    ("release_advantage", advantage),
                ):
                    if isinstance(value, (int, float)):
                        profile[field].append(float(value))
                if isinstance(motor_context, dict):
                    for field in (
                        "turn_angle_degrees",
                        "directional_control_readiness",
                        "release_preparation",
                        "turn_readiness",
                        "release_window",
                    ):
                        value = motor_context.get(field)
                        if isinstance(value, (int, float)):
                            profile[field].append(float(value))
                executed = next(
                    (
                        candidate
                        for candidate in response.get("trace", {}).get("decisions", [])
                        if candidate.get("phase") == "on_ball"
                        and candidate.get("tick") == decision.get("tick")
                        and candidate.get("team") == decision.get("team")
                        and candidate.get("player_idx") == decision.get("player_idx")
                    ),
                    None,
                )
                executed_action = (
                    str(executed.get("chosen", {}).get("action_type", "unknown"))
                    if isinstance(executed, dict)
                    else "missing"
                )
                interrupted_replacement_counts[
                    f"trigger={release_action}:executed={executed_action}"
                ] += 1
    decisions = on_ball_decisions
    possession_interruption = _engine_possession_interruption_hazard(response)
    engine_hazard = possession_interruption.get("hazard_per_active_second")
    fixed_hazards = [
        ("production_reference", 0.005),
        ("sensitivity_0.04", 0.04),
        ("sensitivity_0.08", 0.08),
    ]
    if isinstance(engine_hazard, (int, float)) and float(engine_hazard) > 0.0:
        fixed_hazards.append(("engine_possession_interruption", float(engine_hazard)))
    temporal_hazard_scenarios = {
        f"source={source}:lambda={hazard:.6f}:pass_duration={pass_duration}": {
            "source": source,
            "lambda_per_second": hazard,
            "pass_duration": pass_duration,
            "candidate_transition_hazard": False,
        }
        for source, hazard in fixed_hazards
        for pass_duration in ("flight", "release")
    }
    temporal_hazard_scenarios[
        "source=candidate_transition:lambda=per_candidate:pass_duration=flight"
    ] = {
        "source": "candidate_transition",
        "lambda_per_second": None,
        "pass_duration": "flight",
        "candidate_transition_hazard": True,
    }
    temporal_hazard_counts: dict[str, Counter[str]] = {
        label: Counter() for label in temporal_hazard_scenarios
    }
    temporal_hazard_pacing: dict[str, dict[str, float]] = defaultdict(
        lambda: defaultdict(float)
    )
    transition_hazard_metrics: dict[str, list[float]] = defaultdict(list)
    for decision in decisions:
        candidates = [decision.get("chosen", {}), *decision.get("alternatives", [])]
        scored_candidates: list[dict[str, Any]] = []
        for candidate_index, candidate in enumerate(candidates):
            if not isinstance(candidate, dict):
                continue
            components = candidate.get("value", {}).get("components", {})
            option_return = components.get("option_return")
            temporal_discount = components.get("temporal_discount")
            duration = components.get("option_duration_seconds")
            local_shaping = components.get("local_shaping")
            if not all(
                isinstance(value, (int, float))
                for value in (option_return, temporal_discount, duration, local_shaping)
            ) or float(temporal_discount) <= 1e-12:
                continue
            undiscounted_return = float(option_return) / float(temporal_discount)
            target = candidate.get("target")
            origin = decision.get("pos")
            distance_m = (
                hypot(
                    float(target[0]) - float(origin[0]),
                    float(target[1]) - float(origin[1]),
                )
                if isinstance(target, list)
                and len(target) >= 2
                and isinstance(origin, list)
                and len(origin) >= 2
                else None
            )
            target_kind = components.get("target_kind")
            action_type = str(candidate.get("action_type", "unknown"))
            transition = components.get("outcome_transition", {})
            retained_probability = transition.get("retained_control_probability")
            transition_hazard = (
                -log(max(min(float(retained_probability), 1.0), 1e-12))
                / max(float(duration), 0.05)
                if isinstance(retained_probability, (int, float))
                else None
            )
            if isinstance(transition_hazard, (int, float)):
                transition_hazard_metrics[f"action={action_type}"].append(
                    transition_hazard
                )
                if action_type == "pass" and isinstance(distance_m, (int, float)):
                    distance_band = (
                        "0_10m"
                        if distance_m < 10.0
                        else "10_20m"
                        if distance_m < 20.0
                        else "20_30m"
                        if distance_m < 30.0
                        else "30m_plus"
                    )
                    transition_hazard_metrics[
                        f"action=pass:distance={distance_band}"
                    ].append(transition_hazard)
            scored_candidates.append({
                "observed": candidate_index == 0,
                "action": action_type,
                "undiscounted_return": undiscounted_return,
                "duration_seconds": float(duration),
                "local_shaping": float(local_shaping),
                "distance_m": distance_m,
                "target_kind": (
                    str(target_kind) if isinstance(target_kind, str) else None
                ),
                "transition_hazard": transition_hazard,
            })
        if not scored_candidates:
            continue
        observed_action = str(decision.get("chosen", {}).get("action_type", "unknown"))
        observed_candidate = next(
            (row for row in scored_candidates if row["observed"]),
            None,
        )
        for label, scenario in temporal_hazard_scenarios.items():
            counts = temporal_hazard_counts[label]
            pass_duration_mode = str(scenario["pass_duration"])
            release_preparation = decision.get("control", {}).get("release_preparation")
            if scenario["candidate_transition_hazard"] and any(
                not isinstance(row["transition_hazard"], (int, float))
                for row in scored_candidates
            ):
                counts["decisions_unavailable"] += 1
                continue

            def value_with_hazard(row: dict[str, Any]) -> float:
                hazard = (
                    float(row["transition_hazard"])
                    if scenario["candidate_transition_hazard"]
                    else float(scenario["lambda_per_second"])
                )
                duration_seconds = (
                    max(1.0 - float(release_preparation), 0.05)
                    if row["action"] == "pass"
                    and pass_duration_mode == "release"
                    and isinstance(release_preparation, (int, float))
                    else float(row["duration_seconds"])
                )
                return (
                    float(row["undiscounted_return"])
                    * exp(-hazard * duration_seconds)
                    + float(row["local_shaping"])
                )

            best = max(
                scored_candidates,
                key=value_with_hazard,
            )
            best_action = str(best["action"])
            counts["decisions"] += 1
            counts[f"best={best_action}"] += 1
            counts[f"observed={observed_action}->best={best_action}"] += 1
            if (
                observed_action == "pass"
                and best_action == "pass"
                and observed_candidate is not None
            ):
                temporal_hazard_pacing[label]["comparable_pass_to_pass_decisions"] += 1
                temporal_hazard_pacing[label]["net_flight_seconds_saved"] += (
                    float(observed_candidate["duration_seconds"])
                    - float(best["duration_seconds"])
                )
            pass_candidates = [
                row for row in scored_candidates if row["action"] == "pass"
            ]
            if pass_candidates:
                best_pass = max(pass_candidates, key=value_with_hazard)
                pass_distance = best_pass["distance_m"]
                if isinstance(pass_distance, (int, float)):
                    distance_band = (
                        "0_10m"
                        if pass_distance < 10.0
                        else "10_20m"
                        if pass_distance < 20.0
                        else "20_30m"
                        if pass_distance < 30.0
                        else "30m_plus"
                    )
                    counts[f"best_pass_distance={distance_band}"] += 1
                    counts[
                        f"best_pass_distance={distance_band}:target={best_pass['target_kind'] or 'unknown'}"
                    ] += 1
                    if best_action == "pass":
                        counts[f"selected_pass_distance={distance_band}"] += 1
    active_play_seconds = response.get("match_clock", {}).get("active_play_seconds")
    provider_passes = sum(
        int(response.get(f"{team}_stats", {}).get("passes", 0) or 0)
        for team in ("home", "away")
    )
    baseline_passes_per_active_minute = (
        provider_passes / (float(active_play_seconds) / 60.0)
        if isinstance(active_play_seconds, (int, float))
        and float(active_play_seconds) > 0.0
        else None
    )
    observed_selected_pass_decisions = sum(
        str(decision.get("chosen", {}).get("action_type", "unknown")) == "pass"
        for decision in decisions
    )
    temporal_hazard_report = {
        "scope": (
            "read-only re-ranking of the existing candidate set; pass flight mode uses "
            "each candidate's physical option_duration_seconds, while release mode is a "
            "negative control that substitutes release preparation for pass duration"
        ),
        "possession_interruption": possession_interruption,
        "production_hazard_range_per_second": [0.0015, 0.0075],
        "candidate_transition_hazard": {
            "definition": (
                "-ln(retained_control_probability) / option_duration_seconds"
            ),
            "eligibility": "diagnostic_only_double_counts_action_outcome_risk",
            "reason": (
                "retained, opposing, and unresolved outcome mass already determines the "
                "Bellman continuation and turnover ledger before temporal discounting"
            ),
            "metrics": {
                key: _numeric_distribution(values)
                for key, values in sorted(transition_hazard_metrics.items())
                if values
            },
        },
        "scenarios": {},
    }
    for label, scenario in temporal_hazard_scenarios.items():
        pacing = temporal_hazard_pacing[label]
        net_saved = pacing.get("net_flight_seconds_saved", 0.0)
        reinvestment_ceiling = None
        selection_and_duration_ceiling = None
        counterfactual_selected_pass_decisions = int(
            temporal_hazard_counts[label].get("best=pass", 0)
        )
        selected_pass_decision_delta = (
            counterfactual_selected_pass_decisions
            - observed_selected_pass_decisions
        )
        selection_adjusted_provider_passes = max(
            provider_passes + selected_pass_decision_delta,
            0,
        )
        if (
            baseline_passes_per_active_minute is not None
            and isinstance(active_play_seconds, (int, float))
            and float(active_play_seconds) - net_saved > 0.0
        ):
            reinvestment_ceiling = (
                baseline_passes_per_active_minute
                * float(active_play_seconds)
                / (float(active_play_seconds) - net_saved)
            )
            selection_and_duration_ceiling = (
                selection_adjusted_provider_passes
                / ((float(active_play_seconds) - net_saved) / 60.0)
            )
        temporal_hazard_report["scenarios"][label] = {
            **scenario,
            "counts": dict(sorted(temporal_hazard_counts[label].items())),
            "pass_minute_ceiling": {
                "scope": (
                    "duration-only upper bound over decisions where observed and "
                    "counterfactual choices are both passes; assumes every net flight "
                    "second saved is reinvested into the unchanged provider pass cycle "
                    "and therefore is not a simulated production result"
                ),
                "comparable_pass_to_pass_decisions": int(
                    pacing.get("comparable_pass_to_pass_decisions", 0.0)
                ),
                "net_flight_seconds_saved": round(net_saved, 6),
                "baseline_provider_passes_per_active_minute": round(
                    baseline_passes_per_active_minute, 6
                ) if baseline_passes_per_active_minute is not None else None,
                "observed_selected_pass_decisions": (
                    observed_selected_pass_decisions
                ),
                "counterfactual_selected_pass_decisions": (
                    counterfactual_selected_pass_decisions
                ),
                "selected_pass_decision_delta": selected_pass_decision_delta,
                "duration_reinvestment_upper_bound": round(
                    reinvestment_ceiling, 6
                ) if reinvestment_ceiling is not None else None,
                "selection_and_duration_upper_bound": round(
                    selection_and_duration_ceiling, 6
                ) if selection_and_duration_ceiling is not None else None,
            },
        }
    decisions_by_player: dict[tuple[Any, Any], list[dict[str, Any]]] = defaultdict(list)
    for decision in decisions:
        decisions_by_player[(decision.get("team"), decision.get("player_idx"))].append(
            decision
        )
    for player_decisions in decisions_by_player.values():
        player_decisions.sort(key=lambda decision: int(decision.get("tick", -1)))
    pass_prelude_counts: Counter[str] = Counter()
    pass_prelude_metrics: dict[str, list[float]] = defaultdict(list)
    pass_prelude_by_decision_identity: dict[tuple[Any, Any, Any], str] = {}
    decisions_by_possession: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    for decision in decisions:
        decisions_by_possession[decision.get("possession_id")].append(decision)
    for possession_decisions in decisions_by_possession.values():
        possession_decisions.sort(key=lambda decision: int(decision.get("tick", -1)))
        prelude: list[dict[str, Any]] = []
        for decision in possession_decisions:
            action = str(decision.get("chosen", {}).get("action_type", "unknown"))
            if action != "pass":
                prelude.append(decision)
                continue
            action_counts = Counter(
                str(row.get("chosen", {}).get("action_type", "unknown"))
                for row in prelude
            )
            signature_actions = [
                action_name
                for action_name in ("carry", "reorient", "hold", "clear", "shoot")
                if action_counts[action_name] > 0
            ]
            signature = "direct" if not signature_actions else "+".join(signature_actions)
            pass_prelude_by_decision_identity[(
                decision.get("tick"),
                decision.get("team"),
                decision.get("player_idx"),
            )] = signature
            pass_prelude_counts[signature] += 1
            pass_tick = decision.get("tick")
            first_tick = prelude[0].get("tick") if prelude else pass_tick
            if isinstance(pass_tick, int) and isinstance(first_tick, int):
                pass_prelude_metrics["elapsed_ticks"].append(float(pass_tick - first_tick))
                pass_prelude_metrics[f"{signature}:elapsed_ticks"].append(
                    float(pass_tick - first_tick)
                )
            pass_prelude_metrics["decision_count"].append(float(len(prelude)))
            pass_prelude_metrics[f"{signature}:decision_count"].append(float(len(prelude)))
            for action_name in ("carry", "reorient", "hold", "clear", "shoot"):
                pass_prelude_metrics[f"{action_name}_count"].append(
                    float(action_counts[action_name])
                )
            prelude.clear()
    carry_execution_by_identity = {
        (entry.get("tick"), entry.get("team"), entry.get("player_idx")): entry
        for entry in trace_entries
        if entry.get("action") == "carry"
        and entry.get("phase") in {"start", "continue"}
        and isinstance(entry.get("physical_distance"), (int, float))
    }
    on_ball_candidate_context = {
        (entry.get("tick"), entry.get("team"), entry.get("player_idx")): entry
        for entry in trace_entries
        if entry.get("event") == "on_ball_candidate_counts"
    }
    held_defense_motion_context = {
        (entry.get("tick"), entry.get("holder_team"), entry.get("holder_idx")): entry
        for entry in trace_entries
        if entry.get("event") == "held_defense_motion_projection"
    }
    held_support_state_context = {
        (
            entry.get("possession_id"),
            entry.get("team"),
            entry.get("holder_idx"),
            entry.get("tick"),
        ): entry
        for entry in trace_entries
        if entry.get("event") == "held_support_state"
    }
    held_support_state_by_team_tick = {
        (entry.get("team"), entry.get("tick")): entry
        for entry in trace_entries
        if entry.get("event") == "held_support_state"
        and entry.get("team") in {"home", "away"}
        and isinstance(entry.get("tick"), int)
    }
    pass_releases_by_replay = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("action") == "pass" and entry.get("replay_id") is not None
    }
    pass_replay_by_decision_identity = {
        (entry.get("tick"), entry.get("team"), entry.get("passer_player")): replay_id
        for replay_id, entry in pass_releases_by_replay.items()
    }
    pass_physical_terminals_by_replay = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_physical_terminal"
        and entry.get("replay_id") is not None
    }
    one_touch_eligible_replays = {
        replay_id
        for replay_id, physical in pass_physical_terminals_by_replay.items()
        if bool(physical.get("one_touch_physically_eligible"))
    }
    pass_control_terminals_by_replay = {
        entry.get("replay_id"): entry
        for entry in trace_entries
        if entry.get("event") == "pass_control_terminal"
        and entry.get("replay_id") is not None
    }
    pass_control_full_ticks_by_replay: dict[Any, int] = defaultdict(int)
    pass_control_elapsed_ticks_by_replay: dict[Any, float] = defaultdict(float)
    for entry in trace_entries:
        replay_id = entry.get("pending_pass_replay_id")
        full_ticks = entry.get("free_ball_ticks")
        if replay_id is not None and isinstance(full_ticks, int):
            pass_control_full_ticks_by_replay[replay_id] = max(
                pass_control_full_ticks_by_replay[replay_id],
                full_ticks,
            )
        if replay_id is None or entry.get("event") != "continuous_ball_control":
            continue
        phase_fraction = float(entry.get("phase_tick_fraction", 1.0) or 0.0)
        consumed = entry.get("stable_control_consumed_fraction")
        pass_control_elapsed_ticks_by_replay[replay_id] += (
            float(consumed)
            if bool(entry.get("stable"))
            and isinstance(consumed, (int, float))
            else phase_fraction
        )
    chosen_pass_decisions = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx")): decision
        for decision in decisions
        if decision.get("chosen", {}).get("action_type") == "pass"
    }
    pass_interval_timing: dict[str, list[float]] = defaultdict(list)
    receiver_horizon_live_fit: dict[str, list[float]] = defaultdict(list)
    corner_pass_exit_counts: Counter[str] = Counter()
    corner_pass_exit_metrics: dict[str, list[float]] = defaultdict(list)
    corner_pass_exit_cases: list[dict[str, Any]] = []
    for boundary in trace_entries:
        if (
            boundary.get("event") != "out_of_bounds"
            or boundary.get("reason") != "corner"
            or boundary.get("pending_pass_replay_id") is None
        ):
            continue
        release = pass_releases_by_replay.get(boundary.get("pending_pass_replay_id"), {})
        origin = release.get("origin")
        target = release.get("target")
        team = release.get("team")
        if not (
            isinstance(origin, list) and len(origin) >= 2
            and isinstance(target, list) and len(target) >= 2
            and team in {"home", "away"}
        ):
            continue
        attacking_right = bool(release.get("attacking_right"))
        progress = (float(target[0]) - float(origin[0])) * (1.0 if attacking_right else -1.0)
        direction = "forward" if progress > 3.0 else "backward" if progress < -3.0 else "lateral"
        own_goal_x = 0.0 if attacking_right else 105.0
        corner_pass_exit_counts[f"direction={direction}"] += 1
        corner_pass_exit_counts[
            "last_touch_changed" if boundary.get("last_touch_changed") else "last_touch_passer_team"
        ] += 1
        corner_pass_exit_counts[
            "delivery_error" if release.get("delivery_miss") else "clean_delivery"
        ] += 1
        corner_pass_exit_counts[
            "space_target" if release.get("target_kind") == "space" else "feet_target"
        ] += 1
        corner_pass_exit_metrics["target_own_goal_line_margin_m"].append(
            abs(float(target[0]) - own_goal_x)
        )
        corner_pass_exit_metrics["pass_progress_m"].append(progress)
        predicted = release.get("retention_probability")
        if isinstance(predicted, (int, float)):
            corner_pass_exit_metrics["predicted_retention"].append(float(predicted))
        for field in (
            "predicted_retained_control_probability",
            "predicted_opposing_control_probability",
            "predicted_unresolved_probability",
            "predicted_out_of_play_probability",
        ):
            value = release.get(field)
            if isinstance(value, (int, float)):
                corner_pass_exit_metrics[field].append(float(value))
        decision = chosen_pass_decisions.get(
            (release.get("tick"), release.get("team"), release.get("passer_player")),
            {},
        )
        components = decision.get("chosen", {}).get("value", {}).get("components", {})
        for field in (
            "out_of_play_probability",
            "retained_control_probability",
            "opposing_control_probability",
            "unresolved_probability",
            "retained_restart_probability",
            "opposing_restart_probability",
            "expected_restart_ticks",
        ):
            value = components.get(field)
            if isinstance(value, (int, float)):
                corner_pass_exit_metrics[f"candidate_{field}"].append(float(value))
        for field in (
            "planned_arrival_receiver_control",
            "planned_arrival_opponent_control",
            "planned_arrival_loose_control",
        ):
            value = release.get(field)
            if isinstance(value, (int, float)):
                corner_pass_exit_metrics[field].append(float(value))
        physical = pass_physical_terminals_by_replay.get(
            boundary.get("pending_pass_replay_id"), {}
        )
        if physical.get("strongest_contact_team") is not None:
            corner_pass_exit_counts[
                "physical_contact_passer_team"
                if physical.get("strongest_contact_team") == release.get("team")
                else "physical_contact_opponent"
            ] += 1
        else:
            corner_pass_exit_counts["physical_contact_none"] += 1
        for field in (
            "strongest_contact_quality",
            "strongest_contact_target_distance",
            "terminal_speed",
            "intended_receiver_displacement",
            "intended_receiver_target_distance",
        ):
            value = physical.get(field)
            if isinstance(value, (int, float)):
                corner_pass_exit_metrics[f"physical_{field}"].append(float(value))
        corner_pass_exit_cases.append({
            "replay_id": boundary.get("pending_pass_replay_id"),
            "direction": direction,
            "origin": origin,
            "ideal_target": release.get("ideal_target"),
            "sampled_target": target,
            "target_own_goal_line_margin_m": abs(float(target[0]) - own_goal_x),
            "delivery_miss": bool(release.get("delivery_miss")),
            "planned_receiver_control": release.get("planned_arrival_receiver_control"),
            "predicted_retention": release.get("retention_probability"),
            "receiver_initial_position": physical.get("intended_receiver_initial_position"),
            "receiver_terminal_position": physical.get("intended_receiver_terminal_position"),
            "receiver_displacement": physical.get("intended_receiver_displacement"),
            "receiver_target_distance": physical.get("intended_receiver_target_distance"),
            "receiver_movement_target": physical.get("intended_receiver_movement_target"),
            "strongest_contact_team": physical.get("strongest_contact_team"),
            "strongest_contact_player": physical.get("strongest_contact_player"),
            "strongest_contact_quality": physical.get("strongest_contact_quality"),
            "strongest_contact_position": physical.get("strongest_contact_position"),
            "strongest_contact_target_distance": physical.get("strongest_contact_target_distance"),
            "strongest_contact_flight_progress": physical.get("strongest_contact_flight_progress"),
            "planned_opponent_player": physical.get("planned_opponent_player"),
            "planned_opponent_terminal_position": physical.get("planned_opponent_terminal_position"),
            "planned_opponent_terminal_ball_distance": physical.get("planned_opponent_terminal_ball_distance"),
            "planned_opponent_terminal_target_distance": physical.get("planned_opponent_terminal_target_distance"),
            "terminal_speed": physical.get("terminal_speed"),
        })
    free_ball_stable_action_budget: dict[str, list[float]] = defaultdict(list)
    free_ball_stable_pass_budget_counts: Counter[str] = Counter()
    free_ball_stable_pass_budget_metrics: dict[str, list[float]] = defaultdict(list)
    free_ball_stable_pass_budget_cases: list[dict[str, Any]] = []
    receipt_events_by_holder_tick: dict[
        tuple[Any, Any, Any], list[dict[str, Any]]
    ] = defaultdict(list)
    for entry in trace_entries:
        if entry.get("event") not in {"receipt_fast_pass", "receipt_decision_wait"}:
            continue
        receipt_events_by_holder_tick[(
            entry.get("tick"),
            entry.get("holder_team"),
            entry.get("holder_idx"),
        )].append(entry)
    stable_control_remaining_by_replay: dict[Any, float] = {}
    for budget in trace_entries:
        if budget.get("event") != "free_ball_stable_control_budget" or not budget.get("pending_pass"):
            continue
        budget_tick = budget.get("tick")
        team = budget.get("controller_team")
        player_idx = budget.get("controller_player")
        if not isinstance(budget_tick, int) or team not in {"home", "away"} or not isinstance(player_idx, int):
            continue
        next_decision = next((
            decision
            for decision in decisions_by_player.get((team, player_idx), [])
            if isinstance(decision.get("tick"), int)
            and int(decision["tick"]) >= budget_tick
        ), None)
        if next_decision is None:
            continue
        action = str(next_decision.get("chosen", {}).get("action_type", "unknown"))
        remaining = budget.get("remaining_tick_fraction")
        replay_id = budget.get("pending_pass_replay_id")
        if replay_id is not None and isinstance(remaining, (int, float)):
            stable_control_remaining_by_replay[replay_id] = float(remaining)
        preparation = budget.get("release_preparation")
        if isinstance(remaining, (int, float)):
            free_ball_stable_action_budget[f"next={action}:remaining_fraction"].append(float(remaining))
        if action == "pass" and isinstance(remaining, (int, float)) and isinstance(preparation, (int, float)):
            required = max(1.0 - float(preparation), 0.0)
            margin = float(remaining) - required
            feasible = margin >= -1e-12
            decision_delay = int(next_decision["tick"]) - budget_tick
            receipt_events = receipt_events_by_holder_tick.get(
                (budget_tick, team, player_idx), []
            )
            receipt_event_profiles = [
                (
                    "fast_pass"
                    if event.get("event") == "receipt_fast_pass"
                    else f"wait:{event.get('selected_action') or 'unknown'}:"
                    f"{event.get('reason') or 'unknown'}"
                )
                for event in receipt_events
            ]
            free_ball_stable_action_budget["next=pass:required_release_fraction"].append(required)
            free_ball_stable_action_budget[
                "next=pass:feasible" if feasible else "next=pass:infeasible"
            ].append(1.0)
            profile = "feasible" if feasible else "infeasible"
            free_ball_stable_pass_budget_counts[profile] += 1
            free_ball_stable_pass_budget_counts[
                f"{profile}:decision_delay={decision_delay}"
            ] += 1
            for event_profile in receipt_event_profiles or ["missing"]:
                free_ball_stable_pass_budget_counts[
                    f"{profile}:receipt_event={event_profile}"
                ] += 1
            free_ball_stable_pass_budget_metrics[f"{profile}:remaining_fraction"].append(
                float(remaining)
            )
            free_ball_stable_pass_budget_metrics[f"{profile}:required_release_fraction"].append(
                required
            )
            free_ball_stable_pass_budget_metrics[f"{profile}:release_margin_fraction"].append(
                margin
            )
            free_ball_stable_pass_budget_metrics[f"{profile}:decision_delay_ticks"].append(
                float(decision_delay)
            )
            if feasible and decision_delay > 0:
                free_ball_stable_pass_budget_cases.append({
                    "tick": budget_tick,
                    "team": team,
                    "player_idx": player_idx,
                    "remaining_fraction": float(remaining),
                    "required_release_fraction_from_stable_control": required,
                    "next_pass_decision_tick": next_decision.get("tick"),
                    "next_pass_distance_m": None,
                    "receipt_event_profiles": receipt_event_profiles,
                })
            for field in (
                "pressure_load",
                "containment_load",
                "release_window",
                "turn_readiness",
                "strongest_contact_quality",
                "strongest_contact_separation",
                "strongest_contact_relative_speed",
                "strongest_contact_post_relative_speed",
            ):
                value = budget.get(field)
                if isinstance(value, (int, float)):
                    free_ball_stable_pass_budget_metrics[f"{profile}:{field}"].append(
                        float(value)
                    )
            pass_value = next_decision.get("chosen", {}).get("value", {})
            pass_components = pass_value.get("components", {})
            target = next_decision.get("chosen", {}).get("target")
            origin = next_decision.get("pos")
            pass_distance = (
                hypot(float(target[0]) - float(origin[0]), float(target[1]) - float(origin[1]))
                if isinstance(target, list)
                and len(target) >= 2
                and isinstance(origin, list)
                and len(origin) >= 2
                else None
            )
            if feasible and decision_delay > 0 and free_ball_stable_pass_budget_cases:
                free_ball_stable_pass_budget_cases[-1]["next_pass_distance_m"] = (
                    float(pass_distance)
                    if isinstance(pass_distance, (int, float))
                    else None
                )
            transition = pass_components.get("outcome_transition", {})
            for field, value in (
                ("distance_m", pass_distance),
                ("score", pass_value.get("score")),
                ("retention", pass_value.get("success_prob")),
                ("receiver_arrival", pass_components.get("receiver_arrival")),
                ("receiver_pressure", pass_components.get("receiver_pressure")),
                ("retained_probability", transition.get("retained_control_probability")),
                ("opposing_probability", transition.get("opposing_control_probability")),
                ("unresolved_probability", transition.get("unresolved_probability")),
            ):
                if isinstance(value, (int, float)):
                    free_ball_stable_pass_budget_metrics[f"{profile}:{field}"].append(
                        float(value)
                    )
            replay_id = pass_replay_by_decision_identity.get(
                (next_decision.get("tick"), team, player_idx)
            )
            terminal = pass_control_terminals_by_replay.get(replay_id, {})
            outcome = str(terminal.get("outcome", "unknown"))
            free_ball_stable_pass_budget_counts[f"{profile}:outcome={outcome}"] += 1
            free_ball_stable_pass_budget_counts[
                f"{profile}:target={pass_components.get('target_kind', 'unknown')}"
            ] += 1
            distance_band = (
                "0_10m"
                if isinstance(pass_distance, (int, float)) and pass_distance < 10.0
                else "10_20m"
                if isinstance(pass_distance, (int, float)) and pass_distance < 20.0
                else "20_32m"
                if isinstance(pass_distance, (int, float)) and pass_distance < 32.0
                else "32m_plus"
                if isinstance(pass_distance, (int, float))
                else "unknown"
            )
            free_ball_stable_pass_budget_counts[
                f"{profile}:distance={distance_band}:target="
                f"{pass_components.get('target_kind', 'unknown')}"
            ] += 1
            physical = pass_physical_terminals_by_replay.get(replay_id, {})
            free_ball_stable_pass_budget_counts[
                f"{profile}:one_touch_eligible="
                f"{str(bool(physical.get('one_touch_physically_eligible'))).lower()}"
            ] += 1
    pass_value_realization: dict[str, list[float]] = defaultdict(list)
    mature_chain_pass_timing: dict[str, list[float]] = defaultdict(list)
    mature_chain_long_tail_cases: list[dict[str, Any]] = []
    mature_receipt_action_counts: Counter[str] = Counter()
    mature_receipt_action_metrics: dict[str, dict[str, list[float]]] = defaultdict(
        lambda: defaultdict(list)
    )
    mature_receipt_outlet_context_metrics: dict[
        str, dict[str, list[float]]
    ] = defaultdict(lambda: defaultdict(list))
    completed_replays_by_possession: dict[Any, list[Any]] = defaultdict(list)
    for replay_id, terminal in pass_control_terminals_by_replay.items():
        release = pass_releases_by_replay.get(replay_id, {})
        if (
            terminal.get("outcome") == "completed"
            and release.get("possession_id") is not None
        ):
            completed_replays_by_possession[release.get("possession_id")].append(
                replay_id
            )
    mature_possession_ids = {
        possession_id
        for possession_id, replay_ids in completed_replays_by_possession.items()
        if len(replay_ids) >= 5
    }
    for replay_id in one_touch_eligible_replays:
        physical = pass_physical_terminals_by_replay.get(replay_id, {})
        terminal = pass_control_terminals_by_replay.get(replay_id, {})
        control_tick = terminal.get("tick")
        winner_team = terminal.get("winner_team")
        winner_player = terminal.get("winner_player")
        if terminal.get("outcome") != "completed" or not isinstance(control_tick, int):
            continue
        next_decision = next(
            (
                decision
                for decision in decisions_by_player.get((winner_team, winner_player), [])
                if isinstance(decision.get("tick"), int)
                and int(decision["tick"]) >= control_tick
            ),
            None,
        )
        mature_chain_pass_timing["one_touch_eligible:count"].append(1.0)
        physical_replay_tick = physical.get("physical_terminal_replay_tick")
        remaining = physical.get("full_tick_remaining_fraction")
        if isinstance(remaining, (int, float)):
            mature_chain_pass_timing["one_touch_eligible:remaining_tick_fraction"].append(float(remaining))
        if next_decision is not None:
            action = str(next_decision.get("chosen", {}).get("action_type", "unknown"))
            mature_chain_pass_timing[f"one_touch_eligible:next_action={action}"].append(1.0)
            if action == "pass" and isinstance(physical_replay_tick, (int, float)):
                incoming_release = pass_releases_by_replay.get(replay_id, {})
                next_release = next((
                    candidate
                    for candidate in sorted(
                        pass_releases_by_replay.values(),
                        key=lambda entry: float(
                            entry.get("release_replay_tick", entry.get("tick", -1))
                            or -1
                        ),
                    )
                    if candidate.get("team") == winner_team
                    and candidate.get("passer_player") == winner_player
                    and candidate.get("possession_id")
                        == incoming_release.get("possession_id")
                    and isinstance(
                        candidate.get("release_replay_tick"), (int, float)
                    )
                    and float(candidate["release_replay_tick"])
                        >= float(physical_replay_tick) - 1e-12
                ), None)
                if next_release is not None:
                    delay_seconds = (
                        float(next_release["release_replay_tick"])
                        - float(physical_replay_tick)
                    ) * float(response.get("config", {}).get("tick_duration", 1.0) or 1.0)
                    mature_chain_pass_timing[
                        "one_touch_pass:physical_contact_to_actual_release_seconds"
                    ].append(max(delay_seconds, 0.0))
                    mature_chain_pass_timing[
                        "one_touch_pass:actual_release_distance_m"
                    ].append(float(next_release.get("actual_distance_m", 0.0) or 0.0))
            stable_matches_winner = (
                physical.get("stable_controller_team") == winner_team
                and physical.get("stable_controller_player") == winner_player
            )
            preparation = next_decision.get("control", {}).get("release_preparation")
            release_seconds = (
                1.0 - float(preparation)
                if isinstance(preparation, (int, float))
                else None
            )
            if (
                action == "pass"
                and stable_matches_winner
                and isinstance(remaining, (int, float))
                and isinstance(release_seconds, float)
            ):
                mature_chain_pass_timing[
                    "one_touch_pass:remaining_tick_fraction"
                ].append(float(remaining))
                mature_chain_pass_timing[
                    "one_touch_pass:required_release_seconds"
                ].append(release_seconds)
                if float(remaining) + 1e-12 >= release_seconds:
                    mature_chain_pass_timing[
                        "one_touch_pass:continuous_release_feasible"
                    ].append(1.0)
                    mature_chain_pass_timing[
                        "one_touch_pass:releasable_remaining_seconds"
                    ].append(float(remaining) - release_seconds)
                else:
                    mature_chain_pass_timing[
                        "one_touch_pass:continuous_release_infeasible"
                    ].append(1.0)
    for replay_id, release in pass_releases_by_replay.items():
        release_tick = release.get("tick")
        physical = pass_physical_terminals_by_replay.get(replay_id, {})
        decision = chosen_pass_decisions.get(
            (release.get("tick"), release.get("team"), release.get("passer_player")),
            {},
        )
        projection = (
            decision.get("chosen", {})
            .get("details", {})
            .get("receiver_motion", {})
            .get("production_receipt_projection", {})
        )
        live_terminal = physical.get("intended_receiver_terminal_position")
        rounded_terminal = projection.get("rounded_receiver_end")
        exact_terminal = projection.get("exact_time_receiver_end")
        if all(
            isinstance(point, list)
            and len(point) >= 2
            and all(isinstance(coordinate, (int, float)) for coordinate in point[:2])
            for point in (live_terminal, rounded_terminal, exact_terminal)
        ):
            rounded_error = hypot(
                float(rounded_terminal[0]) - float(live_terminal[0]),
                float(rounded_terminal[1]) - float(live_terminal[1]),
            )
            exact_error = hypot(
                float(exact_terminal[0]) - float(live_terminal[0]),
                float(exact_terminal[1]) - float(live_terminal[1]),
            )
            target_kind = str(release.get("target_kind") or "unknown")
            length = "long" if bool(release.get("is_long")) else "short"
            terminal_outcome = str(
                pass_control_terminals_by_replay.get(replay_id, {}).get(
                    "outcome", "unknown"
                )
            )
            profiles = (
                "all",
                f"length={length}",
                f"target={target_kind}",
                f"outcome={terminal_outcome}",
                f"length={length}:target={target_kind}",
            )
            for profile in profiles:
                receiver_horizon_live_fit[f"{profile}:rounded_error_m"].append(
                    rounded_error
                )
                receiver_horizon_live_fit[f"{profile}:exact_error_m"].append(
                    exact_error
                )
                receiver_horizon_live_fit[
                    f"{profile}:exact_minus_rounded_error_m"
                ].append(exact_error - rounded_error)
            release_to_terminal = physical.get("release_to_terminal_wall_seconds")
            exact_flight = projection.get("exact_flight_ticks")
            tick_duration = float(
                response.get("config", {}).get("tick_duration", 1.0) or 1.0
            )
            if isinstance(release_to_terminal, (int, float)) and isinstance(
                exact_flight, (int, float)
            ):
                receiver_horizon_live_fit[
                    "all:terminal_minus_nominal_exact_seconds"
                ].append(
                    float(release_to_terminal)
                    - float(exact_flight) * tick_duration
                )
        physical_tick = physical.get("match_tick")
        terminal = pass_control_terminals_by_replay.get(replay_id, {})
        control_tick = terminal.get("tick")
        if isinstance(release_tick, int) and isinstance(physical_tick, int):
            pass_interval_timing["release_to_physical_terminal_ticks"].append(
                float(physical_tick - release_tick)
            )
            for field in (
                "flight_distance_m",
                "flight_average_speed_mps",
                "exact_flight_ticks",
                "exact_flight_seconds",
                "release_to_terminal_wall_seconds",
            ):
                value = physical.get(field)
                if isinstance(value, (int, float)):
                    pass_interval_timing[field].append(float(value))
        if isinstance(physical_tick, int) and isinstance(control_tick, int):
            control_delay = float(control_tick - physical_tick)
            control_elapsed = pass_control_elapsed_ticks_by_replay.get(replay_id, 0.0)
            pass_interval_timing["physical_to_control_terminal_ticks"].append(
                control_delay
            )
            pass_interval_timing[
                "physical_to_control_terminal_elapsed_ticks"
            ].append(control_elapsed)
            pass_interval_timing[
                f"physical_to_control_terminal_elapsed_ticks:outcome="
                f"{terminal.get('outcome', 'unknown')}"
            ].append(control_elapsed)
            length = "long" if physical.get("is_long") else "short"
            delivery = "miss" if physical.get("delivery_miss") else "on_target"
            same_team_contact = (
                physical.get("strongest_contact_team") == physical.get("passer_team")
            )
            intended_contact = (
                same_team_contact
                and physical.get("strongest_contact_player")
                == physical.get("intended_receiver_player")
            )
            contact = (
                "intended_receiver"
                if intended_contact
                else "same_team_other"
                if same_team_contact
                else "opponent_or_none"
            )
            pass_interval_timing[
                f"physical_to_control_terminal_ticks:{length}:{delivery}:{contact}"
            ].append(control_delay)
            pass_interval_timing[
                f"physical_to_control_terminal_elapsed_ticks:"
                f"{length}:{delivery}:{contact}"
            ].append(control_elapsed)
            quality = physical.get("strongest_contact_quality")
            if isinstance(quality, (int, float)):
                quality_band = (
                    "high"
                    if float(quality) >= 0.70
                    else "medium"
                    if float(quality) >= 0.40
                    else "low"
                )
                pass_interval_timing[
                    f"physical_to_control_terminal_ticks:contact_quality={quality_band}"
                ].append(control_delay)
                pass_interval_timing[
                    f"physical_to_control_terminal_elapsed_ticks:"
                    f"contact_quality={quality_band}"
                ].append(control_elapsed)
            terminal_speed = physical.get("terminal_speed")
            if isinstance(terminal_speed, (int, float)):
                speed_band = (
                    "under_2mps"
                    if float(terminal_speed) < 2.0
                    else "2_4mps"
                    if float(terminal_speed) < 4.0
                    else "4mps_plus"
                )
                pass_interval_timing[
                    f"physical_to_control_terminal_ticks:terminal_speed={speed_band}"
                ].append(control_delay)
        if (
            release.get("possession_id") in mature_possession_ids
            and terminal.get("outcome") == "completed"
            and isinstance(release_tick, int)
            and isinstance(physical_tick, int)
            and isinstance(control_tick, int)
        ):
            mature_chain_pass_timing["release_to_physical_terminal_ticks"].append(
                float(physical_tick - release_tick)
            )
            distance_m = physical.get("flight_distance_m")
            distance_band = (
                "under_15m"
                if isinstance(distance_m, (int, float)) and float(distance_m) < 15.0
                else "15_25m"
                if isinstance(distance_m, (int, float)) and float(distance_m) < 25.0
                else "25_35m"
                if isinstance(distance_m, (int, float)) and float(distance_m) < 35.0
                else "35m_plus"
            )
            for field in (
                "flight_distance_m",
                "flight_average_speed_mps",
                "exact_flight_ticks",
                "exact_flight_seconds",
                "release_to_terminal_wall_seconds",
            ):
                value = physical.get(field)
                if isinstance(value, (int, float)):
                    mature_chain_pass_timing[field].append(float(value))
                    mature_chain_pass_timing[f"{field}:distance={distance_band}"].append(
                        float(value)
                    )
            exact_seconds = physical.get("exact_flight_seconds")
            wall_seconds = physical.get("release_to_terminal_wall_seconds")
            if isinstance(exact_seconds, (int, float)) and isinstance(
                wall_seconds, (int, float)
            ):
                mature_chain_pass_timing[
                    "release_to_terminal_wall_minus_exact_seconds"
                ].append(float(wall_seconds) - float(exact_seconds))
            mature_chain_pass_timing["physical_to_stable_control_ticks"].append(
                float(control_tick - physical_tick)
            )
            winner_team = terminal.get("winner_team")
            winner_player = terminal.get("winner_player")
            next_decision = next(
                (
                    decision
                    for decision in decisions_by_player.get(
                        (winner_team, winner_player), []
                    )
                    if isinstance(decision.get("tick"), int)
                    and int(decision["tick"]) >= control_tick
                ),
                None,
            )
            initial_best_forward_pass: dict[str, Any] | None = None
            if next_decision is not None:
                next_decision_tick = int(next_decision["tick"])
                next_action = str(
                    next_decision.get("chosen", {}).get("action_type", "unknown")
                )
                next_pos = next_decision.get("pos")
                next_progress = (
                    float(next_pos[0]) / 105.0
                    if isinstance(next_pos, list)
                    and len(next_pos) >= 2
                    and next_decision.get("attacking_right")
                    else (105.0 - float(next_pos[0])) / 105.0
                    if isinstance(next_pos, list) and len(next_pos) >= 2
                    else 0.5
                )
                next_zone = (
                    "defensive"
                    if next_progress < 1.0 / 3.0
                    else "middle"
                    if next_progress < 2.0 / 3.0
                    else "attacking"
                )
                next_position = str(next_decision.get("player_position", "unknown"))
                next_role = (
                    "goalkeeper"
                    if next_position == "GK"
                    else "defender"
                    if next_position in {"LB", "LCB", "CB", "RCB", "RB"}
                    else "midfielder"
                    if next_position
                    in {"LDM", "RDM", "CDM", "LM", "LCM", "CM", "RCM", "RM", "CAM"}
                    else "forward"
                )
                outlet_context = f"{next_zone}:{next_role}:{next_action}"
                mature_receipt_action_counts[next_action] += 1
                chosen_value = next_decision.get("chosen", {}).get("value", {})
                chosen_score = chosen_value.get("score")
                visible_passes = [
                    candidate
                    for candidate in [
                        next_decision.get("chosen", {}),
                        *next_decision.get("alternatives", []),
                    ]
                    if isinstance(candidate, dict)
                    and candidate.get("action_type") == "pass"
                    and isinstance(candidate.get("value", {}).get("score"), (int, float))
                ]
                forward_passes = []
                decision_origin = next_decision.get("pos")
                if isinstance(decision_origin, list) and len(decision_origin) >= 2:
                    for candidate in visible_passes:
                        candidate_target = candidate.get("target")
                        if not (
                            isinstance(candidate_target, list)
                            and len(candidate_target) >= 2
                        ):
                            continue
                        progress_m = (
                            float(candidate_target[0]) - float(decision_origin[0])
                        ) * (1.0 if next_decision.get("attacking_right") else -1.0)
                        if progress_m > 8.0:
                            forward_passes.append(candidate)
                if forward_passes:
                    initial_best_forward_pass = max(
                        forward_passes,
                        key=lambda candidate: float(candidate["value"]["score"]),
                    )
                receiver_positions = {
                    int(row["receiver_idx"]): row.get("receiver_pos")
                    for row in next_decision.get("candidate_receivers", [])
                    if isinstance(row, dict) and isinstance(row.get("receiver_idx"), int)
                }
                best_pass_by_receiver: dict[int, dict[str, Any]] = {}
                for candidate in visible_passes:
                    details = candidate.get("details", {})
                    receiver_idx = details.get(
                        "intended_receiver", details.get("target_player_idx")
                    )
                    if not isinstance(receiver_idx, int):
                        continue
                    current = best_pass_by_receiver.get(receiver_idx)
                    if current is None or float(candidate["value"]["score"]) > float(
                        current["value"]["score"]
                    ):
                        best_pass_by_receiver[receiver_idx] = candidate
                decision_pos = next_decision.get("pos")
                if isinstance(decision_pos, list) and len(decision_pos) >= 2:
                    per_band_counts: Counter[str] = Counter()
                    for receiver_idx, candidate in best_pass_by_receiver.items():
                        receiver_pos = receiver_positions.get(receiver_idx)
                        if not (isinstance(receiver_pos, list) and len(receiver_pos) >= 2):
                            continue
                        receiver_distance = hypot(
                            float(receiver_pos[0]) - float(decision_pos[0]),
                            float(receiver_pos[1]) - float(decision_pos[1]),
                        )
                        distance_band = (
                            "0_10m"
                            if receiver_distance < 10.0
                            else "10_15m"
                            if receiver_distance < 15.0
                            else "15_20m"
                            if receiver_distance < 20.0
                            else "20m_plus"
                        )
                        target_kind = str(
                            candidate.get("details", {}).get("target_kind", "unknown")
                        )
                        if target_kind == "unknown":
                            target = candidate.get("target")
                            target_kind = (
                                "feet"
                                if isinstance(target, list)
                                and len(target) >= 2
                                and hypot(
                                    float(target[0]) - float(receiver_pos[0]),
                                    float(target[1]) - float(receiver_pos[1]),
                                )
                                <= 4.0
                                else "space"
                            )
                        per_band_counts[distance_band] += 1
                        per_band_counts[f"{distance_band}:{target_kind}"] += 1
                        mature_receipt_action_metrics[next_action][
                            f"receiver_count:{distance_band}"
                        ].append(1.0)
                        candidate_value = candidate.get("value", {})
                        candidate_components = candidate_value.get("components", {})
                        mature_receipt_action_metrics[next_action][
                            f"receiver_best_pass_score:{distance_band}"
                        ].append(float(candidate_value["score"]))
                        for field in (
                            "base_accuracy",
                            "lane_risk",
                            "receiver_pressure",
                        ):
                            value = candidate_components.get(field)
                            if isinstance(value, (int, float)):
                                mature_receipt_action_metrics[next_action][
                                    f"receiver_best_pass_{field}:{distance_band}"
                                ].append(float(value))
                    for distance_band in ("0_10m", "10_15m", "15_20m", "20m_plus"):
                        count_in_band = per_band_counts[distance_band]
                        mature_receipt_action_metrics[next_action][
                            f"decision_receiver_count:{distance_band}"
                        ].append(float(count_in_band))
                        mature_receipt_action_metrics[next_action][
                            f"decision_without_receiver:{distance_band}"
                        ].append(float(count_in_band == 0))
                        for target_kind in ("feet", "space"):
                            typed_count = per_band_counts[
                                f"{distance_band}:{target_kind}"
                            ]
                            mature_receipt_action_metrics[next_action][
                                f"decision_receiver_count:{distance_band}:{target_kind}"
                            ].append(float(typed_count))
                            mature_receipt_action_metrics[next_action][
                                f"decision_without_receiver:{distance_band}:{target_kind}"
                            ].append(float(typed_count == 0))
                    feet_within_15m = (
                        per_band_counts["0_10m:feet"]
                        + per_band_counts["10_15m:feet"]
                    )
                    feet_within_20m = (
                        feet_within_15m + per_band_counts["15_20m:feet"]
                    )
                    mature_receipt_action_metrics[next_action][
                        "decision_without_feet_receiver:within_15m"
                    ].append(float(feet_within_15m == 0))
                    mature_receipt_action_metrics[next_action][
                        "decision_without_feet_receiver:within_20m"
                    ].append(float(feet_within_20m == 0))
                    mature_receipt_outlet_context_metrics[outlet_context][
                        "without_feet_receiver_within_15m"
                    ].append(float(feet_within_15m == 0))
                    mature_receipt_outlet_context_metrics[outlet_context][
                        "without_feet_receiver_within_20m"
                    ].append(float(feet_within_20m == 0))
                mature_receipt_action_metrics[next_action]["visible_pass_count"].append(
                    float(len(visible_passes))
                )
                if visible_passes:
                    best_pass = max(
                        visible_passes,
                        key=lambda candidate: float(candidate["value"]["score"]),
                    )
                    best_pass_score = float(best_pass["value"]["score"])
                    mature_receipt_action_metrics[next_action]["best_pass_score"].append(
                        best_pass_score
                    )
                    if isinstance(chosen_score, (int, float)):
                        mature_receipt_action_metrics[next_action][
                            "chosen_minus_best_pass_score"
                        ].append(float(chosen_score) - best_pass_score)
                    details = best_pass.get("details", {})
                    best_pass_components = best_pass.get("value", {}).get("components", {})
                    chosen_components = chosen_value.get("components", {})
                    for field in (
                        "after_value",
                        "option_duration_seconds",
                        "temporal_discount",
                        "option_return",
                        "turnover_cost",
                        "local_shaping",
                    ):
                        pass_value = best_pass_components.get(field)
                        chosen_component = chosen_components.get(field)
                        if isinstance(pass_value, (int, float)):
                            mature_receipt_action_metrics[next_action][
                                f"best_pass_{field}"
                            ].append(float(pass_value))
                        if isinstance(pass_value, (int, float)) and isinstance(
                            chosen_component, (int, float)
                        ):
                            mature_receipt_action_metrics[next_action][
                                f"chosen_minus_best_pass_{field}"
                            ].append(float(chosen_component) - float(pass_value))
                    pass_transition = best_pass_components.get("outcome_transition", {})
                    chosen_transition = chosen_components.get("outcome_transition", {})
                    for field in (
                        "retained_control_probability",
                        "retained_control_value",
                        "opposing_control_probability",
                        "opposing_control_value",
                        "unresolved_probability",
                    ):
                        pass_value = pass_transition.get(field)
                        chosen_component = chosen_transition.get(field)
                        if isinstance(pass_value, (int, float)):
                            mature_receipt_action_metrics[next_action][
                                f"best_pass_{field}"
                            ].append(float(pass_value))
                        if isinstance(pass_value, (int, float)) and isinstance(
                            chosen_component, (int, float)
                        ):
                            mature_receipt_action_metrics[next_action][
                                f"chosen_minus_best_pass_{field}"
                            ].append(float(chosen_component) - float(pass_value))
                    pass_execution = best_pass_components.get("execution_transition", {})
                    for field in (
                        "candidate_retention_probability",
                        "release_probability",
                        "release_opposing_control_probability",
                        "release_unresolved_probability",
                        "technical_delivery_probability",
                        "technical_delivery_failure_probability",
                    ):
                        value = pass_execution.get(field)
                        if isinstance(value, (int, float)):
                            mature_receipt_action_metrics[next_action][
                                f"best_pass_{field}"
                            ].append(float(value))
                    target = best_pass.get("target")
                    decision_pos = next_decision.get("pos")
                    if (
                        isinstance(target, list)
                        and len(target) >= 2
                        and isinstance(decision_pos, list)
                        and len(decision_pos) >= 2
                    ):
                        mature_receipt_action_metrics[next_action]["best_pass_distance_m"].append(
                            hypot(
                                float(target[0]) - float(decision_pos[0]),
                                float(target[1]) - float(decision_pos[1]),
                            )
                        )
                    for field in (
                        "retention_probability",
                        "lane_risk",
                        "receiver_pressure",
                    ):
                        value = details.get(field)
                        if isinstance(value, (int, float)):
                            mature_receipt_action_metrics[next_action][
                                f"best_pass_{field}"
                            ].append(float(value))
                control = next_decision.get("control", {})
                for field in (
                    "pressure_load",
                    "containment_load",
                    "forward_control",
                    "turn_readiness",
                    "release_window",
                    "shape_readiness",
                    "release_preparation",
                    "continuation_control_readiness",
                ):
                    value = control.get(field)
                    if isinstance(value, (int, float)):
                        mature_receipt_action_metrics[next_action][field].append(float(value))
                support = next_decision.get("support_geometry", {})
                for field in (
                    "nearest_outfield_teammate_distance",
                    "teammates_within_10m",
                    "teammates_within_15m",
                    "teammates_within_20m",
                ):
                    value = support.get(field)
                    if isinstance(value, (int, float)):
                        mature_receipt_action_metrics[next_action][field].append(float(value))
                        mature_receipt_outlet_context_metrics[outlet_context][field].append(
                            float(value)
                        )
                candidate_context = on_ball_candidate_context.get(
                    (
                        next_decision.get("tick"),
                        next_decision.get("team"),
                        next_decision.get("player_idx"),
                    ),
                    {},
                )
                last_passer_idx = release.get("passer_player")
                if isinstance(last_passer_idx, int):
                    last_passer_goal = next(
                        (
                            teammate
                            for teammate in candidate_context.get("teammate_goals", [])
                            if isinstance(teammate, dict)
                            and teammate.get("idx") == last_passer_idx
                        ),
                        None,
                    )
                    last_passer_visibility = next(
                        (
                            teammate
                            for teammate in candidate_context.get("teammate_visibility", [])
                            if isinstance(teammate, dict)
                            and teammate.get("idx") == last_passer_idx
                        ),
                        None,
                    )
                    if isinstance(last_passer_visibility, dict):
                        distance_m = last_passer_visibility.get("distance_m")
                        if isinstance(distance_m, (int, float)):
                            mature_receipt_action_metrics[next_action][
                                "last_passer_distance_m"
                            ].append(float(distance_m))
                        belief_confidence = last_passer_visibility.get("belief_confidence")
                        mature_receipt_action_metrics[next_action][
                            "last_passer_in_belief"
                        ].append(
                            float(
                                isinstance(belief_confidence, (int, float))
                                and float(belief_confidence) >= 0.08
                            )
                        )
                    if isinstance(last_passer_goal, dict):
                        goal_type = str(last_passer_goal.get("goal_type") or "none")
                        task_intent = str(last_passer_goal.get("task_intent") or "none")
                        mature_receipt_action_metrics[next_action][
                            f"last_passer_goal={goal_type}"
                        ].append(1.0)
                        mature_receipt_action_metrics[next_action][
                            f"last_passer_task={task_intent}"
                        ].append(1.0)
                        task_target = last_passer_goal.get("task_effective_target")
                        holder_pos = next_decision.get("pos")
                        if (
                            isinstance(task_target, list)
                            and len(task_target) >= 2
                            and isinstance(holder_pos, list)
                            and len(holder_pos) >= 2
                        ):
                            mature_receipt_action_metrics[next_action][
                                "last_passer_task_target_distance_to_holder_m"
                            ].append(
                                hypot(
                                    float(task_target[0]) - float(holder_pos[0]),
                                    float(task_target[1]) - float(holder_pos[1]),
                                )
                            )
                    last_passer_off_ball = off_ball_by_key.get(
                        (next_decision.get("tick"), winner_team, last_passer_idx),
                        {},
                    )
                    last_passer_chosen = last_passer_off_ball.get("chosen", {})
                    last_passer_target = last_passer_chosen.get("target")
                    new_holder_pos = next_decision.get("pos")
                    if (
                        isinstance(last_passer_target, list)
                        and len(last_passer_target) >= 2
                        and isinstance(new_holder_pos, list)
                        and len(new_holder_pos) >= 2
                    ):
                        mature_receipt_action_metrics[next_action][
                            "last_passer_off_ball_target_distance_to_holder_m"
                        ].append(
                            hypot(
                                float(last_passer_target[0]) - float(new_holder_pos[0]),
                                float(last_passer_target[1]) - float(new_holder_pos[1]),
                            )
                        )
                    last_passer_source = last_passer_chosen.get("candidate_source")
                    mature_receipt_action_metrics[next_action][
                        f"last_passer_off_ball_source={last_passer_source or 'stay'}"
                    ].append(1.0)
                    role_support_candidate = next(
                        (
                            candidate
                            for candidate in [
                                last_passer_chosen,
                                *last_passer_off_ball.get("alternatives", []),
                            ]
                            if isinstance(candidate, dict)
                            and candidate.get("candidate_source") == "role_support"
                            and isinstance(candidate.get("target"), list)
                            and len(candidate.get("target")) >= 2
                        ),
                        None,
                    )
                    if isinstance(role_support_candidate, dict):
                        holder_pos = next_decision.get("pos")
                        teammate_positions = [
                            (int(teammate["idx"]), tuple(map(float, teammate["pos"][:2])))
                            for teammate in candidate_context.get("teammate_goals", [])
                            if isinstance(teammate, dict)
                            and isinstance(teammate.get("idx"), int)
                            and isinstance(teammate.get("pos"), list)
                            and len(teammate["pos"]) >= 2
                        ]
                        opponent_positions = [
                            tuple(map(float, opponent["pos"][:2]))
                            for opponent in candidate_context.get("opponents_state", [])
                            if isinstance(opponent, dict)
                            and opponent.get("position") != "GK"
                            and isinstance(opponent.get("pos"), list)
                            and len(opponent["pos"]) >= 2
                        ]
                        if (
                            isinstance(holder_pos, list)
                            and len(holder_pos) >= 2
                            and teammate_positions
                        ):
                            origin = tuple(map(float, holder_pos[:2]))
                            role_target = tuple(
                                map(float, role_support_candidate["target"][:2])
                            )
                            def outlet_access(positions: list[tuple[int, tuple[float, float]]]) -> float:
                                qualities = []
                                for _, target in positions:
                                    qualities.append(_outlet_quality(
                                        origin, target, opponent_positions,
                                        bool(next_decision.get("attacking_right")),
                                    ))
                                qualities.sort(reverse=True)
                                return qualities
                            current_qualities = outlet_access(teammate_positions)
                            projected_positions = [
                                (idx, role_target if idx == last_passer_idx else pos)
                                for idx, pos in teammate_positions
                            ]
                            projected_qualities = outlet_access(projected_positions)
                            def independent_access(qualities: list[float], count: int) -> float:
                                residual = 1.0
                                for quality in qualities[:count]:
                                    residual *= 1.0 - quality
                                return 1.0 - residual
                            current_outlet = independent_access(current_qualities, len(current_qualities))
                            projected_outlet = independent_access(
                                projected_qualities, len(projected_qualities)
                            )
                            mature_receipt_action_metrics[next_action][
                                "last_passer_role_support_outlet_access_current"
                            ].append(current_outlet)
                            mature_receipt_action_metrics[next_action][
                                "last_passer_role_support_outlet_access_projected"
                            ].append(projected_outlet)
                            mature_receipt_action_metrics[next_action][
                                "last_passer_role_support_outlet_access_delta"
                            ].append(projected_outlet - current_outlet)
                            for count in (1, 2, 3):
                                current_bounded = independent_access(current_qualities, count)
                                projected_bounded = independent_access(projected_qualities, count)
                                mature_receipt_action_metrics[next_action][
                                    f"last_passer_role_support_top{count}_outlet_delta"
                                ].append(projected_bounded - current_bounded)
                            if current_qualities:
                                mature_receipt_action_metrics[next_action][
                                    "current_best_outlet_quality"
                                ].append(current_qualities[0])
                            if len(current_qualities) > 1:
                                mature_receipt_action_metrics[next_action][
                                    "current_second_outlet_quality"
                                ].append(current_qualities[1])
                    coordination = off_ball_coordination_by_key.get(
                        (next_decision.get("tick"), winner_team, last_passer_idx),
                        {},
                    ).get("resolution", {})
                    mature_receipt_action_metrics[next_action][
                        "last_passer_coordination_displaced"
                    ].append(
                        float(
                            coordination.get("candidate_index") is not None
                            and coordination.get("candidate_index")
                            != coordination.get("preferred_candidate_index")
                        )
                    )
                receiver_ids = {
                    int(candidate.get("details", {}).get("intended_receiver", candidate.get("details", {}).get("target_player_idx")))
                    for candidate in visible_passes
                    if isinstance(
                        candidate.get("details", {}).get("intended_receiver", candidate.get("details", {}).get("target_player_idx")),
                        int,
                    )
                }
                mature_receipt_action_metrics[next_action][
                    "last_passer_has_pass_candidate"
                ].append(float(isinstance(last_passer_idx, int) and last_passer_idx in receiver_ids))
                teammate_goals_by_id = {
                    int(teammate["idx"]): teammate
                    for teammate in candidate_context.get("teammate_goals", [])
                    if isinstance(teammate, dict) and isinstance(teammate.get("idx"), int)
                }
                for teammate in candidate_context.get("teammate_visibility", []):
                    teammate_idx = teammate.get("idx")
                    distance_m = teammate.get("distance_m")
                    if not isinstance(teammate_idx, int) or not isinstance(distance_m, (int, float)) or float(distance_m) > 15.0:
                        continue
                    in_belief = isinstance(teammate.get("belief_confidence"), (int, float)) and float(teammate["belief_confidence"]) >= 0.08
                    has_candidate = teammate_idx in receiver_ids
                    category = (
                        "candidate"
                        if has_candidate
                        else "belief_without_candidate"
                        if in_belief
                        else "outside_belief"
                    )
                    mature_receipt_action_metrics[next_action][f"near_teammate_outlet:{category}"].append(1.0)
                    teammate_goal = teammate_goals_by_id.get(teammate_idx, {})
                    movement_intent = str(teammate_goal.get("movement_intent", "unknown"))
                    task_intent = str(teammate_goal.get("task_intent", "unknown"))
                    task_active = bool(teammate_goal.get("task_active"))
                    mature_receipt_action_metrics[next_action][
                        f"near_teammate_outlet:{category}:movement={movement_intent}"
                    ].append(1.0)
                    mature_receipt_action_metrics[next_action][
                        f"near_teammate_outlet:{category}:task={task_intent}:active={str(task_active).lower()}"
                    ].append(1.0)
                belief_teammates = candidate_context.get("belief_teammates", {})
                for field in ("count", "within_10m", "within_15m", "within_20m"):
                    value = belief_teammates.get(field)
                    if isinstance(value, (int, float)):
                        mature_receipt_action_metrics[next_action][
                            f"belief_teammates_{field}"
                        ].append(float(value))
                visibility_counts: Counter[str] = Counter()
                visibility_angles: dict[str, list[float]] = defaultdict(list)
                visibility_signed_angles: dict[str, list[float]] = defaultdict(list)
                visibility_counts_by_band: dict[str, Counter[str]] = defaultdict(Counter)
                visibility_errors_by_band: dict[str, dict[str, list[float]]] = defaultdict(
                    lambda: defaultdict(list)
                )
                for teammate in candidate_context.get("teammate_visibility", []):
                    distance_m = teammate.get("distance_m")
                    if not isinstance(distance_m, (int, float)) or distance_m > 20.0:
                        continue
                    raw = teammate.get("raw_confidence")
                    occluded = teammate.get("occluded_confidence")
                    belief = teammate.get("belief_confidence")
                    reason = (
                        "in_belief"
                        if isinstance(belief, (int, float)) and belief >= 0.08
                        else "outside_fov_or_range"
                        if not isinstance(raw, (int, float)) or raw <= 0.0
                        else "occluded"
                        if not isinstance(occluded, (int, float)) or occluded <= 0.0
                        else "below_belief_threshold"
                    )
                    visibility_counts[reason] += 1
                    distance_band = (
                        "within_10m"
                        if float(distance_m) <= 10.0
                        else "within_15m"
                        if float(distance_m) <= 15.0
                        else "within_20m"
                    )
                    visibility_counts_by_band[distance_band][reason] += 1
                    belief_position_error = teammate.get("belief_position_error_m")
                    if isinstance(belief_position_error, (int, float)):
                        visibility_errors_by_band[distance_band][reason].append(
                            float(belief_position_error)
                        )
                    angle = teammate.get("facing_angle_degrees")
                    if isinstance(angle, (int, float)):
                        visibility_angles[reason].append(float(angle))
                    signed_angle = teammate.get("signed_facing_angle_degrees")
                    if isinstance(signed_angle, (int, float)):
                        visibility_signed_angles[reason].append(float(signed_angle))
                        if reason == "outside_fov_or_range":
                            player_iq = next_decision.get("player_iq")
                            if not isinstance(player_iq, (int, float)):
                                player_iq = next_decision.get("chosen", {}).get("value", {}).get(
                                    "player_iq", 80.0
                                )
                            half_fov = max(150.0, min(240.0, 180.0 + (float(player_iq) - 80.0) * 0.5)) / 2.0
                            scan_side = -1.0 if (int(next_decision.get("tick", 0)) + int(next_decision.get("player_idx", 0))) % 2 else 1.0
                            for scan_degrees in (45.0, 60.0, 75.0):
                                scanned_diff = abs((float(signed_angle) - scan_side * scan_degrees + 180.0) % 360.0 - 180.0)
                                angle_confidence = 1.0 - max(
                                    scanned_diff - half_fov * 0.65, 0.0
                                ) / max(half_fov * 0.70, 1.0)
                                mature_receipt_action_metrics[next_action][
                                    f"alternating_scan_recovers:{int(scan_degrees)}deg"
                                ].append(float(angle_confidence > 0.0))
                for reason, count in visibility_counts.items():
                    mature_receipt_action_metrics[next_action][
                        f"near_teammate_visibility_count:{reason}"
                    ].append(float(count))
                for distance_band in ("within_10m", "within_15m", "within_20m"):
                    for reason in (
                        "in_belief",
                        "outside_fov_or_range",
                        "occluded",
                        "below_belief_threshold",
                    ):
                        mature_receipt_action_metrics[next_action][
                            f"near_teammate_visibility_count:{distance_band}:{reason}"
                        ].append(
                            float(visibility_counts_by_band[distance_band][reason])
                        )
                        mature_receipt_outlet_context_metrics[outlet_context][
                            f"near_teammate_visibility_count:{distance_band}:{reason}"
                        ].append(
                            float(visibility_counts_by_band[distance_band][reason])
                        )
                        for position_error in visibility_errors_by_band[distance_band][reason]:
                            mature_receipt_action_metrics[next_action][
                                f"near_teammate_belief_position_error:{distance_band}:{reason}"
                            ].append(position_error)
                            mature_receipt_outlet_context_metrics[outlet_context][
                                f"near_teammate_belief_position_error:{distance_band}:{reason}"
                            ].append(position_error)
                for reason, angles in visibility_angles.items():
                    mature_receipt_action_metrics[next_action][
                        f"near_teammate_facing_angle:{reason}"
                    ].extend(angles)
                for reason, angles in visibility_signed_angles.items():
                    mature_receipt_action_metrics[next_action][
                        f"near_teammate_signed_facing_angle:{reason}"
                    ].extend(angles)
                    mature_receipt_action_metrics[next_action][
                        f"near_teammate_left_share:{reason}"
                    ].extend(float(angle < 0.0) for angle in angles)
                mature_chain_pass_timing[
                    "stable_control_to_next_decision_ticks"
                ].append(float(next_decision_tick - control_tick))
                mature_chain_pass_timing[
                    f"stable_control_to_next_decision_ticks:first_action={next_action}"
                ].append(float(next_decision_tick - control_tick))
            next_release = next(
                (
                    candidate
                    for candidate in sorted(
                        pass_releases_by_replay.values(),
                        key=lambda entry: int(entry.get("tick", -1)),
                    )
                    if candidate.get("possession_id") == release.get("possession_id")
                    and candidate.get("team") == release.get("team")
                    and isinstance(candidate.get("tick"), int)
                    and int(candidate["tick"]) > release_tick
                ),
                None,
            )
            if next_release is not None:
                next_release_tick = int(next_release["tick"])
                intervening_restart = next(
                    (
                        entry
                        for entry in trace_entries
                        if entry.get("event") == "restart"
                        and isinstance(entry.get("tick"), int)
                        and control_tick < int(entry["tick"]) < next_release_tick
                    ),
                    None,
                )
                if intervening_restart is not None:
                    mature_chain_pass_timing[
                        "excluded_restart_interrupted_intervals"
                    ].append(1.0)
                    next_release = None
            if next_release is not None:
                next_release_tick = int(next_release["tick"])
                mature_chain_pass_timing["release_to_next_pass_release_ticks"].append(
                    float(next_release_tick - release_tick)
                )
                control_to_next_release_ticks = float(
                    max(next_release_tick - control_tick, 0)
                )
                mature_chain_pass_timing["stable_control_to_next_pass_release_ticks"].append(
                    control_to_next_release_ticks
                )
                remaining_fraction = stable_control_remaining_by_replay.get(replay_id, 0.0)
                if isinstance(remaining_fraction, (int, float)):
                    continuous_control_seconds = max(
                        control_to_next_release_ticks - float(remaining_fraction),
                        0.0,
                    )
                    mature_chain_pass_timing[
                        "stable_control_to_next_pass_release_continuous_seconds"
                    ].append(continuous_control_seconds)
                    exact_flight_seconds = physical.get("exact_flight_seconds")
                    if isinstance(exact_flight_seconds, (int, float)):
                        mature_chain_pass_timing[
                            "release_to_next_pass_release_continuous_seconds"
                        ].append(float(exact_flight_seconds) + continuous_control_seconds)
                if next_decision is not None:
                    next_action = str(
                        next_decision.get("chosen", {}).get("action_type", "unknown")
                    )
                    mature_chain_pass_timing[
                        f"stable_control_to_next_pass_release_ticks:first_action={next_action}"
                    ].append(float(max(next_release_tick - control_tick, 0)))
                intervening_actions = [
                    str(decision.get("chosen", {}).get("action_type", "unknown"))
                    for decision in decisions
                    if decision.get("team") == terminal.get("winner_team")
                    and decision.get("player_idx") == terminal.get("winner_player")
                    and isinstance(decision.get("tick"), int)
                    and control_tick <= int(decision["tick"]) <= next_release_tick
                ]
                if intervening_actions:
                    compact_path = []
                    for action in intervening_actions:
                        if not compact_path or compact_path[-1] != action:
                            compact_path.append(action)
                    path = "->".join(compact_path)
                    mature_chain_pass_timing[f"path={path}:count"].append(1.0)
                    mature_chain_pass_timing[f"path={path}:ticks"].append(
                        float(max(next_release_tick - control_tick, 0))
                    )
                    mature_chain_pass_timing[f"path={path}:decision_count"].append(
                        float(len(intervening_actions))
                    )
                    mature_chain_pass_timing[f"path={path}:carry_decision_count"].append(
                        float(sum(action == "carry" for action in intervening_actions))
                    )
                    carry_execution_ticks = [
                        entry
                        for entry in trace_entries
                        if entry.get("action") == "carry"
                        and entry.get("team") == terminal.get("winner_team")
                        and entry.get("player_idx") == terminal.get("winner_player")
                        and isinstance(entry.get("tick"), int)
                        and control_tick <= int(entry["tick"]) < next_release_tick
                    ]
                    mature_chain_pass_timing[f"path={path}:carry_execution_ticks"].append(
                        float(len(carry_execution_ticks))
                    )
                    if carry_execution_ticks:
                        last_carry_tick = max(int(entry["tick"]) for entry in carry_execution_ticks)
                        mature_chain_pass_timing[
                            f"path={path}:last_carry_to_pass_ticks"
                        ].append(float(next_release_tick - last_carry_tick))
                        first_carry_tick = min(int(entry["tick"]) for entry in carry_execution_ticks)
                        mature_chain_pass_timing[
                            f"path={path}:control_to_first_carry_ticks"
                        ].append(float(first_carry_tick - control_tick))
                    mature_chain_pass_timing[f"path={path}:carry_distance_m"].append(
                        sum(
                            float(entry.get("physical_distance", entry.get("distance", 0.0)) or 0.0)
                            for entry in carry_execution_ticks
                        )
                    )
                    if "carry" in compact_path and initial_best_forward_pass is not None:
                        initial_details = initial_best_forward_pass.get("details", {})
                        initial_receiver = initial_details.get(
                            "intended_receiver",
                            initial_details.get("target_player_idx"),
                        )
                        final_receiver = next_release.get("target_player")
                        initial_target = initial_best_forward_pass.get("target")
                        final_target = next_release.get("target")
                        mature_chain_pass_timing[
                            "carry_path:initial_forward_pass_available"
                        ].append(1.0)
                        mature_chain_pass_timing[
                            "carry_path:initial_forward_same_receiver"
                        ].append(float(initial_receiver == final_receiver))
                        initial_value = initial_best_forward_pass.get("value", {})
                        initial_score = initial_value.get("score")
                        initial_retention = initial_value.get("success_prob")
                        for field, value in (
                            ("initial_forward_score", initial_score),
                            ("initial_forward_retention", initial_retention),
                        ):
                            if isinstance(value, (int, float)):
                                mature_chain_pass_timing[f"carry_path:{field}"].append(
                                    float(value)
                                )
                        if (
                            isinstance(initial_target, list)
                            and len(initial_target) >= 2
                            and isinstance(final_target, list)
                            and len(final_target) >= 2
                        ):
                            mature_chain_pass_timing[
                                "carry_path:initial_forward_to_final_target_distance_m"
                            ].append(
                                hypot(
                                    float(initial_target[0]) - float(final_target[0]),
                                    float(initial_target[1]) - float(final_target[1]),
                                )
                            )
                    interval_ticks = max(next_release_tick - control_tick, 0)
                    if interval_ticks >= 10:
                        mature_chain_long_tail_cases.append(
                            {
                                "possession_id": release.get("possession_id"),
                                "source_replay_id": replay_id,
                                "control_tick": control_tick,
                                "next_release_tick": next_release_tick,
                                "interval_ticks": interval_ticks,
                                "winner_team": terminal.get("winner_team"),
                                "winner_player": terminal.get("winner_player"),
                                "path": path,
                                "decision_ticks": [
                                    int(decision["tick"])
                                    for decision in decisions
                                    if decision.get("team") == terminal.get("winner_team")
                                    and decision.get("player_idx") == terminal.get("winner_player")
                                    and isinstance(decision.get("tick"), int)
                                    and control_tick <= int(decision["tick"]) <= next_release_tick
                                ],
                                "events": [
                                    {
                                        key: entry.get(key)
                                        for key in (
                                            "tick", "type", "event", "action",
                                            "phase", "player_idx", "winner_player",
                                            "outcome", "reason", "replay_id",
                                        )
                                        if entry.get(key) is not None
                                    }
                                    for entry in trace_entries
                                    if isinstance(entry.get("tick"), int)
                                    and control_tick <= int(entry["tick"]) <= next_release_tick
                                    and (
                                        entry.get("team") == terminal.get("winner_team")
                                        or entry.get("winner_team") == terminal.get("winner_team")
                                    )
                                    and (
                                        entry.get("type") in {"action", "event"}
                                        or entry.get("event") is not None
                                    )
                                ],
                            }
                        )
        if (
            terminal.get("outcome") == "completed"
            and isinstance(control_tick, int)
            and release.get("team") in {"home", "away"}
        ):
            winner_team = terminal.get("winner_team")
            winner_player = terminal.get("winner_player")
            next_decision = next(
                (
                    decision
                    for decision in decisions
                    if decision.get("team") == winner_team
                    and decision.get("player_idx") == winner_player
                    and isinstance(decision.get("tick"), int)
                    and int(decision["tick"]) >= control_tick
                ),
                None,
            )
            if next_decision is not None:
                pass_interval_timing["control_terminal_to_next_decision_ticks"].append(
                    float(int(next_decision["tick"]) - control_tick)
                )
                source_decision = chosen_pass_decisions.get(
                    (release_tick, release.get("team"), release.get("passer_player"))
                )
                predicted = (
                    source_decision.get("chosen", {})
                    .get("value", {})
                    .get("components", {})
                    .get("after_value")
                    if isinstance(source_decision, dict)
                    else None
                )
                predicted_control_readiness = (
                    source_decision.get("chosen", {})
                    .get("value", {})
                    .get("components", {})
                    .get("projected_retained_state", {})
                    .get("control_readiness")
                    if isinstance(source_decision, dict)
                    else None
                )
                realized = (
                    next_decision.get("chosen", {})
                    .get("value", {})
                    .get("components", {})
                    .get("current_value")
                )
                realized_control_readiness = (
                    next_decision.get("control", {})
                    .get("continuation_control_readiness")
                )
                release_origin = release.get("origin")
                release_target = release.get("target")
                distance_band = "unknown"
                if (
                    isinstance(release_origin, list)
                    and len(release_origin) >= 2
                    and isinstance(release_target, list)
                    and len(release_target) >= 2
                ):
                    pass_distance = hypot(
                        float(release_target[0]) - float(release_origin[0]),
                        float(release_target[1]) - float(release_origin[1]),
                    )
                    distance_band = (
                        "0_10m"
                        if pass_distance < 10.0
                        else "10_20m"
                        if pass_distance < 20.0
                        else "20_32m"
                        if pass_distance < 32.0
                        else "32m_plus"
                    )
                if isinstance(predicted, (int, float)) and isinstance(
                    realized, (int, float)
                ):
                    pass_value_realization["predicted_after"].append(float(predicted))
                    pass_value_realization["realized_current"].append(float(realized))
                    pass_value_realization["realized_minus_predicted"].append(
                        float(realized) - float(predicted)
                    )
                    pass_value_realization[
                        f"{distance_band}:predicted_after"
                    ].append(float(predicted))
                    pass_value_realization[
                        f"{distance_band}:realized_current"
                    ].append(float(realized))
                    pass_value_realization[
                        f"{distance_band}:realized_minus_predicted"
                    ].append(float(realized) - float(predicted))
                    pass_value_realization["release_to_next_decision_ticks"].append(
                        float(int(next_decision["tick"]) - int(release_tick))
                    )
                if isinstance(predicted_control_readiness, (int, float)) and isinstance(
                    realized_control_readiness, (int, float)
                ):
                    target_kind = str(release.get("target_kind") or "unknown")
                    profile = f"{distance_band}:{target_kind}"
                    for key in ("all", profile):
                        pass_value_realization[
                            f"{key}:projected_control_readiness"
                        ].append(float(predicted_control_readiness))
                        pass_value_realization[
                            f"{key}:live_control_readiness"
                        ].append(float(realized_control_readiness))
                        pass_value_realization[
                            f"{key}:live_minus_projected_control_readiness"
                        ].append(
                            float(realized_control_readiness)
                            - float(predicted_control_readiness)
                        )
    completed_receipts: list[dict[str, Any]] = []
    for entry in trace_entries:
        if entry.get("event") != "pass_control_terminal" or entry.get("outcome") != "completed":
            continue
        release = pass_releases_by_replay.get(entry.get("replay_id"), {})
        team = entry.get("winner_team")
        player_idx = entry.get("winner_player")
        tick = entry.get("tick")
        origin = release.get("origin")
        if team not in {"home", "away"} or not isinstance(player_idx, int) or not isinstance(tick, int):
            continue
        completed_receipts.append(
            {
                "replay_id": entry.get("replay_id"),
                "tick": tick,
                "team": team,
                "player_idx": player_idx,
                "possession_id": release.get("possession_id"),
                "intended_receiver_idx": entry.get(
                    "intended_receiver_player"
                ),
                "winner_is_intended_receiver": entry.get(
                    "winner_is_intended_receiver"
                ),
                "origin": origin,
            }
        )
