    chosen_reorient_keys = {
        (decision.get("tick"), decision.get("team"), decision.get("player_idx"))
        for decision in decisions
        if decision.get("chosen", {}).get("action_type") == "reorient"
    }
    goal_kick_options = [
        entry
        for entry in response.get("trace", {}).get("entries", [])
        if entry.get("event") == "goal_kick_pass_options"
    ]
    goal_kick_decision_keys = {
        (entry.get("tick"), entry.get("team"), entry.get("player_idx"))
        for entry in goal_kick_options
    }
    for decision in decisions:
        counterfactual = _outcome_distinguishability_selection_counterfactual(
            decision
        )
        if counterfactual is None:
            outcome_distinguishability_counterfactual_counts[
                "missing_inputs"
            ] += 1
            continue
        outcome_distinguishability_counterfactual_counts["decisions"] += 1
        restart_profile = (
            "goal_kick"
            if (
                decision.get("tick"),
                decision.get("team"),
                decision.get("player_idx"),
            )
            in goal_kick_decision_keys
            else "open_play_or_other"
        )
        for field, value in counterfactual.items():
            outcome_distinguishability_counterfactual_metrics[field].append(
                float(value)
            )
            outcome_distinguishability_counterfactual_by_restart[restart_profile][
                field
            ].append(float(value))
        production_best_action = max(
            (
                action
                for action in (
                    "carry", "pass", "shoot", "hold", "reorient", "clear"
                )
            ),
            key=lambda action: counterfactual.get(
                f"production_action_{action}_probability", 0.0
            ),
        )
        raw_best_action = max(
            (
                action
                for action in (
                    "carry", "pass", "shoot", "hold", "reorient", "clear"
                )
            ),
            key=lambda action: counterfactual.get(
                f"raw_action_{action}_probability", 0.0
            ),
        )
        outcome_distinguishability_counterfactual_counts[
            f"best_action={production_best_action}->{raw_best_action}"
        ] += 1
        outcome_distinguishability_counterfactual_counts[
            "best_action_changed"
            if production_best_action != raw_best_action
            else "best_action_unchanged"
        ] += 1
    for entry in trace_entries:
        if entry.get("event") != "reorient_target_counterfactual":
            continue
        if (entry.get("tick"), entry.get("team"), entry.get("player_idx")) not in chosen_reorient_keys:
            continue
        by_profile = {
            str(candidate.get("profile")): candidate
            for candidate in entry.get("candidates", [])
            if isinstance(candidate, dict)
        }
        baseline = by_profile.get("goal_center", {})
        for profile, candidate in by_profile.items():
            for field in (
                "score",
                "after_value",
                "duration_seconds",
                "turn_angle_degrees",
                "control_readiness",
            ):
                value = candidate.get(field)
                if isinstance(value, (int, float)):
                    reorient_target_counterfactual_metrics[
                        f"{profile}:{field}"
                    ].append(float(value))
                baseline_value = baseline.get(field)
                if (
                    profile != "goal_center"
                    and isinstance(value, (int, float))
                    and isinstance(baseline_value, (int, float))
                ):
                    reorient_target_counterfactual_metrics[
                        f"{profile}:minus_goal_center:{field}"
                    ].append(float(value) - float(baseline_value))
    pass_motor_counterfactual_metrics: dict[str, list[float]] = defaultdict(list)
