    goal_kick_marking_counts: Counter[str] = Counter()
    goal_kick_marking_metrics: dict[str, list[float]] = defaultdict(list)
    goal_kick_marking_cases: list[dict[str, Any]] = []
    goal_kick_selector_metrics: dict[str, list[float]] = defaultdict(list)
    for entry in goal_kick_options:
        selector_actions = entry.get("selector", {}).get("actions", [])
        restart_probability_mass: Counter[str] = Counter()
        for action in selector_actions:
            probability = action.get("overall_selection_probability")
            distance_m = action.get("distance_m")
            if (
                action.get("action") != "pass"
                or not isinstance(probability, (int, float))
                or not isinstance(distance_m, (int, float))
            ):
                continue
            probability = float(probability)
            distance_m = float(distance_m)
            length = "long" if distance_m >= 32.0 else "short"
            band = (
                "0_10m" if distance_m < 10.0
                else "10_20m" if distance_m < 20.0
                else "20_32m" if distance_m < 32.0
                else "32_40m" if distance_m < 40.0
                else "40_50m" if distance_m < 50.0
                else "50m_plus"
            )
            restart_probability_mass[f"length={length}"] += probability
            restart_probability_mass[f"distance={band}"] += probability
            for field in (
                "technical_probability",
                "retention_probability",
                "retained_control_probability",
                "opposing_control_probability",
                "unresolved_probability",
            ):
                value = action.get(field)
                if isinstance(value, (int, float)):
                    restart_probability_mass[f"weighted_{length}:{field}"] += (
                        probability * float(value)
                    )
        for field, value in restart_probability_mass.items():
            goal_kick_selector_metrics[field].append(value)
        outlets = [
            outlet
            for outlet in entry.get("outfield_outlets", [])
            if isinstance(outlet, dict)
            and isinstance(outlet.get("pos"), list)
            and len(outlet["pos"]) >= 2
        ]
        defenders = [
            defender
            for defender in entry.get("outfield_defenders", [])
            if isinstance(defender, dict)
            and isinstance(defender.get("pos"), list)
            and len(defender["pos"]) >= 2
        ]
        if not outlets or not defenders:
            goal_kick_marking_counts["missing_geometry"] += 1
            continue
        nearest_outlet_by_defender: list[tuple[int, float]] = []
        nearest_defender_by_outlet: list[float] = []
        for defender in defenders:
            defender_pos = defender["pos"]
            distances = [
                hypot(
                    float(defender_pos[0]) - float(outlet["pos"][0]),
                    float(defender_pos[1]) - float(outlet["pos"][1]),
                )
                for outlet in outlets
            ]
            outlet_index = min(range(len(distances)), key=distances.__getitem__)
            nearest_outlet_by_defender.append((outlet_index, distances[outlet_index]))
        for outlet in outlets:
            outlet_pos = outlet["pos"]
            nearest_defender_by_outlet.append(min(
                hypot(
                    float(defender["pos"][0]) - float(outlet_pos[0]),
                    float(defender["pos"][1]) - float(outlet_pos[1]),
                )
                for defender in defenders
            ))
        coverage = Counter(index for index, _ in nearest_outlet_by_defender)
        duplicate_defenders = sum(max(count - 1, 0) for count in coverage.values())
        uncovered_outlets = sum(index not in coverage for index in range(len(outlets)))
        max_duplicate = max(coverage.values(), default=0)
        goal_kick_marking_counts["restarts"] += 1
        goal_kick_marking_counts["with_duplicate_nearest_outlet"] += int(
            duplicate_defenders > 0
        )
        goal_kick_marking_counts["with_uncovered_outlet"] += int(
            uncovered_outlets > 0
        )
        goal_kick_marking_metrics["duplicate_defenders"].append(
            float(duplicate_defenders)
        )
        goal_kick_marking_metrics["uncovered_outlets"].append(
            float(uncovered_outlets)
        )
        goal_kick_marking_metrics["maximum_defenders_on_one_outlet"].append(
            float(max_duplicate)
        )
        goal_kick_marking_metrics["mean_nearest_outlet_distance_m"].append(
            mean(distance_m for _, distance_m in nearest_outlet_by_defender)
        )
        goal_kick_marking_metrics["mean_outlet_nearest_defender_distance_m"].append(
            mean(nearest_defender_by_outlet)
        )
        goal_kick_marking_metrics["maximum_outlet_nearest_defender_distance_m"].append(
            max(nearest_defender_by_outlet)
        )
        goal_kick_marking_cases.append({
            "tick": entry.get("tick"),
            "team": entry.get("team"),
            "opponent_press_intensity": entry.get("opponent_press_intensity"),
            "outlet_count": len(outlets),
            "defender_count": len(defenders),
            "nearest_assignment_counts": {
                str(outlets[index].get("index")): count
                for index, count in sorted(coverage.items())
            },
            "duplicate_defenders": duplicate_defenders,
            "uncovered_outlets": uncovered_outlets,
            "outlet_nearest_defender_distances_m": [
                round(distance_m, 6) for distance_m in nearest_defender_by_outlet
            ],
        })
